insert into public.chapters
  (story_id, number, title, content, status, published_at, created_at, updated_at)
values
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 21, 'Xin lỗi(bản chỉnh sửa)', '<p style="text-align: justify; margin-bottom: 0.9em">Khi Dư Mạt bưng trà vào phòng, cô nhìn thấy vẻ mặt kinh ngạc của Lâm Châu, cứ như vừa nghe được một bí mật động trời.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bước tới, đưa cốc nước cho Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hoàn hồn:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đang nằm sấp trên giường với tư thế ngủ chẳng mấy ngay ngắn.</p><p style="text-align: justify; margin-bottom: 0.9em">Bao nhiêu năm trôi qua, Thời Vụ đã thay đổi rất nhiều. Chỉ riêng dáng ngủ phóng khoáng này vẫn y như trước.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhớ lại lần đầu tiên Thời Vụ đến nhà mình chơi.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người cuộn mình trong chăn, vừa ăn que cay, uống Coca, vừa đọc hai cuốn truyện tranh mua ở sạp hàng với giá một tệ.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi tiếng bước chân của mẹ cô đến gần căn phòng, cả hai lập tức giấu đồ đi, giả vờ ngủ.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó cũng chẳng biết ai ngủ trước. Dù sao Dư Mạt là người bị đánh thức.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đạp một phát khiến cô rơi khỏi giường.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong vô thức, Dư Mạt cảm thấy mông mình đau nhói.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ngượng ngùng cười với Lâm Châu, kéo chăn đắp lên người Thời Vụ, che kín nàng lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hỏi Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vợ chị ấy ngoại tình rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt suýt bị ngụm nước trong miệng làm sặc chết:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không... không có đâu nhỉ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Mặc dù cô cũng không chắc những lời Triệu Hy Ngọc nói vừa rồi rốt cuộc có ý gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Là đã ngoại tình?</p><p style="text-align: justify; margin-bottom: 0.9em">Hay vẫn chưa ngoại tình?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu "ồ" một tiếng rồi nhìn sang Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao cô biết chuyện vợ của cậu ấy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vừa nãy chị ấy mới nói."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt căng thẳng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu ấy nói gì với cô?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cũng không có gì. Chị ấy gọi điện cho chị tôi, nói rằng vợ mình đã ngoại tình."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt gãi đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị cô?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, một tia sáng chợt lóe lên trong đầu cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị cô... không phải là Lâm Nhược Đường đấy chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Đều mang họ Lâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Lại cùng có bà đang nằm viện.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô cũng quen chị tôi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đúng là cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hai người thân nhau lắm à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi từng nghe Thời Vụ kể, trước đây chị cô là bệnh nhân của mẹ cậu ấy, còn từng ở nhà cậu ấy. Tôi cũng đã gặp chị cô hai lần."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nói vậy là cô và chị Thời Vụ đã quen nhau từ rất sớm rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chúng tôi quen nhau từ nhỏ. Hồi mẫu giáo còn ngồi cùng bàn, sau đó dần dần trở nên thân thiết."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy quan hệ giữa hai người chắc hẳn rất tốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thời Vụ tính tình lãnh đạm, không còn người thân nào, bạn bè cũng ít."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Điểm này quả thật rất giống Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi cha mẹ qua đời, bên cạnh Lâm Nhược Đường chỉ còn bà thương chị ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường còn thảm hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến một người bạn tri kỷ cũng không có.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu càng nghĩ càng thấy buồn, khẽ thở dài, khiến Dư Mạt ngẩn người.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cảm thán:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trên đời này có thật nhiều người khổ mệnh."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đã chứng kiến quá nhiều chuyện trong bệnh viện, trong lòng không khỏi đồng cảm.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô vỗ vai Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu xúc động, cũng vỗ vai Dư Mạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Điện thoại rung lên, phá vỡ bầu không khí ấm áp khi hai người đang an ủi lẫn nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lấy điện thoại ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gửi tới ba chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Năm phút nữa.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hét lên:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tới ngay! Em qua ngay!"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt thấy cô hấp tấp định ra ngoài, cũng lập tức đi theo, vừa đi vừa vội hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi luôn thế à? Không ngồi thêm chút nữa sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nói thừa.</p><p style="text-align: justify; margin-bottom: 0.9em">Người ta là đại minh tinh, bận lắm đấy!</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vừa thay giày vừa quay đầu nói với cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lần sau tôi lại đến chơi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được thôi, lúc nào cũng hoan nghênh."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu xỏ chân vào giày rồi thoắt một cái chạy xuống lầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Đèn cảm ứng ngoài hành lang lần lượt sáng lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt không còn nghe thấy tiếng bước chân nữa, bèn đóng cửa lại, sau đó đi tới bên cửa sổ nhìn xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa xe bảo mẫu mở ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu khom người chui vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Dư Mạt mới yên tâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu chạy đến bệnh viện, không ngờ Lâm Nhược Đường vẫn còn ở đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây chị là người ghét chờ đợi nhất, hôm nay lại đợi cô lâu như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bước đến trước mặt Lâm Nhược Đường, giả vờ ngoan ngoãn:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị, vẫn chưa vào trong à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay đầu nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Không chào hỏi.</p><p style="text-align: justify; margin-bottom: 0.9em">Cũng không cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Cứ nhìn chằm chằm như vậy khiến Lâm Châu nổi da gà.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nheo mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị nhìn em làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Em đi đâu vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu "ồ" một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đưa chị Thời Vụ về nhà."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Về nhà?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cũng không hẳn là về nhà. Vừa nãy, khi đến cổng bệnh viện, em nhìn thấy chị ấy và bạn chị ấy. Chị ấy uống nhiều quá nên tiện đường em đưa chị ấy về nhà bạn."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói đến đây, cô nhìn sang Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Còn cuộc điện thoại kia là sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhíu mày, lạnh lùng liếc cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cái gì mà sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu Lâm Châu không quen với dáng vẻ này của Lâm Nhược Đường, e rằng cô thật sự đã bị chị dọa cho im bặt, chẳng dám hỏi tiếp.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cô đã sớm quen vuốt râu hùm.</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng những không sợ chút nào, ngược lại còn "đe dọa" Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị đưa thẻ phòng cho người khác đấy nhé, hơn nữa còn là người đã kết hôn. Lát nữa em sẽ mách bà!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường giơ tay ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hét lên một tiếng rồi lao thẳng vào phòng bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Bà cụ Lâm nhìn Lâm Châu giống như một con chim sẻ, phía sau lại có Lâm Nhược Đường như chiếc lồng chim bám theo, lập tức cảm thấy đau đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bước vào, tươi cười gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bà! Bà!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng sa sầm mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nghe thấy rồi. Líu ríu ồn ào, chẳng chững chạc chút nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu làm nũng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ồ, ý bà là con không ngoan bằng chị sao? Vậy lần sau con không đến nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Từ nhỏ cô đã biết giả vờ tủi thân.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng biết cô chỉ đang diễn, nhưng vẫn mềm lòng trước chiêu này, bèn nhỏ giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ta đâu có nói con không ngoan."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu sáp lại bên bà, giơ tay ôm lấy Lâm Ngọc Phượng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy là bà nhớ con đến thăm rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Vẻ mặt căng thẳng của Lâm Ngọc Phượng lập tức tan biến.</p><p style="text-align: justify; margin-bottom: 0.9em">Bà vỗ lưng cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chỉ được cái dẻo miệng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vui vẻ cười ha ha:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nếu không thì sao con có thể là cây hài của bà được chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng hoàn toàn hết cách với cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con đó!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đứng sau lưng Lâm Châu, ngay ngắn gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bà."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không có việc gì thì học theo Tiểu Châu nhiều một chút, cười nhiều lên. Suốt ngày cứ sa sầm mặt, cũng chẳng biết đang hù dọa ai."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu phụ họa:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đúng vậy, cũng chẳng biết đang hù dọa ai nữa!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao bữa trưa ta sắp xếp, con lại không đi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con không có thời gian."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Buổi trưa con đâu có hẹn ai, sao lại không có thời gian?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu giơ tay:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con biết!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cảnh cáo liếc cô một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Buổi trưa chị có hẹn rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng cau mày:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hẹn với ai?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu không chút do dự:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Với con. Buổi trưa con nhờ chị đi ăn cùng, tiện thể giúp con ứng phó với một bữa tiệc."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng lập tức quay mũi nhọn về phía cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ta đã nói rồi, nếu con thật sự muốn đóng phim thì đến công ty của bạn ta. Đừng một mình bươn chải bên ngoài. Hôm nay dính tin đồn này, ngày mai lại lộ chuyện kia, ngày nào cũng toàn là người ta mắng con."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vốn không để tâm đến những thứ giả tạo ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng được Lâm Ngọc Phượng quan tâm, lòng cô vẫn cảm thấy ấm áp.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ôm chặt lấy bà:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con biết rồi, bà. Con sẽ cân nhắc."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ta thật sự không khuyên nổi mấy đứa nữa. Đứa nào cũng có chủ kiến lớn hơn trời."</p><p style="text-align: justify; margin-bottom: 0.9em">Bà nhìn Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đường Đường, con nói xem, con có đi xem mắt không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói rõ từng chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con không đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng suýt trợn trắng mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vội dỗ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bà! Bà! Bà nghe con nói này, chị không đi là có lý do."</p><p style="text-align: justify; margin-bottom: 0.9em">Một câu khiến cả hai người đều nhìn về phía cô, ánh mắt sáng rực.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cảm thấy nếu mình hơi nhát gan một chút, chắc chắn sẽ khai hết mọi chuyện.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cô là ai chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Khả năng chịu áp lực mạnh đến mức vô lý.</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng những không khai, cô còn nói bừa:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị vẫn chưa gặp được người thích hợp."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng cân nhắc:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Người thích hợp?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đúng vậy. Thời gian trước chẳng phải con đã đến miếu xin quẻ sao? Con tiện thể xem giúp chị một quẻ. Quẻ nói nhân duyên của chị sắp đến rồi, nhưng chuyện này phải thuận theo tự nhiên, không thể ép buộc."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cho nên bà nghe con đi. Thời gian này đừng bắt chị đi xem mắt nữa. Chị sẽ sớm gặp được nhân duyên lớn của mình thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là nói nhăng nói cuội.</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi Lâm Nhược Đường khẽ giật.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng lại tin thật:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thật sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường kinh ngạc nhìn Lâm Ngọc Phượng.</p><p style="text-align: justify; margin-bottom: 0.9em">Bà lại tin những lời ma quỷ này thật sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu thề thốt chắc nịch:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thật mà!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng cũng không muốn tin, nhưng có bệnh thì vái tứ phương.</p><p style="text-align: justify; margin-bottom: 0.9em">Bà miễn cưỡng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được rồi, chuyện của chị con tạm thời ta không vội. Còn con thì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "..."</p><p style="text-align: justify; margin-bottom: 0.9em">Đến lượt cô thì "bụp" một tiếng, tắt ngúm luôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bước ra khỏi phòng bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nghe Lâm Châu ở bên trong tranh luận với Lâm Ngọc Phượng, hai người không ai chịu nhường ai.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Lâm Châu ra khỏi phòng bệnh, Lâm Nhược Đường đang ngồi trên ghế.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô quay đầu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bà ngủ rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sức khỏe của bà lại kém đi rồi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa rồi hai người mới trò chuyện được vài câu, bà quay đầu một cái đã ngủ mất.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Người đó đã đến thăm chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đã đến."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bĩu môi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không phải đến đòi tài sản thừa kế đấy chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Ai cũng biết cổ phần của Lâm Ngọc Phượng được chia thành ba phần.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường và người đó mỗi người một phần.</p><p style="text-align: justify; margin-bottom: 0.9em">Còn phần cuối cùng, chẳng ai biết bà sẽ để lại cho ai.</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Lâm Châu đầy mỉa mai:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mấy hôm trước ông ta liên lạc với em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay đầu lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ông ta nhận lỗi với em, nói rằng mình đã hối hận, muốn em về nhà."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị nói xem, ông ta sẽ không cho rằng phần cổ phần của bà được để lại cho em đấy chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lẽ ra em nên đồng ý với ông ta, về nhà để ông ta hầu hạ em."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đợi đến khi ông ta biết cổ phần của bà không phải để lại cho em, vẻ mặt lúc đó chắc chắn sẽ thú vị lắm!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thấy cô phấn khích đến mức khoa tay múa chân, vừa cười vừa nói mà chẳng nhìn đường, suýt đi quá thang máy, bèn túm cổ áo kéo cô trở lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu ho khan:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhẹ tay! Nhẹ tay!"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bước vào thang máy rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị đi trước đi, em lên tầng bốn một chuyến."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lên tầng bốn làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có một người hâm mộ nằm ở tầng bốn. Hôm nay em ấy vừa phẫu thuật xong, em lên thăm một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhiệt tình thế sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao có thể sánh với Lâm tổng được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hậm hực nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng còn tự tay đưa thẻ phòng cho người ta cơ mà. Nhớ hồi em bị tung tin đồn, Lâm tổng đến một cuộc điện thoại cũng chẳng nỡ gọi cho em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghiêng đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Không nói gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ nhìn chằm chằm Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu biết mình đùa hơi quá, bèn thu lại nụ cười nịnh nọt trên mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị, em..."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Á!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bước ra khỏi thang máy, bả vai đau nhói.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa rồi bị Lâm Nhược Đường bóp một cái, cô cảm thấy xương mình sắp vỡ vụn đến nơi.</p><p style="text-align: justify; margin-bottom: 0.9em">Ra tay thật độc ác!</p><p style="text-align: justify; margin-bottom: 0.9em">Còn coi cô là em gái nữa không vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Sau này có vợ rồi, chẳng phải chị sẽ càng độc ác hơn sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nghiến răng nghiến lợi, đeo kính râm và khẩu trang rồi đi tìm giường bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường xuống lầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đứng chờ bên cạnh xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy cô đến gần, Trần Hy cúi đầu mở cửa xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Lâm Nhược Đường lên xe, Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiệc đón Triệu tổng đã được ấn định vào tối mai. Ngoài ra, chiều nay Viễn tổng đã gặp Triệu tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Viễn tổng là cậu của Lâm Nhược Đường, tên Lâm Viễn.</p><p style="text-align: justify; margin-bottom: 0.9em">Hiện tại, nhà họ Lâm có hai phó tổng giám đốc.</p><p style="text-align: justify; margin-bottom: 0.9em">Một người là Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Người còn lại là Lâm Viễn.</p><p style="text-align: justify; margin-bottom: 0.9em">Bất kể xét về thâm niên hay tuổi tác, đáng lẽ Lâm Viễn mới là người được gọi là Lâm tổng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng vào ngày đầu tiên Lâm Nhược Đường tới công ty, cô đã nói với Lâm Viễn:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu, tối qua con nằm mơ thấy mẹ. Mẹ vẫn gọi cậu là Tiểu Viễn Tử."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con còn bảo mẹ chẳng lịch sự gì cả, sao có thể gọi cậu như vậy được? Phải gọi là Viễn tổng mới đúng."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu à, đúng không? Cậu sẽ không so đo cách xưng hô với một đứa nhỏ như con chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Cơ mặt Lâm Viễn khẽ giật.</p><p style="text-align: justify; margin-bottom: 0.9em">Ông cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao cậu có thể so đo với con được? Con muốn gọi thế nào thì cứ gọi thế ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Chưa đầy một ngày, cách xưng hô mới này đã truyền khắp công ty.</p><p style="text-align: justify; margin-bottom: 0.9em">Bây giờ mọi người đã có thể phân biệt hai người một cách hoàn hảo.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Họ đã nói chuyện gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Viễn tổng nói muốn mở tiệc đón gió tẩy trần cho Triệu tổng. Tôi đoán là vì chuyện sản phẩm mới của La Mạn Kỷ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ông ta rảnh rỗi đến thế sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy báo cáo:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Gần đây Viễn tổng đã bàn bạc vài dự án phát triển bất động sản, nghe nói lợi nhuận khá cao."</p><p style="text-align: justify; margin-bottom: 0.9em">Vì vậy, ông ta mới rảnh rỗi đến mức muốn thò tay vào phần lợi ích của người khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay đầu nhìn Trần Hy.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong xe tối mờ nhưng đôi mắt Lâm Nhược Đường vẫn sáng và sắc bén.</p><p style="text-align: justify; margin-bottom: 0.9em">Sự lạnh lẽo nơi đáy mắt dần ngưng tụ thành lưỡi dao, bất cứ lúc nào cũng có thể chém xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy hít sâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Đã ở bên Lâm Nhược Đường lâu như vậy, cô vẫn không thể chống đỡ nổi khí thế áp đảo của người kia.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tìm chút việc cho ông ta làm."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vâng."</p><p style="text-align: justify; margin-bottom: 0.9em">Xe chạy thẳng về biệt thự.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Lâm Nhược Đường về đến nhà, Lâm Châu vẫn chưa về.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô tắm xong, vừa bước ra khỏi phòng đã thấy Lâm Châu đang gọi điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nhìn thấy cô, Lâm Châu lè lưỡi rồi lách người chạy vào phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ôm đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Xin lỗi, vừa rồi có phải tôi đã thất thố không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra nàng không nhớ rõ lắm.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ biết sau khi tỉnh giấc, Dư Mạt cứ nhìn nàng chằm chằm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vội vàng xin lỗi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có phải tôi uống say rồi lại nổi cơn không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đúng vậy, hơn nữa không chỉ có mình tôi nhìn thấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Còn ai nữa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Còn có Lâm Châu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ có nằm mơ cũng không ngờ tới:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm Châu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu uống nhiều quá, ở cổng bệnh viện suýt xảy ra chuyện. Lâm Châu đã đưa chúng ta về."</p><p style="text-align: justify; margin-bottom: 0.9em">Được rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu một hơi rồi mới gọi điện cho Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không sao đâu, thật đấy. Chị không hề thất thố."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ôm đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thật sự xin lỗi."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Em thì không sao."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu muốn nói rồi lại thôi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chỉ là chị em..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt tỉnh táo:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị... Chị em làm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng còn nói lắp rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị đã mắng chị ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ suýt bật dậy khỏi giường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị? Chị đã mắng chị ấy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lấy đâu ra lá gan đó?</p><p style="text-align: justify; margin-bottom: 0.9em">Lại dám mắng Lâm Nhược Đường?</p><p style="text-align: justify; margin-bottom: 0.9em">Có nhầm lẫn gì không vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ toát mồ hôi lạnh:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Châu, em đang đùa với chị phải không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị, em biết tâm trạng chị không tốt, sao em có thể lấy chuyện này ra đùa với chị được?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vốn dĩ em cũng không định nói. Chỉ là hai người chẳng phải vẫn còn hợp tác sao? Em sợ lỡ như... chị hiểu mà."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cứng đầu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị hiểu, chị hiểu. Chị sẽ xin lỗi chị ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cúp điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nằm liệt trên giường.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đưa nàng một cốc trà.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Thời Vụ xoa huyệt thái dương, cô hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lại đau đầu à?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừ."</p><p style="text-align: justify; margin-bottom: 0.9em">Vẻ mặt Thời Vụ nhàn nhạt, ánh mắt trống rỗng.</p><p style="text-align: justify; margin-bottom: 0.9em">Những ngón tay vô thức lặp đi lặp lại một động tác, cũng không biết đang nghĩ gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đoán nàng đang nghĩ đến Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô muốn mở miệng nói gì đó nhưng lại do dự.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn ra vẻ mặt rối rắm của cô, bèn nhếch môi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Muốn hỏi gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu... bên phía Triệu Hy Ngọc, cậu định làm thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hé miệng.</p><p style="text-align: justify; margin-bottom: 0.9em">Kể từ khi Thời Ánh Xuân rời đi, thế giới của nàng trở nên yên tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Mỗi ngày đi học rồi tan học.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến giờ thì đi làm.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngay cả khi đi làm cũng luôn lặp lại như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Những tháng ngày bình lặng không gợn sóng ấy đã bị Triệu Hy Ngọc làm xáo trộn.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cùng chị tăng ca.</p><p style="text-align: justify; margin-bottom: 0.9em">Cùng ăn khuya.</p><p style="text-align: justify; margin-bottom: 0.9em">Tan làm rồi cùng nhau đi bộ về nhà.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi nàng bị bệnh, chị sẽ ở bên chăm sóc.</p><p style="text-align: justify; margin-bottom: 0.9em">Không thể phủ nhận, Triệu Hy Ngọc đã mang đến cho nàng rất nhiều hơi ấm.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhiều đến mức trước khi biết chuyện ở bệnh viện, Thời Vụ đã hết lần này đến lần khác tự lừa dối bản thân.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng bây giờ, nàng không thể tiếp tục lừa dối nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngày mai tôi sẽ nói chuyện với chị ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nếu chị ấy vẫn kiên quyết muốn giữ đứa bé này, tôi sẽ tác thành cho họ."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt kinh ngạc:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không phải chứ? Cậu chấp nhận đứa con của chị ta và Triệu Tinh sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩng mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu đang nói gì vậy? Ý tôi là tôi sẽ nhường chỗ, để hai người họ kết hôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt "ồ" một tiếng, sau đó hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu thật sự muốn ly hôn sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây, Thời Vụ luôn cảm thấy hai chữ này thật chói tai.</p><p style="text-align: justify; margin-bottom: 0.9em">Kể từ khi kết hôn với Triệu Hy Ngọc, nàng chưa từng nghĩ đến chuyện ly hôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Tình yêu giữa Thời Ánh Xuân và Thường Anh quá đẹp đẽ.</p><p style="text-align: justify; margin-bottom: 0.9em">Đẹp đến mức khiến nàng lầm tưởng rằng mình cũng sẽ có được một tình yêu hạnh phúc như thế.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng hiện giờ, nàng chỉ cảm thấy cuộc hôn nhân của mình chứa đầy toan tính.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu ngay từ đầu Triệu Hy Ngọc đã thẳng thắn với nàng...</p><p style="text-align: justify; margin-bottom: 0.9em">Thôi vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Cho dù chị ấy có thẳng thắn ngay từ đầu, nàng vẫn không thể chấp nhận được.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừ."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt ôm lấy nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không sao, không sao. Cùng lắm thì vẫn còn có tôi. Cậu ly hôn rồi chuyển qua ở cùng tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tựa cằm lên vai Dư Mạt, hơi nghiêng mặt sang một bên, mặc cho cô ôm mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nàng nhẹ bẫng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Dư Mạt."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hửm?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ thở dài, cố gắng khiến giọng mình nghe thật bình tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có phải tôi rất dễ bị bắt nạt không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không phải. Ai dám bắt nạt cậu, tôi sẽ đánh chết người đó!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười một tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Dư Mạt lại nhận ra cổ mình lạnh ngắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ trong một buổi tối, Thời Vụ đã khóc hai lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc đúng là quá nhẫn tâm!</p><p style="text-align: justify; margin-bottom: 0.9em">Ngày Thời Ánh Xuân qua đời, Thời Vụ cũng không khóc.</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi sáng đưa người đi hỏa táng, tất cả những người nhìn thấy Thời Ánh Xuân lần cuối đều khóc như mưa.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ có Thời Vụ không biểu lộ cảm xúc gì, cứ ngây ngốc đứng đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó là đưa tro cốt đi an táng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Ánh Xuân được chôn trong phần mộ của Thường Anh.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người hợp táng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi xổm trước bia mộ, ngón tay vuốt ve bức ảnh chung của hai người, vẫn không nói một lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con ở bên Tiểu Vụ nhiều một chút, để em ấy khóc ra."</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Dư Mạt nghĩ đủ mọi cách.</p><p style="text-align: justify; margin-bottom: 0.9em">Bà thậm chí còn lấy những bức ảnh Thường Anh chụp trước đây ra, bày đầy trên bàn trà.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng khi Thời Vụ nhìn thấy, nàng chỉ sắp xếp rồi cất những bức ảnh lại ngay ngắn, hoàn toàn không có dấu hiệu muốn khóc.</p><p style="text-align: justify; margin-bottom: 0.9em">Bà lo lắng nhìn Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con cứ khóc đi, không ai nhìn thấy đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có gì đáng để khóc chứ? Khóc rồi bà ấy sẽ trở về sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Khi ấy, bà cảm thấy Thời Vụ thật lạnh lùng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng đến tối, lúc ở lại cùng nàng nghỉ ngơi, bà lại nghe thấy nàng trốn trong phòng vệ sinh, dùng tiếng nước để che giấu tiếng khóc.</p><p style="text-align: justify; margin-bottom: 0.9em">Đã bao lâu rồi Dư Mạt không nghe thấy Thời Vụ khóc?</p><p style="text-align: justify; margin-bottom: 0.9em">Cô tức giận, hai tay siết chặt thành nắm đấm.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu lúc này Triệu Hy Ngọc xuất hiện trước mặt, cô bảo đảm sẽ đấm nát đầu chị ta.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cắn môi, giọng nghèn nghẹn.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đau lòng lấy khăn giấy đưa cho nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Muốn khóc thì cứ khóc đi, cũng chẳng mất mặt."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn vào ánh mắt lo lắng của cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi không muốn khóc."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nói mang theo tiếng nức nở của nàng càng khiến người ta đau lòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không sao đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi gây chuyện rồi. Vừa nãy tôi đã mắng Lâm Nhược Đường."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nói, nàng vừa dùng khăn giấy che mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Nước mắt tuôn ra không sao ngăn được.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sao lại còn có chuyện liên quan đến Lâm Nhược Đường nữa?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vừa khóc vừa nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi gọi điện thoại mắng Lâm Nhược Đường rồi. Chắc chắn cô ấy sẽ không muốn hợp tác với Ưu Lạc nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "..."</p><p style="text-align: justify; margin-bottom: 0.9em">Không hổ là người tận tâm với công việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến lúc này rồi mà vẫn có thể nghĩ đến chuyện của công ty.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ hiện tại nàng chỉ đang mượn chuyện công ty để trút ra cảm xúc bất an.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt động viên:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy cậu gọi điện xin lỗi cô ấy đi. Chắc cô ấy sẽ hiểu thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ nấc một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Gọi điện sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi nhắn tin thôi. Tôi không dám gọi điện cho cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tại sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi hơi sợ cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "..."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô cứ cảm thấy Thời Vụ lúc này đã tỉnh rượu, nhưng dường như lại chưa tỉnh hẳn.</p><p style="text-align: justify; margin-bottom: 0.9em">Cũng đúng.</p><p style="text-align: justify; margin-bottom: 0.9em">Sao có thể tỉnh nhanh như vậy được?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cầm điện thoại lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Chữ trước mắt nàng mờ nhòe.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hơi hoa mắt, dụi mắt một lúc mới tìm thấy ảnh đại diện của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bấm vào rồi gõ thẳng:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi xin lỗi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Ba chữ không đầu không đuôi này khiến Lâm Nhược Đường nhìn chằm chằm điện thoại suốt năm phút.</p><p style="text-align: justify; margin-bottom: 0.9em">Những đường gợn sóng trên màn hình máy tính lúc cao lúc thấp, trông giống như điện tâm đồ.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngón tay cô khẽ gõ lên bàn phím.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn tin nhắn Thời Vụ gửi đến hồi lâu, cô mới trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cô là Lâm Nhược Đường phải không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Gần như trả lời ngay lập tức.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đang ôm điện thoại chờ sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng phải Lâm Châu nói nàng uống say rồi à?</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là đã say.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu không say, sao nàng dám chất vấn cô như vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Là tôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Vậy thì đúng rồi. Xin lỗi nhé.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Xin lỗi chuyện gì?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi không nên mắng cô là "nhóc mập".】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn chằm chằm điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">Vài giây sau, cô bật cười vì tức.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi xin lỗi xong, Thời Vụ ném điện thoại sang một bên rồi nằm xuống giường.</p><p style="text-align: justify; margin-bottom: 0.9em">Chiếc đèn treo trên trần nhà tỏa ra vô số đốm sáng tựa sao trời.</p><p style="text-align: justify; margin-bottom: 0.9em">Bất giác, nàng nhớ lại ngày kết hôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi ấy, Triệu Hy Ngọc đứng dưới ánh đèn, nói với nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Vụ, cảm ơn em đã đồng ý kết hôn với chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhắm mắt lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe mắt nóng ran.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt tắm xong bước vào phòng, nhìn thấy Thời Vụ chống tay lên trán, đuôi mắt long lanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô rón rén bước ra khỏi phòng, đóng cửa lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa mới nằm xuống sofa, chuẩn bị chắp vá qua đêm thì tiếng gõ cửa vang lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bật dậy, còn tưởng mình nghe nhầm.</p><p style="text-align: justify; margin-bottom: 0.9em">Mãi đến khi tiếng gõ cửa lại vang lên lần nữa, Dư Mạt mới lấy áo khoác trên sofa mặc vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bước đến cửa rồi nghe thấy giọng nói quen thuộc:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Dư Mạt, cô có nhà không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây sao cô lại cảm thấy giọng của Triệu Hy Ngọc dễ nghe nhỉ?</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt trợn trắng mắt, mở cửa ra, nhìn vẻ mặt sốt ruột của Triệu Hy Ngọc:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Vụ đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hỏi làm gì? Chị tìm cậu ấy làm gì? Để cậu ấy trở về tiếp tục làm công cụ cho nhà chị sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi không có ý đó. Dư Mạt, cô để tôi nói chuyện với em ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nghiêng người chắn trước mặt cô, ngăn động tác muốn bước vào nhà của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa vốn đã không lớn.</p><p style="text-align: justify; margin-bottom: 0.9em">Một mình Dư Mạt đã chiếm hơn nửa lối vào, Triệu Hy Ngọc hoàn toàn không thể đi vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi mặc kệ chị nghĩ thế nào. Dù sao hôm nay đừng hòng gặp Thời Vụ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi..."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt ngắt lời:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hơn nữa, cậu ấy vốn không muốn gặp chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc sững lại:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Em ấy không muốn gặp tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt tức đến bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có phải chị thấy nhà Thời Vụ không còn ai nên có thể bắt nạt cậu ấy mà không cần kiêng dè không?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thừa lúc cậu ấy không biết nổi giận sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chuyện như thế mà chị cũng làm ra được, sao còn hỏi cậu ấy có muốn gặp chị hay không?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Triệu Hy Ngọc, nếu da mặt tôi dày được như chị, tôi sẽ hiến mặt mình cho đất nước. Biết đâu còn có thể nghiên cứu ra một loại áo chống đạn mới."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc không phải không nghe ra lời châm chọc gay gắt của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô cũng biết Thời Vụ và Dư Mạt đang tức giận.</p><p style="text-align: justify; margin-bottom: 0.9em">Bị mắng thế nào cũng đáng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cô chỉ muốn nhìn Thời Vụ một lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô cứ để tôi gặp em ấy một lần thôi. Tôi sẽ không làm gì cả. Gặp em ấy xong, tôi lập tức về."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt giơ tay đẩy cô ra ngoài, nói rõ từng chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị! Nằm! Mơ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc lùi về sau hai bước.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa ra khỏi cửa, cô còn chưa kịp đưa tay ra, Dư Mạt đã đóng sầm cửa lại.</p><p style="text-align: justify; margin-bottom: 0.9em">...</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các thiên thần nhỏ đã tặng 12 phiếu Bá Vương và 305 chai dung dịch dinh dưỡng~</p><p style="text-align: justify; margin-bottom: 0.9em">Ngẫu nhiên phát 100 bao lì xì 🥳🥳</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ghi thêm một khoản. Lại gọi tôi là ''nhóc mập''. Lần sau phải cởi quần áo cho cô ấy xem rốt cuộc có mập hay không."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "... Không cần đâu...</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 22, 'Dễ nói (bản chỉnh sửa)', '<p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghe thấy bên ngoài có động tĩnh, nàng để chân trần bước ra khỏi phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nghe thấy tiếng mở cửa liền ngồi dậy khỏi sofa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Thời Vụ đi ra, cô lo lắng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không ngủ được à?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vừa rồi Triệu Hy Ngọc đến sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao thế? Cậu mềm lòng rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao không lên giường ngủ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi nằm đây cũng khá ổn. Ở bệnh viện tôi cũng thường xuyên ngủ trên sofa, chẳng có gì khó chịu cả."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Về giường ngủ đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt khẽ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu chắc chứ? Tôi không dám bảo đảm mình sẽ không làm ra chuyện gì đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô giả vờ đưa tay về phía Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ mỉm cười, biết Dư Mạt chỉ đang chọc cho nàng vui.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đứng dậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn thấy Thời Vụ không mang dép, cô kêu lên:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sức khỏe cậu không tốt mà còn không mang dép. Lát nữa chân lạnh cóng mất."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Thời Vụ mới quay về phòng mang dép, sau đó vào phòng tắm, thoải mái tắm nước nóng.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi trở lại phòng, nàng cùng Dư Mạt chen vào ổ chăn ấm áp.</p><p style="text-align: justify; margin-bottom: 0.9em">Màn hình điện thoại của nàng vẫn liên tục nhấp nháy.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt tựa vào đầu giường, hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có cần nghe điện thoại không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tắt điện thoại, nằm xuống bên cạnh Dư Mạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vươn tay ôm lấy nàng, cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu không biết hồi đi học có bao nhiêu người ngưỡng mộ tôi đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nằm nghiêng.</p><p style="text-align: justify; margin-bottom: 0.9em">Trên người Dư Mạt vẫn còn thoang thoảng mùi nước sát khuẩn. Mùi hương nhàn nhạt ấy khiến người ta cảm thấy rất an tâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Tâm trí nàng rối bời, thuận miệng phụ họa:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngưỡng mộ cậu điều gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hơi kéo giãn khoảng cách:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Còn giả vờ nữa. Có phải cậu muốn tôi nói họ ngưỡng mộ tôi vì có một cô bạn gái xinh đẹp như cậu không?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi không nói đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Đôi mắt cong thành hình trăng lưỡi liềm, vẻ mặt dịu dàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn gương mặt tươi cười của nàng, chợt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi hơi hối hận rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hửm?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lúc đầu tôi không nên tác hợp cậu với Triệu Hy Ngọc. Chúng ta đáng lẽ nên chờ thêm, biết đâu sẽ có người tốt hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi không trách cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Là vì khi ấy cậu cũng thích chị ấy, đúng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừm, tôi thích chị ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không hối hận sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tại cậu tốt bụng quá nên ai cũng muốn bắt nạt cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, cô véo má Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Má nàng mềm mại, làn da mịn màng, khiến lòng háo sắc của Dư Mạt chợt nổi lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Thật muốn hôn một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "..."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng gạt tay Dư Mạt ra:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngày mai không đi làm à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngày mai tôi được nghỉ. Hay là cậu cũng xin nghỉ đi, tôi đi dạo phố với cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngày mai không được. Ngày mai có buổi diễn tập, tôi phải trông chừng."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt thở dài:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được rồi, được rồi. Tôi chỉ tò mò một chuyện."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chuyện gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nếu cậu ly hôn với Triệu Hy Ngọc, cậu có nghỉ việc không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không trả lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Một lúc lâu sau, Dư Mạt đã ngủ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ trở mình trên giường.</p><p style="text-align: justify; margin-bottom: 0.9em">Căn nhà lúc nửa đêm vẫn hơi lạnh lẽo.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đắp chăn mỏng cho Dư Mạt rồi bước ra khỏi phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt và nàng đều là người Hà Kiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người không có nhà ở đây.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi còn học đại học, họ học khác trường nhưng khoảng cách không xa.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi ấy, Dư Mạt từng đề nghị thuê nhà bên ngoài rồi ở ghép với nàng, nhưng Thời Vụ không đồng ý.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cảm thấy không cần thiết, như vậy quá lãng phí.</p><p style="text-align: justify; margin-bottom: 0.9em">Hơn nữa, đi đi về về cũng rất mệt.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng biết Dư Mạt đưa ra đề nghị ấy vì lo nàng không thể chấp nhận được việc Thời Ánh Xuân qua đời.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng sau khi tốt nghiệp đại học, hai người vẫn từng thuê chung nhà một thời gian.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bôn ba khắp nơi tìm việc, còn Dư Mạt vẫn đang đi học, nên cả hai thuê nhà gần khu đại học.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, khi công việc của Thời Vụ ổn định, họ lại chuyển đến thuê gần công ty nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Về sau Dư Mạt vào bệnh viện làm việc, quãng đường trở nên xa hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ở luôn trong bệnh viện, còn Thời Vụ một mình thuê căn nhà ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Không lâu sau, căn nhà cũ bị dột nước.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng muốn sửa sang lại toàn bộ căn nhà, nhưng Dư Mạt khuyên rằng nàng sẽ không quay về ở, thậm chí sau này có lẽ cũng chẳng trở về nữa, chi bằng chỉ sửa chữa đơn giản thôi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nàng không đồng ý.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhất quyết sửa sang căn nhà thật đẹp, dốc hết số tiền tích cóp được từ khi đi làm vào đó, còn đóng gói tất cả những món đồ có thể mang đi trong căn nhà cũ rồi gửi đến căn nhà thuê của mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước khi kết hôn, nhìn căn nhà thuê gần như không khác gì nhà cũ, nàng do dự không biết nên gửi đồ về nhà cũ hay chuyển sang nhà mới.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thế nào cũng được, chị nghe theo em."</p><p style="text-align: justify; margin-bottom: 0.9em">Cuối cùng, Thời Vụ vẫn gửi toàn bộ đồ đạc về nhà cũ.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi trở về thu dọn từng món một, Triệu Hy Ngọc ở bên cạnh nàng, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sau này mỗi tháng chúng ta về đây một chuyến nhé. Nhà phải thường xuyên có người ở mới có hơi người."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ thì rất tốt đẹp, nhưng vì công việc bận rộn nên kế hoạch ấy cứ bị trì hoãn.</p><p style="text-align: justify; margin-bottom: 0.9em">Kết hôn hơn nửa năm, họ chỉ về đó hai lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Một lần vào ngày giỗ Thường Anh.</p><p style="text-align: justify; margin-bottom: 0.9em">Một lần vào ngày giỗ Thời Ánh Xuân.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bỗng hơi muốn trở về.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cuộn mình trên sofa, nhìn bóng những chậu hoa ngoài ban công lay động trong bóng tối.</p><p style="text-align: justify; margin-bottom: 0.9em">Tầm mắt cũng dần trở nên mơ hồ.</p><p style="text-align: justify; margin-bottom: 0.9em">Sáng hôm sau, Dư Mạt tỉnh dậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nằm trên giường một lúc lâu mới mò thấy điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">Sáu giờ rưỡi.</p><p style="text-align: justify; margin-bottom: 0.9em">Đêm qua cô ngủ không yên.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc thì mơ thấy Thời Vụ nói rằng đã tha thứ cho Triệu Hy Ngọc, muốn tiếp tục sống hạnh phúc với chị ấy, còn trách cô làm cản trở những phút giây ngọt ngào của hai người.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc lại mơ thấy Thời Vụ và Triệu Hy Ngọc ly hôn, một mình trở về Hà Kiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi cô đi tiễn Thời Vụ, cả hai đều nước mắt giàn giụa.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô lao ra ngoài cửa, gọi lớn:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thời Vụ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Không có ai đáp lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt xỏ dép cũng không kịp, đầu tóc rối bù bước ra khỏi phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Phòng khách rất yên tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Phòng vệ sinh cũng rất yên tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nhìn thấy trên bàn vẫn còn một phần đồ ăn sáng, liền lấy điện thoại nhắn tin cho Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cậu đi rồi à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ừm, tôi đến công ty rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ăn sáng chưa?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ăn rồi. Tôi cũng gọi cho cậu một phần, nhớ ăn nhé.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được, hôn cậu.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không trả lời nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Nỗi lo trong lòng Dư Mạt chẳng những không vơi đi mà còn tăng thêm.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô lướt video một lúc, lại lướt Weibo một lúc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ đến chuyện mua tạp chí của Lâm Châu hôm qua, cô bỗng tò mò, tìm kiếm Weibo của Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Không tìm thì không biết.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa tìm đã giật mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Hóa ra Lâm Châu nổi tiếng đến vậy, có hơn ba mươi triệu người theo dõi.</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy biết số liệu trên Weibo có thể bị thổi phồng, nhưng mỗi bài đăng của cô đều có hai, ba trăm nghìn bình luận và hàng triệu lượt thích.</p><p style="text-align: justify; margin-bottom: 0.9em">Nổi tiếng quá rồi thì phải?</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt bỗng cảm thấy chuyện Lâm Châu đến nhà mình hôm qua cứ như một giấc mơ.</p><p style="text-align: justify; margin-bottom: 0.9em">Có phải hôm qua cô nên xin Lâm Châu chữ ký?</p><p style="text-align: justify; margin-bottom: 0.9em">Hoặc chụp chung một tấm ảnh?</p><p style="text-align: justify; margin-bottom: 0.9em">Lỗ rồi, lỗ nặng rồi!</p><p style="text-align: justify; margin-bottom: 0.9em">Gặp được ngôi sao lớn mà chẳng làm gì cả!</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vừa bấm thích xong thì một bài đăng Weibo mới bỗng xuất hiện.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô còn chưa kịp nhìn đó là gì, đầu óc nóng lên đã lập tức bình luận một biểu tượng cảm xúc.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó cô sững người.</p><p style="text-align: justify; margin-bottom: 0.9em">Hình như cô đã giành được bình luận đầu tiên.</p><p style="text-align: justify; margin-bottom: 0.9em">Trời ơi, cô lại giành được bình luận đầu tiên trên Weibo của Lâm Châu sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Mặc dù Dư Mạt không hiểu giới giải trí, nhưng cô cũng biết những người nằm ở hàng đầu phần bình luận về cơ bản đều là người hâm mộ.</p><p style="text-align: justify; margin-bottom: 0.9em">Tên tài khoản cùng ảnh đại diện của cô quả thực trông rất chói mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc cô đang nghĩ xem có nên xóa đi không thì một người hâm mộ đã bình luận với cô:</p><p style="text-align: justify; margin-bottom: 0.9em">【Oa! Bình luận đầu tiên kìa! Chị ơi, cho tôi ké một chỗ với.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được, cho cô ké một chỗ.】</p><p style="text-align: justify; margin-bottom: 0.9em">Tâm trạng thấp thỏm của Dư Mạt lập tức dịu xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáng yêu.</p><p style="text-align: justify; margin-bottom: 0.9em">Người hâm mộ của cô cũng đáng yêu như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Lát nữa cô sẽ mua ba mươi cuốn tạp chí, tặng cho mỗi đồng nghiệp trong khoa một cuốn!</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vui vẻ quyết định xong, vừa chuẩn bị thoát khỏi Weibo thì thấy một tin nhắn WeChat hiện lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Đó là ảnh chụp màn hình Thời Vụ gửi cho cô:</p><p style="text-align: justify; margin-bottom: 0.9em">【Là cậu sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Trong ảnh là bình luận của cô dưới bài đăng Weibo của Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi vừa khéo bấm vào thì thấy cô ấy đăng Weibo, thế là bình luận luôn.】</p><p style="text-align: justify; margin-bottom: 0.9em">Cô giải thích một tràng dài như vậy để làm gì chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Cứ như kẻ thứ ba bị vợ người ta bắt tại trận vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ừm.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn chữ này:</p><p style="text-align: justify; margin-bottom: 0.9em">【Sao thế?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không có gì, tôi vừa khéo nhìn thấy thôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Dư Mạt mới xem kỹ bài Weibo của Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Đó là bài chia sẻ lại từ Ưu Lạc.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt biết hai bên có hợp tác nhưng không biết có phải để chúc mừng sinh nhật Lâm Châu hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cậu mua quà cho cô ấy chưa?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Quà?】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ngày mai chẳng phải sinh nhật cô ấy sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【...】</p><p style="text-align: justify; margin-bottom: 0.9em">Trước khi Dư Mạt nhắc đến, Thời Vụ thật sự chưa từng nghĩ tới chuyện mua quà.</p><p style="text-align: justify; margin-bottom: 0.9em">Bởi nàng luôn cảm thấy mình và Lâm Châu chỉ có quan hệ hợp tác.</p><p style="text-align: justify; margin-bottom: 0.9em">Hơn nữa, hôm ấy công ty cũng đã chuẩn bị rất nhiều quà sinh nhật.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nghe Dư Mạt nói vậy, nàng lại cảm thấy hình như mình nên chuẩn bị riêng cho Lâm Châu một món quà.</p><p style="text-align: justify; margin-bottom: 0.9em">Một món quà thể hiện tấm lòng của nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao trong khoảng thời gian này, Lâm Châu cũng đã giúp đỡ nàng rất nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi biết rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cảm ơn.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Khách sáo thế.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đúng rồi, Triệu Hy Ngọc đã tìm cậu chưa?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Buổi sáng chị ấy không ở công ty.】</p><p style="text-align: justify; margin-bottom: 0.9em">Sáng nay Triệu Hy Ngọc không đến công ty.</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi ký kết với nhãn hàng đã được thống nhất từ trước. Sáng sớm, cô đã cùng bộ phận pháp vụ đi ký hợp đồng.</p><p style="text-align: justify; margin-bottom: 0.9em">Vốn dĩ còn có một bữa tiệc, nhưng cô thật sự không nuốt nổi.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi khéo léo từ chối phía nhãn hàng, cô trực tiếp bảo Trịnh Ý lái xe trở về công ty.</p><p style="text-align: justify; margin-bottom: 0.9em">Trên đường đi, cô hỏi Trịnh Ý:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hôm nay Giám đốc Thời có đi làm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Giám đốc Thời đã đến trung tâm thương mại mới rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi sáng, khi Trịnh Ý đến đón Triệu Hy Ngọc, trong nhà chỉ có một mình sếp.</p><p style="text-align: justify; margin-bottom: 0.9em">Ban đầu cô còn tưởng vì lịch trình hôm nay không thuận tiện.</p><p style="text-align: justify; margin-bottom: 0.9em">Về sau mới biết tối qua Thời Vụ không ở nhà.</p><p style="text-align: justify; margin-bottom: 0.9em">Xem ra lần cãi nhau này khá nghiêm trọng.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đến thẳng trung tâm thương mại mới."</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý quay đầu xe:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vâng, Triệu tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi trưa, Thời Vụ đưa thẻ cho Tống Kim, bảo cô dẫn các đồng nghiệp trong bộ phận liên hợp đi ăn một bữa ngon.</p><p style="text-align: justify; margin-bottom: 0.9em">Còn nàng ở lại thu dọn những tấm áp phích còn thừa trong văn phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Phía sau truyền đến tiếng mở cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhanh vậy..."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng sững người.</p><p style="text-align: justify; margin-bottom: 0.9em">Là Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Trạng thái của Triệu Hy Ngọc không được tốt lắm.</p><p style="text-align: justify; margin-bottom: 0.9em">Không biết có phải cả đêm không ngủ hay không, dưới mắt chị có quầng thâm nhàn nhạt, vẻ mặt vô cùng mệt mỏi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Thời Vụ nhìn sang, Triệu Hy Ngọc mím môi, cố nở một nụ cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhanh chóng cụp mắt xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc bước lên hai, ba bước:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn chị đang xoa cánh tay mình, không lên tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngoài cửa, Trịnh Ý nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Triệu tổng, vậy em đi ăn trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước khi rời đi, Trịnh Ý còn chu đáo khép cửa lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Em ăn cơm chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vẫn chưa."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cùng đi ăn chút gì nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Em không muốn ăn lắm. Sao chị lại đến đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trịnh Ý nói em không ở công ty nên chị qua đây xem thử. Em chuẩn bị đến đâu rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Buổi chiều còn một buổi diễn tập, không có việc gì khác."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tại sao không nghe điện thoại của chị?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngước mắt nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt tĩnh lặng.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau một đêm suy nghĩ kỹ càng, giờ đây khi đối diện với Triệu Hy Ngọc, nàng không còn cảm giác phẫn nộ như hôm qua nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ còn lại sự bất lực không thể diễn tả thành lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị gọi điện cho em làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc hạ giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Em định không quan tâm đến chị nữa sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Là cười giễu cợt sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Hay cười nhạo?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cũng không biết lúc này mình đang mang biểu cảm gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Hoặc có lẽ chuyện ấy quá buồn cười, khiến nàng không thể nhịn được:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Triệu Hy Ngọc, chị muốn em quan tâm đến chị thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thông cảm cho việc chị và Triệu Tinh sắp có một đứa con sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hay thông cảm cho đứa con của hai người chiếm mất cơ hội được ra đời của con chúng ta?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chúng ta vẫn sẽ có con."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhíu mày:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị nói gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ý chị là chúng ta vẫn có thể có thêm một đứa con. Đứa bé sẽ..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn chằm chằm Triệu Hy Ngọc:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Em chỉ muốn có một đứa con."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị biết. Chị và em sẽ có con, một đứa con thuộc về chúng ta."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy còn đứa con của chị và Triệu Tinh thì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đứa bé..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đứa bé chỉ là công cụ để chị củng cố địa vị thôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị không nghĩ như vậy. Nếu em thật sự không thích, chị có thể để cha mẹ chăm sóc đứa bé. Họ đã nghỉ hưu rồi, chăm sóc một đứa trẻ không thành vấn đề."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chỉ khi có đứa trẻ này, chúng ta mới có thể hoàn toàn nắm quyền kiểm soát Ưu Lạc."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô như thể đây là lần đầu tiên hai người quen biết.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vừa lắc đầu vừa không dám tin:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Triệu Hy Ngọc, chị thật vô liêm sỉ."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vốn tưởng sau một đêm, dù Triệu Hy Ngọc không thay đổi ý định thì ít nhất cũng sẽ nghiêm túc suy nghĩ xem chuyện mình làm rốt cuộc có đúng hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nàng không ngờ Triệu Hy Ngọc chẳng hề tự kiểm điểm, thậm chí còn trơ trẽn muốn có thêm một đứa con với nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Vụ, tất cả những gì chị làm đều là vì tương lai của chúng ta."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đừng nói ''chúng ta''. Đừng kéo em vào."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Triệu Hy Ngọc, chị điên rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhíu mày.</p><p style="text-align: justify; margin-bottom: 0.9em">Cả đêm qua không được nghỉ ngơi khiến thể xác lẫn tinh thần cô đều mệt mỏi.</p><p style="text-align: justify; margin-bottom: 0.9em">Hôm nay cô cứ tưởng mình có thể nói chuyện đàng hoàng với Thời Vụ, không ngờ nàng vẫn luôn trách móc cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Tất cả những gì cô làm đều vì tương lai của mình và Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Tại sao Thời Vụ lại không thể thấu hiểu?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đẩy cô ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Vụ, rốt cuộc phải thế nào em mới có thể chấp nhận?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Em không thể nào chấp nhận được."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy nếu đó là con của em và Tinh Tinh thì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghi ngờ tai mình có vấn đề:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị nói gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nếu em sợ chị sẽ vì đứa trẻ này mà dính líu đến Tinh Tinh, vậy chị..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không thể nhịn nổi nữa, thẳng tay tát vào má phải Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng dùng sức rất mạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Lòng bàn tay tê rần, còn hơi đau.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong văn phòng vang lên một tiếng "chát" giòn tan.</p><p style="text-align: justify; margin-bottom: 0.9em">Tát xong, Thời Vụ nhìn chằm chằm bàn tay mình rồi lùi về sau hai bước.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc sững sờ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Vụ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Triệu Hy Ngọc, em không biết sao chị có thể vô liêm sỉ đến mức này."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đó là gì? Là một món đồ chơi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đó là một đứa trẻ đấy! Là một sinh mạng!"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị sinh đứa bé ra thì phải chịu trách nhiệm với nó cả đời!"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao chị có thể nói ra..."</p><p style="text-align: justify; margin-bottom: 0.9em">Sao chị có thể nói ra lời bảo nàng sinh một đứa con với Triệu Tinh?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thật sự muốn bổ đầu Triệu Hy Ngọc ra xem thử rốt cuộc bên trong chứa thứ gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc cũng sa sầm mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị biết đó là một đứa trẻ. Chị không hề có lỗi với đứa bé."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị có thể cho nó điều kiện sống đầy đủ, cho nó tất cả những gì nó muốn!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị không cho được đâu, Triệu Hy Ngọc. Chị không thể cho được."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trong đầu chị chỉ có Ưu Lạc, chỉ có bản thân chị!"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không phải đâu, Tiểu Vụ. Chị vẫn còn em, chị..."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô định tiến lại gần Thời Vụ nhưng bị nàng dùng một tay đẩy ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Lưng Triệu Hy Ngọc va vào bàn làm việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô chống tay ra sau.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị có biết tối qua Dư Mạt đã nói gì với em không?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô ấy hỏi em liệu em có ly hôn với chị không. Em nói không biết."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lúc đó em còn nghĩ có lẽ chị chỉ nhất thời chưa suy nghĩ thấu đáo, rồi chị sẽ nhận ra mình sai."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhưng người sai lại là em."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Triệu Hy Ngọc, người như chị căn bản không xứng kết hôn, cũng không xứng có con!"</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, Thời Vụ không nhìn Triệu Hy Ngọc lấy một lần, xoay người rời khỏi văn phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Phía sau, Triệu Hy Ngọc gọi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Vụ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Đáp lại cô chỉ có luồng gió lạnh ùa vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không còn nơi nào để đi, đành ngồi xuống chiếc ghế dài ở tầng một trung tâm thương mại.</p><p style="text-align: justify; margin-bottom: 0.9em">Rất nhiều cô gái đến check-in, vui vẻ cầm điện thoại chụp ảnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Hốc mắt Thời Vụ cay xè.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngồi được một lúc thì Tống Kim cũng ăn xong trở về.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nhìn thấy nàng, cô liền vui vẻ chào hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Giám đốc Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cong môi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ăn xong rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vâng, bọn em ăn buffet. Chị ăn chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ăn rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim trả lại thẻ cho nàng rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Giám đốc Thời, Triệu Tinh nói buổi chiều sẽ đến giúp."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chợt cảm thấy so với Triệu Hy Ngọc, người mình căm ghét nhất giờ đây thậm chí cũng chẳng còn là Triệu Tinh nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhếch môi cười lạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim ghé sát tai nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Em nhất định sẽ trông chừng cô ấy, không rời nửa bước! Ngay cả lúc đi vệ sinh cũng sẽ nhìn chằm chằm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được, vậy em trông chừng cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bảo đảm hoàn thành nhiệm vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Vẻ mặt Thời Vụ nhàn nhạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim lại nhìn nàng thêm một lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy bình thường Thời Vụ cũng không thể hiện cảm xúc gì nhiều, nhưng cô vẫn lờ mờ cảm thấy hôm nay nàng hơi không vui, còn có chút khó chịu.</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng lẽ Triệu tổng lại cãi nhau với chị ấy rồi?</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim không dám hỏi thêm.</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi diễn tập chiều hôm ấy, cô luôn đi theo Triệu Tinh nên cũng chẳng có thời gian để ý đến Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi trưa Thời Vụ không ăn gì, buổi chiều dạ dày cứ âm ỉ đau.</p><p style="text-align: justify; margin-bottom: 0.9em">Hơn bốn giờ, nàng nhét hai miếng bánh mì vào bụng mới dễ chịu hơn một chút.</p><p style="text-align: justify; margin-bottom: 0.9em">Bảy, tám giờ tối, những tấm áp phích cỡ lớn được chuyển đến.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cùng các đồng nghiệp treo chúng lên, bận rộn mãi đến hơn mười giờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong trung tâm thương mại không còn ai, chỉ còn lại người của bộ phận liên hợp.</p><p style="text-align: justify; margin-bottom: 0.9em">Họ bàn bạc một lúc xem nên đi đâu ăn khuya rồi hỏi Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi không đói, mọi người đi đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, nàng nhìn thấy Triệu Tinh đang nhìn mình chằm chằm.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt ấy rất phức tạp.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước kia, khi Triệu Tinh nhìn nàng, trong mắt luôn là sự thù địch không hề che giấu.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng giờ đây lại biến thành một cảm xúc khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không để ý đến em ấy, chào mọi người rồi trở về nhà.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc vẫn chưa về.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng không quan tâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đi thẳng vào phòng, thu dọn quần áo của mình rồi kéo một chiếc vali lớn ra khỏi cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Trên đường đi, Triệu Hy Ngọc liên tục gọi điện và nhắn tin cho nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đoán có lẽ khi về đến nhà, chị phát hiện đồ đạc của nàng đều không còn nên mới gọi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Thời Vụ không nghe máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này nàng không muốn nghe giọng của Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Lái xe hơn nửa tiếng đến dưới tòa nhà của Dư Mạt, Thời Vụ gọi điện cho cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bệnh viện có chút việc gấp, tôi đã đến đây rồi. Cậu qua bệnh viện lấy chìa khóa nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mấy giờ cậu về?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi còn phải ở đây một lúc nữa. Cậu đến lấy chìa khóa đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không còn cách nào khác, đành lái xe đến bệnh viện.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi gặp Dư Mạt, nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mấy hôm nay tôi sẽ tìm nhà."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt không hỏi nàng chuyện gì khác, chỉ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Gấp gì chứ? Chỗ tôi đâu phải không ở được. Cứ ở trước đã, chuyện tìm nhà không cần vội."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe thấy ngoài hành lang có người gọi Dư Mạt, nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu đi làm việc đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Về nhà trước đi, đừng chạy lung tung."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cong môi.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi xuống thang máy, nàng mới nhận ra đêm nay ánh trăng sáng lạ thường, lại tròn vành vạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bước về phía trước mấy bước.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước khu nội trú có một bồn hoa hình tròn khá lớn. Xung quanh là một vòng ghế gỗ được sơn đỏ, chạm vào lạnh buốt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi xuống, ngẩng đầu ngắm trăng, tận hưởng làn gió đêm nhè nhẹ.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa sổ hành lang tầng mười đang hé mở.</p><p style="text-align: justify; margin-bottom: 0.9em">Có hai người đứng ở đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi tối, Lâm Ngọc Phượng lại làm ầm lên đòi xuất viện, khuyên thế nào cũng không chịu nghe.</p><p style="text-align: justify; margin-bottom: 0.9em">Bữa tiệc của Lâm Nhược Đường còn chưa kết thúc, cô đã vội chạy đến.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô sa sầm mặt nói với Lâm Ngọc Phượng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được thôi, bà không nghe lời thì con cũng không cần nghe lời bà nữa. Sau này con không đi xem mắt nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng lập tức không làm ầm nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đứng bên cạnh, cố nhịn cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Quả nhiên chỉ có Lâm Nhược Đường mới trị được bà.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi dỗ Lâm Ngọc Phượng ngủ, Trần Hy rón rén theo Lâm Nhược Đường ra khỏi phòng bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi đi ngang qua cửa sổ hành lang, cô nhìn xuống dưới rồi lại nhìn thêm lần nữa, khẽ kêu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ồ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngước mắt nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Người kia hình như là Giám đốc Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô chỉ ra ngoài cửa sổ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn theo.</p><p style="text-align: justify; margin-bottom: 0.9em">Quanh bồn hoa hình tròn có đèn chiếu sáng nên khá sáng sủa, có thể nhìn rõ người đang ngồi trên ghế quả thật là Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi được vài phút, đang thoải mái đến mức sắp ngủ thì chợt nghe thấy một tiếng gọi lạnh nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Giám đốc Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng quay đầu, nhìn thấy Trần Hy và... Lâm Nhược Đường đang bước ra từ khu nội trú.</p><p style="text-align: justify; margin-bottom: 0.9em">Như một phản xạ có điều kiện, Thời Vụ lập tức đứng dậy, vô thức chỉnh lại tóc và quần áo.</p><p style="text-align: justify; margin-bottom: 0.9em">Đợi đến khi Trần Hy đi tới bên cạnh, Thời Vụ chào:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thư ký Trần, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi còn tưởng mình nhìn nhầm. Sao cô lại đến bệnh viện?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi đến lấy đồ. Sao hai người lại ở đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chủ tịch Lâm đang ở trên lầu."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Thời Vụ mới phản ứng lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng đang nằm viện trên lầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng sao đi đâu nàng cũng gặp Lâm Nhược Đường vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bĩu môi.</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe mắt lướt qua Lâm Nhược Đường, thấy cô cụp mắt, ánh nhìn chăm chú dừng trên người mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức dựng cả tóc gáy.</p><p style="text-align: justify; margin-bottom: 0.9em">Tối qua hình như nàng đã gọi điện mắng Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó còn nhắn tin cho cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Sáng nay, nàng đã xem lại đoạn trò chuyện giữa mình và Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đã xin lỗi tử tế như vậy, thế mà Lâm Nhược Đường cứ khăng khăng nhắc đến hai chữ "nhóc mập", hại nàng cả ngày hôm nay không muốn nhìn điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">Thật cay mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lần sau nhất định không thể uống say nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ muốn xin lỗi, nhưng có Trần Hy ở đây nên nàng lại không thể mở lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay đầu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô về trước đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy gật đầu như được đại xá:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vâng, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đồng thời chào Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Giám đốc Thời, vậy tôi đi trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi đường cẩn thận."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Trần Hy rời đi, Lâm Nhược Đường hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngồi đây làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sau chuyện tối qua, Thời Vụ đã chẳng còn chút hình tượng nào trước mặt Lâm Nhược Đường nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng dứt khoát buông xuôi, thở dài:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hấp thụ linh khí của trời đất."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường dường như khẽ cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Vẻ vui thích thoáng qua nơi đáy mắt rồi lập tức trở lại bình thường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Muốn thành tiên sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đang cố gắng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có cần tôi cổ vũ cô không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "..."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bỗng trở nên ngoan ngoãn:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không cần cổ vũ tôi, nhưng tôi hy vọng Lâm tổng có thể đồng ý với tôi một chuyện."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nói đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mím môi, khó khăn mở lời:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chuyện tối qua, có thể xin Lâm tổng đừng coi là thật không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường im lặng hai giây:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đang nói chuyện gọi điện mắng tôi, hay chuyện sau đó nhắn tin xin lỗi rồi gọi tôi là ''nhóc mập''?"</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi Thời Vụ giật giật.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cứng đầu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cả hai. Cả hai chuyện đều đừng coi là thật."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường vui vẻ đồng ý:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Dễ thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lần đầu tiên Thời Vụ cảm thấy hai chữ này nghe thật êm tai.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy Giám đốc Thời định bồi thường cho tôi thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bồi thường?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hoàn toàn chưa từng nghĩ tới.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cách thiết thực và tiết kiệm nhất vẫn là:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi mời cô ăn cơm."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhất thời chưa phản ứng kịp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng bằng ánh mắt trong veo, hỏi ngược lại:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không phải cô nói sẽ mời tôi ăn cơm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "..."</p><p style="text-align: justify; margin-bottom: 0.9em">Bây giờ luôn sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Khả năng hành động này có phải hơi mạnh quá rồi không?</p><p style="text-align: justify; margin-bottom: 0.9em">...</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các thiên thần nhỏ đã tặng 12 phiếu Bá Vương và 219 chai dung dịch dinh dưỡng~</p><p style="text-align: justify; margin-bottom: 0.9em">Phát ngẫu nhiên một trăm bao lì xì nhé.</p><p style="text-align: justify; margin-bottom: 0.9em">Chương sau sẽ bắt đầu bàn chuyện ly hôn. Tiểu Vụ nhà chúng ta sắp trở lại độc thân rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm tổng, cố lên 🤗🤗🤗</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 23, 'Ly hôn', '<p style="text-align: justify; margin-bottom: 0.9em">Có lẽ vì những chuyện gần đây liên quan đến Triệu Hy Ngọc khiến Thời Vụ mệt mỏi cả thể xác lẫn tinh thần, hoặc cũng có thể vì nhớ lại chút "tình xưa" giữa mình và Lâm Nhược Đường, nên cuối cùng nàng không còn giữ vẻ xa cách như ban đầu nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi ra khỏi bệnh viện, nàng nhìn thấy hai quán ăn nằm hai bên đường. Đêm khuya, cả hai đều bán cơm rang và món cay xào thập cẩm. Nàng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Lâm tổng, cô ăn cơm rang không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chỉ thuận miệng hỏi, Lâm Nhược Đường không nhận ra, đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi không ăn hàng quán ven đường."</p><p style="text-align: justify; margin-bottom: 0.9em">Làm màu gì chứ? Trước đây, mỗi khi theo dõi nàng ở nhà, chẳng phải cô vẫn ăn rất ngon sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Trong lòng Thời Vụ thầm châm chọc, ngoài miệng lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy Lâm tổng có món gì muốn ăn không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Gì cũng được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ghét nhất chính là hai chữ "gì cũng được". Nói gì cũng được, thực chất chính là món nào cũng không được, chứng tỏ cô vốn chẳng muốn tử tế ăn cơm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy ăn sủi cảo nước đi. Tôi biết một quán có nhân được nêm nếm rất ngon, Lâm tổng muốn thử không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Không ngờ cô lại đồng ý. Thời Vụ còn tưởng với tiêu chuẩn của cô, ít nhất cũng phải là nhà hàng bốn, năm sao. Sao hôm nay lại dễ nói chuyện đến vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lén liếc Lâm Nhược Đường, vừa hay chạm phải ánh mắt cô nhìn sang. Nàng vô thức đứng thẳng người, siết chặt sống lưng. Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Quán nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Quán ở đầu phố kia."</p><p style="text-align: justify; margin-bottom: 0.9em">Bây giờ đã gần mười hai giờ đêm. Ngoài quán đồ nướng ở đầu phố còn khá đông đúc, những quán khác gần như chẳng có khách.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ dẫn Lâm Nhược Đường vào quán sủi cảo nước ở đầu phố. Chủ quán là một người phụ nữ hơn ba mươi tuổi, đang nhào bột. Nghe tiếng động, chị ngẩng đầu lên, nhìn thấy Thời Vụ liền cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sao giờ này em lại tới?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Em tiện đường ghé qua lấy đồ giúp Dư Mạt."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, nàng nhìn Lâm Nhược Đường từ trên xuống dưới một lượt rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô ăn nhân gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi lại:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô ăn nhân gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi ăn nhân rau cần."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không biết nghĩ đến điều gì, hai giây sau mới nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi cũng vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói với bà chủ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hai bát sủi cảo nước, nhân rau cần."</p><p style="text-align: justify; margin-bottom: 0.9em">Bà chủ đáp một tiếng rồi đi chuẩn bị. Thấy Thời Vụ quen đường quen lối, Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô thường tới đây à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Dư Mạt thường xuyên ghé. Tôi từng đi cùng cậu ấy vài lần nên quen bà chủ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu, không hỏi thêm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lấy một đôi đũa dùng một lần đưa cho Lâm Nhược Đường. Lâm Nhược Đường hiếm khi cau mày, Thời Vụ vội bóc bao đũa, tách đôi rồi đưa lại cho cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đoán chắc Lâm Nhược Đường đã quen dùng bộ đồ ăn đặt riêng, bây giờ phải cầm đũa dùng một lần nên không quen. Chính nàng cũng chẳng hiểu vì sao lại đưa Lâm Nhược Đường tới đây.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ nàng muốn lấy lòng cô, để Lâm Nhược Đường bỏ qua chuyện xảy ra tối qua.</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao bữa cơm đầu tiên của họ cũng từng là sủi cảo nước.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không nói gì, vẫn nhận lấy đôi đũa Thời Vụ đưa sang. Chẳng bao lâu sau, bà chủ bưng ra hai bát sủi cảo nước. Thời Vụ đặt một bát trước mặt Lâm Nhược Đường, cung kính nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Lâm tổng, cô nếm thử đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này mới nhớ người ta là Lâm tổng sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bật cười vì tức.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cô vẫn dùng đũa khuấy nước dùng, gắp một chiếc lên, cắn một miếng rồi chậm rãi nhai.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cách cô ăn sủi cảo mà cứ có cảm giác như đang xem một màn trình diễn tao nhã của giới thượng lưu. Khóe môi nàng khẽ giật, bà chủ thì hoàn toàn ngẩn người.</p><p style="text-align: justify; margin-bottom: 0.9em">Bắt đầu từ người ngồi cạnh Thời Vụ, ánh mắt của bà chủ cứ vô thức trôi về phía Lâm Nhược Đường. Chỉ cần nhìn qua cũng biết cô khí chất bất phàm. Tuy quần áo không nhận ra là nhãn hiệu gì, nhưng lại vừa vặn, chỉnh tề. Từ mái tóc đến lớp trang điểm đều toát lên vẻ tinh tế không thể tả, giống hệt những bà chủ lớn cả ngày ngồi trong văn phòng trên TV, hoàn toàn không hợp với cả quán nhỏ này.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng xinh đẹp, nhưng vẻ đẹp của nàng lại dịu dàng. Trong vẻ đẹp của cô gái này lại ẩn giấu một chút sắc bén.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn cô chậm rãi thưởng thức sủi cảo, bà chủ cứ cảm thấy mình đang bị lãnh đạo kiểm tra, một áp lực vô hình như bàn tay bóp chặt trái tim đang đập thình thịch của chị.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường vừa ăn miếng đầu tiên, Thời Vụ đã hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Mùi vị không tệ đúng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không trả lời nàng, chỉ liếc Thời Vụ một cái, sau đó lại nhìn về phía bà chủ đang đứng sau lưng nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Bà chủ giả vờ bận rộn lau bàn, nhưng thật ra hai tai đã dựng đứng lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngon không? Sao không nói gì vậy? Không ngon sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Rốt cuộc có ngon hay không đây!</p><p style="text-align: justify; margin-bottom: 0.9em">Bà chủ sốt ruột vung khăn lau xuống bàn, "bốp" một tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu nhìn chị, bà chủ cười tít mắt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hai em có cần giấm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không thích ăn giấm, khẽ cau mày. Thời Vụ lập tức hiểu ý:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bọn em không cần."</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra thỉnh thoảng Thời Vụ cũng ăn giấm, nhưng đó không phải thứ nhất định phải có. Hôm nay nàng chẳng ăn uống gì mấy, buổi chiều chỉ nhét tạm ít bánh mì. Tuy không cảm thấy đói, nhưng cơ thể rất thành thật, mới ăn hai ba miếng đã hết hơn nửa bát.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc điện thoại rung lên, Thời Vụ vừa cúi đầu húp canh, vừa liếc nhìn sắc mặt Lâm Nhược Đường, chậm rãi thổi làn khói nóng bốc lên từ bát sủi cảo.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ vì quá ồn, cuối cùng nàng vẫn không nhịn được, lấy điện thoại ra khỏi túi.</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải Triệu Hy Ngọc gọi, mà là Dư Mạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi xong việc rồi, cậu về đến nhà chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chưa, tôi vẫn đang ở ngoài."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt "ồ" một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ở đâu vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đang ăn sủi cảo nước."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Gọi giúp tôi một bát nhé, tôi bận cả tối, sắp chết đói rồi!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cúp điện thoại rồi nói với Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bạn tôi......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi nghe thấy rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Điện thoại bị lọt âm nghiêm trọng đến vậy sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cười ngượng ngùng, quay sang nói với bà chủ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cho thêm một phần trứng xào hẹ."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ một chút, nàng lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Phần lớn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khuấy bát canh.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Dư Mạt ăn khá nhiều."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi nhớ sức ăn của cô cũng không ít."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nhớ chuyện này làm gì chứ? Hơn nữa, khi đó nàng còn đang tuổi lớn, ăn nhiều một chút thì có vấn đề gì đâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Ai giống cô chứ, một bát sủi cảo chỉ ăn hai cái, đến nước dùng cũng chẳng uống.</p><p style="text-align: justify; margin-bottom: 0.9em">Còn nói mình không kén ăn.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đang nghĩ ngợi lung tung thì từ cửa quán vang lên tiếng Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thời Vụ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng quay đầu lại. Dư Mạt lao tới như một cơn gió, nhưng đến trước mặt Lâm Nhược Đường thì đột ngột khựng lại, như đâm phải một bức tường vô hình. Dư Mạt há hốc miệng, lắp bắp chào:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Lâm... Lâm Nhược Đường?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt từng nhìn thấy cô vài lần trên TV. Khi nghe Thời Vụ nói muốn hợp tác với Lâm Nhược Đường, nàng còn cắn ống hút Coca, hỏi với vẻ khó tin:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ai cơ? Cậu nói Lâm Nhược Đường ấy à? Chính là Lâm Nhược Đường của tập đoàn Lâm Thái, người xuất hiện trên TV đó sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Có gì mà ngạc nhiên đến thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Làm ơn đi, đó là nhà họ Lâm đấy. Nhân vật lớn chỉ có thể nhìn thấy trên TV thôi! Tôi nghe nói rất nhiều bất động sản ở Cửu Xuyên đều thuộc tập đoàn Lâm Thái, chưa kể thương hiệu trang sức của họ, vàng, kim cương, ngọc khí... Chậc! Người khác chỉ cần làm tốt một lĩnh vực đã thành đại gia rồi, còn nhà họ thì đúng là đại gia trong giới đại gia!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ưu Lạc của bọn tôi cũng đâu đến nỗi nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt cười hì hì:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng là không tệ. Đã có thể hợp tác trực tuyến với nhà họ Lâm rồi, sau này cậu phát tài thì đừng quên tôi nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, khi biết Thời Vụ đã tốn bao công sức mà vẫn chưa gặp được Lâm Nhược Đường, nàng còn an ủi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bình thường thôi. Nhân vật lớn như thế trong giới thượng lưu, đâu phải loại người chúng ta muốn gặp là có thể gặp."</p><p style="text-align: justify; margin-bottom: 0.9em">Thế mà bây giờ không chỉ gặp được, còn đang ngồi đối diện nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt lập tức cảm thấy bát sủi cảo cũng không còn thơm nữa. Đôi mắt nàng nhìn chằm chằm Lâm Nhược Đường, tò mò hơn cả khi hôm qua nhìn thấy ngôi sao lớn.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngước mắt nhìn Dư Mạt. Dư Mạt khẽ hắng giọng, chen vào ngồi sát bên Thời Vụ. Thời Vụ suýt bị cậu ta đẩy rơi khỏi ghế, Lâm Nhược Đường nhìn hai người tương tác rồi lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Dư Mạt?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt giống như học sinh bị giáo viên chủ nhiệm gọi tên, theo phản xạ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Có!"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vừa định đứng dậy đã bị Thời Vụ túm lại, kéo ngồi xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt cười gượng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Xin lỗi, tôi vừa ở bệnh viện về, vẫn chưa điều chỉnh lại trạng thái."</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc bà chủ bưng một bát sủi cảo ra, Dư Mạt dùng hai tay nhận lấy:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đưa đũa cho nàng. Dư Mạt liếc nàng, rồi lại liếc Lâm Nhược Đường, sự tò mò trong lòng đã lên đến đỉnh điểm, cuối cùng vẫn không nhịn được mà hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hai người đang bàn chuyện hợp tác sao? Tôi có làm phiền không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nghe Thời Vụ nói Ưu Lạc đang bàn chuyện hợp tác với tập đoàn Lâm Thái. Hai người gặp nhau muộn thế này, chắc không thể vì chuyện riêng được chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Tối nay Thời Vụ thật sự chẳng hề nghĩ đến công việc. Chỉ vì đầu óc quá phiền loạn, nếu thật sự muốn bàn chuyện hợp tác với Lâm Nhược Đường, nàng hẳn phải đưa cô đi ăn một bữa thịnh soạn, chứ không phải đơn giản là một bát sủi cảo.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lắc đầu, nói với Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Mau ăn đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn hai người chằm chằm, vốn bụng đã réo vang, lúc này lại chẳng còn chút khẩu vị nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Điện thoại của Thời Vụ lại bắt đầu rung liên tục. Nàng đau đầu, Lâm Nhược Đường thản nhiên nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-" Giám đốc Thời không nghe điện thoại sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nghe chứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bất đắc dĩ cười với Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Lâm tổng ngồi đây một lát nhé, tôi ra ngoài nghe điện thoại."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cầm điện thoại bước ra khỏi quán.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong đêm khuya hơn mười hai giờ, gió lạnh thổi vào mặt khiến da thịt đau rát. Thời Vụ nhận cuộc gọi nhưng không nói gì, chỉ im lặng lắng nghe.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Vụ, em đi đâu rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu đá viên đá dưới chân, giọng lạnh nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Có gì thì nói đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trong quán, Lâm Nhược Đường và Dư Mạt ngồi đối diện nhau. Dư Mạt không dám ngẩng đầu, chỉ cúi xuống lặng lẽ ăn sủi cảo. Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô cũng là người Hà Kiều sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt không ngờ cô lại chủ động bắt chuyện với mình, vì căng thẳng mà có phần kích động. Cô ấy đúng là quá khiêm tốn, gần gũi rồi!</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vừa tự cười mình, vừa đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng vậy, tôi cũng là người Hà Kiều."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô chính là Dư Mạt từng đón Thời Vụ về nhà ở sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hạ thấp giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"À... cô đang nói đến lần cậu ấy cãi nhau với mẹ mình sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ừm. Khi ấy tôi ở nhờ nhà cô ấy, có lẽ khiến cô ấy gặp không ít bất tiện."</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không có, không có đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Dù không biết hiện giờ Thời Vụ và Triệu Hy Ngọc đã tiến triển đến mức nào, nhưng Dư Mạt biết Ưu Lạc muốn hợp tác với tập đoàn Lâm Thái, vì vậy cậu ta nói đỡ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Khi đó không phải vì cô đâu, mà do kết quả kỳ thi tháng của Thời Vụ không được tốt lắm. Cậu ấy tự giận mình, ngày nào cũng như ăn phải thuốc nổ vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bật cười, dường như rất vui.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy vậy, Dư Mạt cũng mạnh dạn hơn:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nhưng tôi thật sự không ngờ cô gái từng ở nhà cô ấy lại chính là cô, cứ như nằm mơ vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao hai người cũng chẳng thuộc cùng một thế giới.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi cũng không ngờ còn có cơ hội gặp lại, đúng là rất có duyên."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng vậy! Có duyên thật đấy! À, hôm qua tôi còn gặp em gái cô nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Đan?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng vậy, hôm qua là Lâm tiểu thư đưa bọn tôi về. Tôi còn quên chưa cảm ơn cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không cần khách sáo, tôi có thể nói lại với con bé giúp cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vui mừng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thật sao? Vậy thì cảm ơn cô nhiều!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nhưng tôi cũng có một việc nhỏ muốn nhờ cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt lập tức nghiêm túc:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô cứ nói."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bà nội tôi ở bệnh viện một mình, tôi không yên tâm lắm. Thỉnh thoảng có thể phiền Dư tiểu thư qua xem giúp tôi không? Có vấn đề gì thì cứ báo cho tôi bất cứ lúc nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nói, cô vừa lấy điện thoại trong túi ra, mở màn hình rồi đưa mã QR WeChat của mình cho Dư Mạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt sững người, một lúc sau mới phản ứng lại:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được, được chứ. Có vấn đề gì tôi sẽ lập tức báo cho cô!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cong mày:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy thì cảm ơn Dư tiểu thư. Sau này có việc gì cần giúp, cô cũng có thể nói với tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vẫn chưa thoát khỏi niềm vui bất ngờ như trúng số độc đắc, tim đập thình thịch, mặt đỏ bừng, liên tục gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được, được!"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô vậy mà đã kết bạn WeChat với Lâm Nhược Đường rồi!!!</p><p style="text-align: justify; margin-bottom: 0.9em">Trời ơi!</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vui đến mức không tìm được phương hướng. Lâm Nhược Đường ngồi đối diện nói gì cô cũng không nghe rõ. Sau đó Lâm Nhược Đường đứng dậy, cô nhìn thấy cô ấy bước ra ngoài, đứng cạnh Thời Vụ. Hai người không biết nói gì với nhau, Thời Vụ gật đầu, rồi Lâm Nhược Đường rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng bao lâu sau, Thời Vụ quay lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vui vẻ ra mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thời Vụ, vừa rồi tôi đã kết bạn WeChat với Lâm Nhược Đường rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngoảnh đầu nhìn Lâm Nhược Đường đã đi xa. Vừa rồi tài xế của cô đã đến trước cửa quán, Lâm Nhược Đường chào nàng một tiếng rồi rời đi. Nghe Dư Mạt nói vậy, nàng ngạc nhiên:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Kết bạn rồi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ừ. Bà nội cô ấy đang nằm viện nên cô ấy muốn tôi thỉnh thoảng qua xem giúp. Không đúng nha, Thời Vụ, nhà cô ấy có mấy vệ sĩ túc trực ngoài cửa, còn cần tôi sang đó trông nom sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nhìn thấu được Lâm Nhược Đường, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Có lẽ cô ấy cảm thấy bác sĩ đáng tin cậy hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cũng đúng. Này, tôi thấy Lâm Nhược Đường khá dễ gần đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Cơ mặt Thời Vụ khẽ giật:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Dễ gần?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng vậy. Vừa rồi cô ấy nói chuyện với tôi, thái độ cũng không quá tệ. Tôi thấy cô ấy còn khá dịu dàng, không đáng sợ như lời đồn trên mạng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghĩ kỹ lại, đúng là nàng không thấy Lâm Nhược Đường đáng sợ, nhưng hai chữ "dễ gần" thì nàng không dám đồng tình.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi ăn xong sủi cảo, hai người vẫn còn chưa thỏa mãn nên lại gói thêm một phần mang về. Trên đường đi, Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cậu có WeChat của Lâm Đan không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hôm qua cô ấy đến thăm fan kia. Cô bé fan ấy rất vui, còn quay một đoạn video muốn tôi gửi cho Lâm Đan, nhưng chắc chắn tôi không thể gửi được."</p><p style="text-align: justify; margin-bottom: 0.9em">Trong lòng Thời Vụ khẽ động:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Gửi cho tôi xem."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt lập tức gửi video cho nàng. Nội dung chẳng có gì đặc biệt, chỉ là lời tâm tình của một cô bé, cảm ơn Lâm Đan đã đến thăm mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ xem video vài phút rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi gọi điện thoại một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vốn định gọi cho Lâm Đan nhưng nhìn thời gian đã hơn mười hai giờ, để chắc chắn hơn, nàng nhắn cho cô ấy:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ngủ chưa?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chưa.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Thời Vụ mới gọi điện qua. Lâm Đan nghe thấy nàng gọi thì rất ngạc nhiên:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Có vấn đề gì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hoạt động đều đã sắp xếp xong rồi. Có một đoạn video muốn em xem thử."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-" Chị gửi cho em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ồ, được."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa mở video, cô vừa hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Muộn thế này mà chị vẫn còn làm việc sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị vừa đến bệnh viện tìm bạn, còn tình cờ gặp Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan lập tức dừng video:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị em?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dường như cô rất hứng thú.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thản nhiên đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ừ, gặp ở khu nội trú. Cô ấy đến thăm Lâm lão phu nhân."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan "ồ" một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy hai người đã làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không có gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cảm thấy đề tài này hơi kỳ quặc, bèn nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chỉ cùng nhau ăn khuya thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan vô cùng kinh ngạc:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hai người cùng ăn khuya? Chị ấy trước giờ chẳng phải không bao giờ ăn khuya sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khó hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tại sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sợ mập chứ sao. Buổi tối ăn những thứ này rất dễ tăng cân."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan tiếp tục truy hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hai người ăn gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sủi cảo nước."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ôi trời! Còn là món chứa tinh bột nữa!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Là nàng không theo kịp tư duy của người trẻ sao? Chỉ ăn sủi cảo nước thôi mà, có cần kinh ngạc như vậy không? Hơn nữa, Lâm Nhược Đường không chỉ ăn tại chỗ mà còn gói mang về.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đang chăm chú nghe điện thoại thì bất chợt nghe thấy động tĩnh ngoài cửa. Cô quay đầu, thấy Lâm Nhược Đường mang dép lê bước vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đưa mắt đánh giá chị từ trên xuống dưới, khóe môi cong lên đầy ẩn ý. Thấy vẻ mặt kỳ quái của cô, Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Muộn thế này rồi, em còn ở đây làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đợi chị về chứ. Muộn thế này chị đi đâu vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đến thăm bà nội."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan che micro điện thoại:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Còn gì nữa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bình tĩnh nhìn cô, cứ thế không nói gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Bị ánh mắt ấy nhìn đến đau nhói cả vai, chỗ xương từng bị cô bóp đau âm ỉ trở lại. Lâm Đan lè lưỡi với cô rồi nhanh chóng quay về phòng mình, nói với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị em về rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ồ, được. Vậy chị không làm phiền nữa. Xem xong video thì nói cho chị biết nhé, có chuyện muốn bàn với em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"OK, lát nữa nói."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúp điện thoại. Hai người băng qua đường, Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chìa khóa."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đưa chìa khóa cho cô, tiện tay sờ đến chìa khóa xe, lập tức khựng lại:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Dư Mạt."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Xe của tôi hình như vẫn còn ở bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người lại vội vàng chạy trở lại bệnh viện. Trên đường đi, Dư Mạt lẩm bẩm:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cậu còn nhớ hôm tôi bị xe tông, cậu lái xe đến bệnh viện tìm tôi không? Hôm đó tôi có ca phẫu thuật, bận đến tối muộn. Chúng ta ăn tối xong về đến nhà mới nhớ ra xe vẫn còn để ở bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Sao Thời Vụ có thể không nhớ? Hai người vẫn giống hệt khi ấy, hấp tấp quay lại lấy xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thời Vụ, bất kể xảy ra chuyện gì, cậu cũng đừng quên vẫn còn có tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chớp mắt hai lần rồi khẽ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nói chuyện này làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt khoác lấy cánh tay nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi sợ cậu cố tỏ ra mạnh mẽ, sợ cậu cảm thấy bây giờ mình chỉ có một mình, sợ cậu chẳng quan tâm gì nữa, sợ cậu tự hành hạ bản thân."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu. Dư Mạt ôm chặt cánh tay nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sao nào? Cảm động rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ai cảm động chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đẩy cô ra. Dư Mạt lại bám lấy, Thời Vụ quay đầu nhìn cô, bật cười rạng rỡ.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người lái xe về chưa đến năm phút thì tới nơi. Khi đang lấy hành lý, Thời Vụ nhận được điện thoại của Lâm Đan. Em ấy nói đã xem xong video rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-" Chị có một ý tưởng, không biết em có đồng ý nghe thử không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan dựa vào gối ôm:</p><p style="text-align: justify; margin-bottom: 0.9em">-" Chị nói đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói với Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cậu lên trước đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt kéo vali:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi giúp cậu mang lên."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ xua tay. Chiếc vali này khá nặng, Dư Mạt đã bận rộn cả tối ở bệnh viện, chắc chắn rất mệt. Nàng tự mình xách lên là được.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt cũng không cố chấp, chỉ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thật sự không cần sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu. Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy tôi lên trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Dư Mạt rời đi, Thời Vụ nói ý tưởng của mình với Lâm Đan.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy à? Em phải hỏi ý kiến chị Lâm trước đã."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đương nhiên. Chị muốn hỏi ý kiến em trước. Nếu em đồng ý, chị mới đi bàn với chị Lâm, em không cần phải ra mặt."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được thì được, chỉ là người hâm mộ kia......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Em ấy đồng ý. Trước khi bàn với em, chị đã nói chuyện với em ấy rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy thì em OK."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được, ngày mai chị sẽ bàn cụ thể với chị Lâm."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúp điện thoại, thở phào nhẹ nhõm rồi nhét điện thoại vào túi, kéo vali lên lầu. Tuy bên trong không có bao nhiêu quần áo, nhưng chiếc vali vẫn khá nặng, Thời Vụ xách lên cũng chẳng hề nhẹ nhàng. Sau khi leo được ba tầng, nàng đã hơi thở dốc, bèn tựa vào tường nghỉ ngơi.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh đèn cảm ứng màu vàng lần lượt sáng lên từ tầng dưới. Thời Vụ cúi đầu, qua khe hở giữa cầu thang nhìn thấy một bóng dáng quen thuộc.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc bước vài bước đã đến bên cạnh Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi tan làm về nhà không thấy Thời Vụ, gọi điện nàng cũng không nghe, nhưng biết nàng đang ở chỗ Dư Mạt nên cô không quá lo lắng. Chỉ là căn nhà thiếu đi một người, bỗng trở nên trống trải lạnh lẽo.</p><p style="text-align: justify; margin-bottom: 0.9em">Căn nhà tân hôn là do cô và Thời Vụ cùng nhau lựa chọn. Khi sửa sang, cô rất bận, gần như mọi việc đều do một tay Thời Vụ lo liệu. Bởi vậy, khắp căn nhà đều chất chứa những ký ức liên quan đến Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngồi một lúc, Triệu Hy Ngọc càng cảm thấy buồn bực, cuối cùng vẫn không nhịn được mà ra ngoài tìm nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi cô đến nơi, Thời Vụ đang đứng dưới lầu gọi điện thoại. Cô không biết nàng đang gọi cho ai, cũng không biết hai người đã nói những gì, nhưng trong lòng lại cảm thấy rất yên tâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi ở bên Thời Vụ, cảm giác rõ rệt nhất của cô chính là sự an tâm. Có lẽ vì mối quan hệ giữa Thời Ánh Xuân và Thường Anh, Thời Vụ luôn nghiêm túc và chuyên nhất trong tình cảm, tuyệt đối không mập mờ với người khác, cũng sẽ không thay lòng đổi dạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Vì thế, dù nhìn thấy Thời Vụ nửa đêm đứng ngoài gọi điện thoại, Triệu Hy Ngọc cũng không suy nghĩ nhiều. Sau đó, cô lại nhìn thấy Thời Vụ xách vali lên lầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lần trước cô giúp Thời Vụ chuyển nhà, là chuyển đồ đến căn nhà tân hôn của hai người. Khi ấy, cô xách vali rồi nói với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đây sẽ là lần cuối cùng em chuyển nhà."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc bất giác nhớ lại nụ cười dịu dàng của Thời Vụ khi ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ngẩng đầu, chạm mắt với Thời Vụ đang đứng phía trên cầu thang, khẽ gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu nhìn cô:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sao chị lại đến đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Trong nhà trống trải quá, chị không ngủ được nên sang đây xem em."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn đang xách vali, chưa kịp bước tiếp. Triệu Hy Ngọc đi đến bên cạnh nàng, nhận lấy vali từ tay nàng. Thời Vụ cau mày, nhưng Triệu Hy Ngọc đã xách vali lên lầu, còn nàng đi phía sau, mím chặt môi.</p><p style="text-align: justify; margin-bottom: 0.9em">Không gian yên tĩnh đến mức khiến người ta khó thở, chỉ còn lại tiếng bước chân nặng nề. Thời Vụ lặng lẽ theo cô lên lầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến cửa cầu thang tầng năm, Triệu Hy Ngọc tới trước. Cô đứng đó chờ Thời Vụ. Thời Vụ bước nhanh thêm hai bước, nhận lại vali từ tay cô rồi đi về phía cửa nhà Dư Mạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Phía sau, Triệu Hy Ngọc lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Vụ, giữa chị và Tinh Tinh chưa từng có vấn đề gì khác. Em không cần lo chị sẽ nảy sinh tình cảm gì với cô ấy. Chị biết chuyện con cái khiến em không thể chấp nhận, chị......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ổn định lại cảm xúc, lên tiếng ngắt lời cô:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Triệu Hy Ngọc."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng xoay người, đứng đối diện với Triệu Hy Ngọc. Ánh mắt nàng bình thản, nhưng lại vô cùng nghiêm túc và chân thành, giống hệt ngày hai người kết hôn, khi Triệu Hy Ngọc hỏi nàng có đồng ý hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô thật lâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ là câu "em đồng ý" của ngày hôm ấy, giờ đây đã biến thành:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chúng ta ly hôn đi."</p><p style="text-align: justify; margin-bottom: 0.9em">⸻</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các thiên thần nhỏ đã tặng 13 vé Bá Vương và 286 chai dung dịch dinh dưỡng~</p><p style="text-align: justify; margin-bottom: 0.9em">Ngẫu nhiên phát một trăm bao lì xì nhé.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Trước đây chị em cũng không ăn khuya, sao bây giờ lại ăn rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Để chuẩn bị cho cuộc sống về đêm sau này."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">.... Chú thích: chị Lâm ở đây là người quản lý của Lâm Đan chứ không phải Lâm Nhược Đường nhé. Đáng nhẽ nên edit thành tên: Lâm tỷ thì sẽ không bị nhầm nhưng do ban đầu mình đã lỡ edit thành chị Lâm nên thành ra không sửa lại được nữa. 😔 xin tạ lỗi !.tạ lỗi !</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 24, 'Luật sư', '<p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc cầu hôn vào cuối năm. Ngày 26, công ty nghỉ, lúc Thời Vụ kiểm tra xong toàn bộ máy tính và tắt máy, Triệu Hy Ngọc gõ cửa bước vào, trong tay xách theo túi máy tính, hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Xong chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩng đầu cười với cô:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Xong rồi. Dư Mạt còn hẹn tối nay chúng ta cùng ăn cơm."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy đi không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chẳng phải chị đã hẹn nhà hàng để hai chúng ta đến đó sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bởi vì cuối năm có quá nhiều chuyện lớn nhỏ, thời gian hai người ở riêng bên nhau gần như chẳng có. Giờ tan làm cũng không khớp, Triệu Hy Ngọc thường xuyên ngủ lại công ty. Thời Vụ biết cô bận, khoảng thời gian này ngoài việc mang cơm cho cô thì gần như không tìm đến. Vẫn là trước khi tan làm, Triệu Hy Ngọc liên lạc với nàng, đặt nhà hàng, còn nói sau khi ăn xong sẽ cùng đi xem phim.</p><p style="text-align: justify; margin-bottom: 0.9em">Những hoạt động giải trí trong những lần hẹn hò của họ không nhiều, xem phim là một trong số đó. Nếu chỉ đơn thuần đi ăn, đôi khi Thời Vụ sẽ gọi cả Dư Mạt, nhưng hẹn hò thì không. Đây cũng xem như chút ích kỷ của nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ừm, chỉ hai chúng ta thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vui vẻ cùng cô đến nhà hàng. Lúc sắp ăn xong, nhạc trong đại sảnh đột nhiên đổi, một bó hoa được đưa đến trước mặt. Triệu Hy Ngọc cầm hộp nhẫn, mỉm cười nhìn nàng, mấy bàn xung quanh đều reo hò. Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Vụ, chúng ta kết hôn nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hối hận vì năm đó đã chấp nhận lời cầu hôn của Triệu Hy Ngọc, cũng không hối hận vì đã kết hôn với cô. Giống như hiện tại, nàng cũng không hối hận khi đề nghị ly hôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nghe thấy hai chữ "ly hôn", tựa như bị sét đánh trúng, giọng cũng lớn hẳn lên:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ly hôn? Em muốn ly hôn với chị?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng, em muốn ly hôn với chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Gần đây xảy ra quá nhiều chuyện, chị biết giữa chúng ta thiếu giao tiếp. Nhưng những chuyện em muốn biết, chị đều đã nói với em rồi. Em bình tĩnh lại, suy nghĩ cho thật kỹ..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Em đã nghĩ kỹ rồi, Triệu Hy Ngọc. Giữa chúng ta không còn gì để nói nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc lạnh giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị không đồng ý!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn chưa kịp lên tiếng, Dư Mạt đã đạp cửa xông ra. Cô đứng trước mặt Thời Vụ, chỉ vào Triệu Hy Ngọc mà mắng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Úi chà chà, chị còn không đồng ý cơ đấy? chị dựa vào đâu mà không đồng ý? Triệu Hy Ngọc, trước đây tôi cứ tưởng chị là người tốt, đúng là tôi mù mắt rồi. Tôi hối hận vì đã mai mối chị với Thời Vụ. Chị đúng là không biết xấu hổ! Nghe rõ chưa? Không biết xấu hổ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc bị chỉ thẳng vào mũi mắng đến hơi bực, cau mày, sắc mặt không vui. Giọng Dư Mạt lại lớn, ít nhất trong đêm yên tĩnh thế này chẳng khác nào pháo nổ. Triệu Hy Ngọc không muốn dây dưa thêm ở đây, chỉ để lại một câu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Em suy nghĩ kỹ đi, ngày mai chúng ta đến công ty rồi nói tiếp."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt "chậc chậc" định tranh luận với chị ta thêm nhưng Thời Vụ kéo tay Dư Mạt, lắc đầu. Dư Mạt trợn mắt nhìn Triệu Hy Ngọc, lẩm bẩm:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cút đi!"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhìn Thời Vụ. Thời Vụ thậm chí không thèm nhìn cô lấy một lần, cùng Dư Mạt vào nhà.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa đóng lại, Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tức chết tôi rồi, chị ta có ý gì vậy? Ý chị ta là còn muốn có con với Triệu Tinh à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không giấu giếm, gật đầu. Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thật sự coi cậu là con thỏ ngốc à? Ngày mai cậu cứ đến công ty làm loạn! Làm lớn chuyện lên mới tốt! Xem chị ta còn dám tỏ thái độ thế nào!"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đầy căm phẫn. Nhưng sau đó nghĩ đến việc công việc của Thời Vụ vẫn còn ở Ưu Lạc, chắc chắn nàng không thể bất chấp như mình. Cô lại hơi đau đầu, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Lỡ Triệu Hy Ngọc thật sự không đồng ý thì phải làm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-" Chị ấy sẽ không đồng ý."</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy khoảng thời gian này Triệu Hy Ngọc khiến Thời Vụ cảm thấy xa lạ, nhưng nàng và Triệu Hy Ngọc quen nhau bốn năm, hiểu cách làm việc của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt càng tức càng phiền:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy phải làm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Khởi kiện."</p><p style="text-align: justify; margin-bottom: 0.9em">-"Khởi kiện á? Vậy chẳng phải sẽ phải ra tòa sao?" Dư Mạt nói. "Hai người không chỉ có chuyện công ty, còn có nhà cửa và phân chia tài sản nữa. Tôi nghe nói người có tiền trước khi kết hôn đều ký thỏa thuận, cậu cũng ký rồi đúng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi không ký thỏa thuận tiền hôn nhân."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói nàng ngây thơ cũng được, nói nàng ngốc cũng chẳng sai. Khi đó nàng thật sự chưa từng nghĩ đến chuyện sẽ ly hôn với Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi cũng cảm thấy với tính khí của Triệu Hy Ngọc, chị ta sẽ không dễ dàng đồng ý ly hôn đâu. Cho dù ly hôn, chắc chắn cũng phải lột của chị ta một lớp da!"</p><p style="text-align: justify; margin-bottom: 0.9em">Không được, không được. Cô phải giúp hỏi thăm xem sao, xem có luật sư nào giỏi không. Bệnh viện đúng là có phòng pháp vụ, nhưng cô không thân với người ta. Hơn nữa, cô từng nghe Thời Vụ nói phòng pháp vụ lâu năm của Ưu Lạc đã bị thay rồi. Chuyện đầu tiên Triệu Hy Ngọc làm sau khi tiếp quản Ưu Lạc chính là thay phòng pháp vụ. Vì vậy, đến giờ những vụ bảo vệ quyền lợi của Ưu Lạc vẫn chưa từng thua.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu thật sự như vậy, một mình Thời Vụ khó địch lại bốn phía, nghĩ thế nào cũng thiệt.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt lo lắng bất an. So với nàng, Thời Vụ lại bình tĩnh hơn nhiều, còn có thể ăn hết số sủi cảo mang về. Dư Mạt cau mày, suýt khóc:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sao cậu vẫn còn ăn được vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nuốt xuống, gắp một cái đưa cho Dư Mạt, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cậu ăn không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô vừa rơi nước mắt vừa ăn.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong lúc Thời Vụ đi tắm, Dư Mạt dọn dẹp nhà cửa. Tối qua không còn cách nào nên đành ngủ lại một đêm, nhưng không thể để Thời Vụ ngày nào cũng ngủ chung giường với mình. Cô thì vui lòng, nhưng Thời Vụ chưa chắc đã vui. May mà căn hộ thuê lúc đầu là hai phòng ngủ một phòng khách, căn còn lại dùng làm phòng sách và chất đồ. Dư Mạt đơn giản dọn giường ra, trải bộ chăn ga gối mới, mở cửa sổ. Đột nhiên cô có cảm giác như trở lại lúc mới thuê nhà cùng Thời Vụ. Khi ấy cũng là căn hộ hai phòng ngủ một phòng khách, một phòng hướng nắng, căn còn lại không được đón nắng nhiều. Cuối cùng hai người đặt cả hai chiếc giường vào căn phòng có ánh nắng, phòng còn lại làm phòng sách.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi đó cô chẳng thể nào ngờ Thời Vụ sẽ kết hôn sớm như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Càng không ngờ, Thời Vụ lại ly hôn khi cô còn chưa có nổi một người yêu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thật thê thảm. Dư Mạt cắn răng trải ga giường. Đợi Thời Vụ tắm xong bước ra, cô hất cằm, nhiệt tình mời:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ấm áp chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ló đầu nhìn căn phòng đã được dọn dẹp đơn giản, mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Khách sáo gì chứ, cứ yên tâm ở đây đi. Lát nữa tôi sẽ tìm cho cậu một chiếc chìa khóa khác, chắc ở trong ngăn kéo."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Để tôi tự tìm. Cậu có muốn tắm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Có chứ. Tối nay bận đến toát mồ hôi, vậy tôi đi tắm trước. Cậu tìm trong ngăn kéo của chiếc tủ cạnh cửa ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt quay về phòng lấy đồ ngủ rồi vào nhà vệ sinh. Nhưng cô không lập tức tắm, mà theo thói quen ngồi trên bồn cầu lướt video, lướt Weibo và vòng bạn bè. Vòng bạn bè lập tức hiện lên một ảnh đại diện, Dư Mạt không nhận ra. Hình như là Lâm Nhược Đường, là Lâm Nhược Đường đúng không? Dư Mạt cẩn thận quay lại WeChat xem ảnh đại diện mèo ấy, rồi lại quay về vòng bạn bè. Thật ra cũng chẳng có gì, chỉ là một thông báo về việc tái tổ chức phòng pháp vụ của Lâm Thái.</p><p style="text-align: justify; margin-bottom: 0.9em">Không hổ là bà chủ, vòng bạn bè cũng toàn chuyện công việc. Dư Mạt định nhấn thích, lại thấy như vậy hơi đột ngột, liền lướt qua bài đăng này. Kéo xuống tiếp cũng chẳng có gì mới lạ. Nhưng lúc chuẩn bị thoát khỏi vòng bạn bè, cô chợt nhớ ra một chuyện.</p><p style="text-align: justify; margin-bottom: 0.9em">Phòng pháp vụ của Lâm Thái tái tổ chức, vậy có phải đồng nghĩa với việc Lâm Nhược Đường quen biết rất nhiều luật sư không? Nhất là những luật sư giỏi. Chắc chắn rồi, cô ấy là bà chủ lớn như vậy, sao có thể không quen vài luật sư chứ!</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đó Dư Mạt còn lo Thời Vụ sẽ chịu thiệt trong việc ly hôn và phân chia tài sản, giờ dường như đã tìm được một con đường sống. Chỉ là không biết Lâm Nhược Đường có thể giúp giới thiệu một hai người hay không. Cô đột nhiên chạy đến hỏi Lâm Nhược Đường liệu có làm phiền cô ấy quá không?</p><p style="text-align: justify; margin-bottom: 0.9em">Chắc là không đâu. Nói thế nào thì hồi xưa từng chăm sóc Lâm Nhược Đường. Tuy chẳng thể gọi là có ân tình gì, nhưng ít nhiều cũng có chút tình nghĩa chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt tự tẩy não mình, ngón tay run run gửi tin nhắn cho Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Lâm tổng, chào cô. Tôi muốn hỏi cô có quen luật sư nào tương đối giỏi không? Chỉ cần một người là được.】</p><p style="text-align: justify; margin-bottom: 0.9em">Gửi xong, cô còn bổ sung:</p><p style="text-align: justify; margin-bottom: 0.9em">【Nếu làm phiền cô thì thật sự rất xin lỗi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Cách dùng từ này còn nghiêm cẩn hơn cả luận văn tốt nghiệp của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">-"Dư Mạt."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gõ cửa. Dư Mạt suýt bật dậy khỏi bồn cầu, cô quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Làm gì vậy!"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bị dọa hết hồn, tim đập liên hồi, bệnh tim cũng sắp tái phát. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-" Tôi ngủ trước đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ừ, biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô vuốt ngực cho nhịp tim bình ổn. WeChat vang lên một tiếng, có tin nhắn mới. Dư Mạt nheo mắt nhìn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Về phương diện nào?】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ly hôn......】</p><p style="text-align: justify; margin-bottom: 0.9em">Có phải thẳng thắn quá không? Nhưng chẳng phải Lâm Nhược Đường đã biết chuyện này rồi sao? Hôm qua Lâm Đan đã nói.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Về việc phân chia tài sản.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Vụ ly hôn à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【......Ừ.】</p><p style="text-align: justify; margin-bottom: 0.9em">Cô chột dạ gì chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Có một người bạn chuyên xử lý loại kiện tụng này, tỷ lệ thắng chín mươi phần trăm. Có cần tôi giới thiệu cho cô không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cần!!!】</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này cô chính là hậu phương vững chắc của Thời Vụ! Lỡ đàm phán không thành, vậy cô lập tức tung át chủ bài!</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gửi một danh thiếp qua. Dư Mạt lập tức kết bạn, còn cảm ơn rối rít. Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không cần.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vui vẻ thêm đối phương làm bạn. Nửa đêm vẫn chưa được thông qua nhưng cô cũng không để ý, phấn khởi đi tắm. Lúc đi ra, ngang qua phòng Thời Vụ, thấy cửa vẫn còn hé. Cô nhìn vào trong, gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thời Vụ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không trả lời. Dư Mạt đoán nàng đã ngủ, rón rén quay về phòng mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngày hôm sau vẫn không thấy bóng dáng Thời Vụ, Dư Mạt cũng đã quen rồi. Chỉ là buổi sáng vị luật sư kia đã chấp nhận lời mời kết bạn của cô, còn vô cùng ân cần nhắn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Xin chào, có vấn đề gì cứ hỏi tôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt khá kích động, nhưng không nói nhiều. Cô gọi điện cho Thời Vụ. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi vừa đến công ty."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đã chạm mặt Triệu Hy Ngọc chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vẫn chưa, sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đừng nói chuyện với chị ta."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ mím môi. Dư Mạt lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"À đúng rồi, hai người kết hôn lâu như vậy, cậu có nắm được điểm yếu nào của công ty chị ta không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Điểm yếu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng đó, kiểu như hợp đồng âm dương, trốn thuế lậu thuế, giao dịch ngầm trái quy định..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ rất tiếc phải nói với cô:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không có."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Dư Mạt, tôi và chị ấy không can thiệp vào công việc của nhau."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hiểu ra. Thật ra trước khi hai người xác nhận quan hệ, Thời Vụ từng cân nhắc có nên nghỉ việc hay không. Nhất là trước khi kết hôn, nàng còn hỏi ý kiến Dư Mạt. Đối với nàng và Triệu Hy Ngọc mà nói, công việc là công việc, nhưng đối với những người khác, khi đi làm nàng không chỉ phải đối diện với cấp trên, mà còn phải đối diện với mối quan hệ hôn nhân giữa nàng và Triệu Hy Ngọc, vô hình trung gây áp lực cho người khác. Thời Vụ không muốn nhìn thấy tình cảnh đó, nhưng Triệu Hy Ngọc không đồng ý để nàng nghỉ việc, chỉ nói việc công là việc công, việc riêng là việc riêng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra chuyện này rất khó. Ví dụ như vào thời khắc hiện tại, Thời Vụ không thể nào phân biệt rõ công tư.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng biết cuộc hôn nhân giữa mình và Triệu Hy Ngọc đã đi đến hồi kết, cũng là lúc rời khỏi Ưu Nhạc. Nhưng đây là nơi nàng đã gắn bó suốt bốn năm. Ngoài Triệu Hy Ngọc, nàng còn có rất nhiều đồng nghiệp. Kỳ Văn gần như là do nàng một tay dìu dắt, ngoài ra còn có những người khác. Trong bộ phận truyền thông cũng có hai người được nàng điều chuyển từ bộ phận khác sang. Nàng đã bỏ không ít tâm huyết cho Ưu Lạc. Nàng mong Ưu Lạc phát triển tốt, không chỉ vì Triệu Hy Ngọc, mà còn vì những đồng nghiệp từng cùng nhau vượt qua hoạn nạn.</p><p style="text-align: justify; margin-bottom: 0.9em">Bây giờ mọi thứ đều trở về con số không. Thời Vụ đứng trước cửa văn phòng mở, những đồng nghiệp đi qua đi lại đều chào hỏi nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng khẽ gật đầu đáp lại. Kỳ Văn đi tới, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Kỳ Văn, cô vào văn phòng với tôi một lát."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Văn vẫn chưa đặt túi xuống, nghi hoặc hỏi mọi người:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Có chuyện gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Mọi người đều ngơ ngác lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Văn vội vàng theo Thời Vụ vào văn phòng. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đây là toàn bộ phương án hợp tác với Lâm Thái. Đây là quy trình sinh nhật của Lâm Đan và những nội dung cần bổ sung. Buổi sáng cô liên hệ với quản lý của cô ấy, lát nữa tôi sẽ gửi video cho cô. Còn đây là phương án quảng bá cho mấy thương hiệu đang hợp tác. Đây là kế hoạch cho nửa cuối năm, cô xem kỹ đi. Có chỗ nào không hiểu thì cứ hỏi tôi. Còn nữa..."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Văn nhìn nàng bàn giao công việc hiện tại đâu ra đấy, nhất thời chưa phản ứng kịp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thời tổng giám, chị muốn nghỉ phép sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi muốn nghỉ việc."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Văn trợn tròn mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt Thời Vụ vẫn bình tĩnh như thường, nhưng Kỳ Văn nhìn ra nàng không hề nói đùa.</p><p style="text-align: justify; margin-bottom: 0.9em">Bàn giao xong cho Kỳ Văn, Thời Vụ hít sâu một hơi rồi lên lầu tìm Triệu Hy Ngọc. Trịnh Ý nói cô đang họp. Thời Vụ ngồi trong văn phòng chờ. Không đợi được Triệu Hy Ngọc, ngược lại lại chờ được một người đã lâu không gặp. Thời Vụ thoáng sững sờ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Mẹ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu đến một mình. Sau khi bước vào, bà ra hiệu cho Trịnh Ý ra ngoài. Trịnh Ý cúi đầu nhìn Thời Vụ một cái rồi đóng cửa rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng dậy. Mẹ Triệu bước nhanh hai bước đến trước mặt nàng, vừa mở miệng đã hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Con cãi nhau với Tiểu Ngọc à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lần trước Thời Vụ gặp mẹ Triệu hình như là trong một bữa tiệc gia đình. Triệu Tinh ngồi bên cạnh Triệu Hy Ngọc. Triệu Hy Ngọc cau mày, không vui, nhưng mẹ Triệu lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Em gái con lâu lắm rồi mới gặp con, muốn ngồi gần con một chút thì có gì sai?"</p><p style="text-align: justify; margin-bottom: 0.9em">Từ đầu đến cuối, bà đều không tôn trọng Thời Vụ, cũng không tôn trọng cuộc hôn nhân giữa Thời Vụ và Triệu Hy Ngọc. Nhưng Thời Vụ không quá để tâm, vì nàng rất ít khi gặp mẹ Triệu. Nếu không phải Triệu Tinh trở về ăn hai bữa cơm, có lẽ một hai tháng nàng cũng chẳng gặp bà được một lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Bởi Triệu Hy Ngọc bận rộn, không mấy khi về nhà, vừa hay nàng cũng có lý do để không về.</p><p style="text-align: justify; margin-bottom: 0.9em">Bố mẹ nhà họ Triệu cũng không đến nhà mới của nàng, bởi vậy hai bên vẫn duy trì được sự cân bằng vi diệu.</p><p style="text-align: justify; margin-bottom: 0.9em">Bây giờ sự cân bằng ấy đã bị phá vỡ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không phải cãi nhau, con chuẩn bị ly hôn với chị ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu nghe vậy, bất ngờ nhìn Thời Vụ. Ngay từ đầu bà đã không tán thành Triệu Hy Ngọc và Thời Vụ ở bên nhau. Triệu Hy Ngọc quản lý Ưu Lạc, lại ở bên một nhân viên, chẳng phải khiến người ta chê cười sao? Tuy nhà họ Triệu không phải gia đình quyền quý gì, nhưng ít nhất cũng phải môn đăng hộ đối chứ. Bố mẹ Thời Vụ đều không còn, nàng không có chỗ dựa, đến cả ở Cửu Xuyên cũng chẳng có nổi một căn nhà, thật sự không lọt nổi vào mắt bà.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Triệu Hy Ngọc thích nàng, bà còn có thể làm gì được? Hơn nữa bà cũng từng nghĩ, nếu là Thời Vụ thì có lẽ chuyện đứa bé của Triệu Tinh sẽ thuận lợi hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Dẫu sao Thời Vụ cũng không có chỗ dựa.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong mắt mẹ Triệu, xã hội vốn là như vậy. Không phải cứ đáng thương thì tất cả mọi người đều sẽ giúp đỡ. Trái lại, bởi vì không quyền không thế nên càng dễ bị bắt nạt, bị tính kế. Bà chưa từng bắt nạt hay tính kế Thời Vụ, mà có tính thì sao? Cũng không thể nói chuyện với nhau được. Dẫu sao cuộc sống sung túc mà Thời Vụ đang hưởng hiện tại đều do nhà họ Triệu cho, vì thế khi nghe Thời Vụ nói muốn ly hôn, bà vô cùng bất ngờ.</p><p style="text-align: justify; margin-bottom: 0.9em">-"Con thật sự muốn ly hôn với Tiểu Ngọc?" Mẹ Triệu nhìn nàng dò xét, như thể muốn xem nàng có đang giở trò lạt mềm buộc chặt hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bình tĩnh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vâng. Hôm qua con đã nói chuyện này với Triệu Hy Ngọc rồi, chị ấy không nói với mọi người sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu đương nhiên biết hai người đã cãi nhau. Nhưng khi bà hỏi Triệu Hy Ngọc, Triệu Hy Ngọc chỉ nói đừng xen vào, cô sẽ tự xử lý.</p><p style="text-align: justify; margin-bottom: 0.9em">Xem ra vẫn chưa xử lý ổn thỏa. Mẹ Triệu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Là vì chuyện của Tinh Tinh sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không giấu giếm:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vâng."</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Trước khi hai đứa kết hôn, mẹ đã nói với Tiểu Ngọc rằng hai đứa không hợp nhau. Con không giúp được nó, dù là sự nghiệp, gia đình hay cuộc sống, con chẳng giúp được gì cả. Hai đứa ở bên nhau, vậy mà còn phải để Tiểu Ngọc nấu cơm cho con. Mẹ thật sự không biết nó thích con ở điểm nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng từng hỏi Triệu Hy Ngọc rằng cô thích nàng ở điểm nào. Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị thích mọi thứ. Chỉ cần là em, chị đều thích."</p><p style="text-align: justify; margin-bottom: 0.9em">Khi đó nàng còn cảm động.</p><p style="text-align: justify; margin-bottom: 0.9em">Bây giờ nghĩ lại, sự yêu thích của cô rốt cuộc vẫn không thắng nổi lợi ích.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Con và chị ấy quả thật không hợp nhau, nhưng không phải vì tiền bạc hay địa vị."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhìn thẳng mẹ Triệu, không kiêu ngạo cũng chẳng tự ti:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Là vì quan điểm của chúng con khác nhau. Con vĩnh viễn không thể nuôi dưỡng con của chị ấy và người khác."</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu như bị đâm trúng chỗ đau, có phần xấu hổ tức giận:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cái gì mà con của nó với người khác? Đó là con cháu nhà họ Triệu!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Là con cháu nhà họ Triệu, không liên quan đến con."</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vốn dĩ mẹ còn nghĩ, nếu con có thể nuôi dưỡng đứa trẻ này thật tốt, mẹ sẽ nhắm một mắt mở một mắt, để con và Tiểu Ngọc tiếp tục sống với nhau cũng chẳng sao. Không ngờ con lại không đồng ý."</p><p style="text-align: justify; margin-bottom: 0.9em">Lại còn dùng từ "không ngờ"?</p><p style="text-align: justify; margin-bottom: 0.9em">Rốt cuộc bà dùng từ ấy bằng cách nào vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây Thời Vụ vẫn không thể hiểu nổi suy nghĩ của Triệu Hy Ngọc, bây giờ nàng đã hiểu. Tư tưởng được truyền từ đời này sang đời khác. Hóa ra người nhà họ Triệu đều nghĩ như vậy, chẳng ai thấy có vấn đề.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngược lại, người mà họ cho rằng có vấn đề lại là nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là buồn cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi mẹ Triệu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Triệu Hy Ngọc là do bà sinh ra sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu bị hỏi đến ngẩn người, lập tức nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đương nhiên là tôi sinh ra!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy còn con của người khác?"</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu đỏ bừng mặt vì tức:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô!"</p><p style="text-align: justify; margin-bottom: 0.9em">Bà giơ tay định đánh Thời Vụ. Thời Vụ lùi lại hai bước. Cái tát của mẹ Triệu rơi vào khoảng không, đập lên lưng ghế sofa. Bà tức tối nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô đang nói linh tinh gì vậy? Tôi đã bảo loại gia đình nhỏ bé như cô thì có được giáo dưỡng gì chứ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ phản kích:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bà biết rõ việc mình đang làm là không có giáo dưỡng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lần này mẹ Triệu thật sự nổi giận. Bà thở hổn hển, nhìn ánh mắt Thời Vụ như nhìn kẻ thù. Thời Vụ không hề sợ hãi, giống như một con nhím dựng hết gai nhọn trên người, đối mặt với bà.</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu nghiêm giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô đúng là phản rồi! Dù sao bây giờ tôi vẫn là mẹ cô! Cô nói chuyện với tôi như vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Rất nhanh sẽ không còn nữa. Bà Triệu, xin bà mau chóng thích nghi với thân phận mới này."</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu bị nàng chặn đến không nói nên lời. Thời Vụ bình thản nói xong, không hề chần chừ, xoay người định rời khỏi văn phòng. Khi mở cửa, Triệu Hy Ngọc đang đứng trước cửa. Nàng ngước mắt, đối diện với Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Em đã nói gì với mẹ chị?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị tự hỏi bà ấy đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc cau mày:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Vụ..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sáng mai tám giờ, mang đầy đủ tài liệu. Em sẽ đợi chị trước cửa Cục Dân chính."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nghiến răng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không thể nào!"</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu nói với Triệu Hy Ngọc:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Để nó ly hôn! Hai đứa vốn dĩ đã không nên ở bên nhau. Thời Vụ, tôi cảnh cáo cô, ly hôn rồi đừng hòng lấy từ chỗ Tiểu Ngọc một xu!"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc không vui:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Mẹ! Chuyện của con không cần mẹ quản!"</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ Triệu cũng không vui:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Con sắp ly hôn rồi, mẹ còn không được quản sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Con sẽ xử lý ổn thỏa!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không kiên nhẫn nghe hai người nói chuyện, liền nói với Triệu Hy Ngọc:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chuyện của công ty, em đã bàn giao công việc cho Kỳ Văn rồi. Chuyện giữa chúng ta, có phải cũng nên chấm dứt rồi không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được, chuyện công ty em giao cho Kỳ Văn. Em về nhà nghỉ ngơi trước đi, đợi chị xử lý xong chuyện bên này sẽ quay về. Chị và em sẽ nói chuyện đàng hoàng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không cần đâu, Triệu Hy Ngọc. Chị đã khiến em ghê tởm một lần rồi, đừng tiếp tục khiến em ghê tởm nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc thấy nàng mềm cứng đều không chịu, cũng hơi sốt ruột:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Rốt cuộc em muốn chị phải làm thế nào!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ly hôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhìn nàng chằm chằm, chậm rãi lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nhìn cô thêm lần thứ hai, trực tiếp đẩy vai cô ra rồi rời khỏi văn phòng. Thời Vụ biết Triệu Hy Ngọc sẽ không dễ dàng đồng ý ly hôn. Tối qua nàng đã nghĩ kỹ, cho nên cũng không bất ngờ. Sau khi rời khỏi Ưu Lạc, nàng lên xe, ngồi rất lâu. Ánh nắng ngoài cửa sổ xe từ nghiêng dần thành chiếu thẳng, nàng mới chậm rãi hoàn hồn.</p><p style="text-align: justify; margin-bottom: 0.9em">Điện thoại không có động tĩnh gì, yên tĩnh đến đáng sợ. Nàng lái xe, không mục đích đi dạo trên phố. Bất giác đã đến gần bệnh viện, Thời Vụ nhớ lúc trước Dư Mạt từng nói sau khi phẫu thuật xong sẽ cùng nàng ăn một bữa. Nàng hít sâu một hơi, gọi điện cho Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ra ngoài ăn cơm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt kinh ngạc:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bây giờ á?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ừm, tôi đang ở trước cửa bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được!"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô vội vàng chạy ra khỏi bệnh viện, hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hôm nay cậu không đi làm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi đã nộp đơn xin nghỉ việc rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nhanh quá rồi đó? Đương nhiên cô biết Thời Vụ và Triệu Hy Ngọc ly hôn thì chắc chắn sẽ không ở lại Ưu Lạc, nhưng không ngờ tiến độ nghỉ việc còn nhanh hơn cả ly hôn. Có điều tính cách Thời Vụ vốn là như vậy, một khi đã quyết định làm thì sẽ không dây dưa.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy chúng ta ăn mừng một chút!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Buổi sáng cậu đã chạm mặt Triệu Hy Ngọc chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Gặp rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-" Chị ta không làm khó cậu chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-" Chị ấy không muốn ly hôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đoán cũng đoán ra rồi. Vậy cậu định làm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chiều nay tôi sẽ tìm vị luật sư từng quen trước đây, xem thử..."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vung tay:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi tìm được cho cậu rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hửm?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi tìm cho cậu một người chuyên xử lý kiện ly hôn. Tôi giới thiệu cho cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, cô hất cằm ra hiệu Thời Vụ xem WeChat. Thời Vụ nhấn vào danh thiếp, cái tên đập vào mắt khiến nàng sững lại:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Diệp Lãnh Tinh?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng, chính là cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy nàng đã lên mạng tìm kiếm, không tìm được thông tin hữu ích nào, nhưng người do Lâm Nhược Đường giới thiệu sao có thể sai được?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sao cậu lại có phương thức liên lạc của cô ấy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ừm... bạn bè giới thiệu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghi ngờ liếc cô một cái. Bạn bè giới thiệu? Tuy nàng không hiểu quá rõ giới luật sư, trước đây phần lớn những vụ án nàng tiếp xúc đều là tranh chấp kinh tế và các vụ bảo vệ quyền lợi, nhưng cái tên Diệp Lãnh Tinh nàng vẫn từng nghe qua. Cô ấy là đối tác của Văn phòng luật sư Tinh Thần. Mà Tinh Thần là văn phòng luật sư lớn nhất Cửu Xuyên, những vụ họ tiếp nhận đều đủ tiêu chuẩn được đưa vào kho tư liệu của các trường đại học. Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cậu còn có người bạn như vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vừa chột dạ vừa đắc ý:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Có chứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu. Dư Mạt giục:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cậu kết bạn với cô ấy đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Bị cô nhìn chằm chằm, Thời Vụ gửi lời mời kết bạn.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh đang xem hồ sơ vụ án, nói với Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Trong hợp đồng có quy định, nếu tỷ lệ hao hụt vượt quá năm phần trăm thì phía nhà sản xuất phải chịu trách nhiệm. Nhưng chắc chắn họ sẽ cãi rằng đây là hao hụt phát sinh trong quá trình gia công..."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô còn chưa nói hết, điện thoại đã rung. Diệp Lãnh Tinh nhìn thấy lời mời kết bạn, ngẩng mắt nhìn Lâm Nhược Đường, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô ấy kết bạn với tôi rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngẩng đầu khỏi máy tính, sống mũi đeo kính. Cô thờ ơ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đã kết bạn rồi thì cứ xử lý cho cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chậc, cậu nói nghe nhẹ nhàng thật đấy. Cậu có biết vụ trước tôi nhận là của ai không? Là vụ ly hôn của thiên kim Hậu Thiên. Chỉ riêng phí luật sư đã là con số tám chữ số."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy cậu đừng nhận."</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nhận chứ!" Diệp Lãnh Tinh nói. "Sao có thể không nhận? Đây là lần đầu tiên cậu nhờ tôi. Thời Vụ này là ai vậy, từng cứu mạng cậu à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">-"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh cũng không trông mong cô sẽ trả lời, nghĩ một lúc rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nhưng vụ ly hôn của cô ấy không dễ xử lý. Phía bệnh viện chắc chắn sẽ không cấp giấy chứng minh cho cô ấy. Cho dù có cái gọi là phiếu kiểm tra sức khỏe của em gái kia, cũng không thể dùng làm bằng chứng."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Lâm Nhược Đường lạnh đi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bệnh viện không xử lý được thì xử lý từ công ty của cô ta."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nói, cô vừa bấm đường dây nội bộ, dặn:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bảo tổng giám đốc Triệu của Ưu Lạc chiều nay mang thư bày tỏ nguyện vọng đến văn phòng tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy không do dự:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vâng, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cúp máy. Diệp Lãnh Tinh chống ngón tay lên môi, vẻ mặt khoa trương:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không phải chứ, cô ấy thật sự từng cứu mạng cậu à?"</p><p style="text-align: justify; margin-bottom: 0.9em">.....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn 35 phiếu Bá Vương và 413 bình dinh dưỡng của các thiên thần nhỏ~</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu ngẫu nhiên rơi xuống một trăm bao lì xì thì sao nhỉ?</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh: Thời Vụ này là ai vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Vợ tương lai. 👶🏻👶🏻</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 25, 'Quà tặng', '<p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ có từng cứu mạng Lâm Nhược Đường hay không, Diệp Lãnh Tinh không biết. Nhưng cô biết, như vậy thì mọi chuyện sẽ dễ xử lý hơn nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi chiều, cô chủ động liên lạc với Thời Vụ. Sau khi Thời Vụ đưa Dư Mạt đến bệnh viện, nàng nhận được cuộc gọi của Diệp Lãnh Tinh, liền nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi có thời gian, sẽ qua ngay."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không vội đâu, cô Thời. Tôi đợi cô ở quán cà phê Tinh Nguyệt."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi cúp điện thoại, nàng thấy có chút kỳ lạ. Hình như nàng còn chưa tự giới thiệu với Diệp Lãnh Tinh, sao cô ấy biết mình họ Thời? Là Dư Mạt nói cho cô ấy biết sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không biết rốt cuộc Diệp Lãnh Tinh biết bao nhiêu chuyện, nhưng nàng vẫn vội vã đến đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi tới quán cà phê, bên trong không có mấy người. Thời Vụ nhìn quanh một vòng, thấy một người phụ nữ tóc xoăn dài đang ngồi trong khu ghế sofa. Mái tóc xoăn gợn sóng màu nâu, lúc ấy cô đang gọi điện thoại. Thời Vụ chậm rãi bước lại gần. Người phụ nữ quay đầu, nhìn thấy nàng liền mỉm cười, sau đó nói với người ở đầu dây bên kia:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được rồi, tôi còn có việc, cúp máy trước nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó cô ra hiệu cho Thời Vụ ngồi xuống đối diện mình rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô muốn uống gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Gì cũng được."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh giơ tay gọi nhân viên phục vụ tới:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hai ly latte, cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc Thời Vụ nhìn sang cô, nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đây là tài liệu của tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đưa túi hồ sơ cho Diệp Lãnh Tinh. Diệp Lãnh Tinh nhận lấy bằng hai tay:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được, để tôi xem trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô, chần chừ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Luật sư Diệp, cô là bạn của bạn Dư Mạt sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô Thời không cần khách sáo như vậy. Nếu cô không ngại thì có thể gọi thẳng tên tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô dừng một chút rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cho phép tôi hỏi một câu, hiện giờ cô còn thích cô Triệu không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô Thời đừng hiểu lầm. Đây là câu hỏi theo thông lệ thôi. Dù sao rất nhiều vụ ly hôn đến phút cuối vẫn có người đổi ý, không muốn ly hôn nữa. Tôi chỉ lo sẽ xảy ra tình huống như vậy, mong cô thông cảm."</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi... tôi ghê tởm chị ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nói là không còn thích nữa. Trước khi những chuyện này xảy ra, nàng thật sự có tình cảm với Triệu Hy Ngọc, hơn nữa còn là tình cảm rất sâu đậm.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng sẽ không lừa luật sư. Bảo nàng chỉ trong vài ngày đã hoàn toàn rút mình ra khỏi đoạn tình cảm này thì không thực tế.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh âm thầm quan sát nàng. Trước khi nhận được tài liệu của Thời Vụ, cô đã xem qua ảnh. Người thật còn đẹp hơn trong ảnh, cũng mang vẻ dịu dàng hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô từng tiếp nhận rất nhiều vụ ly hôn. Có người tình cảm rạn nứt, cũng có người kết hôn không vì tình yêu. Tiếp xúc nhiều rồi, cô rất dễ nhìn ra một người còn lưu luyến tình cảm hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn còn tình cảm, nhưng cô cũng hiểu tình cảm không phải trắng đen rõ ràng, cũng không phải muốn buông là lập tức buông được. Nó giống như một loại cảm xúc âm thầm chuyển biến theo thời gian hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cô không cho rằng Thời Vụ sẽ hối hận.</p><p style="text-align: justify; margin-bottom: 0.9em">Bởi vì đoạn tình cảm này đã chạm tới giới hạn cuối cùng của nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt chân thành và thẳng thắn của nàng đã cho Diệp Lãnh Tinh câu trả lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tài liệu tôi đã xem sơ qua. Nếu tôi không nhầm thì bốn mươi phần trăm cổ phần của Ưu Lạc hiện nằm dưới tên bố mẹ cô ấy phải không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng."</p><p style="text-align: justify; margin-bottom: 0.9em">Trước khi kết hôn, bố mẹ nhà họ Triệu thậm chí còn sang tên lại căn biệt thự đứng tên Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nhấp một ngụm cà phê:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nói cách khác, tài sản đứng tên hai người chỉ có căn nhà hôn nhân đang ở, hai chiếc xe và khoản tiền tích lũy trong những năm qua?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh không bất ngờ, cô hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hai người yêu nhau rồi kết hôn đúng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe đến cụm từ ấy, đã rất lâu rồi Thời Vụ mới mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ly hôn sau khi yêu nhau tự nguyện, phiền phức nhất không phải là phân chia tài sản mà là vấn đề tình cảm. Chắc cô cũng hiểu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi hiểu."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Về mặt tình cảm, tôi không giúp cô giải quyết được. Nhưng về mặt tài sản, tôi vẫn rất có lòng tin."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi chỉ muốn biết làm thế nào mới có thể khiến chị ấy đồng ý ly hôn nhanh nhất. Tôi không muốn tiếp tục dây dưa nữa. Có phải có thể bắt đầu từ phía bệnh viện..."</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không được."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh dường như biết nàng định nói gì, lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô Thời, tôi biết chuyện ở bệnh viện. Việc cô Triệu làm thật sự rất đáng ghê tởm. Nhưng chúng ta không có chứng cứ xác thực. Muốn bắt đầu từ hướng đó thì hơi khó. Trước hết cô phải kiện bệnh viện. Bệnh viện chắc chắn sẽ không chuyện lớn hóa nhỏ. Cho dù cô thắng kiện, cô cũng không thể chứng minh chuyện em gái cô Triệu có liên quan đến hai người. Nếu bây giờ cô công khai chuyện đó ra ngoài, ngược lại sẽ trở thành điểm để luật sư phía bên kia công kích. Họ sẽ kiện cô tội vu khống."</p><p style="text-align: justify; margin-bottom: 0.9em">Điều này cũng gần giống với những gì Thời Vụ đã nghĩ. Nàng gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh thấy nàng bình tĩnh tiếp nhận cũng không bất ngờ, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tuy nhiên vẫn còn cách khác. Theo tôi được biết, hiện tại Ưu Lạc đang thúc đẩy hợp tác với Lâm Thái. Có lẽ chúng ta có thể bắt đầu từ phương diện này. Chắc Lâm Thái sẽ không muốn một đối tác hợp tác đầy tai tiếng và có nguy cơ bùng nổ bất cứ lúc nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Dưới áp lực từ Lâm Thái, Ưu Lạc buộc phải sớm đưa ra một câu trả lời khiến Thời Vụ hài lòng. Càng kéo dài sẽ càng bất lợi cho Ưu Lạc.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt nhớ tới dự án hợp tác mà trước đây nàng đã dốc bao công sức mới xúc tiến được, giờ đây lại trở thành lá bùa hộ mệnh giúp nàng rời khỏi đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là khó nói nên lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nàng vẫn thành thật nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hiện tại Lâm Thái vẫn chưa đồng ý hợp tác."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không sao."</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Diệp Lãnh Tinh đầy tự tin, Thời Vụ cũng không hỏi nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người uống xong cà phê, mọi chuyện cũng bàn bạc gần xong. Diệp Lãnh Tinh rời đi trước.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi lại trong quán cà phê, nhìn dòng người qua lại rồi lại gọi thêm một ly cà phê nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Khoảng năm giờ chiều, nàng nhận được điện thoại của Dư Mạt hỏi mọi chuyện đã xong chưa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng dậy rời khỏi quán:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Xong rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy cậu về nhà trước đi. Chắc tối nay tôi sẽ về hơi muộn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa cúp điện thoại, lại có một cuộc gọi khác tới. Trước khi nghe máy, đôi mày đang nhíu nhẹ của Thời Vụ cũng dần giãn ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Ở đầu dây bên kia, giọng Lâm Đan trong trẻo vang lên:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị Thời, buổi hoạt động của em kết thúc rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không có mặt tại hiện trường nên có chút tiếc nuối.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chúc mừng em."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chúc em sinh nhật vui vẻ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan cười khúc khích:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nhưng hôm nay sao em không gặp chị vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị nghỉ việc rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nghỉ việc á?!"</p><p style="text-align: justify; margin-bottom: 0.9em">Đôi mắt cô đảo một vòng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nghỉ việc cũng tốt. Vậy bây giờ chị đang ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị đang chuẩn bị về nhà."</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đừng mà chị!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hôm nay buổi hoạt động thành công lắm. Em còn định mời chị ăn cơm. Hơn nữa hôm nay là sinh nhật em, chị không thể nể mặt em một chút sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngập ngừng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị..."</p><p style="text-align: justify; margin-bottom: 0.9em">Chợt nhớ ra nàng vẫn còn quà chưa tặng Lâm Đan, liền đồng ý:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được. Tối nay em ăn ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đến nhà em trước nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng có địa chỉ nhà Lâm Đan, liền lái xe tới trước cổng biệt thự.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi đỗ xe, nàng gọi điện cho Lâm Đan.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Em xuống ngay."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ kiên nhẫn ngồi chờ trong xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong lúc đó, điện thoại hiện thông báo tin nhắn từ nhóm chat công việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Để tiện bàn giao công việc, nàng vẫn chưa rời khỏi một số nhóm làm việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong nhóm nhỏ của phòng truyền thông, đồng nghiệp nhắn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cuối cùng cũng kết thúc rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Văn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tiểu Lưu, lát nữa gửi ảnh chụp hôm nay cho Đắc Cần nhé.】</p><p style="text-align: justify; margin-bottom: 0.9em">Tiểu Lưu:</p><p style="text-align: justify; margin-bottom: 0.9em">【OK, em sắp xếp xong sẽ gửi cho chị ấy.】</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Văn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Hôm nay mọi người vất vả rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Tiểu Lưu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tuy rất mệt nhưng rất mãn nguyện. Em còn xin được chữ ký của Lâm Đan nữa.】</p><p style="text-align: justify; margin-bottom: 0.9em">Trong nhóm trò chuyện rôm rả không ngớt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lướt xuống xem, thấy không ít người đăng ảnh góc chụp của Lâm Đan.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên tai vang lên tiếng gõ cửa kính xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hoàn hồn, quay đầu nhìn.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngoài cửa sổ xe có một người đang đứng.</p><p style="text-align: justify; margin-bottom: 0.9em">Người đó gõ nhẹ lên cửa kính.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lập tức mở cửa bước xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải Lâm Đan.</p><p style="text-align: justify; margin-bottom: 0.9em">Là Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sững người mất hai giây:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường mặc đồ ở nhà, áo len rộng màu nâu, quần dài màu xám.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nhìn ra là nhãn hiệu gì, nhưng chỉ cần nhìn chất liệu cũng biết rất cao cấp, mềm mại và thoải mái.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bỗng cảm thấy Lâm Nhược Đường rất hợp làm người đại diện cho các quảng cáo đồ ngủ, đồ mặc ở nhà. Hiệu quả chắc chắn sẽ rất tốt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Đan còn phải một lúc nữa. Đã tới rồi sao không vào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi tưởng trong nhà không có ai."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói với nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vào đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đi theo phía sau cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến trước cửa, nàng thấy trên sàn có một đôi dép bông màu đỏ.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây nàng mang dép dùng một lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn đang chần chừ thì nghe Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Có cần tôi giúp cô thay giày không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lập tức đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không cần."</p><p style="text-align: justify; margin-bottom: 0.9em">Lại còn chuẩn bị sẵn cho nàng nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Chắc không phải Lâm Đan chuẩn bị.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ là...</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ hơi lãng phí một chút.</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao sau này nàng cũng sẽ không tới đây nhiều lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thay dép rồi đi theo Lâm Nhược Đường vào biệt thự.</p><p style="text-align: justify; margin-bottom: 0.9em">Khoảng năm, sáu giờ chiều, đèn chùm pha lê trong phòng khách đều đã bật, cả căn phòng sáng rực.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ liếc nhìn Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Ở riêng với cô, nàng luôn có một cảm giác ngượng ngùng khó diễn tả.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng không nói rõ được.</p><p style="text-align: justify; margin-bottom: 0.9em">Dù thế nào cũng thấy không tự nhiên.</p><p style="text-align: justify; margin-bottom: 0.9em">Đang định tìm chuyện gì đó để xoa dịu bầu không khí thì Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Muốn uống gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Gì cũng được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bưng một tách trà đưa cho nàng, cúi đầu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô căng thẳng lắm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngơ ngác:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô mang dép ngược rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức đỏ bừng cả mặt, cúi đầu xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Lại nghe Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tôi đùa thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: "..."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng siết chặt tách trà trong tay, cười gượng, khóe môi khẽ giật:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ha ha."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không buồn cười sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Buồn cười chỗ nào chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ miễn cưỡng đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Buồn cười."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bĩu môi, khẽ cúi đầu rồi lén trợn mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt Lâm Nhược Đường khẽ hạ xuống, nhìn thấy mắt cá chân của Thời Vụ hơi co lại. Nàng đang rất căng thẳng, cũng rất bối rối.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thong thả nhấp một ngụm trà rồi thu ánh mắt về.</p><p style="text-align: justify; margin-bottom: 0.9em">Không bao lâu sau, ngoài cửa biệt thự có tiếng động.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩng đầu lên, thấy Lâm Đan ôm một chiếc thùng carton lớn xuất hiện ở cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Còn chưa vào đến nơi, cô đã gọi lớn:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị, chị! Chị mau tới giúp em với!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không nhúc nhích.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đặt tách trà xuống, bước nhanh tới đón lấy chiếc thùng lớn trong tay Lâm Đan.</p><p style="text-align: justify; margin-bottom: 0.9em">Nó rất nặng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng không ngờ lại nặng đến vậy. Tay vừa trượt một cái, suýt nữa làm rơi.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc ấy, một cánh tay từ bên cạnh vững vàng đỡ lấy phần nặng hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Một tay Lâm Nhược Đường vẫn cầm tách trà, tay còn lại đang giúp nàng đỡ chiếc thùng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ mấp máy đôi môi mỏng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không có gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Khoảng cách giữa hai người rất gần.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong tầm mắt còn lại của Lâm Nhược Đường là chiếc cổ trắng nõn hơi nghiêng của Thời Vụ, xương quai xanh nổi rõ, làn da trắng mịn.</p><p style="text-align: justify; margin-bottom: 0.9em">Trên người nàng thoang thoảng hương thơm nhè nhẹ.</p><p style="text-align: justify; margin-bottom: 0.9em">Không nhầm thì là mùi chanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhớ khi trước từng ở trong phòng của nàng, thấy có hai chai nước hoa hương chanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc Thời Ánh Xuân vào dọn phòng còn từng trêu Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Mẹ sắp bị mùi chanh ướp thành người chanh luôn rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bĩu môi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Mùi chanh thơm mà, rất thơm. Đây là mùi hương cơ thể của con!"</p><p style="text-align: justify; margin-bottom: 0.9em">Quả thật là mùi chanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Bao nhiêu năm rồi, Lâm Nhược Đường vẫn còn nhớ rõ mùi hương ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan xoa xoa cánh tay:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Mệt chết em rồi. Chị, giúp em!</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thấy chiếc thùng này khá nặng, chắc Lâm Đan ôm cũng đủ mệt.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Để ở đâu? Chị mang vào giúp em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy chị để vào phòng em nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ôm chiếc thùng. Vì tầm nhìn bị che khuất nên đi không được thuận lắm.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan chạy lon ton phía trước dọn chỗ trong phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đi theo sau.</p><p style="text-align: justify; margin-bottom: 0.9em">Đột nhiên dưới chân như đá phải thứ gì đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Cơ thể nàng nghiêng đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngay sau đó cổ tay bị Lâm Nhược Đường nắm lấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lập tức đứng vững lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Lâm Nhược Đường đặt tách trà lên bàn rồi nhận lấy chiếc thùng từ tay nàng, chỉ vài bước đã mang tới trước cửa phòng Lâm Đan.</p><p style="text-align: justify; margin-bottom: 0.9em">Người này...</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng phía sau cô, lần này không trợn mắt nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan nhường đường để Lâm Nhược Đường đặt chiếc thùng xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đi theo phía sau hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đây là gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nàng trong trẻo, vì nói chậm nên tạo cảm giác bình yên mà dịu dàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàn toàn khác với chất giọng lạnh lùng của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan cười đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đây là thư fan gửi cho em. Em đã mang về một phần. Quà vẫn còn ở phòng làm việc, nhiều quá không mang hết được nên em đem thư về trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Em đều đọc hết sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Mỗi lần anti-fan lên mạng chửi em, em sẽ đọc."</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là biết cách giữ cân bằng tâm lý.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hay thật."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan hí hửng chạy đến bên cạnh Thời Vụ, huých nhẹ Lâm Nhược Đường sang một bên rồi khoác lấy cánh tay nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hôm nay em vui lắm. Buổi hoạt động thành công ngoài mong đợi. Đặc biệt là đoạn video đó, làm em khóc luôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đã xem livestream hiện trường.</p><p style="text-align: justify; margin-bottom: 0.9em">Quả thật rất thành công.</p><p style="text-align: justify; margin-bottom: 0.9em">Mấy chủ đề hot trên mạng đều liên quan đến Ưu Nhạc.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Buổi hoạt động do một tay chị gây dựng nên. Chị còn chưa tham gia xong đã nghỉ việc, chị có thấy tiếc không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Buổi hoạt động là thành quả chung của toàn bộ đồng nghiệp trong bộ phận, không phải công sức của riêng chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường liếc nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan chợt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"À đúng rồi, hôm nay em gặp vợ cũ của chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan chớp chớp mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">-"À không, là sắp thành vợ cũ mới đúng. Em nhớ chị từng nói cô ấy ngoại tình mà? Vậy chị định ly hôn với người ấy đúng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vốn không muốn nói về chuyện riêng tư như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng sự quan tâm trong mắt Lâm Đan gần như tràn ra ngoài.</p><p style="text-align: justify; margin-bottom: 0.9em">Không hiểu sao, hai người họ nói chuyện một hồi là lại chuyển sang đề tài này.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hôm nay chị đã đề nghị ly hôn với chị ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan lập tức nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy thì đúng rồi, gọi là vợ cũ tương lai."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"..."</p><p style="text-align: justify; margin-bottom: 0.9em">Lối suy nghĩ nhảy cóc này, nàng thật sự theo không kịp.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thật ra ly hôn cũng chẳng có gì không tốt. Hồi mẹ em mang thai em, phát hiện người đàn ông khốn đó ngoại tình, mẹ em lập tức ly hôn. Em thấy đó là quyết định đúng đắn nhất mà bà từng đưa ra. Chị, tin em đi, đây cũng sẽ là quyết định đúng đắn nhất của chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe lời an ủi của cô, Thời Vụ khẽ cúi đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cảm ơn em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Khách sáo gì chứ. Lát nữa chị phải ăn nhiều một chút nhé. Có no bụng mới có sức tiếp tục chiến đấu!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ăn... ở nhà sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải ra ngoài à?</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải tụ tập với bạn bè sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Ăn ngay ở đây?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng vậy. Ăn ở nhà. Sao thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chỉ có chúng ta thôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bạn em trưa nay đã tổ chức sinh nhật cho em rồi. Đoàn phim cũng tụ tập từ sáng. Chị không thích ăn cơm ở nhà à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vội xua tay:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không, không đâu. Chị chỉ sợ làm phiền mọi người thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan cười rạng rỡ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sao lại phiền được chứ. Chị chịu đến mừng sinh nhật em, em vui còn không hết ấy!"</p><p style="text-align: justify; margin-bottom: 0.9em">Niềm vui của cô hiện rõ trên gương mặt.</p><p style="text-align: justify; margin-bottom: 0.9em">Nó cũng làm tan đi sự gượng gạo của Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường từ đầu đến cuối đều không lên tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cảm giác hiện diện của cô quá mạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Mỗi khi Thời Vụ mỉm cười với Lâm Đan, ánh mắt vô tình lướt qua Lâm Nhược Đường thì lại thấy cô đang quang minh chính đại nhìn mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt ấy khiến Thời Vụ vô thức đứng thẳng người.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị, tối nay em muốn ăn hải sản."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tự làm đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan bĩu môi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy em tự làm thì chị phải ăn hết đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lạnh nhạt liếc cô một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan lập tức làm mặt quỷ, tỏ vẻ "em nấu thì chị phải ăn".</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường im lặng hai giây rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vào rửa rau."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan liền kéo Thời Vụ vào bếp phụ giúp.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa rửa hải sản vừa tò mò hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Đan nấu ăn khó ăn lắm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bình thản đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không khó ăn. Chỉ là ăn xong sẽ phải vào bệnh viện thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"..."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe hai người nói vậy, Lâm Đan không phục:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Lần đó chỉ là ngoài ý muốn thôi. Thịt chưa chín chứ có phải em cố ý đâu. Lát nữa món tôm hấp để em làm, đảm bảo..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cắt lời:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Để chị làm cho."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan tủi thân:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị cũng không tin em sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không phải. Hôm nay em là nhân vật chính, nào có chuyện để nhân vật chính vào bếp."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan lập tức vui vẻ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đúng ha. Vậy hôm nay em sẽ được thưởng thức tay nghề của chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ thở phào.</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra nàng cũng không biết làm món tôm hấp.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng chẳng phải chỉ cần cho gia vị vào rồi đem hấp là được sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng khá tự tin.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đứng bên cạnh chuẩn bị nguyên liệu, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Biết làm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không biết."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">-"..."</p><p style="text-align: justify; margin-bottom: 0.9em">Tối nay chắc phải chuẩn bị vào bệnh viện một chuyến rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nhưng tôi thấy chắc cũng không khó."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cười, nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Làm đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bị cô nhìn như vậy, cả người không được tự nhiên.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng quay mặt đi, lại thấy Lâm Nhược Đường vẫn nhìn mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô..."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Biết dùng nồi hấp không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ biết dùng.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây nàng thường hấp bánh bao làm bữa sáng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nồi hấp nhà Lâm Nhược Đường khác hẳn cái nàng từng dùng, hiện đại quá mức.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng tìm mãi cũng không thấy nút bấm ở đâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đưa tay từ phía sau người nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Khoảng cách bất ngờ kéo gần khiến Thời Vụ cứng cả người.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường tiện tay chạm lên màn hình.</p><p style="text-align: justify; margin-bottom: 0.9em">Thì ra là màn hình cảm ứng.</p><p style="text-align: justify; margin-bottom: 0.9em">Một cái nồi hấp mà cũng hiện đại đến mức này sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thầm than trong lòng rồi buột miệng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Lâm tổng đúng là lợi hại. Đến cái nồi hấp cũng lợi hại như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhướng mày:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không biết khen thì khỏi cần khen. Dù sao cô cũng nghỉ việc rồi, không cần lấy lòng tôi nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không phải lấy lòng cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Dù đã nghỉ việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng lỡ sau này công việc mới vẫn phải hợp tác với Lâm Thái thì sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Nói vài câu dễ nghe cũng chẳng mất gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe vậy, Lâm Nhược Đường có vẻ rất vui.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nhìn Thời Vụ rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy cô nói thử xem, tôi lợi hại ở chỗ nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"..."</p><p style="text-align: justify; margin-bottom: 0.9em">Có cần truy đến cùng như vậy không?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đành đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Nấu ăn rất ngon."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cười hai tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đành cứng đầu tiếp tục pha nước chấm.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây khi giảm cân, nàng thường làm các món salad nguội nên cũng từng pha không ít loại nước sốt.</p><p style="text-align: justify; margin-bottom: 0.9em">Theo nàng thì cũng na ná nhau, cứ nếm rồi điều chỉnh một chút là được.</p><p style="text-align: justify; margin-bottom: 0.9em">May mà chỉ là tôm hấp.</p><p style="text-align: justify; margin-bottom: 0.9em">Phức tạp hơn chút nữa thì nàng thật sự bó tay.</p><p style="text-align: justify; margin-bottom: 0.9em">Phần hải sản còn lại đều do Lâm Nhược Đường xử lý.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ và Lâm Đan chỉ phụ bày biện, bưng đĩa và đưa gia vị.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong lúc chờ đồ ăn, Lâm Đan kéo Thời Vụ ra phòng khách, mở TV rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị có muốn xem phim gì không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vốn không nghiên cứu phim ảnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhìn bộ phim hiện lên đầu tiên trên trang chủ rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bộ này thì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan lập tức lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không được. Diễn viên chính là bạn em, cứ nhìn thấy mặt cô ấy là em bị tụt mood."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"..."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan chọn một bộ khác:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Bộ này được đấy, phim trinh thám. Bình thường chị có xem thể loại này không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thỉnh thoảng."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vốn không có thời gian xem phim.</p><p style="text-align: justify; margin-bottom: 0.9em">Chủ yếu xem các video phân tích tóm tắt phim nhiều hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy xem bộ này."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mỉm cười rồi quay đầu nhìn về phía bếp.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đang nấu ăn.</p><p style="text-align: justify; margin-bottom: 0.9em">Ống tay áo sơ mi được xắn đến khuỷu tay. Vì áo khá rộng nên còn gập thêm một lớp ở khớp tay.</p><p style="text-align: justify; margin-bottom: 0.9em">Đoạn cẳng tay lộ ra trắng trẻo mà săn chắc.</p><p style="text-align: justify; margin-bottom: 0.9em">Động tác nấu nướng của cô rất nhanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ trong chốc lát, Thời Vụ đã thấy một đĩa nguyên liệu được cắt xong đặt sang bên cạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cực kỳ sạch sẽ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc nãy trong bếp, Thời Vụ để ý thấy sau mỗi lần cắt xong một món, cô đều cẩn thận rửa dao và thớt một lượt, không hề qua loa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi Lâm Đan:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị em có phải bị chứng sạch sẽ quá mức không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan ngẩng đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đâu có. Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không có gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan lại cúi đầu tiếp tục chiến đấu với điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai tiếng sau, cả ba mới ngồi vào bàn ăn.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngoại trừ đĩa tôm hấp do Thời Vụ làm, tuy màu sắc và hương vị đều không tệ...</p><p style="text-align: justify; margin-bottom: 0.9em">Những món còn lại quả thực có thể gọi là tác phẩm nghệ thuật.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chỉ muốn giấu luôn đĩa tôm mình làm đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thế mà Lâm Nhược Đường còn trịnh trọng giới thiệu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Đan, đây là tay nghề của giám đốc Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"..."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vô thức siết chặt đôi đũa.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan nghe vậy liền gắp một con tôm, bóc vỏ, nếm thử rồi quay sang nói với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ừm, ngon lắm. Tôm rất tươi, rất ngọt."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu, có chút không tin:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thật sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan bóc thêm một con cho nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nếm thử.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là hơi ngọt và rất tươi.</p><p style="text-align: justify; margin-bottom: 0.9em">Hình như còn có thêm vài loại gia vị khác nên thịt tôm càng mềm và ngon hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao cũng không phải nàng cho vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Là Lâm Nhược Đường thêm sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Quả nhiên người này rất kén ăn.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhờ có Lâm Đan, Thời Vụ được thưởng thức một bữa hải sản thịnh soạn.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai hôm nay khẩu vị của nàng khá kỳ lạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lúc chẳng muốn ăn gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lúc lại thấy món gì cũng ngon.</p><p style="text-align: justify; margin-bottom: 0.9em">Tối qua ăn hai bát sủi cảo.</p><p style="text-align: justify; margin-bottom: 0.9em">Hôm nay lại ăn đủ loại tôm với cua mà vẫn còn thấy chưa đã.</p><p style="text-align: justify; margin-bottom: 0.9em">Không ngờ lúc này nàng vẫn có khẩu vị tốt như vậy, còn ăn được nhiều đến thế.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng không biết nên vui hay nên lo cho bản thân.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan ôm bụng than:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chị Lâm lại sắp mắng em rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bình thản nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Biết mình sẽ tăng cân thì ăn ít lại."</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan phản đối:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Hôm nay là sinh nhật em. Em vui, em phải ăn thật nhiều."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mỉm cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Gương mặt thanh tú dịu dàng như hoa sen mới nở, vừa đẹp vừa yên tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Đột nhiên nàng nhớ ra điều gì đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đứng dậy đi đến ghế sofa, lấy trong túi xách ra một hộp quà đã được gói cẩn thận.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên trong là chiếc dây chuyền nàng đã chọn.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đưa cho Lâm Đan:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Tiểu Đan, quà sinh nhật của em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan kinh ngạc.</p><p style="text-align: justify; margin-bottom: 0.9em">Đôi mắt sáng rực:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cho em sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Biểu cảm của cô quá chân thật.</p><p style="text-align: justify; margin-bottom: 0.9em">Hôm nay hẳn cô đã nhận vô số quà và lời chúc.</p><p style="text-align: justify; margin-bottom: 0.9em">Thế nhưng khi nhận món quà của Thời Vụ, cô vẫn xúc động đến mức hai má đỏ ửng, mỉm cười hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Thật sự là cho em sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng bị niềm vui của cô lây sang.</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi khẽ cong lên:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Ừm, hy vọng em thích."</p><p style="text-align: justify; margin-bottom: 0.9em">-"Chắc chắn thích!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan nhận lấy hộp quà rồi mở ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên trong là một sợi dây chuyền bạch kim.</p><p style="text-align: justify; margin-bottom: 0.9em">Mặt dây là một chú hổ nhỏ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan tuổi Dần nên cực kỳ thích.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô áp mặt dây lên trước ngực rồi hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đẹp không? Đẹp không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đẹp."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Đan vui vẻ nhảy chân sáo vào phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn bóng lưng đầy hứng khởi của cô, màn u ám trong lòng Thời Vụ cũng tan đi không ít.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là niềm vui có thể lây lan.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ mỉm cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngồi đối diện nàng bỗng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vì sao cô lại tặng quà sinh nhật cho Tiểu Đan?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn sang cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong chốc lát không hiểu cô muốn hỏi điều gì nên cẩn thận đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vì hôm nay là sinh nhật Tiểu Đan, mà đúng lúc tôi biết."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Biết sinh nhật thì sẽ tặng quà?"</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng phải vậy sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không dám hỏi lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hắng giọng, khẽ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vâng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vậy vì sao cô không tặng quà sinh nhật cho tôi? Hai hôm trước là sinh nhật tôi, cô cũng biết mà?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sững người nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Cô không biết sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Đôi mắt cô nhìn thẳng vào nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dưới ánh nhìn ấy, Thời Vụ rất khó nói dối.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chỉ đành đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sau này tôi mới biết."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường chậm rãi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Sau này biết rồi thì cũng là biết. Vậy tại sao không tặng quà cho tôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Vì đã qua sinh nhật của cô rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Qua rồi vẫn có thể bù."</p><p style="text-align: justify; margin-bottom: 0.9em">Còn có thể như vậy sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cố nặn ra một nụ cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn vẻ mặt mất tự nhiên của nàng rồi bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đùa thôi, giám đốc Thời không để ý chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thở phào:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Không để ý. Tất nhiên là không."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Đã không để ý, vậy món quà đó... cô bù cho tôi được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">-"..."</p><p style="text-align: justify; margin-bottom: 0.9em">Quả nhiên người càng có tiền càng biết cách "đòi quà".</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bật cười, khẽ gật đầu rồi cắn môi đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">-"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Bù!</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng sẽ bù!</p><p style="text-align: justify; margin-bottom: 0.9em">Bù ngay bây giờ luôn!!!</p><p style="text-align: justify; margin-bottom: 0.9em">⸻</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các thiên thần đã tặng 14 Bá Vương Phiếu và 258 chai Dinh Dưỡng Dịch~</p><p style="text-align: justify; margin-bottom: 0.9em">Đoạn nhỏ:</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: "Từng thấy có người phát ngẫu nhiên một trăm bao lì xì chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: "Sau này thấy nhiều rồi sẽ quen."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: "......"</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 26, 'Nói ra', '<p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu ra khỏi phòng, thấy Thời Vụ và Lâm Nhược Đường đang trò chuyện rất vui vẻ. Cô nàng đi tới, hỏi hai người:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hai người đang nói chuyện gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu lại, Lâm Nhược Đường đã lên tiếng trước:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không nói gì cả. Giám đốc Thời biết sinh nhật chị là hai ngày trước nên nói muốn tặng bù cho chị một món quà."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, cô đứng dậy đi pha cà phê, để lại Thời Vụ đứng phía sau trợn mắt há miệng.</p><p style="text-align: justify; margin-bottom: 0.9em">Quả nhiên là nhà tư bản, mánh khóe đúng là sâu. Câu này nghe cứ như nàng chủ động mở miệng đề nghị vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn sang Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sao? Chị muốn mua quà cho chị ấy à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đón lấy ánh mắt nhiệt tình của cô nàng, rơi vào thế cưỡi hổ khó xuống, đành gật đầu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chỉ là chị không biết Lâm tổng thích gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị ấy kén chọn lắm. Em nói chị nghe, tặng trang sức thì không được, chị ấy bảo không hợp gu; tặng túi xách, chị ấy bảo tục; tặng mỹ phẩm, chị ấy bảo không dám dùng. Chị Thời Vụ, chị định tặng chị ấy thứ gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Ban đầu Thời Vụ định tặng một sợi dây chuyền giống của Lâm Châu. Bây giờ nghe cô      nàng nói vậy, tám phần Lâm Nhược Đường nhận được quà sẽ buông một câu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời đây là không có ý tưởng mới, hay là không có thành ý?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đau đầu. Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Để em góp ý cho chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn chưa kịp cảm ơn, Lâm Châu đã nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hay là chị cũng tự làm cho chị ấy một món đồ thủ công đi. Gói nguyên liệu lần trước của em vẫn còn nhiều lắm, chị có thể làm cho chị ấy một cái móc treo."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Móc treo?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Móc treo gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Móc chìa khóa hay móc điện thoại đều được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thử tưởng tượng cảnh Lâm Nhược Đường ra ngoài cầm điện thoại, bên trên treo một con mèo nhỏ lông xù; hoặc khi cô nghe điện thoại, món đồ treo áp vào gương mặt lạnh như băng của cô. Nghĩ thế nào cũng thấy rợn người, lông tơ trên người Thời Vụ đều dựng đứng lên. Nàng lập tức lắc đầu khéo léo từ chối, nhưng Lâm Châu lại vô cùng nhiệt tình:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị! Chị Thời Vụ nói muốn tặng chị một cái móc treo!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn chưa kịp thốt ra lời, Lâm Nhược Đường đã ngẩng đầu lên từ phía sau máy pha cà phê, nhìn hai người rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được thôi, vậy thì tôi xin cảm ơn Giám đốc Thời trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải chứ, cô ấy thật sự định nhận sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó Thời Vụ nghĩ lại, thật ra cũng chẳng có gì. Dù gì người ta cũng đâu nói nhất định sẽ treo lên chìa khóa hay điện thoại. Quà đã tặng rồi, dùng thế nào là chuyện của Lâm Nhược Đường. Nghĩ vậy, nàng bỗng thấy nhẹ nhõm hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hớn hở chạy về phòng, ôm ra một đống nguyên liệu, nói với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật ra em cũng mới học cách đây hai tháng thôi, là để làm con mèo đó tặng chị em."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe cô nhắc đến mèo, Thời Vụ bất giác nghĩ đến hình ảnh của Lâm Nhược Đường. Nàng vẫn rất khó tưởng tượng Lâm Nhược Đường sẽ nuôi mèo.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu chất đống nguyên liệu lên ghế sofa. Trên tivi vẫn đang chiếu phim, từ phim trinh thám đã chuyển sang phim hài. Cô vừa vui vẻ xem, vừa giới thiệu cho Thời Vụ cách sử dụng từng loại dụng cụ. Thời Vụ đột nhiên cảm thấy, quyết định làm móc treo đúng là không phải lựa chọn sáng suốt.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn món đồ nhỏ trước mặt, nàng vốn tưởng cũng giống lần trước, chỉ cần khâu vài mũi là xong. Không ngờ còn phải chú ý đủ thứ, đặc biệt là hình dáng và màu sắc, khiến nàng nhìn đến hoa cả mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vừa hướng dẫn vừa nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chỗ này thêm một chút màu vàng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vừa làm theo vừa hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Con mèo đó nhà hai người nuôi được bao nhiêu năm rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là chị em nuôi, cũng mấy năm rồi. Chị ấy cưng con mèo đó lắm, còn tự tay làm cho nó hai căn nhà mèo, đặt ở khu vườn phía sau."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói đến đây, Thời Vụ mới nhận ra mình vẫn chưa từng ra phía sau biệt thự. Căn biệt thự này rộng thật, chỉ riêng phòng khách và nhà bếp đã đủ để tham quan rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bình thường trong nhà đều là chị ấy dọn dẹp sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao nàng vẫn thường thấy Lâm Nhược Đường nấu ăn.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao có thể được. Vậy thì chị em chẳng phải mệt chết à? Nhà có người giúp việc, mỗi tuần đến một lần."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thật sự...</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ gì vậy chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra trước đây Triệu Hy Ngọc cũng từng nhắc đến chuyện thuê người giúp việc. Vì hai người đều bận công việc, cũng rất ít khi xuống bếp, có người giúp việc sẽ tiện hơn nhiều. Nhưng nàng cảm thấy căn nhà tân hôn hiện tại không thích hợp để có người giúp việc ở lại lâu dài, không đủ rộng rãi, nên đã bàn với Triệu Hy Ngọc rằng sau này đổi sang căn hộ lớn hơn rồi hãy tính tiếp.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu ghé sát tai Thời Vụ, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy? Chị thấy chị em rất siêng năng à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bên tai Thời Vụ bị hơi thở của cô nàng làm nhột, nàng khẽ rụt vai, đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng đúng là rất chăm chỉ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Dù sao cũng giỏi hơn em. Tất cả mọi thứ trong căn nhà mèo kia đều do chị ấy tự tay làm, chị ấy còn biết làm mộc nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thật lòng khâm phục.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lợi hại đến vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Khả năng làm thủ công max luôn!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thực sự không thể tưởng tượng nổi. Trước đây, nàng vẫn luôn cho rằng Lâm Nhược Đường là kiểu người chỉ cần động miệng chỉ đạo. Hình tượng của một người ở địa vị cao đã ăn sâu trong lòng nàng từ trước, nên ít nhiều cũng bị méo mó. Càng tiếp xúc, nàng càng nhận ra con người thật của cô khác xa với những gì mình từng tưởng tượng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu khẽ "a" một tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sai rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu, tay lệch sang bên. Đầu kim xuyên thẳng qua đầu ngón tay. Cánh tay nàng theo phản xạ giật lên, hất trúng chiếc túi đặt trên bàn trà. Túi rơi xuống đất. Vì lúc nãy vừa lấy điện thoại ra nên miệng túi vẫn mở, đồ bên trong lập tức văng tung tóe.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lo lắng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có phải chị đâm trúng tay rồi không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chỉ đâm một chút thôi, không sao."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vừa định cúi xuống nhặt đồ thì một bóng người đã khom lưng trước nàng, giúp nàng nhặt chiếc túi lên, rồi gom hết những món đồ rơi vãi bỏ lại vào trong.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ có chút ngượng ngùng.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đặt chiếc túi lên bàn trà, bình thản đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lấy một miếng băng cá nhân. Thời Vụ cảm thấy chuyện bé xé ra to, nhưng Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lỡ một lát nữa lại đâm trúng thì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ cũng có lý, Thời Vụ liền để cô nàng dán băng lên đầu ngón tay mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngồi xuống bên cạnh. Trên tivi, diễn viên phim hài đang đọc lời thoại, vẻ mặt khoa trương. Cô liếc nhìn Thời Vụ bằng khóe mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay lưng về phía cô. Hôm nay nàng mặc một chiếc sơ mi đen phối với quần cạp cao màu nâu cà phê, phần eo được tôn lên càng thêm thon gọn. Áo sơ mi là kiểu dáng cơ bản, cổ áo hơi rộng, cúc áo được cài đến vị trí xương quai xanh. Mỗi khi nàng cúi đầu, xương quai xanh lại thấp thoáng hiện ra. Làn da trắng ngần, đường cong nơi cổ thon dài mềm mại. Mái tóc được búi gọn nhưng không quá cầu kỳ, vài lọn tóc buông xuống vừa vặn chạm tới gáy. Mỗi khi nàng khẽ lắc đầu, đuôi tóc lại lay động rất nhẹ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường dùng thìa khuấy cà phê trong tách, tạo thành những vòng xoáy nhỏ, rồi khẽ nhấp một ngụm.</p><p style="text-align: justify; margin-bottom: 0.9em">Bầu không khí trong phòng khách không thể nói là quá ấm áp, nhưng quả thật đã có hơi thở hơn trước.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vốn là người hướng ngoại. Chỉ cần nhìn số lượng bạn bè của cô nàng là biết. Nhưng cô nàng chưa từng dẫn bạn về biệt thự.</p><p style="text-align: justify; margin-bottom: 0.9em">Thứ nhất, trong giới không ai biết mối quan hệ giữa cô và Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Thứ hai, cô biết Lâm Nhược Đường không thích người lạ bước vào nhà.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lần cô tuyển một trợ lý mới, nhờ người đó giúp mang đồ vào nhà. Hôm ấy Lâm Nhược Đường đang nấu ăn. Người trợ lý nhìn thấy thì vô cùng kinh ngạc, cứ bám theo hỏi hết câu này đến câu khác. Sau khi biết đó là chị gái của cô thì càng hứng thú hơn, ánh mắt nhìn Lâm Nhược Đường sáng rực.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lúc ấy không nói gì. Nhưng ngay ngày hôm sau, khi cô đi làm thì đã không còn gặp người trợ lý đó nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Ban đầu, Lâm Châu cũng không cảm thấy Thời Vụ có gì đặc biệt. Nhưng biểu hiện của Lâm Nhược Đường rõ ràng khác thường. Có lẽ vì trước kia cô quá lạnh nhạt, nên chỉ cần có một chút thay đổi cũng đủ để Lâm Châu nhận ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy nguyên nhân là gì?</p><p style="text-align: justify; margin-bottom: 0.9em">Là vì mẹ của Thời Vụ từng là bác sĩ tâm lý của Lâm Nhược Đường, từng chăm sóc cô rất nhiều sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Điều đó quả thật có khả năng.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi ấy, Lâm Nhược Đường không gặp bất kỳ ai, không ăn không ngủ, còn ngất xỉu hai lần phải nhập viện truyền nước suốt một tuần. Sau khi xuất viện về nhà, cô không chịu nói chuyện với ai. Bà nội sốt ruột đến mức chạy khắp nơi tìm bác sĩ.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó mọi chuyện diễn ra thế nào, Lâm Châu cũng không rõ. Cô chỉ nhớ sau khi Lâm Nhược Đường trở về từ Hà Kiều, cả con người như hoàn toàn thay đổi, dần dần bình ổn lại, còn nói muốn ra nước ngoài du học. Bà nội đồng ý. Khi đó Lâm Châu không yên tâm nên đã đi cùng cô sang nước ngoài.</p><p style="text-align: justify; margin-bottom: 0.9em">Về Hà Kiều và vị bác sĩ tâm lý kia, Lâm Nhược Đường chưa từng nhắc đến, cô cũng chưa từng hỏi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cô biết, Lâm Nhược Đường vẫn luôn rất biết ơn vị bác sĩ tâm lý ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy nên việc Lâm Nhược Đường đối xử đặc biệt với Thời Vụ bây giờ là vì đơn thuần có hứng thú, hay là vì muốn báo đáp?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nghĩ mãi vẫn không tìm ra đáp án. Đôi mắt xinh đẹp của cô nàng hết nhìn Thời Vụ lại nhìn sang Lâm Nhược Đường, nhưng vẫn không nhìn ra được điều gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ mãi cũng không ra nguyên do.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng khép hờ mắt, nghiêng người về phía Thời Vụ. Thời Vụ đang chăm chú xỏ kim, thấy cô đưa tay dụi mắt thì mỉm cười hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm nay em mệt lắm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu mở mắt ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Hàng mày của Thời Vụ thanh tú, ngũ quan thật sự rất đẹp. Lâm Châu từng hợp tác với không ít nghệ sĩ, người trang điểm đậm, người trang điểm nhạt đều có, nhưng cô rất khó phân loại gương mặt của Thời Vụ thuộc kiểu nào. Chỉ cảm thấy dù là trang điểm nhạt hay đậm, mọi đường nét trên gương mặt nàng đều hài hòa một cách hoàn hảo, tựa như được trời cao ưu ái. Kết hợp với khí chất thanh nhã ấy, khi làm việc nàng mang phong thái của một nữ lãnh đạo mạnh mẽ, còn lúc riêng tư lại dịu dàng hơn đôi chút, đặc biệt là khi nàng mỉm cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong lòng Lâm Châu bỗng dâng lên một cảm giác mềm mại, ấm áp như đang ngâm mình trong làn nước ấm.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng bất giác nhích người tới gần, định dựa sát vào Thời Vụ thì bỗng bị ai đó nắm lấy cánh tay. Không biết từ lúc nào Lâm Nhược Đường đã đứng phía sau cô, túm lấy cổ áo cô nàng. Cổ áo siết ngang cổ khiến cô nàng ho khẽ một tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường buông tay, bình thản nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tránh sang một chút, em che mất tầm nhìn của chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thật hay giả vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Chị ấy còn xem tivi nữa sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng phải chị ấy chỉ xem kênh tài chính thôi à?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu xoa bụng, lặng lẽ làm mặt quỷ với Lâm Nhược Đường. Thấy cô không để ý, cô nàng bèn nhích mông, ngồi sát lại cạnh Thời Vụ, vừa dè dặt quan sát phản ứng của Lâm Nhược Đường, vừa hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, sinh nhật chị là ngày nào vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị à? Chị sinh vào Rằm tháng Giêng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Rằm tháng Giêng à? Bảo sao chị tên là Thời Vụ. Thời Vụ, Thời Vụ, mười lăm tháng Giêng... Cái tên này đặc biệt thật."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhớ lại chuyện trước đây, mỉm cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật ra lúc đầu mẹ chị định đặt tên chị là Thời Thường."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu ngẩn ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời Thường?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời Ánh Xuân, Thường Anh. Đó là tên của mẹ chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu tò mò hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy sao chị không lấy tên là Thời Thường?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vì chị thấy khó nghe quá."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Rồi cô nàng bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"May thật."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhưng em thích cái tên hiện tại của chị hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng xoay người, hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chị thấy Thời Thường hay hay Thời Vụ hay hơn?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lười biếng liếc cô nàng một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng không thấy lạ. Lâm Nhược Đường sao có thể cùng họ bàn luận mấy chuyện như thế này chứ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cúi đầu tiếp tục xỏ kim thì điện thoại trong túi rung lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Là cuộc gọi của Dư Mạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bắt máy.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có chuyện gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt sốt ruột hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu đang ở đâu? đang ở cùng Triệu Hy Ngọc à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe giọng điệu có vẻ rất lo lắng, âm lượng cũng cao hơn bình thường vài phần.</p><p style="text-align: justify; margin-bottom: 0.9em">Tai Thời Vụ nóng bừng lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Âm thanh từ điện thoại đã truyền khắp phòng khách, đến cả tiếng tivi cũng không át nổi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cắn môi.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy cậu đang ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cười híp mắt, nói lớn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị Thời Vụ đang ở nhà em."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt sững người một lúc vì nghe thấy giọng người lạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó nghe Lâm Châu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là người bạn bác sĩ của chị sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt cũng đoán ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm Châu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừ. Hôm nay chẳng phải sinh nhật em ấy sao? Tôi đến chúc mừng sinh nhật."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe không liên quan đến Triệu Hy Ngọc, Dư Mạt mới thở phào nhẹ nhõm.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được rồi. Vậy tối nay cậu về không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về chứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu khẽ thở dài, không lên tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Rất nhanh sau đó, Thời Vụ cúp máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhìn thấy luật sư đã gửi cho mình mấy tin nhắn từ mười phút trước mà giờ mới để ý.</p><p style="text-align: justify; margin-bottom: 0.9em">Chắc là mải làm đồ thủ công quá nên không thấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng trả lời ngắn gọn rồi nhìn đồng hồ.</p><p style="text-align: justify; margin-bottom: 0.9em">Đã hơn mười giờ rưỡi.</p><p style="text-align: justify; margin-bottom: 0.9em">Không ngờ thời gian lại trôi nhanh đến vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai ngày nay nàng cứ sống trong trạng thái mơ màng, hoàn toàn không có khái niệm về thời gian.</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi sáng nói chuyện với luật sư xong, nàng ngồi ở quán cà phê một lúc, cảm giác như đã ngồi cả thế kỷ.</p><p style="text-align: justify; margin-bottom: 0.9em">Bây giờ chỉ ăn một bữa cơm mà đã mất năm sáu tiếng đồng hồ.</p><p style="text-align: justify; margin-bottom: 0.9em">Bảo sao Dư Mạt lại gọi điện giục.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn món đồ thủ công mới làm được một nửa, nói với Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị mang về nhà làm tiếp nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị định mang về làm à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng không còn sớm nữa. Chị mang về nhà làm, tiền nguyên liệu chị sẽ chuyển cho em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu xua tay.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đâu. Nhưng chị mang về thật sao? Chị đâu biết làm. Hay mai chị lại qua nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn ra sự yêu mến và nhiệt tình chân thành của cô nàng nhưng lại không tiện nhận.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng mỉm cười lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bĩu môi, trông chẳng khác nào một đứa trẻ.</p><p style="text-align: justify; margin-bottom: 0.9em">Khách đến nhà, thế nào cũng không nỡ để khách đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng còn tỏ vẻ đáng thương:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sự không đến nữa sao? Khó lắm em mới có được một người bạn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em chẳng phải có rất nhiều bạn sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sáng nay Lâm Châu còn đăng Weibo, chín ô ảnh gần như không đủ chỗ cho đám bạn của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu im lặng vài giây rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không giống nhau. Chị không giống họ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng rất quý Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng quý đến đâu cũng không thể bỏ qua phép tắc.</p><p style="text-align: justify; margin-bottom: 0.9em">Đây dù sao cũng là nhà của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Hôm nay nàng đến dự sinh nhật Lâm Châu thì không sao, nhưng nếu cứ tiếp tục ở lại sẽ không thích hợp.</p><p style="text-align: justify; margin-bottom: 0.9em">Hơn nữa, cả tối nay Lâm Nhược Đường hầu như không nói gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Biết đâu trong lòng cô đã thấy không vui nhưng ngại nói ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hiểu ý, mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thôi nhé, chị về trước đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vẫn còn lưu luyến.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được rồi. Vậy chị nhớ gọi điện cho em bất cứ lúc nào nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về đến nhà nhớ gọi cho em một cuộc."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ biết đây chỉ là lời khách sáo nhưng cũng rất ấm lòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, chị biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Lâm Châu mới đứng ở cửa nhìn theo Thời Vụ bước ra ngoài, lên xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng chợt quay đầu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ơ? Chị, từ lúc nào trong nhà lại có thêm một đôi dép lê thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt cô nàng ra hiệu về đôi dép lê Thời Vụ vừa mang. Thật ra lúc xem phim cô đã để ý thấy đôi dép này không phải của mình, cũng không phải của Lâm Nhược Đường, trước đây chưa từng thấy, vừa nhìn đã biết là mới mua.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng cười hì hì hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị mua cho chị Thời Vụ à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mua cho em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu sững người, vẻ mặt kinh ngạc.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị mua dép lê cho em làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ nhướng mày.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quà sinh nhật."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Ai đời lại tặng dép lê làm quà sinh nhật chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Hơn nữa chẳng phải món quà đó là tặng cho cô sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Sao cuối cùng lại để Thời Vụ mang?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu không phục.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cái này không tính. Chị phải tặng em món khác."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không để ý đến cô, giơ tay khẽ gõ lên trán cô nàng một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lùi về sau hai bước, bĩu môi nhìn theo Lâm Nhược Đường đi vào trong.</p><p style="text-align: justify; margin-bottom: 0.9em">Phòng khách chỉ còn lại tiếng tivi, bỗng trở nên vắng lặng hơn hẳn.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng cũng chẳng còn tâm trạng xem tiếp, liền tắt tivi và đèn phòng khách rồi trở về phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngay khoảnh khắc bật đèn, cô nàng nhìn thấy trên bàn có một hộp quà.</p><p style="text-align: justify; margin-bottom: 0.9em">Chiếc hộp màu xanh lam đậm được thắt bằng một chiếc nơ bướm màu hồng.</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi vừa xụ xuống của Lâm Châu lập tức cong lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng bước nhanh tới, cầm chiếc hộp lên mở ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên trong là một chiếc đồng hồ nạm đá màu hồng.</p><p style="text-align: justify; margin-bottom: 0.9em">Mặt đồng hồ cũng là màu hồng nhạt, rất thiếu nữ.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên dưới hộp còn đặt một tấm thiệp.</p><p style="text-align: justify; margin-bottom: 0.9em">Trên đó chỉ viết bốn chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chúc mừng sinh nhật.】</p><p style="text-align: justify; margin-bottom: 0.9em">Nét chữ mạnh mẽ, hằn sâu qua mặt giấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Là chữ của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đã bỏ vào từ lúc nào?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu phấn khích nhảy cẫng tại chỗ, rồi chạy vội ra khỏi phòng, lao đến cửa phòng Lâm Nhược Đường gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bình thản đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nói đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu chẳng để ý thái độ của cô, mặt mày đầy hưng phấn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em thích chị nhất! Sau này em còn muốn làm em gái chị ở kiếp sau nữa!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không đáp.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vui vẻ quay về phòng, giơ cổ tay chụp liền mấy tấm ảnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Định đăng lên vòng bạn bè, chợt nhớ đến món quà Thời Vụ tặng, cô nàng đặt hai món cạnh nhau, tạo dáng rồi chụp thêm vài tấm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn chưa về đến nhà.</p><p style="text-align: justify; margin-bottom: 0.9em">Điện thoại liên tục rung lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong nhóm công ty có thông báo, Tống Kim cũng gọi điện cho nàng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời, bệnh của chị đỡ hơn chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sáng nay, điều nàng nói với Kỳ Mai là xin nghỉ việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Kỳ Mai không dám nói với người khác, chỉ thông báo ra ngoài rằng Thời Vụ xin nghỉ bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Đợt trước nàng vừa mới ốm, nên lý do này cũng không ai nghi ngờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Hôm nay có không ít đồng nghiệp nhắn tin, gọi điện hỏi thăm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hai tay nắm vô lăng, cũng đáp với Tống Kim:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đỡ nhiều rồi, cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Cuộc hôn nhân với Triệu Hy Ngọc...</p><p style="text-align: justify; margin-bottom: 0.9em">Há chẳng phải cũng là một trận bệnh nặng sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy mai chị đến công ty chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có lẽ sẽ đến."</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy đã bàn giao công việc cho Kỳ Mai nhưng vẫn còn rất nhiều việc chưa hoàn tất.</p><p style="text-align: justify; margin-bottom: 0.9em">Hơn nữa...</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cũng cần gặp Triệu Hy Ngọc một lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim yên tâm hơn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy thì tốt, mai em đợi chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe giọng nói dịu dàng của cô, Thời Vụ bỗng gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Tống."</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim vẫn cầm điện thoại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Dạ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ dừng một chút.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nghỉ ngơi sớm đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim cũng đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, Giám đốc Thời cũng nghỉ sớm nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Xe dừng hẳn dưới khu chung cư. Thời Vụ cúp máy, tựa người vào ghế lái, tắt đèn trong xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Phía trước là một màn đêm đen kịt.</p><p style="text-align: justify; margin-bottom: 0.9em">Bốn bề yên tĩnh đến lạ. Ánh đèn đường chỉ soi được một khoảng nhỏ, huống hồ đây lại là khu chung cư cũ, cách một quãng khá xa mới có một cột đèn, nên khi ngồi trong xe, Thời Vụ có cảm giác như đang ngồi giữa vực sâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Bóng tối bao trùm lấy nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc ấy, màn hình điện thoại bỗng sáng lên, ánh sáng chói mắt lóe qua.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lần tìm điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">Là cuộc gọi WeChat của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hơi nhíu mày, nhận cuộc gọi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đến đâu rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn tưởng cô gọi nhầm, nghi hoặc khẽ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm, về đến nhà chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vừa mới đến. Có chuyện gì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Dưới ghế sofa phòng khách vừa nãy có một thỏi son Dazzle, là của cô sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Tim Thời Vụ hẫng một nhịp.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Dazzle?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hạ thấp giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức kéo chiếc túi của mình lại, bật đèn trong xe lục tìm, nhưng không thấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là của tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Còn cần không? Nếu không thì tôi vứt đi."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cần!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lời vừa bật ra, đầu óc Thời Vụ mới kịp phản ứng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đau đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Sao lại đúng là thỏi son này bị rơi chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Mấy món mỹ phẩm khác mất cũng không sao, nhưng riêng thỏi này giá hơn hai nghìn tệ, nàng mới dùng đúng một lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Hơn nữa còn là nhờ người khác mua hộ, làm mất thì đúng là tiếc không chịu nổi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi qua lấy ngay."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi sắp ngủ rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy tôi qua lấy vào ngày mai."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu một hơi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật xin lỗi, lại làm phiền Lâm tổng rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Có vẻ tâm trạng của Lâm Nhược Đường khá tốt, giọng nói cũng dịu hơn thường ngày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần khách sáo, Giám đốc Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúp máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Chút buồn xuân thương thu vừa rồi như tan biến hết. Gió lạnh lùa tới khiến nàng tỉnh táo hơn. Nàng vừa bước xuống xe thì đã thấy một bóng người chạy tới.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đứng lại trước mặt nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao cậu xuống đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xuống đổ rác. Tôi đoán cậu sắp về nên tiện chờ cậu luôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nói, cậu ấy vừa đảo mắt nhìn quanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đang nhìn gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xem Triệu Hy Ngọc có đang núp đâu đó không."</p><p style="text-align: justify; margin-bottom: 0.9em">Tối qua Thời Vụ đã kể với Dư Mạt rằng Triệu Hy Ngọc từng đến đây. Liên tiếp hai tối bị Triệu Hy Ngọc tìm tới, Dư Mạt cũng cảnh giác thay nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị ấy chắc sẽ không tới đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt thở phào, nhìn chiếc túi giấy trên tay nàng rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đó là gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đồ thủ công."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt ngơ ngác:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ suýt nữa thì bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thế cũng tốt. Tìm chút việc để làm thì sẽ không suy nghĩ lung tung nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Hôm nay ở nhà Lâm Nhược Đường lâu như thế, nàng không hề nghĩ đến Triệu Hy Ngọc, cũng không nghĩ đến Triệu Tịnh và cha mẹ nhà họ Triệu.</p><p style="text-align: justify; margin-bottom: 0.9em">Bận rộn quả thật có ích.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu, hai người cùng lên tầng năm.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa vào nhà, Dư Mạt ngã phịch xuống sofa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đặt đồ xuống rồi đi tắm.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chiều nay cậu gặp luật sư rồi đúng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chiều nay gặp rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Luật sư nói thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đang soạn thảo thỏa thuận ly hôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tốc độ cũng nhanh thật."</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là rất nhanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi tắm xong bước ra khỏi phòng tắm, trên WeChat luật sư đã gửi cho nàng tệp thỏa thuận ly hôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ xác nhận đã nhận, trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Để tôi xem trước.】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cô Thời vẫn chưa nghỉ sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chưa đâu. Luật sư Diệp cũng chưa nghỉ ngơi à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">【Vẫn đang tăng ca. Cô xem trước các điều khoản đi, nếu có chỗ nào không hài lòng, tôi sẽ sửa cho cô.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được, cảm ơn.】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh đóng khung trò chuyện với Thời Vụ, rồi gửi thêm một bản thỏa thuận khác cho Lâm Nhược Đường, kèm theo tin nhắn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi đã tranh thủ tăng ca làm xong cho cậu. Bên phía nhà máy tôi cũng đã điều tra kỹ, chứng cứ đều đã thu thập đầy đủ. Nếu phía bên kia không đồng ý, chúng ta vẫn còn có thể nâng thêm điều kiện.】</p><p style="text-align: justify; margin-bottom: 0.9em">Vài phút sau.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ừm.】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lập tức gọi điện sang:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lần này phí đại diện của tôi có phải nên tăng lên mười phần trăm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thắng kiện rồi tính."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh cười mắng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đồ keo kiệt! Mà này, tôi gửi bản thỏa thuận cho cô Thời rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nhiều chuyện hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Rốt cuộc hai người là quan hệ gì vậy? Cô ấy ly hôn mà cậu còn quan tâm đến thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bình thản đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nếu cậu ly hôn, tôi cũng sẽ rất quan tâm."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Độc thân thì lấy đâu ra ly hôn?</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là đáng đời không có vợ!</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh khẽ hắng giọng, nghe Lâm Nhược Đường nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thêm vào thỏa thuận của cô ấy hai mươi phần trăm cổ phần của Ưu Lạc."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lập tức từ chối:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không thể nào. Cổ phần của Ưu Lạc đâu đứng tên Triệu Hy Ngọc."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thong thả nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đương nhiên là không thể. Nhưng ngay cả chuyện đổi suất ở bệnh viện lúc đó, cuối cùng chẳng phải cũng đã làm được sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh ngẫm nghĩ một lát rồi bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu Triệu Hy Ngọc nhìn thấy điều khoản này được thêm vào thỏa thuận ly hôn của Thời Vụ, chắc chắn sẽ cho rằng Thời Vụ bị thần kinh.</p><p style="text-align: justify; margin-bottom: 0.9em">Giống hệt như lúc đó, khi Thời Vụ biết được chuyện ở bệnh viện, nàng cũng từng cho rằng Triệu Hy Ngọc là kẻ thần kinh vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Đã đến lúc để Triệu Hy Ngọc nếm thử cảm giác ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh cầm điện thoại, cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vẫn là cậu cao tay. Mai tôi sẽ thêm điều khoản này vào."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không lên tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Yên tâm đi, tôi tuyệt đối sẽ không nói với cô Thời rằng cậu đang âm thầm giúp cô ấy phía sau."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi ngược lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tại sao không nói cho cô ấy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô hỏi Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi là nhà từ thiện à?"</p><p style="text-align: justify; margin-bottom: 0.9em">....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các thiên thần nhỏ đã tặng 8 Phiếu Bá Vương và 421 chai Dinh Dưỡng Dịch~</p><p style="text-align: justify; margin-bottom: 0.9em">⸻</p><p style="text-align: justify; margin-bottom: 0.9em">Phong bao lì xì ngẫu nhiên ×100, chụt chụt~</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi đâu phải Cận lão sư, làm gì phải làm học sinh ba tốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Cận Lão Sư: —"QAQ Thu Thu, em nhìn cô ấy đi!"</p><p style="text-align: justify; margin-bottom: 0.9em">——-</p><p style="text-align: justify; margin-bottom: 0.9em">Giải thích: đầu chương chắc mọi người sẽ thấy cái tên Lâm Châu xuất hiện, đây thực sự là sơ sót của mình, mình đã đối chiếu lại với bản gốc, tên nhân vật này phải dịch là Lâm Châu mới đúng chứ không phải Lâm Đan, tên Lâm Đan của bản mình nhận được bị sai về mặt chữ, mình phát hiện ra ở chương này. Tuy nhiên, ngoài tên nhân vật này thì tên nhân vật trưởng phòng Ưu Lạc vừa được Thời Vụ đề bạt phải dịch là Kỳ Mai chứ không phải Kỳ Văn. Qua đây, từ chương này trở về sau, mình sẽ dịch lại là Lâm Châu và Mỳ Mai. Còn ở những chương trước, mình sẽ tranh thủ chỉnh sửa lại tên 2 nhân vật này. Thành thật cáo lỗi vì sự sai sót này😔😔😔😔</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 27, 'Đợi em', '<p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quả thực không phải nhà từ thiện, cũng không có quá nhiều thời gian để dây dưa với Ưu Lạc. Với một trung tâm thương mại như vậy, sau khi điều tra, đánh giá kỹ lưỡng, vốn dĩ sẽ không bao giờ nằm trong danh sách đối tác của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Thế nhưng cô vẫn phá lệ, hết lần này đến lần khác cho Ưu Lạc cơ hội.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu nói lúc ban đầu, đúng là cô từng có ý định báo đáp ân tình, cũng muốn xem Thời Vụ sẽ lựa chọn thế nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu sau khi biết chuyện của Triệu Hy Ngọc, Thời Vụ vẫn lựa chọn tha thứ, vẫn quyết định hợp tác với bọn họ, vậy thì vì nể mặt Thời Vụ, hay nói đúng hơn là vì nể mặt Thời Ánh Xuân, cô sẽ điều vài thương hiệu vào Ưu Lạc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Thời Vụ đã không làm vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Lần gặp lại này, Thời Vụ điềm tĩnh hơn cô tưởng rất nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước kia, mỗi lần nhắc đến Thời Vụ, Thời Ánh Xuân đều đau đầu. Bà thường nói, kể từ sau khi Thường Anh rời đi, bà càng ngày càng không biết phải giao tiếp với con gái thế nào. Rõ ràng bản thân là bác sĩ tâm lý, vậy mà lại chẳng thể trò chuyện được với chính con gái mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ đến cũng thật buồn cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Lâm Nhược Đường lại không thấy vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Con người ta thường dễ nổi nóng nhất với người thân cận, bởi vì biết đối phương sẽ bao dung, sẽ tha thứ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chính là như thế.</p><p style="text-align: justify; margin-bottom: 0.9em">Bướng bỉnh, tùy hứng, ngang ngạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Giống hệt một chú bê con cố chấp, đâm đầu vào tường nam cũng nhất quyết không quay đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Ánh Xuân thường mắng nàng là...</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đồ đá thối."</p><p style="text-align: justify; margin-bottom: 0.9em">Quả thật là một hòn đá.</p><p style="text-align: justify; margin-bottom: 0.9em">Bao nhiêu năm trôi qua, cái cốt cách cứng đầu ấy vẫn chẳng thay đổi chút nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cúi đầu nhìn bản đề xuất hợp tác đặt cạnh máy tính. Cô lật vài trang, rồi tiện tay ném lại lên bàn làm việc, cầm cốc cà phê đi ra ngoài.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong phòng, Lâm Châu đang đi tới đi lui không biết bận rộn chuyện gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc Lâm Nhược Đường rót cà phê rồi đi ngang qua cửa phòng cô nàng, nghe thấy từ căn phòng hé mở vọng ra tiếng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chị về đến nhà rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bước chân cô khựng lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô liếc nhìn đồng hồ.</p><p style="text-align: justify; margin-bottom: 0.9em">Đã mười phút kể từ lúc cô gọi điện cho Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lên lầu mất đến mười phút sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị thấy bài đăng Moments của em rồi hả? Ôi, em chụp linh tinh thôi mà..."</p><p style="text-align: justify; margin-bottom: 0.9em">Cái giọng điệu ngượng ngùng pha chút làm nũng ấy khiến Lâm Nhược Đường khẽ nhíu mày. Cô quay về phòng làm việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Moments?</p><p style="text-align: justify; margin-bottom: 0.9em">Có gì trong đó sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Cô mở Moments của Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Có vài tấm ảnh được đăng lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Một chiếc đồng hồ cô tặng.</p><p style="text-align: justify; margin-bottom: 0.9em">Một sợi dây chuyền Thời Vụ tặng.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỹ thuật chụp ảnh của Lâm Châu khá tốt, hai món quà dưới ống kính đều lấp lánh rực rỡ.</p><p style="text-align: justify; margin-bottom: 0.9em">Đang định thoát ra, Lâm Nhược Đường chợt khựng lại một lát, cuối cùng bấm vào Moments của Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Khác hẳn tưởng tượng của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Không hề vắng vẻ.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngược lại còn khá phong phú.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ có điều...</p><p style="text-align: justify; margin-bottom: 0.9em">Toàn bộ đều là nội dung công việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Hôm qua không đăng.</p><p style="text-align: justify; margin-bottom: 0.9em">Hôm kia cũng không.</p><p style="text-align: justify; margin-bottom: 0.9em">Ba hôm trước là thông báo hoạt động của trung tâm thương mại.</p><p style="text-align: justify; margin-bottom: 0.9em">Bốn hôm trước là bản xem trước quy hoạch của trung tâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là quá tận tụy.</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi Lâm Nhược Đường hơi cong lên. Cô tiện tay bấm thích một bài đăng của người tận tụy ấy, rồi thoát khỏi Moments.</p><p style="text-align: justify; margin-bottom: 0.9em">...</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi tắm xong, Thời Vụ bước ra khỏi phòng tắm.</p><p style="text-align: justify; margin-bottom: 0.9em">Phòng khách yên tĩnh đến lạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhẹ tay nhẹ chân trở về phòng mình, khép cửa lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Điện thoại vẫn rung không ngừng.</p><p style="text-align: justify; margin-bottom: 0.9em">Là một số lạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ suy nghĩ chốc lát rồi vẫn bắt máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Quả nhiên là Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe nàng nhận cuộc gọi, giọng Triệu Hy Ngọc nghẹn lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ..."</p><p style="text-align: justify; margin-bottom: 0.9em">Vẫn là chất giọng mà Thời Vụ đã quá quen thuộc.</p><p style="text-align: justify; margin-bottom: 0.9em">Mang theo chút tủi thân, xen lẫn làm nũng.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngày trước, nàng rất dễ mềm lòng trước kiểu này.</p><p style="text-align: justify; margin-bottom: 0.9em">Dù hai người cãi nhau dữ dội đến đâu, chỉ cần Triệu Hy Ngọc dùng giọng điệu ấy, nàng đều có thể bình tĩnh lại để nghe đối phương nói hết.</p><p style="text-align: justify; margin-bottom: 0.9em">Lần này cũng vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ là tâm trạng đã khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hỏi: —" Chị đổi số rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Thời Vụ bình tĩnh đến không gợn sóng, không hề có sự tức giận như những lần trước nhận điện thoại của cô ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc siết chặt điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chị thấy em không nghe số cũ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn thản nhiên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chỉ là... em không biết nên nói gì với chị nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc sốt ruột nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chị biết, chị biết em không biết phải nói gì với chị. Em à, để chị đến đón em về nhà được không? Em về đi, chúng ta có chuyện gì cũng có thể cùng nhau bàn bạc."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ im lặng vài giây rồi đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ngày mai gặp ở công ty đi. Em cũng có chuyện muốn nói với chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Dường như nàng định cúp máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc vội hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em... còn về nhà không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đến đây thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Ba chữ ngắn ngủi.</p><p style="text-align: justify; margin-bottom: 0.9em">Không rõ nàng đang nói về cuộc điện thoại hôm nay...</p><p style="text-align: justify; margin-bottom: 0.9em">Hay là về mối quan hệ giữa hai người lúc này.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc bỗng không còn dám hỏi thêm.</p><p style="text-align: justify; margin-bottom: 0.9em">...</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi cúp máy, cảm giác mệt mỏi lại như thủy triều dâng lên bao trùm lấy Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Rõ ràng trước khi đi tắm, nàng còn cảm thấy hôm nay nhẹ nhõm hơn hôm qua.</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao cũng không ngủ được.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lấy món đồ thủ công mang về từ nhà họ Lâm ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Chiếc bàn không đủ rộng, nàng dứt khoát trải chăn trên giường, bày mọi thứ lên đó, rồi đối chiếu với bản mẫu, từng chút một chọc kim.</p><p style="text-align: justify; margin-bottom: 0.9em">Đầu tiên là tạo hình.</p><p style="text-align: justify; margin-bottom: 0.9em">Tiếp đến là phối màu.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó men theo các đường viền, cẩn thận hoàn thiện từng chi tiết.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ làm vô cùng chăm chú.</p><p style="text-align: justify; margin-bottom: 0.9em">...</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đã quen với việc mỗi sáng thức dậy đều không thấy Thời Vụ đâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng hôm nay đi ngang qua phòng nàng, thấy cửa vẫn đóng, cô không khỏi khựng lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt rón rén bước tới, gõ cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời Vụ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Không có ai đáp.</p><p style="text-align: justify; margin-bottom: 0.9em">Lại đi rồi sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đặt tay lên tay nắm cửa, nhẹ nhàng mở ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ thấy Thời Vụ đang nằm úp trên chăn ngủ say.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa sổ vẫn mở.</p><p style="text-align: justify; margin-bottom: 0.9em">Từng cơn gió sớm luồn vào phòng. Buổi sáng vẫn còn khá lạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt bước tới đóng cửa sổ lại, rồi đưa tay sờ thử trán nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhiệt độ bình thường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc ấy cô mới yên tâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến khi cúi đầu, cô mới nhìn thấy thành phẩm nằm trong tay Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Đó là một chú mèo mướp màu cam nho nhỏ.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ lớn hơn lòng bàn tay một chút.</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy nhỏ nhưng có đầy đủ mắt, mũi, trông rất đáng yêu.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ là nhìn vẫn có thể nhận ra tay nghề chưa thật sự thuần thục.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt từng xem rất nhiều video các blogger làm đồ thủ công, món nào cũng sống động như thật.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu để cô nhận xét tác phẩm của Thời Vụ...</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ có hai chữ.</p><p style="text-align: justify; margin-bottom: 0.9em">Dụng tâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Quả thật rất dụng tâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Dụng tâm đến mức làm rồi ngủ quên lúc nào không hay.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt kéo chăn đắp lại cẩn thận cho nàng, sau đó nhẹ tay nhẹ chân rời khỏi phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">...</p><p style="text-align: justify; margin-bottom: 0.9em">Giấc ngủ này của Thời Vụ rất sâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Sâu đến mức nàng mơ thấy Thời Ánh Xuân.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Ánh Xuân quay lưng về phía nàng, đang đứng trong bếp nấu bữa sáng.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Thường Anh rời đi, hai mẹ con rất hiếm khi có thể bình tĩnh ngồi ăn cùng nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Thông thường chỉ nói chưa được hai câu đã cãi nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Đã có một khoảng thời gian rất dài, trong mơ nàng chỉ gặp Thường Anh, chưa từng gặp lại Thời Ánh Xuân.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng từng nói với Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chắc mẹ vẫn còn giận mình."</p><p style="text-align: justify; margin-bottom: 0.9em">Bây giờ...</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ đã hết giận rồi sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng yên tại chỗ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Ánh Xuân quay đầu lại, dịu dàng gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ, ăn cơm thôi. Con đi gọi Đường Đường xuống ăn đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Đường Đường...</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Thời Vụ mới chợt nhớ.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi còn nhỏ, mẹ nàng luôn gọi Lâm Nhược Đường là Đường Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Hồi ấy nàng cứ tưởng chữ "Đường" là đường trong nước đường, bởi nàng chưa từng nhìn thấy tên của Lâm Nhược Đường, càng không biết tên đầy đủ của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy nàng vẫn đứng ngẩn người, Thời Ánh Xuân cầm chiếc xẻng nấu ăn bước đến.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sống mũi Thời Vụ cay xè.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mẹ... con xin lỗi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Ánh Xuân nhíu mày.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao thế? Con lại gây ra chuyện gì rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có... Con..."</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc ấy, phía sau vang lên tiếng bước chân.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Người nàng nhìn thấy là Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải Lâm Nhược Đường mũm mĩm năm xưa.</p><p style="text-align: justify; margin-bottom: 0.9em">Mà là Lâm Nhược Đường của hiện tại.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bước nhanh vài bước đến trước mặt hai mẹ con rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em ấy gây chuyện rồi. Kết hôn xong, vợ còn..."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường còn chưa nói hết.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đã không chút do dự lao thẳng về phía cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng vồ hụt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bỗng ngồi bật dậy trên giường.</p><p style="text-align: justify; margin-bottom: 0.9em">Giấc mơ vừa rồi chân thật đến mức khiến lòng nàng nghẹn lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng không muốn sau bao năm, Thời Ánh Xuân mới xuất hiện trong giấc mơ của mình, lại biết rằng nàng sống chẳng hề hạnh phúc.</p><p style="text-align: justify; margin-bottom: 0.9em">Còn Lâm Nhược Đường trong mơ là sao chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Lại còn đi mách lẻo với mẹ nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Mình đã nghĩ cô ấy thành người gì vậy...</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhắm mắt, day nhẹ sống mũi rồi hắt hơi một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Quay đầu nhìn sang, cửa sổ đã được đóng lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Đêm qua nàng đứng bên cửa sổ rất lâu vì mất ngủ, hình như sau đó quên đóng.</p><p style="text-align: justify; margin-bottom: 0.9em">Chắc là Dư Mạt vào phòng giúp nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lúc này mới chợt nhớ đến thời gian.</p><p style="text-align: justify; margin-bottom: 0.9em">Mấy giờ rồi?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vội cầm điện thoại lên xem.</p><p style="text-align: justify; margin-bottom: 0.9em">Đã hơn mười một giờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thoáng sững người.</p><p style="text-align: justify; margin-bottom: 0.9em">WeChat có rất nhiều tin nhắn chưa đọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lần lượt trả lời từng tin.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến đoạn trò chuyện với Diệp Lãnh Tinh, nàng nhìn thấy điều khoản ly hôn mà đối phương vừa sửa lại, khẽ nhíu mày rồi nhắn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Luật sư Diệp, 20% cổ phần của Ưu Lạc này là sao vậy?】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh trả lời rất nhanh:</p><p style="text-align: justify; margin-bottom: 0.9em">【À, cái này ấy mà, tôi biết số cổ phần đó không đứng tên Triệu Hy Ngọc. Thêm vào đơn thuần chỉ là để làm nhục cô ta thôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn chằm chằm điều khoản ấy thật lâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Cuối cùng nàng đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">【Phiền cô bỏ điều khoản này giúp tôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">【 Cô...】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Hôm nay tôi sẽ nói chuyện với chị ấy trước.】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">【Có cần tôi qua đó không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không cần.】</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lại gửi thêm một tin:</p><p style="text-align: justify; margin-bottom: 0.9em">【 cô yên tâm, phí tư vấn vẫn tính theo đúng như chúng ta đã thống nhất trước đó.】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh vốn chẳng để tâm chút tiền tư vấn ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Điều khiến cô tò mò là...</p><p style="text-align: justify; margin-bottom: 0.9em">Rốt cuộc Thời Vụ định nói gì với Triệu Hy Ngọc?</p><p style="text-align: justify; margin-bottom: 0.9em">Bảo cô bỏ điều khoản kia đi...</p><p style="text-align: justify; margin-bottom: 0.9em">Lẽ nào muốn quay lại?</p><p style="text-align: justify; margin-bottom: 0.9em">Không thể nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh tự nhận mình đã gặp đủ mọi kiểu người. Tuy thỉnh thoảng cũng nhìn lầm, nhưng phần lớn đều không sai.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tuyệt đối không phải kiểu người sẽ chấp nhận nối lại tình cảm.</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy nên...</p><p style="text-align: justify; margin-bottom: 0.9em">Một mình nàng đến đó là muốn nói gì?</p><p style="text-align: justify; margin-bottom: 0.9em">Người nàng phải đối mặt không chỉ có Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Mà còn là cả nhà họ Triệu.</p><p style="text-align: justify; margin-bottom: 0.9em">Là toàn bộ Ưu Lạc.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh càng nghĩ càng tò mò.</p><p style="text-align: justify; margin-bottom: 0.9em">Tò mò đến mức trong giờ làm việc cũng nhắn tin quấy rầy Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">【Cô ấy không đồng ý thêm điều khoản đó.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn tin nhắn, ngón tay khẽ gõ lên mặt bàn.</p><p style="text-align: justify; margin-bottom: 0.9em">Một lát sau mới trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Biết rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh hỏi tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cậu nói xem... có phải cô ấy mềm lòng rồi không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">【Muốn hỏi gì thì hỏi thẳng đi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ một câu đã vạch trần hoàn toàn ý dò hỏi của Diệp Lãnh Tinh.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ôm ngực.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường có cần nhạy bén đến thế không?</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là cô đến để thăm dò thật.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh đành thẳng thắn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi chỉ lo cô ấy sẽ hối hận thôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Luật sư Diệp, với góc độ chuyên môn của cậu thì sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">【...】</p><p style="text-align: justify; margin-bottom: 0.9em">Bị hỏi ngược một câu.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là không còn gì để nói.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô dứt khoát không vòng vo nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">【Thế cậu không tò mò xem hai người họ sẽ nói những gì sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">...</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này, Thời Vụ đang ngồi trong văn phòng của Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý đứng trước mặt nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Triệu tổng sẽ đến ngay thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩng đầu nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt bình tĩnh, ôn hòa.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhẹ giọng.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi ngồi đây đợi chị ấy là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý lập tức rót một tách cà phê đặt lên bàn trà.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong công ty, người khác có thể không biết.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cô thì biết.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sắp nghỉ việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Không rõ là vì chuyện bộ lễ phục của Lâm Châu bị đánh tráo mấy hôm trước.</p><p style="text-align: justify; margin-bottom: 0.9em">Hay vì Triệu Tinh vào công ty.</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao thì...</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không muốn tiếp tục ở lại Ưu Lạc nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây Trịnh Ý từng làm việc cho một cặp vợ chồng.</p><p style="text-align: justify; margin-bottom: 0.9em">Hồi ấy cô còn chưa tốt nghiệp, chỉ làm bán thời gian, phụ trách thu thập thông tin.</p><p style="text-align: justify; margin-bottom: 0.9em">Bình thường thì không sao.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng hễ hai người họ cãi nhau hoặc chiến tranh lạnh, cô chính là người khổ nhất.</p><p style="text-align: justify; margin-bottom: 0.9em">Ban đầu cô còn tưởng Thời Vụ và Triệu Hy Ngọc cũng sẽ như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng hoàn toàn không phải.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người rất rõ ràng giữa công và tư.</p><p style="text-align: justify; margin-bottom: 0.9em">Hay nói đúng hơn...</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ từ đầu đến cuối đều giữ được sự tỉnh táo tuyệt đối.</p><p style="text-align: justify; margin-bottom: 0.9em">Cho dù mâu thuẫn với Triệu Hy Ngọc vì chuyện Triệu Tinh đến mức nào, nàng cũng chưa từng mang cảm xúc cá nhân vào công việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Điều này khiến Trịnh Ý rất thích.</p><p style="text-align: justify; margin-bottom: 0.9em">Thậm chí còn vô cùng khâm phục.</p><p style="text-align: justify; margin-bottom: 0.9em">Bởi vậy cô cũng quan tâm đến Thời Vụ nhiều hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời, nghe nói chị định nghỉ việc?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng điềm tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng vậy. Tôi đã nộp đơn xin thôi việc cho Triệu tổng rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý chính là vì nhìn thấy lá đơn trên bàn làm việc của Triệu Hy Ngọc nên mới biết chuyện.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô tiếc nuối hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là công việc có vấn đề gì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Rồi vội vàng khuyên nhủ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hoạt động của Lâm Châu hôm qua rất thành công. Có không ít nhãn hàng chủ động liên hệ với chúng ta, nói muốn vào Ưu Lạc. Cả Lâm Thái nữa, hôm qua cũng đã gặp Triệu tổng và ký biên bản ghi nhớ hợp tác."</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý vốn muốn khiến Thời Vụ đổi ý.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng sắc mặt Thời Vụ vẫn bình thản như cũ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe vậy, nàng chỉ nhàn nhạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chúc mừng."</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý có cảm giác...</p><p style="text-align: justify; margin-bottom: 0.9em">Giống như nàng đang chúc mừng một người xa lạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Rõ ràng cho dù có nghỉ việc, nàng vẫn là vợ của Triệu tổng mà.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhấp một ngụm cà phê.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc ấy, ngoài cửa vang lên tiếng giày cao gót.</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý lập tức bước nhanh ra mở cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc đi vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nhìn thấy Thời Vụ, cô khựng người một thoáng, theo bản năng gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Vì vui mừng, giọng nói cũng run lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng dậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt hai người giao nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bình tĩnh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nói chuyện một chút đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý lập tức hiểu ý.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Triệu tổng, Giám đốc Thời, vậy tôi xin phép ra ngoài trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô khép cửa lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Văn phòng lập tức chìm vào yên tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc vừa định bước đến gần.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đã lấy từ trong túi xách ra một tập tài liệu, đưa cho cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Không cần mở ra, Triệu Hy Ngọc cũng biết đó là gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô khẽ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhất định phải làm vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nói rất nhẹ.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hy Ngọc, chúng ta quen nhau bốn năm rồi. Trong bốn năm đó, chúng ta đã cùng nhau trải qua rất nhiều chuyện. Em từng nghĩ, chúng ta sẽ có một gia đình hạnh phúc. Sẽ có một đứa con của riêng hai chúng ta."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em sẽ dành cho con tất cả tình yêu của mình. Em không phải một người con tốt...Nhưng em luôn mong mình có thể trở thành một người mẹ tốt. Ngày chị nói chị muốn có một cô con gái, em thật sự rất vui. Em đã chuẩn bị mọi thứ để chào đón con đến với thế giới này. Nhưng rồi em phát hiện... tất cả chỉ là một màn lừa dối của chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngước mắt nhìn Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị hỏi em có nhất định phải làm đến mức này không. Vậy trước khi làm những chuyện ấy...Tại sao chị chưa từng nghĩ đến cảm nhận của em?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc từ từ ngồi xổm xuống trước mặt nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Giống hệt như trước đây.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ngẩng đầu nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong mắt tràn ngập áy náy và hối lỗi.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng... chuyện này là chị sai. Chị thừa nhận. Những gì em nói đều đúng. Chị sẽ sửa, được không? Chỉ cần chị sửa..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cắt ngang:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc lập tức im bặt.</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Thời Vụ vẫn chậm rãi.</p><p style="text-align: justify; margin-bottom: 0.9em">Vẫn bình tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng từng chữ đều dứt khoát.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hy Ngọc, chị biết không? Thật ra em đã từng cho chị một cơ hội. Đêm biết được chuyện đó, em từng nghĩ...Nếu chị biết mình sai. Nếu chị thật lòng hối hận. Có lẽ em sẽ bỏ qua tất cả. Nhưng chị đã không làm vậy. Lòng chị đã bị lợi ích che mờ."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trong đầu chị chỉ nghĩ làm sao để có được toàn bộ Ưu Lạc. Chị là người có thể hy sinh hôn nhân. Hy sinh tình cảm. Hy sinh cả con mình. Còn em thì không. Em không rộng lượng được như chị. Em không làm được."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc khẽ mấp máy môi.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị...Chị chỉ muốn...Chúng ta hoàn toàn nắm quyền ở Ưu Lạc. Để mọi chuyện tốt hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn thẳng vào mắt cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ một ánh nhìn đã như nhìn thấu tất cả.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Muốn hoàn toàn nắm quyền ở Ưu Lạc, rõ ràng chị còn rất nhiều cách khác. Nhưng chị lại chọn cách nhanh nhất. Thuận tiện nhất. Cũng là cách gần như không phải trả giá gì. Chỉ cần có một đứa trẻ. Triệu Tinh sẽ hài lòng. Chị sẽ hài lòng. Mọi người đều sẽ hài lòng. Chỉ là...Chị chưa từng nghĩ xem vợ mình có hài lòng hay không? Đứa bé ấy có hài lòng hay không. Bởi trong mắt chị...Cả em và đứa trẻ ấy chẳng qua chỉ là những quân cờ."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc lập tức lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị chưa bao giờ xem em là quân cờ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy là chị thừa nhận... chị đã xem đứa bé ấy là quân cờ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nghẹn lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Sắc mặt đầy khó xử.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ, em đừng mãi cố chấp như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Người cố chấp là chị. Triệu Hy Ngọc...Rốt cuộc là chị thật sự không hiểu...Hay chỉ giả vờ không hiểu? Ngay từ khoảnh khắc chị đưa ra lựa chọn...Cuộc hôn nhân của chúng ta đã kết thúc rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc vẫn chưa chịu từ bỏ.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nếu như..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngắt lời:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có nếu như."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc im lặng.</p><p style="text-align: justify; margin-bottom: 0.9em">Sắc mặt càng thêm tái nhợt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đưa tập tài liệu về phía cô.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ký đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Đó là...</p><p style="text-align: justify; margin-bottom: 0.9em">Đơn thỏa thuận ly hôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc chưa từng nghĩ.</p><p style="text-align: justify; margin-bottom: 0.9em">Giữa cô và Thời Vụ...</p><p style="text-align: justify; margin-bottom: 0.9em">Lại có ngày xuất hiện thứ này.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đưa tay gạt bản thỏa thuận sang một bên.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bình tĩnh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em khuyên chị nên ký. Triệu Hy Ngọc. Em đã làm ở bộ phận truyền thông của Ưu Lạc bốn năm. Từng xử lý đủ loại khủng hoảng dư luận. Em biết vào thời điểm nào tung tin gì... sẽ khiến Ưu Lạc lao dốc nhanh nhất. Hiện tại chị còn đang chuẩn bị hợp tác với Lâm Thái. Chắc chị cũng không muốn vào lúc này xảy ra chuyện đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc chậm rãi đứng dậy nhìn Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Hôm qua cô vừa ký biên bản ghi nhớ hợp tác với Lâm Thái.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô vốn không định giấu Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Thời Vụ nói không sai.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai bên mới chỉ ký biên bản ghi nhớ, hợp đồng chính thức vẫn chưa được ký kết.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu lúc này Ưu Lạc bùng nổ bất kỳ scandal nào, thậm chí là chuyện tình cảm cá nhân của cô, đều sẽ ảnh hưởng đến việc hợp tác.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ là...</p><p style="text-align: justify; margin-bottom: 0.9em">Cô chưa từng nghĩ tới.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em đang uy hiếp chị sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc cúi đầu, giọng nặng nề.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bình tĩnh đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải uy hiếp. Em chỉ đang nói sự thật. Triệu Hy Ngọc, chị biết không? Điều em ghét nhất chính là uy hiếp người khác. Em không cho rằng uy hiếp có thể giải quyết được vấn đề gì. Nhưng khi chị không chịu ly hôn, em đã từng nghĩ đến việc uy hiếp chị. Em từng nghĩ sẽ công khai cho tất cả mọi người biết chuyện giữa chị và Triệu Tinh. Muốn tất cả đều nhìn thấy toan tính của chị. Thậm chí em còn từng nghĩ...Cho dù phải đánh đổi cả sự nghiệp sau này của mình...Em cũng sẽ khiến Ưu Lạc không được yên ổn. Triệu Hy Ngọc...Đó mới là uy hiếp. Là chị đã biến em thành người mà chính em ghét nhất."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhìn nàng, vẻ mặt sững sờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn thẳng vào mắt cô, bỗng khẽ cười.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy? Có phải chị thấy em như thế này rất xa lạ không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trong mắt Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ trước nay vẫn luôn bình tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Ôn hòa.</p><p style="text-align: justify; margin-bottom: 0.9em">Không nổi nóng.</p><p style="text-align: justify; margin-bottom: 0.9em">Cũng chưa từng mất kiểm soát.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc khẽ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ... em thay đổi rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em không thay đổi. Có lẽ... người chị biết chưa phải là toàn bộ con người em. Cũng giống như em...Em cũng chưa từng thật sự hiểu hết con người chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc cắn môi.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ, em cũng nói rồi. Em đã làm ở Ưu Lạc bốn năm. Em phải biết...Nếu chị không để em đi...Thì em sẽ rất khó rời khỏi Ưu Lạc một cách yên ổn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em biết. Triệu Hy Ngọc, em đều biết. Cho nên hôm nay em không đi cùng luật sư. Em muốn tự mình đến nói chuyện với chị. Chị biết vì sao không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chậm rãi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bởi vì...Em không muốn người mình từng yêu...Cuối cùng lại rơi vào kết cục lưỡng bại câu thương. Hy Ngọc...Chúng ta chia tay trong yên bình đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhìn nàng thật lâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Biết rằng Thời Vụ đã quyết tâm ly hôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Không còn bất kỳ khả năng xoay chuyển nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Một lúc sau, cô khàn giọng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Để đó đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đặt bản thỏa thuận ly hôn lên bàn.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ký xong thì gửi cho em."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, nàng quay người rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Phía sau, Triệu Hy Ngọc gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ dừng bước.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc cất giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chị hy vọng em hiểu...Nếu chị đồng ý ly hôn...Không phải vì những lời em vừa nói. Chỉ là chị không muốn em đau lòng. Chuyện của Triệu Tinh, chị thừa nhận mình sai. Nhưng đối với em...Chị vẫn luôn nghiêm túc. Chị thích em. Chị yêu em. Điều đó... em biết mà."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không đáp.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị thừa nhận, vì muốn nhanh chóng có được cổ phần của Ưu Lạc nên đã bất chấp thủ đoạn. Nhưng đó là vì Ưu Lạc đang trong giai đoạn phát triển rất nhanh. Chị nhất định phải nắm quyền kiểm soát toàn cục, chị..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn quay lưng về phía cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nói lạnh lẽo:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ưu Lạc phát triển nhanh hay chậm... đều do chị quyết định. Rốt cuộc chị muốn lợi dụng đứa bé ấy để không tốn chút sức nào mà có được toàn bộ cổ phần...Hay lấy cái cớ nắm quyền kiểm soát toàn cục để tự biện minh cho mình...Trong lòng chị và em đều hiểu rõ."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhìn bóng lưng nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không thể cho chị thêm một cơ hội sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em đã cho chị rồi. Là chính chị không cần."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, nàng rời khỏi văn phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Tấm lưng thẳng tắp ấy mang theo sự quyết tuyệt chưa từng có.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhìn cánh cửa gỗ đỏ đã khép chặt.</p><p style="text-align: justify; margin-bottom: 0.9em">Cả người như mất hết sức lực, ngồi phịch xuống sofa.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô cầm lấy bản thỏa thuận ly hôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Không có bất kỳ yêu cầu quá đáng nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngay cả căn nhà hôn nhân...</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng không cần.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ yêu cầu quy đổi theo giá thị trường thành tiền mặt.</p><p style="text-align: justify; margin-bottom: 0.9em">Đó là ngôi nhà mà nàng đã bỏ biết bao tâm huyết.</p><p style="text-align: justify; margin-bottom: 0.9em">Rèm cửa là nàng chọn.</p><p style="text-align: justify; margin-bottom: 0.9em">Ga giường là nàng mua.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngay cả chiếc tủ đầu giường cũng là sau khi nàng so sánh giữa ba cửa hàng mới quyết định.</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy mà bây giờ...</p><p style="text-align: justify; margin-bottom: 0.9em">Nói không cần là không cần nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc siết chặt bản thỏa thuận.</p><p style="text-align: justify; margin-bottom: 0.9em">Đi đến bàn làm việc, nhấn điện thoại nội bộ.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trịnh Ý, gọi luật sư Trương đến gặp tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">...</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý vừa đáp lời, vừa đi về phía thang máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc nhìn thấy Thời Vụ vẫn đang đứng đợi thang máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô vội bước nhanh tới.</p><p style="text-align: justify; margin-bottom: 0.9em">Khẽ cúi đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu, khẽ gật đầu với cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người cùng bước vào thang máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị xuống tầng mấy?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tầng hầm B1."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, Thời Vụ lùi về phía sau hai bước.</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý quay đầu nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ mỉm cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Nụ cười dịu dàng hơn trước.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng không hiểu sao, Trịnh Ý lại cảm thấy còn xa cách hơn bất cứ lúc nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Giống như...</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng không chỉ nghỉ việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Mà còn đang hoàn toàn cắt đứt mọi liên hệ với Ưu Lạc.</p><p style="text-align: justify; margin-bottom: 0.9em">Lẽ nào...</p><p style="text-align: justify; margin-bottom: 0.9em">Cuộc hôn nhân của hai người thật sự xảy ra vấn đề?</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ đến đây, Trịnh Ý bất giác lạnh cả sống lưng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhắc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thư ký Trịnh, chị đến nơi rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">—"À..."</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý hoàn hồn.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời, tạm biệt."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mỉm cười.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tạm biệt."</p><p style="text-align: justify; margin-bottom: 0.9em">Không hiểu sao.</p><p style="text-align: justify; margin-bottom: 0.9em">Trịnh Ý lại có cảm giác...</p><p style="text-align: justify; margin-bottom: 0.9em">Đây sẽ là lần cuối cùng cô gặp Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">...</p><p style="text-align: justify; margin-bottom: 0.9em">Xuống đến tầng hầm B1 mới chỉ bốn giờ chiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lái xe ra đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Không mục đích.</p><p style="text-align: justify; margin-bottom: 0.9em">Cho đến khi điện thoại của Diệp Lãnh Tinh gọi đến.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng tấp xe vào lề, nhận cuộc gọi.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nói chuyện xong rồi chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, tôi đã nói chuyện với chị ấy rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xem ra kết quả cũng không tệ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có lẽ vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bỗng thấy mình như quay về quãng thời gian sau khi Thời Ánh Xuân qua đời.</p><p style="text-align: justify; margin-bottom: 0.9em">Mịt mờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Không biết phải đi đâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh dịu giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô Thời, không phải ai cũng đủ dũng cảm để dứt khoát cắt đứt như vậy. Cô rất dũng cảm."</p><p style="text-align: justify; margin-bottom: 0.9em">Biết đối phương đang an ủi mình, Thời Vụ khẽ siết chặt điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn cô, luật sư Diệp. Đợi chị ấy ký xong thỏa thuận rồi gửi cho tôi, tôi sẽ liên hệ với cô."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được. Có vấn đề gì cứ tìm tôi bất cứ lúc nào. Tôi luôn ở đây."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng. Tôi biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi cúp máy, Thời Vụ nghiêng đầu nhìn bầu trời ngoài cửa kính.</p><p style="text-align: justify; margin-bottom: 0.9em">Bầu trời xanh thẫm.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh nắng rực rỡ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngồi yên thêm một lúc.</p><p style="text-align: justify; margin-bottom: 0.9em">Rồi lấy từ túi ở ghế phụ món đồ thủ công đã làm xong.</p><p style="text-align: justify; margin-bottom: 0.9em">May mà tối qua đã hoàn thành.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu không hôm nay đi lấy son mà tay không...</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thật sự sẽ thấy ngại.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mở khung chat với Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Hít sâu vài lần để lấy hết can đảm.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó mới gửi tin nhắn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Lâm tổng, hôm nay mấy giờ cô tan làm?】</p><p style="text-align: justify; margin-bottom: 0.9em">Hai phút sau.</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải tin nhắn.</p><p style="text-align: justify; margin-bottom: 0.9em">Mà là một cuộc gọi.</p><p style="text-align: justify; margin-bottom: 0.9em">Mọi sự chuẩn bị tâm lý của Thời Vụ lập tức tan biến.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vô thức căng thẳng.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bây giờ cô không bận gì chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghẹn lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe cứ như nàng là người thất nghiệp vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng buồn bực một chút, nhưng cũng chẳng biết phản bác thế nào.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng... tôi vừa xong việc."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy cô có thể đến đón tôi không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩn người.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tòa nhà Hiểu Băng, khu B, bãi đỗ xe số 3. Có tiện qua đây không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mở bản đồ chỉ đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Khá xa.</p><p style="text-align: justify; margin-bottom: 0.9em">Hơn bốn mươi cây số.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng hiện giờ nàng cũng chẳng có việc gì.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được ạ. Chỉ là hơi xa, chắc mất khoảng nửa tiếng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy ba mươi phút nữa..."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi sẽ đợi cô ở cổng."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng."</p><p style="text-align: justify; margin-bottom: 0.9em">Cúp máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cài định vị rồi lái xe ra đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Đi được một đoạn.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng mới chợt nhớ ra một chuyện.</p><p style="text-align: justify; margin-bottom: 0.9em">...Xe của Lâm Nhược Đường đâu?</p><p style="text-align: justify; margin-bottom: 0.9em">....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các thiên thần nhỏ đã tặng 15 phiếu Bá Vương, 278 bình dinh dưỡng~</p><p style="text-align: justify; margin-bottom: 0.9em">Ngẫu nhiên gửi 100 bao lì xì nhé, moah moah~ 💕</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Không ngờ đúng không? Tôi có vợ đến đón tan làm. (＾▽＾)</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: ...</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 28, 'Cãi nhau', '<p style="text-align: justify; margin-bottom: 0.9em">Xe của Lâm Nhược Đường không sao, nhưng người lái xe thì có việc, Trần Hy xin nghỉ phép.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe lý do đó, Thời Vụ chỉ biết âm thầm than thở trong lòng. Với ba mươi phút chờ cô như thế, Lâm Nhược Đường tự lái xe về công ty còn nhanh hơn. Nghĩ lại thì đúng thật, cô ấy là sếp lớn, sao có thể tự mình lái xe được chứ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ đến đây, Thời Vụ xuống xe, mở cửa ghế sau, cung kính hơi khom người, ra hiệu mời Lâm Nhược Đường lên xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Cái dáng vẻ ấy, cứ như tự coi mình là tài xế riêng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường liếc nàng một cái, bước ngang qua người nàng, mở cửa ghế phụ rồi ngồi vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ cau mày, đóng cửa lại, quay về ghế lái.</p><p style="text-align: justify; margin-bottom: 0.9em">Việc đầu tiên Lâm Nhược Đường làm sau khi lên xe là điều chỉnh ghế ngồi. Bình thường khi đi làm, Thời Vụ và Triệu Hy Ngọc đều tự lái xe riêng, hoặc đôi khi nàng ngồi xe của Triệu Hy Ngọc, nên ghế phụ này hiếm khi có người dùng. Lần trước ghế được đẩy lên phía trước một chút để phía sau đặt quần áo lễ phục, mà Lâm Nhược Đường lại có đôi chân dài, vừa ngồi vào đã thấy chật chội.</p><p style="text-align: justify; margin-bottom: 0.9em">Rõ ràng có chiếc SUV rộng rãi, thoải mái của mình không đi, lại chen chúc trong chiếc xe nhỏ này, Thời Vụ thật sự không hiểu. Nhưng nàng cũng không hỏi nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đến công ty trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Đây là... coi nàng thành tài xế thật rồi sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bỗng nổi hứng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Biết đường đi chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: —"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nhắm mắt nàng cũng lái được ấy chứ. Xem ra trước đây đúng là nàng ít qua lại với Lâm Thái quá, đến mức Lâm Nhược Đường chẳng có ấn tượng gì về nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười mà như không cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng nói đùa rồi. Ở Cửu Xuyên làm gì có ai không biết nhà họ Lâm."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghiêng đầu nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô đang nói mát tôi đấy à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức ngồi thẳng người, quay đầu sang, vẻ mặt nghiêm túc hơn hẳn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngắm nhìn biểu cảm của nàng một lúc, khẽ bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu một hơi, hai tay siết chặt vô lăng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm nay nói chuyện với Tổng giám đốc Triệu thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe cô nhắc đến Triệu Hy Ngọc, Thời Vụ có hơi bất ngờ. Lâm Nhược Đường cũng nhiều chuyện đến vậy sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Đột nhiên nàng lại cảm thấy việc cô tặng thẻ phòng để xem kịch còn hợp lý hơn nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mím môi, im lặng một lúc rồi đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Khá tốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Cô ta đồng ý ly hôn rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: —"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Tại sao nàng phải thảo luận chuyện này với Lâm Nhược Đường chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt nhận ra, tính tình đã yên ổn suốt bao năm của mình, sao cứ mỗi lần nghe Lâm Nhược Đường nói là lại dễ nổi nóng như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Là vì Lâm Nhược Đường quá đường đột, còn bản thân cô thì chẳng hề nhận ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Thời Vụ cũng chẳng còn cách nào khác. Ai bảo người ta địa vị cao hơn mình chứ? Biết đâu sau này công việc còn phải nhờ đến cô. Nàng cố giữ giọng điềm tĩnh:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị ấy vẫn chưa ký, nhưng chắc cũng sắp rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao sáng nay cô không đi cùng luật sư?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi vốn định......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng còn chưa nói hết câu thì quay đầu nhìn Lâm Nhược Đường, khó hiểu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng biết chuyện đó sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bình thản đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Diệp Lãnh Tinh là người tôi giới thiệu cho cô. Sao vậy? Dư Mạt chưa nói với cô à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: —"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thảo nào Dư Mạt lại có mối quan hệ như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Hóa ra chỉ là nhờ Lâm Nhược Đường giới thiệu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đừng hiểu lầm. Trước đây mẹ cô từng giúp đỡ tôi rất nhiều, tôi cũng từng làm phiền gia đình cô vài ngày. Bây giờ có việc gì trong khả năng, tôi giúp được thì sẽ giúp."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vừa định nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đâu..."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chắc hẳn mẹ cô cũng hy vọng vào lúc như thế này sẽ có một người có thể giúp đỡ cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt nhớ đến giấc mơ tối qua. Nghĩ đến ánh mắt đầy lo lắng của Thời Ánh Xuân khi nhìn mình, những lời sắp thốt ra lại bị nàng nuốt trở vào, đổi thành:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy cảm ơn Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nếu thật sự muốn cảm ơn tôi thì mời tôi một bữa đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nghiêng đầu, bổ sung:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải sủi cảo."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe vậy, vẻ mặt Thời Vụ lập tức giãn ra, nàng hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô không thích ăn sao hôm đó lại không nói?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng không phải không thích, chỉ là thỉnh thoảng mới ăn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Loại nào? Loại có vỏ nhập khẩu ấy à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường liếc nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô lại đang nói mát tôi đấy à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Da đầu Thời Vụ lập tức căng lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cười, vẻ mặt đầy thích thú:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đùa cô thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe miệng Thời Vụ giật giật:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ha ha."</p><p style="text-align: justify; margin-bottom: 0.9em">Xe còn chưa tới Lâm Thái, Thời Vụ đã nhìn thấy tấm biển hiệu màu vàng nổi bật. Tòa nhà Lâm Thái rất cao, biển hiệu được treo trên đỉnh nên cực kỳ dễ nhận ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chưa từng nghĩ sẽ có một ngày mình đến Lâm Thái, còn chở theo Lâm Nhược Đường. Cảm giác ấy thật kỳ lạ, khiến nàng thoáng ngẩn người vài giây.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thuận theo ánh mắt nàng nhìn về phía tấm biển, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Muốn vào làm việc không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sững sờ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Làm việc?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô chẳng phải đã nghỉ việc rồi sao? Không cần tìm công việc mới à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng là tôi đã nghỉ việc, nhưng tôi vẫn muốn đợi giải quyết xong chuyện giữa tôi và Triệu Hy Ngọc rồi mới tính đến kế hoạch nghề nghiệp."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có thể hiểu được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhưng dù sao cũng cảm ơn Lâm tổng đã cho tôi một cơ hội làm việc."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chỉ là tiện tay thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Đối với Lâm Nhược Đường, có lẽ đó chỉ là một việc tiện tay.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng với Thời Vụ, đó lại giống như một con đường lui.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây sau khi rời Ưu Lạc, nàng vẫn còn vài phần mịt mờ về tương lai. Giờ đây, cuối cùng nàng cũng đã có một phương hướng. Dù chưa chắc sẽ nhận công việc này, nhưng lòng nàng đã yên tâm hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là nên mời cô một bữa cơm tử tế.</p><p style="text-align: justify; margin-bottom: 0.9em">Cũng nên gọi cả Lâm Châu và Dư Mạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Không biết Lâm Nhược Đường có để ý hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lén liếc cô bằng khóe mắt. Tay phải Lâm Nhược Đường chống lên thành cửa sổ xe, đỡ cằm, tay trái nghịch điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô thuận tay trái à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Ngón tay đang gõ chữ của Lâm Nhược Đường khựng lại. Cô quay sang nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tay nào cũng được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nghe nói người dùng được cả hai tay đều rất thông minh."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Coi như cô đang khen tôi vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......Lâm tổng khiêm tốn rồi, đó là sự thật."</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi Lâm Nhược Đường cong lên thành một vòng cung đẹp mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Xe vừa dừng hẳn, cô mở cửa ghế phụ bước xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Thời Vụ vẫn ngồi yên, Lâm Nhược Đường khom người, nhìn nàng qua ô cửa kính xe còn hạ một nửa, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô không xuống xe à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngơ ngác chớp mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi cũng phải xuống sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xuống nghỉ ngơi một lát."</p><p style="text-align: justify; margin-bottom: 0.9em">Còn chu đáo thật.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ liền xuống xe, đi bên cạnh cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Sảnh chính của tòa nhà có sáu thang máy, năm chiếc dừng ở tất cả các tầng, còn một chiếc đi thẳng lên tầng mười lăm trở lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ từng đến đây không ít lần, nhưng cao nhất cũng chỉ đến tầng mười lăm. Từ đó trở lên là khu vực không mở cho người ngoài.</p><p style="text-align: justify; margin-bottom: 0.9em">Văn phòng của Lâm Nhược Đường ở tầng hai mươi tám.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi cửa thang máy mở ra, bên trái là quầy lễ tân. Lễ tân lúc này đang nghe điện thoại. Nghe thấy tiếng thang máy liền ngẩng đầu lên, lập tức cúp điện thoại rồi bước tới, quẹt thẻ cho Lâm Nhược Đường đi vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên trong là một không gian văn phòng mở rộng lớn. Sự yên tĩnh ngoài cửa vừa biến mất, thay vào đó là âm thanh bận rộn khắp nơi. Những nữ nhân viên trong trang phục công sở tất bật trước bàn làm việc: người gọi điện thoại, người chuyển tài liệu, người xác nhận lịch trình, người điều phối công việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Sự xuất hiện của Lâm Nhược Đường dường như không thu hút quá nhiều sự chú ý, trái lại cô lễ tân phía sau còn lén nhìn hai người thêm vài lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ theo sau Lâm Nhược Đường, đi ngang qua khu thư ký rồi đến văn phòng của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Văn phòng của Lâm Nhược Đường rất rộng, tầm nhìn cực đẹp. Hai mặt đều là cửa kính sát đất, đủ để bao quát toàn cảnh Cửu Xuyên.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa bước vào, Lâm Nhược Đường khẽ hất cằm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ngồi đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi xuống sofa.</p><p style="text-align: justify; margin-bottom: 0.9em">Không hiểu sao, giữa khung cảnh bận rộn xung quanh, còn mình lại ngồi trong văn phòng của Lâm Nhược Đường, nàng bỗng có cảm giác như đang ở một thế giới hoàn toàn tách biệt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Muốn uống gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ dùng luôn câu trả lời vạn năng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Gì cũng được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhấn máy nội bộ, nói với đầu dây bên kia:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mang một ly cà phê lên."</p><p style="text-align: justify; margin-bottom: 0.9em">Không lâu sau, thư ký mang cà phê vào, đặt lên bàn trà.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây Thời Vụ chỉ từng chào hỏi Trần Hy đôi lần, không quá thân quen. Nàng chỉ khẽ gật đầu, mỉm cười lịch sự.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ngồi đây đợi một lát, tôi đi họp."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó Lâm Nhược Đường bước ra khỏi văn phòng, thư ký cũng đi theo.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước khi rời đi, Lâm Nhược Đường còn dặn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lát nữa Tổng giám đốc Triệu của Ưu Lạc tới, cô đưa cô ấy đến thẳng văn phòng tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thư ký cung kính đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Lâm Nhược Đường rời đi, Thời Vụ yên lặng ngồi trong văn phòng của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngồi một lúc, nàng càng nghĩ càng thấy không ổn.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lên tầng cùng Lâm Nhược Đường để làm gì chứ? Đến Lâm Thái nàng đâu có việc gì. Dù Lâm Nhược Đường có ý tốt muốn nàng lên đây nghỉ ngơi một lát, nhưng thật sự cũng không cần thiết.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi không yên, khẽ cựa người, lấy điện thoại ra rồi nhắn cho Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Diệp Lãnh Tinh là do Lâm Nhược Đường giới thiệu cho cậu à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vừa từ phòng phẫu thuật đi ra, đang ngửa đầu uống nước. Cô y tá bên cạnh đưa cho cô một viên kẹo.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt ngậm viên kẹo, lấy điện thoại từ trong túi áo blouse ra. Viên kẹo suýt nữa làm cô sặc, phải mất một lúc mới bình tĩnh lại rồi trả lời Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Sao cậu biết?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cô ấy nói với mình.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ai nói? Lâm Nhược Đường à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ừm.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【......Mình chỉ sợ cậu ngại làm phiền người ta thôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Nhưng Thời Vụ này, mình nói thật, lúc này cậu đừng có mềm lòng. Ly hôn thì nhất định phải tính toán rõ ràng. Đặc biệt là Triệu Hy Ngọc, chị ta hút máu cậu bao nhiêu năm rồi. Nếu cậu không mời một luật sư thật giỏi thì không đấu lại chị ấy đâu.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Mình đã gặp Triệu Hy Ngọc rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Hai người nói gì?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không nói gì nhiều, mình chỉ bảo chị ấy ký vào đơn thỏa thuận ly hôn.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị ta đồng ý không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị ấy cũng không đồng ý, mà cũng không từ chối.】</p><p style="text-align: justify; margin-bottom: 0.9em">Theo sự hiểu biết của Thời Vụ về Triệu Hy Ngọc, có đến tám mươi phần trăm chị sẽ đồng ý.</p><p style="text-align: justify; margin-bottom: 0.9em">Một mặt, Triệu Hy Ngọc quả thật vẫn còn tình cảm với nàng. Chuyện ở bệnh viện tuy khiến người ta thất vọng, nhưng tình cảm ấy vẫn tồn tại.</p><p style="text-align: justify; margin-bottom: 0.9em">Mặt khác, Ưu Lạc sắp hợp tác với Lâm Thái. Đây là dự án mà Triệu Hy Ngọc đã dồn rất nhiều tâm huyết, chị tuyệt đối sẽ không để bản thân thất bại vào lúc này.</p><p style="text-align: justify; margin-bottom: 0.9em">Vì vậy, việc ký tên chỉ là chuyện sớm hay muộn.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Dù thế nào thì cậu cũng không được mềm lòng.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn chưa kịp trả lời thì ngoài cửa văn phòng có tiếng động.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngẩng đầu lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Thư ký mở cửa, dẫn một người bước vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Sắc mặt Thời Vụ lập tức thay đổi.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến khi nhìn rõ là ai, sắc mặt của Triệu Hy Ngọc cũng thay đổi theo.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người từng là người yêu thân thiết nhất, vậy mà giờ phút này lại xa lạ như người dưng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dường như thư ký không nhận ra bầu không khí căng thẳng, cô nói với Triệu Hy Ngọc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Triệu tổng, phiền cô đợi một lát. Lâm tổng họp xong sẽ quay lại ngay."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc khẽ thở ra một hơi, gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Làm phiền rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thư ký nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mời cô vào ngồi trước, tôi đi pha cà phê."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc khẽ đáp một tiếng rồi bước vào văn phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cất điện thoại đi, ánh mắt nhìn về phía Triệu Hy Ngọc vẫn không hề rời khỏi.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi thư ký rời đi, Triệu Hy Ngọc hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao em lại ở đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không muốn dây dưa với cô quá nhiều, chỉ cúi đầu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em Có việc."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Việc gì? Tiểu Vụ, là vì chuyện Ưu Lạc hợp tác với Lâm Thái sao? Chị còn chưa trả lời em mà em đã không chờ nổi, vội vàng đến tìm Lâm tổng rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe vậy, Thời Vụ ngẩng đầu nhìn chị.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong mắt Triệu Hy Ngọc, nàng nhìn thấy sự căng thẳng xen lẫn hoảng hốt.</p><p style="text-align: justify; margin-bottom: 0.9em">Hoảng hốt điều gì?</p><p style="text-align: justify; margin-bottom: 0.9em">Hoảng hốt vì sợ nàng đến tìm Lâm Nhược Đường để tố cáo những chuyện chị và Triệu Tinh đã làm sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Đáng tiếc...</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường biết hết rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Có hoảng cũng vô ích.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lạnh nhạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Triệu Hy Ngọc, chị nghĩ nhiều rồi. Em ở đây không liên quan gì đến Ưu Lạc."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhìn chằm chằm nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không liên quan đến Ưu Lạc? Đừng quên, bây giờ em vẫn là Giám đốc của Ưu Lạc."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng bắt đầu bực bội:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hay là trong lòng chị còn chưa rõ? Có cần em nói thẳng trước mặt Lâm Nhược Đường không? Chị sợ em đến thế sao? Hay trong mắt chị, em là loại người hèn hạ như vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc bị nàng chất vấn đến nghẹn lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Im lặng hai giây, chị khẽ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ, xin lỗi... Chị thật sự rất cần dự án hợp tác lần này. Em biết mà..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười chua chát:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Em không biết, Triệu Hy Ngọc. Em không biết những kế hoạch của chị, cũng không biết rốt cuộc chị muốn làm gì. Đến bây giờ em mới nhận ra, em hoàn toàn không hiểu chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc định lên tiếng giải thích.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị cũng chẳng hiểu em."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc khẽ gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải như vậy đâu, Tiểu Vụ..."</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc ấy, cửa văn phòng mở ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Thư ký bưng cà phê bước vào, đặt trước mặt Triệu Hy Ngọc, rồi quay sang Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô Thời, Lâm tổng mời cô qua bên đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hề do dự, lập tức đứng dậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Phía sau, Triệu Hy Ngọc gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Đáp lại cô chỉ có tiếng bước chân của nàng ngày càng xa.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc biết phản ứng và biểu hiện vừa rồi của mình thật sự quá tệ.</p><p style="text-align: justify; margin-bottom: 0.9em">Sao cô lại có thể nghi ngờ Thời Vụ đến Lâm Thái là để tìm Lâm Nhược Đường tố cáo mình chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Rõ ràng đó là chuyện Thời Vụ không bao giờ làm.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ vì lúc nãy quá sốt ruột, đầu óc rối loạn nên cô mới buột miệng nói ra những lời như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Bảo sao Thời Vụ lại nổi giận.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cô không ngờ, vẫn còn một khả năng khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đến tìm Lâm Nhược Đường...</p><p style="text-align: justify; margin-bottom: 0.9em">Là để làm gì?</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng lẽ hai người vẫn âm thầm qua lại với nhau?</p><p style="text-align: justify; margin-bottom: 0.9em">Hay Lâm Nhược Đường đã biết chuyện giữa cô và Thời Vụ?</p><p style="text-align: justify; margin-bottom: 0.9em">Chắc là không.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu đã biết, sao cô ấy còn đồng ý ký ý định thư hợp tác?</p><p style="text-align: justify; margin-bottom: 0.9em">Hơn nữa, Thời Vụ vốn chậm nóng, lại không thích kể chuyện tình cảm của mình với người khác. Nếu không phải năm đó cô kiên quyết, thì trong công ty cũng chẳng mấy ai biết hai người từng ở bên nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sẽ không đi nghi ngờ cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc cúi mắt, lặng lẽ nhìn ly cà phê trước mặt vẫn còn bốc khói.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi rời khỏi văn phòng, Thời Vụ định nói với thư ký là mình về trước. Nhưng lại sợ làm khó cô ấy, nên vẫn đi theo.</p><p style="text-align: justify; margin-bottom: 0.9em">Thư ký dẫn nàng đến trước một văn phòng khác, mở cửa ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên trong là một phòng họp.</p><p style="text-align: justify; margin-bottom: 0.9em">Thư ký nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng đang bên trong."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ cau mày, bước vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cũng không ngẩng đầu, chỉ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ngồi đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không ngồi mà nhìn cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng có ý gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Lâm Nhược Đường mới ngẩng đầu lên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ý gì là ý gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không vui:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô để tôi đợi trong văn phòng rồi gặp Triệu Hy Ngọc, chắc không phải trùng hợp đâu nhỉ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Tay phải Lâm Nhược Đường cầm bút ký, tay kia giữ tập tài liệu, đầu ngón tay lướt dọc mép giấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bình thản đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quả thật không phải trùng hợp."</p><p style="text-align: justify; margin-bottom: 0.9em">Vì không vui, giọng Thời Vụ trầm xuống:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không biết Lâm tổng rốt cuộc muốn làm gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chẳng phải cô muốn cô ấy nhanh chóng ký đơn ly hôn sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cố nén cơn giận:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng, tôi muốn ly hôn với chị ấy càng sớm càng tốt. Nhưng đó là chuyện giữa tôi và chị ấy. Lâm tổng, cô không thấy mình can thiệp quá nhiều rồi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lặng lẽ nhìn nàng, một câu đã nói trúng tim đen:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô tức giận như vậy... là vì tôi can thiệp quá nhiều, hay vì cô ấy hiểu lầm cô?"</p><p style="text-align: justify; margin-bottom: 0.9em">Đường nét nơi cằm Thời Vụ căng cứng, môi mím chặt, đầu lưỡi khẽ chống vào hàm răng.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt hờ hững của Lâm Nhược Đường vẫn dừng trên gương mặt nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ siết chặt bàn tay buông bên người, có cảm giác như mình đã bị nhìn thấu.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lạnh giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi thừa nhận, chị ấy hiểu lầm tôi, tôi không vui. Nhưng điều tôi càng không thích hơn là cô tự ý xen vào chuyện của tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ hé môi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi đã nói..."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi biết!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cao giọng ngắt lời:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi biết cô giúp tôi là vì nể mặt mẹ tôi. Nhưng Lâm tổng, giúp một người thì tiền đề phải là người đó cần được giúp. Nếu thật sự cần cô giúp, tôi sẽ tự nói với cô. Xin cô đừng làm như vậy nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng thật sâu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Biết rồi. Cô ra ngoài trước đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu rời khỏi phòng họp.</p><p style="text-align: justify; margin-bottom: 0.9em">Rõ ràng nàng đã nói rõ mọi chuyện với Lâm Nhược Đường, nhưng tảng đá đè nặng trong lòng chẳng những không biến mất mà còn càng lúc càng nặng hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Người qua lại bên ngoài đều là nhân viên của văn phòng thư ký, ai cũng tò mò nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không muốn tiếp tục bị người khác dõi theo như thế, bèn đi thẳng xuống khỏi tầng hai mươi tám.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy không có ở đây. Người duy nhất nàng có thể nói chuyện là cô lễ tân ở tầng một, nhưng lúc này quay lại đó cũng không thích hợp.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghĩ đi nghĩ lại, cuối cùng vẫn trở về xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cũng không biết lát nữa Lâm Nhược Đường có còn dùng xe hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Giờ cứ ngồi chờ như một tài xế thế này thì còn ra thể thống gì nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt không muốn lấy thỏi son kia về nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng tiện tay ném điện thoại lên ghế phụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Điện thoại va vào túi giấy đựng đồ, phát ra một tiếng cạch.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu nhìn, thấy trong túi giấy lộ ra một món đồ treo nhỏ xíu.</p><p style="text-align: justify; margin-bottom: 0.9em">Càng nhìn càng thấy ngượng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hít sâu hai hơi, ngả đầu tựa vào ghế, ngước mắt nhìn trần xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Bãi đỗ xe yên tĩnh đến lạ, chỉ có ánh đèn huỳnh quang trắng hắt xuống, nhưng không chiếu vào trong xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Không biết đã ngồi bao lâu, điện thoại bỗng rung lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi dậy, với tay sang ghế phụ lấy điện thoại, vừa day trán vừa nghe máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Là Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng cô nàng vẫn tràn đầy sức sống như mọi khi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chị đang ở đâu vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn tấm biển chỉ dẫn bãi đỗ xe phía trước:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị đang ở ngoài."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"À, vậy khi nào chị qua lấy son?"</p><p style="text-align: justify; margin-bottom: 0.9em">Tim Thời Vụ khẽ thắt lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ở chỗ em à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vừa rồi chị gọi cho em, nói chị để quên son ở nhà bọn em. Em vừa về đến nhà rồi, chị qua lấy luôn nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Không hiểu sao, nàng lại hỏi thêm một câu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị em đâu rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị ấy à, bảo là tăng ca."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chắc tối nay không về ăn cơm đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Tăng ca.</p><p style="text-align: justify; margin-bottom: 0.9em">Để nàng đến tìm Lâm Châu lấy son.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đâu phải ngốc, sao có thể không hiểu ý của Lâm Nhược Đường?</p><p style="text-align: justify; margin-bottom: 0.9em">Là một tổng giám đốc bận rộn như cô, đã chủ động giúp nàng, vậy mà nàng chẳng những không cảm kích, còn nổi nóng với cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là chẳng biết điều chút nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nói với Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, chị qua ngay đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi cúp điện thoại, Lâm Châu đi tắm, đắp mặt nạ rồi vào phòng Lâm Nhược Đường tìm thỏi son.</p><p style="text-align: justify; margin-bottom: 0.9em">Xong xuôi, cô ngồi trên sofa vừa xem phim vừa đợi Thời Vụ, còn đang nghĩ tối nay có nên ăn ít trái cây cho đỡ đói không thì điện thoại rung lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nhấc máy, Thời Vụ đã nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Châu, chị đến cổng rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vội vàng chạy ra cửa, vừa cúi đầu vỗ nhẹ mép miếng mặt nạ vừa nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vào đi, vào đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị không vào đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu kéo nàng vào:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Khách sáo gì chứ, mau vào đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bị cô kéo vào nhà, thay đôi dép đi trong nhà hôm qua.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị ăn tối chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chưa. Còn em?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em cũng chưa. Đang tính xem có nên ăn hay không. Hôm nay lên cân thêm hai cân rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy cô vừa muốn ăn lại vừa không dám ăn, Thời Vụ chợt nhớ đến mấy món ăn giảm mỡ trước đây mình từng làm.</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy nàng không thích vào bếp, cũng chẳng có tài nấu nướng gì, nhưng vài món giảm mỡ đơn giản vẫn biết làm.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nói với Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Để chị làm cho em món ít calo nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu mừng rỡ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được được! Thật ra chiều nay em tập luyện suốt, đói lắm rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đi vào bếp.</p><p style="text-align: justify; margin-bottom: 0.9em">Món giảm mỡ nàng nói đơn giản là luộc chín các loại rau ít calo, sau đó trộn gia vị.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng còn luộc thêm hai quả trứng cho Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu ngoan ngoãn ngồi bên bàn ăn chờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Thời Vụ bưng bát ra, cô lập tức đón lấy bằng hai tay rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chuyện ly hôn của chị sao rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng gần xong rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy thì tốt. Nhưng trước đây chị đúng là mù quáng thật đấy. Có một người vợ tốt như vậy mà còn ngoại tình."</p><p style="text-align: justify; margin-bottom: 0.9em">Dĩ nhiên cô nàng không biết Triệu Hy Ngọc không phải kiểu người ngoại tình.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cũng chẳng sao.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chỉ cười cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói với nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Yên tâm, sau này em sẽ giới thiệu cho chị người tốt hơn!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lần này Thời Vụ thật sự bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Hàng mày cong cong, ánh mắt dịu dàng, nàng khẽ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cắn một miếng trứng, ăn rất mãn nguyện.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy cô ăn gần xong, Thời Vụ đứng dậy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy chị về trước đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lưu luyến:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không chơi thêm chút nữa à? Xem một bộ phim cũng được mà."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không đâu, chị còn có chút việc."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được rồi. À, son của chị để trên bàn trà ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn thấy thỏi son Dazzle đặt trên bàn trà.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bước tới cầm lấy, rồi suy nghĩ một lát, lại quay về bàn ăn, đưa món quà thủ công của mình cho Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đây là quà sinh nhật bù cho Lâm tổng. Cô ấy không có nhà, phiền em chuyển giúp chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn món quà rồi lại nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị em chắc lát nữa là về thôi. Hay chị tự đưa cho chị ấy đi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thôi, chị về đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, nàng đặt món quà xuống rồi xoay người rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn theo bóng lưng nàng, cảm thấy có gì đó là lạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Ăn hết chỗ rau trong bát, cô mang bát đi rửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc ấy, ngoài cửa có tiếng động.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu thò đầu ra nhìn, thấy Lâm Nhược Đường xách túi đựng laptop bước vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Gương mặt cô lạnh lùng hơn thường ngày, sắc mặt cũng nhàn nhạt, khiến người khác không dám đến gần.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vội lau khô tay, bước đến cạnh cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, sao chưa đến mười phút đã về rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay đầu nhìn cô, không đáp.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đã quen với bầu không khí áp thấp như thế, tự mình nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chị Thời Vụ vừa mới đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Lâm Nhược Đường mới lên tiếng, giọng điềm tĩnh nhưng lạnh nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy? Muốn chị đưa cô ấy về à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vội xua tay:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải ý đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng đi đến bàn ăn, cầm lấy chiếc túi quà nhỏ.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Người ta mang quà đến tặng chị đấy. Chị không nói một câu cảm ơn thì cũng hơi quá rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn chiếc túi quà trong tay cô, khẽ nhướng mày.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đặt món quà vào tay chị mình, rồi lấy từ trong túi ra chiếc móc khóa nhỏ.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng cười hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có phải đáng yêu lắm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Là một chiếc móc khóa hình mèo nhỏ xíu.</p><p style="text-align: justify; margin-bottom: 0.9em">Nói tinh xảo đến mức nào thì cũng không hẳn, nhưng vì nhỏ nhắn nên trông lại rất dễ thương.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhét lại vào túi, sắc mặt vẫn không thay đổi, quay người đi về phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Phía sau, Lâm Châu gãi đầu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, tối nay chị ăn nhầm thuốc nổ à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Cuối cùng Lâm Nhược Đường cũng chịu mở miệng, chỉ nói đúng ba chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em rảnh lắm?"</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng điệu quen thuộc ấy khiến Lâm Châu lập tức bị bầu không khí lạnh lẽo bao trùm.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bĩu môi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ai rảnh chứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đi thẳng vào phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đứng phía sau, nghĩ mãi vẫn không hiểu chuyện gì, dứt khoát ngồi phịch xuống sofa, nhắn tin cho Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị, chị có phải cãi nhau với chị em không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc về đến nhà, Thời Vụ mới nhìn thấy tin nhắn.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngồi trong xe, suy nghĩ hồi lâu không biết nên trả lời thế nào, cuối cùng vẫn giả vờ như không có chuyện gì:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không có mà, sao thế?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu trả lời ngay trong tích tắc:</p><p style="text-align: justify; margin-bottom: 0.9em">【Hôm nay chị ấy lạnh lùng cực kỳ luôn, đáng sợ lắm!!】</p><p style="text-align: justify; margin-bottom: 0.9em">⸻</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả:</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các thiên thần đã tặng 12 Bá Vương Phiếu và 248 bình Dinh Dưỡng Dịch~</p><p style="text-align: justify; margin-bottom: 0.9em">Ngẫu nhiên tặng 100 hồng bao, nếu Dinh Dưỡng Dịch đạt 10.000 sẽ đăng thêm 1 chương, mọi người nhớ bình luận dưới chương nhé~</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: Cầu sinh mãnh liệt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Khổ sở với em như vậy mới có thể đi tìm chị Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: "......"</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 29, '"Đừng đi đâu cả, tuyệt đối đừng đi, tôi qua ngay!"', '<p style="text-align: justify; margin-bottom: 0.9em">( tác giả: Thêm chương mừng 10.000 dịch dinh dưỡng) ....</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn luôn biết mình biết người. Trong mắt Lâm Nhược Đường, nàng chưa bao giờ cho rằng bản thân có vị trí đặc biệt đến thế.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường sẵn lòng giúp nàng, chẳng qua là vì năm xưa Thời Ánh Xuân từng giúp cô. Vì vậy, sau khi biết chuyện giữa Triệu Hy Ngọc và Triệu Tinh, cô mới mượn chuyện căn phòng để kín đáo nhắc nhở nàng. Biết nàng muốn ly hôn, cô lại nhờ luật sư giúp đỡ, thậm chí còn sẵn lòng cho nàng một công việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Đối với Lâm Nhược Đường, có lẽ tất cả những chuyện ấy chỉ là tiện tay giúp một chút, nhưng với Thời Vụ thì không phải vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng biết ơn sự giúp đỡ của Lâm Nhược Đường vào lúc này, nhưng đây là tình cảm của chính nàng, là cuộc hôn nhân của chính nàng. Dẫu có rất nhiều điều không hoàn hảo, dẫu kết cục có tệ đến đâu, đó vẫn là lựa chọn của nàng. Bây giờ nàng đã chọn kết thúc, nàng không muốn người khác nhúng tay vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Nói nàng ngu ngốc cũng được, nói nàng cố chấp giữ lấy chút lòng tự trọng chông chênh ấy cũng chẳng sao. Nàng chỉ muốn giữ lại chút tôn nghiêm cuối cùng.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ tất cả mọi người đều sẽ cảm thấy nàng không biết phân biệt tốt xấu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cầm điện thoại, tựa vào lưng ghế sofa. Dư Mạt ở phía sau hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Món quà kia của cậu đã tặng cho Lâm Nhược Đường rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chậm mất nửa nhịp mới phản ứng lại, khẽ ừ một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi nhờ Lâm Châu đưa cho cô ấy rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ấy nói thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi cũng không biết."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu nghĩ kỹ lại xem. Tặng cô ấy một món quà như vậy, sợ là cô ấy sống từng này tuổi rồi cũng chưa từng nhận được món quà kiểu đó đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Ban đầu khi biết Thời Vụ định làm một món đồ thủ công, Dư Mạt còn tưởng nàng làm cho Lâm Châu, không ngờ lại là tặng Lâm Nhược Đường. Chỉ riêng việc nhìn cô một cái thôi cũng đủ khiến Dư Mạt sợ hãi, vậy mà Thời Vụ lại dám tặng cô món đồ thủ công như thế, phản ứng của Lâm Nhược Đường chắc chắn sẽ rất thú vị.</p><p style="text-align: justify; margin-bottom: 0.9em">Đáng tiếc, cô lại không được tận mắt nhìn thấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi cũng không biết lúc đó mình nghĩ thế nào nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Bị Lâm Châu kéo đi một hồi, thế là suy nghĩ cũng lệch theo luôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhưng nói thật nhé, tôi thấy Lâm Nhược Đường cũng khá tốt. Trước đây khi cậu muốn hợp tác với cô ấy, đến mặt còn chẳng gặp được, lúc đó tôi cứ nghĩ cô ấy kiêu ngạo lắm, chắc là kiểu nhà tư bản lạnh lùng vô tình. Bây giờ xem ra, hình như cũng không phải như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ im lặng một lúc, cuối cùng vẫn nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ấy nói là vì muốn cảm ơn mẹ tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt chợt hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng phải, hồi đó cô ấy còn từng ở nhà cậu mà."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu, sau đó nhìn Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sau này đừng làm phiền cô ấy nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nghi hoặc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sau này những chuyện như thế này, đừng làm phiền cô ấy nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt lập tức căng thẳng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có phải cô ấy nói gì rồi không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có, chỉ là tôi cảm thấy làm phiền cô ấy như vậy không hay."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt thở phào:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời Vụ à, cậu thật thà quá rồi đấy. Người sống trên đời chẳng phải là cậu giúp tôi, tôi giúp cậu sao? Cậu xem Lâm Nhược Đường là bà chủ lớn như vậy, cũng sẽ có lúc gặp chuyện không giải quyết được, cũng sẽ có lúc cần người khác giúp đỡ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không giống nhau."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Khác chỗ nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nếu cô ấy gặp bất kỳ vấn đề gì và nói với tôi, tôi nhất định sẽ giúp cô ấy. Nhưng nếu cô ấy không nói cho tôi biết, nghĩa là cô ấy không muốn tôi biết chuyện đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy lỡ như đó là chuyện cô ấy không thể mở miệng nói ra thì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại. Dư Mạt nói với nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi biết cậu cần có ranh giới, nhưng là bạn của cậu, tôi cũng thật sự rất muốn giúp cậu làm chút gì đó. Dù chỉ là một chuyện nhỏ nhặt chẳng đáng kể. Có lẽ Lâm Nhược Đường cũng muốn báo đáp sự giúp đỡ mà mẹ cậu từng dành cho cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Dư Mạt đi tắm, Thời Vụ ngồi trên sofa. Hết bộ phim này đến bộ phim khác chiếu trên TV. Nàng ngồi cuộn mình quá lâu, lúc bước xuống đất hai chân còn hơi tê. Nàng vỗ vỗ bắp chân, hoạt động gân cốt một lúc rồi mới đứng dậy. Dư Mạt lau mái tóc còn ướt, đi đến phòng bếp hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ăn táo không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không ăn đâu, tôi đi tắm trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng trở về phòng lấy đồ ngủ rồi vào phòng tắm. Có lẽ đầu óc hơi rối, nàng quên bật chế độ nước nóng lạnh luân phiên, nước lạnh từ vòi sen xối xuống khiến nàng lạnh đến rùng mình, vội vàng chỉnh sang nước nóng. Hơi lạnh và nóng đột ngột thay nhau chạm vào da khiến Thời Vụ hắt hơi một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Ra khỏi phòng tắm, nàng lấy khăn giấy ấn lên mũi. Dư Mạt đi tới, lo lắng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vừa rồi tắm bị lạnh."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu đúng là tham mát mà. Tối qua ngủ còn chẳng đóng cửa sổ. Tôi lấy cho cậu ít thuốc cảm, uống rồi nghỉ ngơi sớm đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ừ một tiếng, uống thuốc cảm Dư Mạt đưa cho rồi quay về đóng cửa sổ, nằm lên giường. Đầu óc nàng vẫn còn quay cuồng, cơ thể không chống lại được tác dụng của thuốc, chẳng mấy chốc đã chìm vào giấc ngủ. Nàng cũng không biết mình có nằm mơ hay không. Sáng hôm sau tỉnh dậy, Dư Mạt đã không còn ở nhà. Nàng bị tiếng điện thoại rung đánh thức. Kỳ Mai có một phương án không tìm thấy, gọi hỏi nàng nó nằm trong thư mục nào. Thời Vụ nhắm mắt, ngồi dậy khỏi giường rồi nói với Kỳ Mai:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trong thư mục thứ ba, cái có khóa ấy, mật khẩu là 2346."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai thở phào:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tìm thấy rồi, cảm ơn Giám đốc Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không còn là giám đốc nữa, không cần gọi tôi như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, chị Thời... Thời Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô vẫn chưa quen gọi thẳng tên Thời Vụ, cứ cảm thấy như vậy rất mạo phạm. Trước đây khi Thời Vụ chưa làm giám đốc, cô cũng gọi nàng là quản lý, chưa bao giờ dám gọi cả họ lẫn tên. Kỳ Mai vừa gọi một tiếng, tim đã đập thình thịch như sắp nhảy ra khỏi cổ họng. Trái lại, giọng Thời Vụ vẫn bình thản:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm, còn chỗ nào không hiểu thì cứ liên lạc với tôi bất cứ lúc nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, tôi biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trước khi Thời Vụ cúp máy, Kỳ Mai nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy gần đây chị có rảnh không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi vẫn còn nợ chị một bữa cơm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ nhíu mày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nợ tôi một bữa cơm?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm, lúc tôi được thăng chức đã nói sẽ mời chị ăn cơm mà."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hiểu ra, chân mày cũng giãn ra đôi chút. Nàng nói với Kỳ Mai:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đâu, tôi cũng chẳng giúp được gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phải mời chứ. Nếu lúc trước không phải chị và Triệu tổng kiên trì, tôi cũng chẳng được thăng chức. Bữa cơm này dù thế nào tôi cũng phải mời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không từ chối thêm nữa, nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, vậy cô chọn thời gian rồi báo cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai thở phào, cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, Giám đốc Thời!"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cắn môi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải, chị Thời Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không để ý đến sự thay đổi trong cách xưng hô, chỉ bình thản cúp điện thoại.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai rất vui, đến lúc đi họp khóe môi vẫn cong lên. Tống Kim cũng ngồi bên cạnh Kỳ Mai, hạ giọng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị Kỳ, Giám đốc Thời thật sự nghỉ việc rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trong công ty có đủ loại lời đồn, ai cũng nói Giám đốc Thời không phải xin nghỉ phép mà là nghỉ việc. Cô nàng muốn hỏi thẳng Thời Vụ nhưng lại không dám, đành lén hỏi Kỳ Mai.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai liếc nhìn những người đang họp, nghiêng đầu sang một bên, lấy tay che miệng, nhỏ giọng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có lẽ vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim trợn tròn mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai gật đầu với cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim lập tức xụ vai, vẻ mặt như muốn khóc mà không có nước mắt. Kỳ Mai nhớ lại hôm qua khi mình biết Thời Vụ nghỉ việc, biểu cảm cũng chẳng khác cô nàng là bao. Sau đó, sáng nay khi đến đưa tài liệu cho Triệu Hy Ngọc, cô nhìn thấy một bản thỏa thuận bị đè dưới tập hồ sơ. Hai chữ ở đầu trang, cô phải dụi mắt đến cả vạn lần mới nhìn rõ.</p><p style="text-align: justify; margin-bottom: 0.9em">Ly hôn.</p><p style="text-align: justify; margin-bottom: 0.9em">Bọn họ sắp ly hôn sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Giám đốc Thời và Triệu tổng?</p><p style="text-align: justify; margin-bottom: 0.9em">Tại sao chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Tinh?</p><p style="text-align: justify; margin-bottom: 0.9em">Nỗi buồn của Kỳ Mai lập tức bị một cảm xúc khác nhấn chìm. Tuy không nên như vậy, nhưng cô thật sự rất tò mò.</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim cũng nghiêng đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em cũng muốn xin nghỉ."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lo mà làm việc cho tốt đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim ồ một tiếng, buồn bực không vui.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhận được gói biểu cảm Tống Kim gửi tới. Trước đó nàng vừa gọi điện cho luật sư, trong cuộc gọi Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi nhận được điện thoại của thư ký bên cô ta rồi, hẹn chúng ta chiều nay gặp nhau ở quán cà phê, tiện thể ký luôn thỏa thuận."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng không quá bất ngờ. Bất kể là chuyện hôm qua đã kích thích đến Triệu Hy Ngọc, hay là Triệu Hy Ngọc cảm thấy áy náy với nàng, nàng đều đã đoán được Triệu Hy Ngọc sẽ đồng ý ly hôn. Nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, vậy hai giờ chiều chúng ta gặp nhau ở quán cà phê."</p><p style="text-align: justify; margin-bottom: 0.9em">Cúp điện thoại, nàng nhìn thấy tin nhắn Tống Kim gửi tới, liên tiếp mấy gói biểu cảm khóc hu hu, trông có vẻ rất đau lòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gửi lại cho cô nàng một biểu cảm mỉm cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim: 【Giám đốc Thời! Hu hu hu hu, Giám đốc Thời!】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: 【Sao vậy?】</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim: 【Em nhớ chị rồi.】 Kèm theo một biểu cảm khóc lớn.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: 【Lo làm việc cho tốt.】</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim: 【Sao chị cũng giống chị Kỳ vậy.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: 【Cô ấy làm sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim: 【Chị ấy biết chị nghỉ việc mà chẳng nói với bọn em gì cả. Bây giờ cả công ty đều đồn ầm lên, nói chị sắp nghỉ việc, còn nói chị với Triệu tổng cãi nhau nữa.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: 【Ừ......】</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim: 【Em thấy chắc chắn là Triệu Tinh truyền ra đấy, người này xấu chết đi được.】</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây Thời Vụ cũng ghét Triệu Tinh, nhưng từ sau khi biết được những toan tính của Triệu Hy Ngọc, người nàng ghét nhất đã trở thành chị ấy, tiếp đến mới là mẹ Triệu. Triệu Tinh ngược lại bị xếp xuống cuối cùng, hoặc có thể nói, nàng thậm chí còn có chút đồng cảm với cô ta.</p><p style="text-align: justify; margin-bottom: 0.9em">Mặc dù Triệu Tinh chẳng cần đến sự đồng cảm ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ôm điện thoại, không nhịn được hắt hơi hai cái. Nàng dùng sức hơi mạnh, trước mắt lập tức hoa lên. Nàng rút khăn giấy trên bàn trà, lau chóp mũi vừa đau vừa ngứa.</p><p style="text-align: justify; margin-bottom: 0.9em">Hình như thật sự bị cảm rồi. Cả người Thời Vụ từng cơn phát lạnh. Nàng đi vào bếp rót một cốc nước nóng, pha thuốc cảm, hai tay ôm cốc sưởi ấm rồi trở lại sofa, vừa trò chuyện câu được câu không với Tống Kim, vừa uống thuốc.</p><p style="text-align: justify; margin-bottom: 0.9em">Tống Kim còn nói với nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">【Nhưng hôm nay Triệu Tinh không đến công ty, nghe nói xin nghỉ bệnh rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không mấy quan tâm, nhưng Tống Kim vốn nhiều chuyện, kể hết những chuyện lớn nhỏ trong công ty cho nàng nghe. Thời Vụ trả lời được vài câu rồi chẳng biết từ lúc nào đã ngủ thiếp đi. Khi tỉnh lại đã hơn một giờ. Đầu nàng đau, mũi nghẹt, cổ họng vừa khô vừa rát. Nàng buồn bực ho một tiếng, dạ dày lập tức cuộn lên, buồn nôn. Thời Vụ vội cầm cốc nước trên bàn uống một ngụm để ép cảm giác ấy xuống. Nước đã lạnh ngắt, uống vào chưa được hai giây, cổ họng lại càng đau hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Cứ đúng vào lúc này lại bị cảm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi trên sofa.</p><p style="text-align: justify; margin-bottom: 0.9em">Từ nhỏ thể chất nàng không được tốt lắm, nhưng cũng chỉ là tay chân dễ lạnh, rất hiếm khi cảm sốt. Hay nói đúng hơn, Thường Anh và Thời Ánh Xuân chăm sóc nàng rất tốt. Từ nhỏ nàng đã giống như một cây pháo nhỏ, đi đến đâu quậy tung đến đó, chẳng khác nào một tiểu ma vương không sợ trời không sợ đất. Thường Anh thích nhìn dáng vẻ tràn đầy sức sống của nàng. Ban đầu nàng không hiểu, mãi đến sau khi Thường Anh rời đi, nàng mới chợt hiểu ra rằng Thường Anh chỉ muốn nhìn thấy nàng khỏe mạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến một giờ rưỡi, dù vẫn chẳng muốn nhúc nhích, Thời Vụ vẫn đứng dậy, xách túi lái xe đến quán cà phê. Vẫn là quán lần trước, chỉ có điều lần này có thêm một người.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc ngồi đối diện Diệp Lãnh Tinh, một mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng ở cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc dường như cảm nhận được điều gì, quay đầu nhìn về phía Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Cách cánh cửa kính của quán cà phê, ánh mắt hai người chạm nhau. Hôm nay lớp trang điểm của Triệu Hy Ngọc không còn tinh tế như mọi khi, dưới mắt là quầng thâm nhàn nhạt, hai tay đặt trên bàn, gương mặt đầy vẻ mệt mỏi. Sắc mặt Thời Vụ còn tệ hơn cô, cơn cảm khiến đầu nàng đau dữ dội, vừa rồi lúc lái xe rẽ một khúc cua nàng còn thấy choáng váng.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ nhận ra nàng không khỏe, Triệu Hy Ngọc theo bản năng đứng dậy. Nhưng khi còn chưa kịp bước tới, Thời Vụ đã đi đến.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người ngồi đối diện nhau, Triệu Hy Ngọc khẽ gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi bên cạnh Diệp Lãnh Tinh, không nói gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em không khỏe sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Chắc hẳn nàng rất khó chịu. Bọn họ ở bên nhau lâu như vậy, bao nhiêu tình cảm của Thời Vụ đều đặt hết nơi cô. Đã từng yêu cô đến thế, giờ phải đi đến bước ly hôn, trong lòng sao có thể dễ chịu được.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc cũng chẳng thoải mái hơn. Nhìn Thời Vụ bước vào, không còn nở nụ cười với cô như mọi khi, không gọi tên cô, cả người cô như bị kiến bò khắp, khó chịu đến cực điểm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng ổn, ký tên vẫn không thành vấn đề."</p><p style="text-align: justify; margin-bottom: 0.9em">Gương mặt nghiêng của Triệu Hy Ngọc lạnh lẽo mà quyết tuyệt. Cô không nhịn được hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không ly hôn có được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngước mắt nhìn cô, ánh mắt tĩnh lặng, như đang nhìn một người xa lạ. Trái tim Triệu Hy Ngọc như bị một bàn tay siết chặt, càng lúc càng đau. Hơi thở cô trở nên khó nhọc, sắc mặt trắng bệch. Khi Thời Vụ vừa quen cô, nàng cũng từng nhìn cô bằng ánh mắt như thế, chẳng khác gì cách nàng nhìn những người khác. Chính Triệu Hy Ngọc là người từng bước chủ động tiếp cận, chủ động trêu chọc, chủ động dỗ dành. Cho dù Thời Vụ có lạnh nhạt với cô thế nào, cô cũng nhận hết. Rồi đến một ngày, ánh mắt Thời Vụ nhìn cô bắt đầu có chút khác biệt tinh tế, nàng bắt đầu mỉm cười với cô, bắt đầu làm nũng với cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ là Thời Vụ của khi ấy đã không còn nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khôi phục vẻ bình thản thường ngày, nhàn nhạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không được."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nàng không lớn, thái độ cũng chẳng gay gắt, nhưng lại dứt khoát không chút do dự. Thời Vụ quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Luật sư Diệp, bắt đầu đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lấy tài liệu từ trong túi ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Nửa tiếng sau, hai người ký tên xong. Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có vấn đề gì thì tuần sau có thể làm thủ tục."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cố nén một tiếng ho, giọng hơi khàn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhìn sang Triệu Hy Ngọc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chín giờ sáng thứ Hai tuần sau, em đợi chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe tiếng ho của nàng, bàn tay đang duỗi ra của Triệu Hy Ngọc khựng lại, cuối cùng chỉ khẽ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nán lại thêm dù chỉ một giây. Hay nói đúng hơn, nàng thật sự không chịu nổi nữa. Vừa lên xe, nàng liền ho dữ dội. Những cảm xúc vừa cố đè nén lại trào lên. Một tay nàng nắm vô lăng, tay kia che miệng, nghiêng người sang một bên, ho đến mức như muốn bật cả phổi ra ngoài. Trước mắt choáng váng mất hai giây, Thời Vụ mới dần lấy lại được hơi thở. Nàng hạ ghế xe xuống, nằm ngửa trong xe, không nghĩ gì cả, để đầu óc hoàn toàn trống rỗng.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi cửa kính xe bị gõ vang, nàng đang chậm rãi điều hòa hơi thở. Thời Vụ quay đầu, nhìn thấy Diệp Lãnh Tinh đang đứng bên ngoài xe, liền vội hạ kính xuống. Trên gương mặt tái nhợt thoáng hiện một nụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Luật sư Diệp."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xin lỗi cô Thời, trời mưa thế này không dễ bắt xe. Có thể phiền cô đưa tôi đến một nơi được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ nhíu mày. Nhìn bầu trời âm u cùng cơn mưa phùn lất phất, kính chắn gió phía trước cũng đã ướt đẫm. Nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không vấn đề gì, lên xe đi, luật sư Diệp."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh đi sang ghế phụ, mở cửa ngồi vào, mang theo một thân hơi lạnh. Vai cô bị nước mưa làm ướt. Thời Vụ đưa khăn giấy cho cô. Diệp Lãnh Tinh vừa lau vừa ngượng ngùng giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xe tôi mang đi bảo dưỡng rồi, không ngờ hôm nay lại mưa, mà còn khá lớn."</p><p style="text-align: justify; margin-bottom: 0.9em">Quả thật rất lớn. Từ lúc Diệp Lãnh Tinh lên xe, cơn mưa phùn vừa rồi đã chuyển thành mưa như trút, đến cần gạt nước cũng gần như không kịp gạt. Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô Thời, chúng ta cứ lái chậm thôi, không cần vội."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu, lúc này mới nhớ ra hỏi Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đi đâu vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm Thái."</p><p style="text-align: justify; margin-bottom: 0.9em">Bàn tay đang nắm vô lăng của Thời Vụ siết chặt, gương mặt tái nhợt thoáng qua một tia cứng đờ. Mấy giây sau, nàng mới lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Luật sư Diệp và Lâm tổng có quan hệ khá tốt sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng được. Vợ tôi và cô ấy là bạn học. Nể mặt vợ tôi nên cô ấy mời văn phòng luật của chúng tôi làm cố vấn pháp lý."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mím môi, im lặng hai giây rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi nghe Lâm tổng nói, vụ ly hôn lần này của tôi là cô ấy nhờ cô giúp?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vụ ly hôn lần này có thể thuận lợi như vậy đều là nhờ công của cô Thời, tôi thật sự chẳng giúp được gì nhiều."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô khiêm tốn quá rồi. Nếu Triệu Hy Ngọc chịu chia tay trong êm đẹp thì quả thực chẳng cần Diệp Lãnh Tinh giúp gì nhiều. Nhưng nếu Triệu Hy Ngọc cứ dây dưa không chịu buông, vậy vai trò của Diệp Lãnh Tinh sẽ rất lớn. Cô chính là chỗ dựa của Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Dù thế nào đi nữa, lần này vẫn phải đặc biệt cảm ơn luật sư Diệp. Đợi tôi lấy được giấy chứng nhận ly hôn, tôi mời cô ăn cơm."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được thôi, vậy tôi có thể dẫn vợ tôi theo không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đương nhiên là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, nàng lại cố nén một tiếng ho. Diệp Lãnh Tinh hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô bị cảm à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hơi nhiễm lạnh một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh đưa tay ra, định thử nhiệt độ của Thời Vụ, nhưng lại cảm thấy không ổn nên bàn tay khựng giữa không trung. Cô nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hình như cô đang sốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Hai má tái nhợt của nàng ửng lên một màu đỏ bất thường, đáy mắt phủ một lớp hơi nước, rõ ràng là triệu chứng điển hình của sốt. Đôi mắt Thời Vụ cay xót, cổ họng cũng đau rát, vừa đau vừa ngứa. Nàng cố gắng chống đỡ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao, sáng nay tôi uống thuốc rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lo lắng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô chưa đi bệnh viện sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đến bệnh viện đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vẫn nên đến bệnh viện một chuyến đi. Dạo này cúm do virus nhiều lắm, uống thuốc cảm thông thường không có tác dụng đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Hai tay Thời Vụ nắm vô lăng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, đưa cô đến nơi xong tôi sẽ đến bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô đừng cố gắng quá. Nếu không khỏe thì để tôi tự bắt taxi qua đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn ra ngoài cửa kính:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trời đang mưa, khó bắt taxi lắm."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy hay là để tôi lái xe?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sự không sao, tôi vẫn lái được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Diệp Lãnh Tinh mới hơi yên tâm, chỉ là ánh mắt vẫn thường xuyên liếc sang Thời Vụ, có lẽ sợ nàng đang lái xe lại ngủ gật mất. Diệp Lãnh Tinh tìm một chủ đề:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô với Lâm tổng quen nhau thế nào vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhẹ giọng giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quen nhau do công việc."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh không phải Lâm Châu. Cô không chắc Lâm Nhược Đường có muốn Diệp Lãnh Tinh biết những chuyện trong quá khứ hay không, vì vậy không nhắc đến.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mới quen thôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng không hẳn, quen nhau khá lâu rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi còn tưởng hai người là bạn bè."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ liếc sang cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đây là lần đầu tiên cô ấy nhờ tôi giúp người khác xử lý một vụ kiện."</p><p style="text-align: justify; margin-bottom: 0.9em">Ngón tay Thời Vụ khẽ vuốt trên vô lăng. Lần đầu tiên sao? Mẹ nàng đúng là có thể diện thật.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ lại cũng phải. Nếu không nhờ mối quan hệ với Thời Ánh Xuân, sau vụ va chạm xe lần đó, Lâm Nhược Đường vốn chẳng đời nào đồng ý ăn bữa cơm ấy với nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng im lặng một lúc rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là Lâm tổng trọng tình trọng nghĩa."</p><p style="text-align: justify; margin-bottom: 0.9em">Trọng tình trọng nghĩa?</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh đã nghe rất nhiều lời đánh giá về Lâm Nhược Đường, nhưng đây là lần đầu tiên cô nghe thấy hai chữ "trọng nghĩa" dùng để nói về cô ấy. Bình thường khi làm ăn với đối tác, Lâm Nhược Đường là kiểu người hận không thể ép đối phương đến giọt máu cuối cùng, ngay cả 0,5% lợi nhuận cũng không chịu nhường.</p><p style="text-align: justify; margin-bottom: 0.9em">Trọng tình trọng nghĩa????</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ dám nói, cô cũng chẳng dám nghe.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh mang vẻ mặt khó nói thành lời, vội vàng đổi chủ đề:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô Thời, tiếp theo cô có dự định gì không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhất thời không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi nghe nói cô nghỉ việc rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừ, vừa mới nghỉ."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có nghĩ đến chuyện sau này sẽ làm việc ở đâu chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu tại sao ai cũng có vẻ hứng thú với công việc tiếp theo của nàng như vậy. Nàng lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vẫn chưa, tôi cần suy nghĩ kỹ."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nếu có gì cần thì cứ nói với tôi, tôi có một người bạn làm bên tuyển dụng. "</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cảm kích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Xe thuận lợi chạy vào bãi đỗ xe của Lâm Thái, xuống tầng B1. Nàng đỗ xe đúng chỗ hôm qua. Diệp Lãnh Tinh xuống xe rồi hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hay là xuống nghỉ một lát?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không khỏi nhớ đến chuyện hôm qua Lâm Nhược Đường cũng từng bảo nàng xuống xe nghỉ một lát. Nàng lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không đâu, tôi còn phải đến bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, vậy cô đi đường cẩn thận."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm nay cảm ơn cô, luật sư Diệp."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô mà khách sáo nữa thì tôi cũng ngại thu phí đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mỉm cười, nhìn theo Diệp Lãnh Tinh rời đi. Nàng không lập tức lái xe đi mà tựa vào lưng ghế. Tiếng còi xe khiến đầu nàng đau nhức, nàng khó chịu tắt máy, đưa tay ra phía sau lấy chai nước khoáng ở hàng ghế sau, uống hai ngụm để đè cơn ho xuống. Vừa nâng mắt lên, nàng nhìn thấy một chiếc xe khác đỗ ở vị trí đối diện.</p><p style="text-align: justify; margin-bottom: 0.9em">Một chiếc Range Rover màu đen.</p><p style="text-align: justify; margin-bottom: 0.9em">Tài xế mở cửa ghế sau, Lâm Nhược Đường bước xuống. Cô vẫn mặc bộ đồ công sở màu xám nhạt, sơ mi trắng phối cùng quần tây xám, chân đi giày cao gót. Mới đi được hai bước, giọng nói trong trẻo của cô đã vọng tới. Thời Vụ cứ ngồi yên nhìn như vậy. Người bước xuống bên cạnh Lâm Nhược Đường là Trần Hy, đang báo cáo gì đó với cô. Lâm Nhược Đường khẽ nhướng mày, nói gì đó. Khoảng cách không xa, nhưng Thời Vụ ngồi trong xe nên gần như không nghe thấy âm thanh bên ngoài.</p><p style="text-align: justify; margin-bottom: 0.9em">Có nên chào cô ấy một tiếng không?</p><p style="text-align: justify; margin-bottom: 0.9em">Hình như...</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn đang do dự, vừa ngước mắt nhìn sang Lâm Nhược Đường thì đúng lúc Lâm Nhược Đường cũng đưa mắt nhìn về phía nàng. Không biết cô đang nhìn chiếc xe của nàng, hay xuyên qua kính chắn gió nhìn thấy nàng ngồi ở ghế lái. Ánh mắt hai người chạm nhau qua lớp kính. Cổ họng Thời Vụ căng lên, hai tay siết lấy vô lăng, mu bàn tay nổi rõ gân xanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không có phản ứng gì, chỉ nhàn nhạt nhìn nàng một cái rồi dời mắt đi. Thời Vụ thở phào, cơ thể vừa rồi vì căng thẳng mà đau nhức, giờ thả lỏng xuống lại có chút choáng váng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ấn huyệt thái dương, tựa vào lưng ghế. Một lúc lâu sau, điện thoại rung lên. Nàng nhìn màn hình, không ngờ lại là tin nhắn Trần Hy gửi tới, hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">【Giám đốc Thời, người vừa rồi là chị sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy là vẫn nhìn thấy nàng rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Là tôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi còn tưởng mình nhìn nhầm. Biết thế vừa rồi đã chào chị một tiếng.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thuận tay trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi cũng tưởng mình nhìn nhầm.】</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy: 【Sao chị lại đến Lâm Thái vậy?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: 【Đưa luật sư Diệp qua đây.】</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy: 【Vất vả cho chị rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gửi lại cho cô một biểu cảm mỉm cười. Trần Hy nhìn về phía văn phòng đang đóng kín cửa. Bên trong, Diệp Lãnh Tinh và Lâm Nhược Đường đang ngồi đối diện nhau. Diệp Lãnh Tinh đưa túi tài liệu cho cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Biết cậu đang vội nên đóng dấu xong tôi mang qua cho luôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường mở túi tài liệu ra, nghe Diệp Lãnh Tinh nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đoán xem ai đưa tôi tới đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Người đối diện thậm chí chẳng buồn ngẩng đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh sửng sốt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao cậu biết?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nâng mí mắt nhìn cô một cái, giọng lạnh nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vừa rồi nhìn thấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được thôi, tôi còn định úp mở một chút. Cô ấy vẫn chưa đi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Không đợi Lâm Nhược Đường trả lời, Diệp Lãnh Tinh lẩm bẩm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải sốt đến mơ màng rồi đấy chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường siết chặt tập tài liệu trong tay, đầu ngón tay khẽ miết dọc theo mép giấy. Cô ngỡ mình nghe nhầm, liền hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu nói sốt đến mơ màng là sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"À, cô ấy bị cảm, đang sốt. Tôi thấy hình như sốt cũng khá cao, chẳng biết còn lái xe nổi không nữa. Đừng để giữa đường lại xảy ra chuyện gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lạnh lùng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy tốt nhất cậu nên cầu cho cô ấy không xảy ra chuyện gì. Nếu không, người đầu tiên phải chịu trách nhiệm chính là cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">—"...Sao lời này của cậu nghe dọa người thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không để ý đến cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lập tức tìm số điện thoại của Thời Vụ rồi gọi sang. Chuông reo vài tiếng, đầu bên kia truyền đến một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"A lô."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nói rất khẽ, mang theo vẻ yếu ớt vì đang bệnh, nhưng Lâm Nhược Đường vẫn nghe thấy. Ánh mắt cô vẫn dừng trên tập tài liệu trước mặt. Những con số vốn ngay ngắn trước mắt dần biến thành những ký hiệu méo mó. Diệp Lãnh Tinh hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô vẫn chưa đi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vẫn chưa, sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lập tức nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đừng đi đâu cả, tuyệt đối đừng đi, tôi qua ngay!"</p><p style="text-align: justify; margin-bottom: 0.9em">....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn 14 vé Bá Vương và 461 chai dịch dinh dưỡng của các tiểu thiên sứ~</p><p style="text-align: justify; margin-bottom: 0.9em">[Danh sách tài khoản độc giả tặng quà]</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Ghi sổ trước, sau này tính sổ.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh: "......"</p><p style="text-align: justify; margin-bottom: 0.9em">....</p><p style="text-align: justify; margin-bottom: 0.9em">Editor: Do dạo này mình bận build website nên thời gian edit bị giảm đi, nhưng sẽ cố gắng edit tiến độ nhanh trở lại, phần nhầm lẫn tên mình sẽ nhanh chóng chỉnh sửa lại cho đồng nhất. Với lại, do thời gian ngưng Edit quá lâu, sẽ có đôi lúc mình thậm chí bị quên cách xưng hô đã thiết lập ban đầu cho nhân vật, nếu đọc mà phát hiện sai sót hoặc điểm không hợp lý các bạn hãy để lại COMMENT để mình sửa lại, vì kể cả có edit hoàn đi nữa thì tỷ lệ sai sót vẫn có, mình ngoài edit các bộ trên này còn edit các bộ khác thuộc các thể loại khác nữa nên sai sót vẫn là xảy ra, quá trình edit hoàn không có nghĩa là kết thúc mà là vẫn sẽ là quá trình mình chỉnh sửa lại cho hoàn thiện hơn, vẫn là mong các bạn góp ý. Hiện tại trên Tấn Giang tác giả Ngư Sương đã viết xong và hoàn bộ: Đoạt Vợ, tổng cộng là: 142 chương cả phiên ngoại, mình sẽ cố gắng edit nhanh nhất để xong bộ này.</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 30, 'Giúp đỡ', '<p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cứ ngỡ Diệp Lãnh Tinh làm rơi thứ gì đó nên vẫn ngồi trong xe chờ. Mãi đến khi nghe thấy tiếng giày cao gót, nàng mới quay đầu lại. Diệp Lãnh Tinh xách túi, bước nhanh đến bên cửa xe của nàng rồi gõ nhẹ lên cửa kính. Thời Vụ quay sang nhìn, Diệp Lãnh Tinh ra hiệu cho nàng xuống xe. Thời Vụ không hiểu vì sao, nhưng vẫn mở cửa bước xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lập tức kéo nàng ra, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Để tôi lái xe, cô nghỉ một lát đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lúc này mới hiểu ra Diệp Lãnh Tinh đang lo cho mình, vội nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đâu, tôi lái được."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi cũng đang định đến bệnh viện, tiện đường."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hé miệng, cuối cùng vẫn đi sang ghế phụ, kéo cửa xe ngồi vào. Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chủ tịch Lâm cũng đang ở bệnh viện, tôi qua đó thăm bà ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là ở bệnh viện thật, nhưng làm gì có chuyện trùng hợp đến vậy. Thời Vụ hiểu rõ trong lòng, nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy cảm ơn luật sư Diệp."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô tranh thủ chợp mắt một lát đi, đến nơi tôi gọi cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Vốn dĩ Thời Vụ cũng không mệt đến thế, nhưng nghe Diệp Lãnh Tinh nói vậy, nàng bỗng cảm thấy mình thật sự mệt mỏi rã rời. Cơ thể nóng ran vì sốt cao, hai má đỏ ửng, đôi mắt phủ một tầng mơ màng. Sau khi ngồi xuống, Diệp Lãnh Tinh định giúp nàng thắt dây an toàn, chẳng ngờ vô tình chạm phải cánh tay nàng, lập tức giật mình:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao người cô nóng thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hoàn toàn không nhận ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nóng lắm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh đưa tay ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chắc là bị cảm rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Mu bàn tay cô áp lên trán Thời Vụ, nóng đến mức khiến cô kinh ngạc. Tay cô cũng bị hơi nóng hun đến nóng ran. Với nhiệt độ này, e rằng phải hơn bốn mươi độ. Ban đầu cô còn tưởng chỉ khoảng ba mươi bảy, ba mươi tám độ. Diệp Lãnh Tinh có chút áy náy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đáng lẽ tôi nên đưa cô đến bệnh viện sớm hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn còn tâm trạng nói đùa:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao, do thể chất của tôi thôi, cứ sốt là rất dễ sốt cao."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lo lắng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy thể chất này của cô vẫn nên ít ốm thì hơn. Sốt cao có thể làm hỏng cả đầu óc đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bị cơn sốt cao thiêu đến mức giọng nói hơi khàn, nàng trầm giọng đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi sẽ chú ý."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh vừa lái xe vừa quay đầu nhìn nàng, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật ra lần ốm này của cô chưa chắc đã là chuyện xấu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghiêng đầu nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Kết thúc một cuộc hôn nhân cũng giống như trải qua một trận ốm vậy. Đợi cô khỏi bệnh sẽ như trời quang mây tạnh."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nghỉ đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tựa vào ghế phụ, đầu óc nặng trĩu, chẳng bao lâu sau thật sự ngủ thiếp đi. Trời mưa lớn, Diệp Lãnh Tinh lái xe chậm, dọc đường còn nhận mấy cuộc điện thoại tư vấn. Không nghe thấy động tĩnh gì từ Thời Vụ, cô quay sang nhìn, thấy nàng ngủ rất say, đôi mày nhíu chặt. Vì khó chịu, trán nàng không ngừng toát mồ hôi. Diệp Lãnh Tinh không dám trì hoãn, xe vừa đến bệnh viện liền gọi Thời Vụ dậy, đỡ nàng đi về phía khu nội trú. Nàng lúc này mới chậm chạp nhận ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải chúng ta nên đến khoa cấp cứu sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bạn tôi có phòng bệnh ở đây, đang để trống, cô cứ vào nằm trước đi. Tôi vừa nói chuyện với cô ấy rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Vì sốt cao nên đầu óc Thời Vụ không còn tỉnh táo lắm. Diệp Lãnh Tinh bảo gì nàng làm nấy, thậm chí còn quên cả việc gọi điện cho Dư Mạt. Cứ mơ mơ màng màng như vậy, nàng được đưa lên tầng mười. Hai y tá trên tầng vừa thấy nàng liền lập tức bước tới. Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bệnh nhân ở đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ được y tá thay nhau dìu vào phòng bệnh, sau đó lại lấy máu, kiểm tra. Bác sĩ ra vào mấy lượt, khiến Thời Vụ thoáng có cảm giác sai lầm rằng mình không phải bị cảm sốt, mà là mắc phải bệnh nan y. Diệp Lãnh Tinh vẫn đứng bên cạnh hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bao nhiêu độ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá đo nhiệt độ rồi đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bốn mươi mốt độ."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh kinh ngạc:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chả trách lại nóng đến thế."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đã chẳng còn sức để nhấc tay, mí mắt nặng trĩu. Vốn dĩ trước khi Diệp Lãnh Tinh đưa nàng tới đây vẫn cảm thấy mình có thể tự chống đỡ được. Nhưng vừa đến bệnh viện, dường như mọi lớp phòng bị đều được tháo xuống, cả người lập tức rã rời. Bác sĩ bảo làm gì nàng làm nấy, hoàn toàn chẳng còn tâm trí tự quyết định nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng còn nghe thấy Diệp Lãnh Tinh gọi điện thoại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng, bốn mươi mốt độ, may mà đã đến bệnh viện rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Cũng không biết Diệp Lãnh Tinh đang nói chuyện với ai. Sau khi kiểm tra xong, Thời Vụ nằm trên giường bệnh, dịch truyền theo kim truyền chảy vào cơ thể, lạnh buốt. Cánh tay vốn đã lạnh của nàng nổi cả da gà. Y tá chu đáo đưa cho nàng một túi chườm ấm, Thời Vụ ôm trong lòng bàn tay, cảm thấy dễ chịu hơn rất nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh có lẽ khá bận, điện thoại hết cuộc này đến cuộc khác. Lúc Thời Vụ thấy cô ghé lại gần quan sát tình hình của mình, nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Luật sư Diệp, cô cứ đi làm việc đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Diệp Lãnh Tinh định xua tay, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bạn tôi chính là bác sĩ ở đây, lát nữa tôi sẽ bảo cô ấy qua, cô không cần lo."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Diệp Lãnh Tinh mới hơi do dự:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Thời Vụ rất khẽ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật. Hôm nay cô ấy đi làm, lát nữa tôi sẽ nhắn tin bảo cô ấy qua đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy được, văn phòng luật của tôi vẫn còn chút việc, tôi về trước. Nếu bạn cô không qua được thì gọi cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khó nhọc gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, làm phiền cô rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh vỗ nhẹ lên vai nàng, an ủi vài câu rồi rời đi. Thời Vụ nằm truyền dịch, mí mắt nặng đến mức không mở nổi, ý thức mơ hồ, cả người cứ chìm chìm nổi nổi. Lúc thì cảm thấy mình đang đứng ngoài trời dầm mưa lớn, lúc lại cảm thấy mình đang bị lửa thiêu, miệng khô lưỡi rát. Nàng khẽ ho vài tiếng, tự làm mình tỉnh giấc.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong phòng bệnh không có ai. Nàng cúi đầu nhìn cổ tay mình, trên đó vẫn còn kim lưu, nhưng chai truyền đã hết. Đoán chừng thuốc của hôm nay đã truyền xong, Thời Vụ lấy điện thoại từ trong túi ra, nhìn đi nhìn lại mấy lần mới xác định được — chín giờ rưỡi.</p><p style="text-align: justify; margin-bottom: 0.9em">Chín giờ rưỡi???</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đến bệnh viện lúc mấy giờ?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hoàn toàn không có chút ấn tượng nào, thậm chí còn chẳng nhớ mình đã đến đây bằng cách nào. Đầu óc vẫn mơ mơ màng màng, chưa tỉnh táo được bao nhiêu. Nàng đưa tay sờ trán, may mà không còn nóng đến thế nữa. Trong điện thoại có mấy cuộc gọi nhỡ, một cuộc của Kỳ Mai, hai cuộc của Dư Mạt, còn có một cuộc của Lâm Châu. Nàng bấm mở WeChat, lập tức bị hàng loạt tin nhắn dồn dập hiện ra kín màn hình.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt gửi nhiều nhất, ba phút trước vẫn còn hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cậu đâu rồi?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gọi cho cô trước. Điện thoại mới đổ chuông hai tiếng, Dư Mạt đã bắt máy, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu đang ở đâu vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hé mắt nhìn trần nhà. Xung quanh đều là mùi nước khử trùng. Chỗ này hình như là phòng bệnh riêng, chỉ bật một ngọn đèn đầu giường. Nàng không nhìn rõ cách bài trí trong phòng, chỉ cảm thấy khá rộng, bèn nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa thốt ra hai chữ, Thời Vụ đã siết cổ họng. Cái giọng khàn đặc như vịt kêu này thật sự là của nàng sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt rõ ràng cũng giật mình:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời Vụ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thôi xong, đến Dư Mạt còn không nhận ra giọng nàng. Thời Vụ mím môi hai giây rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhíu mày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giọng cậu làm sao thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bị sốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nàng thật sự khó nghe đến mức chính nàng cũng chẳng muốn nói nữa. Dư Mạt đoán trúng ngay:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu bị cảm nặng rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm, tôi đang ở bệnh viện, cậu đang ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi cũng đang ở bệnh viện đây. Hơn năm giờ tôi quay về một chuyến nhưng không thấy cậu, gọi điện cậu cũng không nghe. Vừa rồi cậu còn không trả lời tin nhắn, tôi đang định gọi cho luật sư hỏi thử."</p><p style="text-align: justify; margin-bottom: 0.9em">Luật sư.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt nhớ ra, là Diệp Lãnh Tinh đã đưa nàng đến bệnh viện. Những ký ức vụn vặt dần dần trở lại, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi ngủ quên mất, không để ý."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu đang ở khu nội trú à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm, tầng mười."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt mặc áo blouse trắng, vội vội vàng vàng chạy lên tầng mười. Lúc cô đến nơi, y tá vừa hay đang kiểm tra cho Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi y tá kiểm tra xong, Dư Mạt chào hỏi cô ấy vài câu rồi bước vào, một tay chống eo, chạy một mạch đến bên nàng, kinh ngạc hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao cậu lại nằm ở tầng mười?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tầng mười là phòng bệnh của nhà họ Lâm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thật sự không biết:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tòa nhà nội trú này do nhà họ Lâm tài trợ, cả tầng này đều là của nhà họ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng định vén chăn xuống giường, Dư Mạt vội nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ê ê ê, cậu đừng động."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không biết. Vậy cậu giúp tôi làm thủ tục xuất viện đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phòng bệnh này thì tôi thật sự không làm thủ tục xuất viện cho cậu được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng mím môi. Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao cậu vào được đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khàn giọng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Luật sư Diệp đưa tôi đến."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hiểu ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Luật sư Diệp là bạn của Lâm tổng, chắc là để tiện nên mượn cho cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cảm thấy sức nặng trên vai mình trong nháy mắt lại nặng thêm. Hôm qua nàng vừa thẳng thừng nói với Lâm Nhược Đường rằng không cần cô giúp đỡ, vậy mà hôm nay lại...</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt thấy sắc mặt nàng tái nhợt, đưa tay đặt lên trán nàng, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu vẫn còn sốt à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sốt nhẹ."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phải nằm viện mấy ngày?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu, trước mắt vẫn còn choáng váng, nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vừa rồi quên hỏi y tá rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt thấy nàng cố gắng mở mắt, bèn nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lát nữa tôi đi hỏi họ xem sao. Hay là cậu nghỉ trước đi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ "ừ" một tiếng. Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu có muốn ăn gì không? Tôi gọi cháo cho cậu nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không muốn." Thời Vụ nói: —"Tôi muốn uống nước."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn quanh rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Để tôi bật đèn."</p><p style="text-align: justify; margin-bottom: 0.9em">Trong phòng bệnh chỉ có một ngọn đèn đầu giường. Thời Vụ gật đầu, Dư Mạt "tách" một tiếng bật đèn lớn, cả căn phòng lập tức sáng bừng. Lúc này Thời Vụ mới nhìn rõ bên trong, sofa, TV, tủ lạnh, lò vi sóng, thứ gì cũng có, chỉ thiếu mỗi gian bếp. Dư Mạt nhìn thấy máy nước uống, tìm một chiếc cốc dùng một lần, rót cho nàng một cốc nước ấm. Thời Vụ được đỡ ngồi dậy, uống một ngụm cho ẩm cổ họng, cảm giác khó chịu nơi cổ họng lập tức dịu đi rất nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối nay tôi về lấy quần áo để cậu thay nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lát nữa tôi vẫn nên về nhà."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ngày mai cậu không truyền dịch nữa à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn kim lưu trên mu bàn tay, im lặng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đã nhập viện rồi thì cứ ở lại đi. Lát nữa tôi lấy quần áo cho cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">Phòng bệnh im lặng hai giây, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt thấy nàng uống hết một cốc nước, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Còn uống nữa không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu. Dư Mạt lại rót cho nàng một cốc, vừa đặt xuống tủ đầu giường thì điện thoại của Dư Mạt rung lên. Cô lấy điện thoại từ túi áo blouse trắng ra, nhìn tên người gọi rồi nói với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chủ nhiệm Thôi gọi tôi, tôi qua đó trước. Tối nay tôi trực, nửa đêm sẽ qua thăm cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu cứ lo việc đi." Thời Vụ nói: —"Chỗ tôi không cần lo."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Còn bảo không cần lo nữa, sơ ý một cái là vào viện rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ cười, sắc mặt vẫn tái nhợt. Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối một chút tôi sẽ mang trái cây và quần áo thay cho cậu. Còn cần mang gì nữa thì nhắn tin cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước khi rời đi, Dư Mạt vẫn không yên tâm dặn dò:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhớ nghỉ ngơi cho nhiều."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhìn theo Dư Mạt rời đi, sau đó quay đầu quan sát đầu giường của mình. Phía trên có dán thông tin liên lạc của bác sĩ trực ban, bác sĩ điều trị chính và y tá. Thời Vụ nằm trên giường, nhớ đến những cuộc gọi của Lâm Châu và Kỳ Mai, vừa đưa tay lấy điện thoại định gọi lại thì bên ngoài vang lên tiếng bước chân.</p><p style="text-align: justify; margin-bottom: 0.9em">Là tiếng giày cao gót.</p><p style="text-align: justify; margin-bottom: 0.9em">Tiếng bước chân ấy rất quen thuộc.</p><p style="text-align: justify; margin-bottom: 0.9em">Là Lâm Nhược Đường sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghe ra được đôi chút, nhưng lại không chắc chắn. Nàng do dự hai giây, vén chăn xuống giường, xỏ dép đi đến cửa. Vừa mở cửa phòng bệnh, nàng nhìn thấy một bóng người bước vào căn phòng chéo đối diện. Trước cửa phòng đó còn có mấy người mặc đồ đen đứng canh, là vệ sĩ. Thời Vụ lập tức hiểu ra, người đang ở trong căn phòng ấy chính là chủ tịch Lâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy Lâm Nhược Đường đến thăm bà nội cô ấy sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ siết chặt điện thoại trong tay, cũng không biết mình đang chờ đợi điều gì, cứ đứng bất động ở cửa. Vài phút trôi qua, nàng đứng đến mức đầu óc choáng váng, mới chậm rãi đi đến bên sofa ngồi xuống, tai vẫn luôn chú ý động tĩnh ngoài cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Năm phút, mười phút... Thời Vụ cũng không biết đã qua bao lâu, chỉ biết cơ bắp vì căng cứng mà bắt đầu đau nhức. Nàng liên tục nhìn ra ngoài cửa. Lâm Nhược Đường đi rồi sao? Không yên tâm, nàng lại đi đến cửa nhìn từ xa một lần, Trần Hy vẫn đang đứng ở đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Vẫn chưa đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Trái tim đang lơ lửng của nàng lại thấp thỏm không yên. Nàng cố gắng sắp xếp lời lẽ, nghĩ xem lát nữa nên nói thế nào. Đến khi thật sự nghe thấy tiếng giày cao gót vang bên ngoài, nàng vội vàng mở cửa. Lâm Nhược Đường quay đầu, ánh mắt nhàn nhạt lướt qua nàng. Tất cả những lời Thời Vụ đã chuẩn bị sẵn lập tức mắc kẹt trong bụng, cuối cùng nàng chỉ thốt ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm... Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Vì giọng khàn đặc, nghe càng thêm yếu ớt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhắm mắt lại, trong lòng dâng lên cảm giác áy náy. Quả thực nàng không thể nào thản nhiên được.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không lên tiếng, chỉ lặng lẽ nhìn nàng. Ánh sáng ngoài hành lang phản chiếu trong đôi mắt cô, sâu thẳm, tĩnh lặng và đen như mực. Trần Hy không chịu nổi bầu không khí gượng gạo, lên tiếng phá vỡ sự im lặng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời, chị không sao chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi truyền dịch rồi, giờ đỡ hơn nhiều."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, tôi chợt nhớ ra còn một cuộc điện thoại chưa gọi lại, tôi đi gọi điện trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường liếc sang cô, dường như nhìn thấu cái cớ vụng về ấy, nhưng cũng không ngăn cản, chỉ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đi đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy như được đại xá, vội vàng rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chần chừ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời có chuyện gì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Phía sau hai người, một vệ sĩ đứng bên cửa liếc mắt sang. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vào trong nói được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nghiêng người sang một bên, cũng không biết Lâm Nhược Đường có chịu vào hay không. Trong lòng thấp thỏm, nàng cúi đầu nhìn đôi giày cao gót của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường vẫn mặc bộ đồ lúc chiều, sơ mi trắng phối cùng quần âu đen, ống quần rất dài, phủ lên phần thân giày cao gót, chỉ để lộ mũi giày. Màu nâu cà phê, chất liệu da, không một vết xước. Dù chỉ nhìn thoáng qua, Thời Vụ vẫn cảm thấy sạch sẽ, chỉn chu đến mức không thể bắt bẻ.</p><p style="text-align: justify; margin-bottom: 0.9em">Năm ngón tay đang nắm tay nắm cửa phòng bệnh của nàng khẽ siết lại, trên cánh tay nổi rõ những đường nét cơ bắp mảnh mai, trơn mượt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn Thời Vụ đang mặc đồ bệnh nhân trước mặt. Mái tóc dài xõa trên vai, bộ đồ bệnh nhân rộng thùng thình che lấy cơ thể khiến nàng trông có phần nhợt nhạt và yếu ớt. Làn da vốn trắng, giờ hai má lại ửng đỏ bất thường vì cơn sốt, tựa như một lớp phấn hồng được thoa không đều, chỗ đậm chỗ nhạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Vốn đã có nét đẹp sẵn, dù trong bộ dạng thế này, nàng vẫn rất đẹp.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ là vẻ đẹp ấy giờ lại nhuốm thêm vài phần bệnh tật, khiến người ta nhìn mà xót xa.</p><p style="text-align: justify; margin-bottom: 0.9em">Đôi giày cao gót của Lâm Nhược Đường khẽ động, cô bước vào phòng bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Những ngón tay đang siết chặt tay nắm cửa của Thời Vụ dần thả lỏng, cả người cũng nhẹ nhõm hơn không ít. Sau khi hai người vào trong, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi nghe Dư Mạt nói, phòng bệnh này là của nhà họ Lâm."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Diệp Lãnh Tinh hỏi mượn tôi. Nếu cô muốn hỏi tội ai vì chuyện này thì nên tìm cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghẹn lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không có ý hỏi tội."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy sao?" Lâm Nhược Đường nói: —"Tôi còn tưởng Giám đốc Thời giận lắm chứ, còn định hỏi xem có cần tôi gọi điện cho Diệp Lãnh Tinh, mắng cô ấy một trận giúp cô không."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Có cần phải nói móc như vậy không?</p><p style="text-align: justify; margin-bottom: 0.9em">Tâm trạng khó khăn lắm nàng mới vực lên được, chỉ một câu của Lâm Nhược Đường đã khiến nó vỡ tan. Nghe vậy, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi mắng cô lúc nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chẳng phải hôm qua sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm qua tôi chỉ đang nói lý với cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không thích người khác nói lý với tôi, tôi chỉ cần biết kết quả."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng khẽ động môi nói với Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phải, hôm qua tính tôi không tốt. Tôi chỉ không ngờ lại đụng phải Triệu Hy Ngọc ở đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đụng phải thì đã sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao cả, tôi chỉ không thích bị tính kế như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng chằm chằm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô cảm thấy tôi đang tính kế cô sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi......" Thời Vụ nghẹn lời: —"Lâm tổng, tôi biết cô đang giúp tôi, nhưng đây là chuyện giữa tôi và cô ấy, tôi muốn tự mình giải quyết."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu, giọng không nghe ra vui giận:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thở phào:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Lâm Nhược Đường hơi trầm xuống, lạnh nhạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần khách sáo, Giám đốc Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tựa người vào sofa. Nói ra được những lời ấy, tâm trạng nàng cũng thả lỏng hơn. Nàng vừa định rót cho Lâm Nhược Đường một cốc nước thì ngoài cửa bỗng vang lên tiếng động. Thời Vụ cau mày, nghe thấy giọng Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, là em."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vội bước đến cửa mở ra. Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em nghe nói......"</p><p style="text-align: justify; margin-bottom: 0.9em">Chưa nói hết câu, cô nghi hoặc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị?"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao chị lại ở đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đến thăm bà nội, em đến đây làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu mím môi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em cũng đến thăm bà nội."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thăm rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà vừa ngủ, em chưa vào."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn cô một cái. Lâm Châu quay sang hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao chị lại bệnh vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cố nặn ra một nụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao em biết?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị nằm phòng bệnh của nhà em, sao em có thể không biết được." Cô quay đầu nhìn Lâm Nhược Đường: —"Chị, là chị sắp xếp à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Diệp Lãnh Tinh sắp xếp."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nghi hoặc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị Lãnh Tinh? Chị ấy sao lại......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ấy đang giúp chị xử lý vụ kiện ly hôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bừng tỉnh:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ồ...".  Sau đó cô chợt nhận ra điều quan trọng: —"Chị nói lại một câu xem."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Gì cơ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bật cười, bắt chước giọng Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ấy đang giúp chị xử lý vụ kiện ly hôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cười đủ rồi mới nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em Xin lỗi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhợt nhạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cụp mắt nhìn nụ cười bị Thời Vụ cố nặn ra, đầu ngón tay khẽ cọ xát. Lâm Châu hoàn toàn không hay biết, hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chị phải nằm viện mấy ngày?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vẫn chưa biết, ít nhất ba ngày."</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây mỗi lần nàng phải truyền dịch cũng đều ít nhất ba ngày.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy vất vả cho chị rồi. Em ghét bệnh viện nhất, mùi thuốc khử trùng thật sự không chịu nổi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không có cảm giác gì đặc biệt với bệnh viện. Có lẽ vì Thời Ánh Xuân là bác sĩ tâm lý, nên từ nhỏ nàng đã có thiện cảm tự nhiên với nghề bác sĩ, vô hình trung còn cảm thấy mùi thuốc khử trùng khiến người ta rất an tâm.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngoài cửa lại vang lên tiếng gõ. Thời Vụ không biết tối nay còn có ai đến nữa. Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là chị Lâm, em nhờ chị ấy mua giúp ít trái cây."</p><p style="text-align: justify; margin-bottom: 0.9em">Vẻ mặt Thời Vụ thoáng ngẩn ra hai giây rồi chân thành nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn, thật ra không cần đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cần chứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng đứng dậy đi ra cửa. Quả nhiên người đứng bên ngoài là chị Lâm. Vừa nhìn thấy Thời Vụ, chị Lâm đang định mỉm cười chào hỏi, nhưng khi liếc thấy Lâm Nhược Đường đứng bên cạnh nàng, nụ cười trên mặt lập tức cứng lại. Chị chớp mắt, rồi mới dè dặt gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường liếc nhìn chị một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Chị Lâm mỉm cười với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời, chút trái cây thôi, không đáng để cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Chị vốn là người tinh ý, thái độ kiêu ngạo vừa rồi đối với Thời Vụ lập tức thu lại không ít. Nếu nói Lâm Châu hợp tác với Thời Vụ vì thích gương mặt của nàng, chị cũng chẳng để tâm. Nhưng Lâm Nhược Đường thì khác. Giờ cô đang đứng ngay trong phòng bệnh của Thời Vụ, ý nghĩa hoàn toàn khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ định đưa tay nhận lấy, nhưng Lâm Châu đã cầm giúp nàng, đặt lên bàn trà. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn chị Lâm."</p><p style="text-align: justify; margin-bottom: 0.9em">Chị Lâm lắc đầu cười, ra hiệu không cần khách sáo, sau đó quay sang nói với Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Châu, em ra đây một lát."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đang định bóc quýt, nghe vậy liền nhìn chị Lâm. Chị Lâm khẽ gật đầu, Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy chị Thời, em ra ngoài một lát."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn hai người rời đi, phòng bệnh lại trở về yên tĩnh. Nàng liếc sang Lâm Nhược Đường. Người này vẫn bình thản, nét mặt chẳng để lộ chút cảm xúc nào, đôi mắt lạnh nhạt. Thời Vụ ngồi trên sofa, lấy một quả quýt trong giỏ trái cây, bóc vỏ rồi đưa cho Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, ăn quýt đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cũng không khách sáo, nhận lấy từ tay nàng, bóc một múi rồi thong thả ăn.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nhất thời thật sự chẳng phân biệt nổi ai mới là bệnh nhân.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vừa định nói chuyện thì cổ họng ngứa ngáy, nghiêng đầu sang một bên ho khan, đến nước mắt cũng bị ho đến trào ra. Lâm Nhược Đường quay đầu nhìn đuôi mắt nàng, long lanh ướt át, khẽ chao động.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhai múi quýt, nước quả căng mọng, ngay cả đầu lưỡi cũng ngập trong vị chua ngọt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ho thêm mấy tiếng mới dịu lại. Cơ thể yếu ớt tựa vào sofa, sống lưng mảnh mai, gầy đi trông thấy, sắc mặt càng thêm tái nhợt. Cơn bệnh đè nặng nơi chân mày, khiến cả người nàng trông vô cùng yếu ớt. Lâm Nhược Đường chăm chú nhìn nàng, lại bóc thêm một múi quýt, đưa vào miệng.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong căn phòng bệnh yên tĩnh, khi không còn ho nữa, Thời Vụ cũng chẳng phát ra tiếng động gì. Nàng ôm bụng dưới, có chút ngượng ngùng nói với Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, tôi đi vệ sinh một lát."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bước nhanh vài bước vào nhà vệ sinh. Có lẽ vì vừa tỉnh dậy đã uống liền hai cốc nước, cộng thêm cả buổi chiều truyền dịch nên nàng buồn tiểu rất gấp. Nàng vừa mở vòi nước vừa đi vệ sinh.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngồi trên sofa, nghe thấy có người gọi mình. Giọng nói khàn khàn, trầm thấp, vọng ra từ phía sau. Cô cau mày, quay đầu đi đến trước cửa nhà vệ sinh, gõ cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vội nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, là tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nàng vốn đã khàn, vì vậy rất nhỏ, lại thêm nhà vệ sinh cách âm khá tốt, ban đầu Lâm Nhược Đường không nghe rõ. Cô hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trong nhà vệ sinh hết giấy rồi, cô có thể lấy giúp tôi một gói được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đảo mắt nhìn quanh phòng bệnh, thấy khăn giấy trên bàn trà. Cô bước tới, đi được hai ba bước lại quay về. Lúc Thời Vụ vừa đi vào đã tiện tay mở khóa cửa nhà vệ sinh, giờ đang ngồi lại trên bồn cầu. Nàng nói với Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, cửa không khóa, cô nhét vào giúp tôi, hoặc cô để ở cửa cũng...."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng còn chưa nói hết, cửa nhà vệ sinh đã "cạch" một tiếng hé ra một khe. Thời Vụ lập tức dùng hai tay túm chặt quần bệnh nhân. Lâm Nhược Đường không nhét gói khăn giấy vào, ngược lại còn thản nhiên hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời, nếu tôi không nghe nhầm, cô đang nhờ tôi giúp đỡ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Người này sao lại thù dai đến vậy chứ? Chỉ một gói khăn giấy thôi mà, có cần phải thế không?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nghiến răng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng vậy, Lâm tổng, cô không nghe nhầm."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy tức là cô thừa nhận mình cần tôi giúp?"</p><p style="text-align: justify; margin-bottom: 0.9em">Ý cô là "sau này".</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu, không cần suy nghĩ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi thừa nhận, tôi cần cô giúp."</p><p style="text-align: justify; margin-bottom: 0.9em">Ý nàng là "ngay lúc này".</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe vậy, vẻ mặt lạnh lùng suốt cả ngày của Lâm Nhược Đường cuối cùng cũng giãn ra, chân mày ánh lên vẻ vui thích. Cô cong môi, giọng nói nhẹ tênh:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Được thôi ."</p><p style="text-align: justify; margin-bottom: 0.9em">.....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn 10 phiếu Bá Vương và 711 chai dung dịch dinh dưỡng của các tiểu thiên thần~</p><p style="text-align: justify; margin-bottom: 0.9em">Phát ngẫu nhiên 100 bao lì xì nhé.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Đây chính là lời em nói đấy 😼😼 Thời Vụ: ..................</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 31, 'Tắm rửa', '<p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu chỉ ra ngoài một chuyến, lúc trở về đã nhận ra tâm trạng của chị mình khác hẳn ban nãy. Mười phút trước, khi vừa bước vào, giọng Lâm Nhược Đường nói với cô còn lạnh như băng. Tuy lúc này giọng điệu vẫn lạnh nhạt như cũ, nhưng chẳng hiểu sao Lâm Châu lại cảm thấy, so với ban nãy thì đã dịu đi không ít, quả thực chẳng khác nào gió xuân phả mặt.</p><p style="text-align: justify; margin-bottom: 0.9em">Đôi mắt xinh đẹp của cô đảo sang Thời Vụ, lại liếc qua Lâm Nhược Đường, rồi cuối cùng quay về phía Thời Vụ, tò mò ghé lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, vừa rồi hai người nói chuyện gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vừa từ nhà vệ sinh bước ra, tay còn chưa kịp lau khô đã bị cô kéo lấy. Nàng ngơ ngác:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có nói gì đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Nãy giờ nàng vẫn ở trong nhà vệ sinh, căn bản chưa hề nói chuyện với Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu không tin:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao có thể?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sự không nói gì mà, chị đi vệ sinh."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy chị em đã làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ấy chẳng làm gì cả."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe giọng điệu của Lâm Châu, cứ như thể Lâm Nhược Đường đã làm gì nàng vậy. Cô nheo mắt nhìn chị mình, nhưng vừa chạm phải ánh mắt lạnh nhạt sắc như dao của Lâm Nhược Đường, chút tâm tư muốn hóng chuyện lập tức bị chém sạch. Lâm Châu vội nở nụ cười lấy lòng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, lát nữa đưa em về nhà nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lạnh nhạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xe em đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị Lâm về trước rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hờ hững:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu còn chưa kịp mừng thì cô đã nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trả tiền xe."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô lén nhe răng trợn mắt với bóng lưng Lâm Nhược Đường, sau đó quay sang Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị xem chị em keo kiệt chưa kìa."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ đảo mắt, không nhịn được bật cười. Lâm Châu thấy vậy liền hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị có muốn nghỉ ngơi không?."</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra Thời Vụ vẫn ổn. Hôm nay nàng đã ngủ gần như suốt cả buổi chiều, chẳng qua không muốn làm mất thời gian của hai chị em họ nên mới nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hơi buồn ngủ một chút, chắc thuốc bắt đầu có tác dụng rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu "ồ" một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Buổi tối không có ai ở lại đây với chị sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Dư Mạt sẽ tới."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng giải thích thêm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là người bạn bác sĩ hôm đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em nhớ chị ấy. Khỏe ghê lắm, hôm đó bế chị lên lầu mà nhẹ tênh."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm đó cảm ơn em nhé. Tửu lượng của chị không được tốt lắm."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hiểu mà. Nếu là em, chắc em ngày nào cũng uống đến say mất."</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi Thời Vụ khẽ giật. Ngày nào cũng uống đến say thì chưa đến mức đó, nàng cũng không cho phép bản thân buông thả như vậy. Chỉ một lần hiếm hoi mất kiểm soát đã đủ khiến nàng mất mặt đến chẳng muốn nhớ lại, trong thời gian ngắn này nàng tuyệt đối không muốn đụng đến rượu nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường giơ cổ tay xem giờ, rồi hỏi Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hay là em ở lại đây qua đêm?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lập tức:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đi thôi!"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bước đến bên Lâm Nhược Đường rồi nói với nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chị nghỉ ngơi cho khỏe nhé. Khi nào rảnh em lại tới thăm chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần qua nữa đâu, chị sắp được về nhà rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được thôi, vậy có chuyện gì thì gọi cho em."</p><p style="text-align: justify; margin-bottom: 0.9em">Sự chu đáo của một người trưởng thành vào khoảnh khắc này khiến lòng Thời Vụ chợt ấm lên. Nàng cũng không ngờ rằng sau khi ly hôn, những người khiến nàng lưu luyến nhất lại là hai chị em nhà họ Lâm — những người mà trước đây nàng thậm chí còn chẳng dám nghĩ tới.</p><p style="text-align: justify; margin-bottom: 0.9em">Đáy mắt Thời Vụ thoáng dâng lên một tầng hơi nước. Nàng khẽ gật đầu, dặn Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về cẩn thận."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cười hì hì:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có chị em ở đây, chị cứ yên tâm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn sang Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Đường nét chân mày của người phụ nữ này sắc sảo, gương mặt chẳng để lộ vui buồn. Ánh mắt cô hờ hững quét sang, Thời Vụ theo bản năng thẳng lưng, những ngón tay khẽ siết lấy ống quần bệnh nhân. Nàng muốn nói gì đó, nhưng lời đến bên môi lại thôi. Mãi đến khi tiễn hai người ra tận cửa, nàng vẫn không nhịn được mà lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, lái xe chậm một chút nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghiêng mắt liếc nàng, thản nhiên đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải tôi lái."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là mình nhiều lời rồi !</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cố nén khóe môi đang muốn cong lên. Còn chưa kịp nói gì, Lâm Nhược Đường đã tiếp lời:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhưng tôi sẽ chuyển lời giúp cô đến Trần Hy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười, chân thành nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn gương mặt tươi cười của nàng hồi lâu, vài giây sau mới dời mắt đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy vẫn luôn chờ dưới lầu, từ xa đã nghe thấy giọng Lâm Châu vang lên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chị tới từ lúc nào vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, sao chị biết chị Thời Vụ bị bệnh?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị...... ưm......"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy ngẩng đầu, vừa hay nhìn thấy Lâm Nhược Đường đang bóp miệng Lâm Châu lại như bóp mỏ vịt. Thế giới lập tức yên tĩnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ưm ưm ưm!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối nay nói với bà nội, tiền sinh hoạt tháng này của em hơi nhiều rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ưm!"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô lập tức im bặt.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy mở cửa ghế sau cho hai người. Lâm Châu nhỏ giọng chào cô, nhưng vừa lên xe đã đột nhiên "á" lên một tiếng, khiến Trần Hy giật mình quay đầu lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu chỉ về phía trước xe, vẻ mặt như vừa nhìn thấy ma:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cái này ở đâu ra vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nhìn theo hướng cô chỉ. Đó là một món đồ treo nhỏ xíu, nghe nói là đồ trang trí trên xe. Cô cũng chưa từng thấy món nào nhỏ đến vậy, chẳng qua là Lâm Nhược Đường đưa cho nên cô không dám hỏi nhiều, cứ thế treo lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chị......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên buông một câu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiền sinh hoạt."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nhìn Lâm Châu hiếm khi im thin thít suốt cả quãng đường, không nhịn được bật cười. Đến khi xe về tới biệt thự, cuối cùng Lâm Châu cũng nhịn hết nổi. Cô ghé sát bên tai Lâm Nhược Đường, hạ giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, tháng này chị có cho em tiền sinh hoạt thì em vẫn phải nói. Chị đúng là độc ác quá đi!!!"</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, cô rụt vai, một tay dùng sức kéo cửa xe, nhanh như chớp chạy mất, quyết không cho Lâm Nhược Đường cơ hội véo tai mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại chẳng hề tức giận.</p><p style="text-align: justify; margin-bottom: 0.9em">Bình thường, mỗi khi Lâm Châu nói mấy lời thiếu đòn như thế, Lâm Nhược Đường luôn mặc kệ cô, đợi đến khi cô tự chột dạ rồi chủ động chạy tới nhận lỗi mới thôi. Nhưng lần này lại khác. Lâm Nhược Đường không những không giận, sau khi về nhà còn chủ động hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trái cây em mua ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhất thời chưa phản ứng kịp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trái cây? Trái cây gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Một lúc sau cô mới hiểu ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"À, chị nói trái cây em mua cho chị Thời Vụ ấy à? Em mua ngay gần bệnh viện. Chị muốn ăn sao? Trên mạng đặt được đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mua ít cam đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu "ồ" một tiếng, tiện tay đặt cam, táo và dâu tây. Thật ra cô cũng đang thèm. Ban đầu còn định ở phòng bệnh ăn ké chút trái cây, ai ngờ lại bị chị mình gọi về. Đặt hàng xong, cô trở về phòng tắm rửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Đến khi tắm xong đi ra, Lâm Nhược Đường đã không còn ở đó. Mãi đến lúc trái cây được giao tới, cô mới sang gõ cửa phòng chị mình. Lâm Nhược Đường bưng cốc cà phê bước ra, Lâm Châu đưa cho cô một túi cam. Cô lấy một quả rồi đi vào bếp, đợi cà phê pha xong mới thong thả bóc vỏ.</p><p style="text-align: justify; margin-bottom: 0.9em">Cam không mọng nước, vị cũng chẳng đủ ngọt. Lâm Nhược Đường chỉ ăn hai múi rồi trở lại phòng khách, tiện tay đưa phần còn lại cho Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Này..."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không ăn nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lãng phí quá đi mất!</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu ghét nhất kiểu lãng phí đồ ăn thế này. Cô cảm thấy trở ngại lớn nhất trên con đường giảm cân của mình chẳng phải những món ngon đầy rẫy ngoài kia, mà chính là Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa ấm ức cắn cam, cô vừa chợt nhớ ra một chuyện:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, hay là để chị Thời Vụ tới studio của em làm việc đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đến studio của em làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Làm bên quan hệ công chúng ấy. Quản lý PR trước đây của em nghỉ rồi, đến giờ vẫn chưa tìm được người thích hợp."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Lâm Nhược Đường lạnh nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em thấy cô ấy thích hợp?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp ngay:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thích hợp chứ, sao lại không? Chị ấy xử lý mọi chuyện khá có chừng mực. Chỉ riêng chuyện ly hôn thôi là em nhìn ra được, chị ấy là người có nguyên tắc, lại còn rất đàng hoàng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường chỉ dùng một câu đã thẳng tay bác bỏ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ấy uống rượu kém."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Hóa ra không thích hợp là ở chỗ này.</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy bản thân Lâm Châu cũng cực kỳ ghét thứ văn hóa bàn rượu tệ hại ấy, nhưng đã ở trong giới thì khó tránh khỏi những cuộc xã giao. Huống hồ sự nghiệp của cô vẫn đang trên đà phát triển. Nghĩ đến đây, Lâm Châu tiếc nuối:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiếc thật, nếu không thì ngày nào em cũng được gặp chị ấy rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Người ta chưa chắc đã muốn ngày nào cũng gặp em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......Chị ấy thích em lắm đấy, được chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đưa mắt đánh giá cô từ trên xuống dưới, vẻ ghét bỏ trong ánh mắt chẳng buồn che giấu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu chịu hết nổi, lập tức than thở:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng vâng vâng, chị ấy không muốn ngày nào cũng gặp em. Chị ấy muốn ngày nào cũng gặp chị. Chị ấy không thích em, chị ấy thích chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Cũng chẳng chịu tự nhìn lại cái dáng vẻ khó ưa của mình, ai mà thích cho nổi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng câu này Lâm Châu không dám nói thành lời, chỉ có thể nặn ra một nụ cười giả lả.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn cô, ung dung nhận xét:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cười giả tạo thật."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Tức chết cô rồi. Nhất định phải tìm người để mách mới được. Lâm Châu liền nhớ đến Thời Vụ, chắc hẳn là đang nằm nghỉ ngơi, cô liền nhắn cho nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">["Chị thấy chị em thế nào?"]</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghi hoặc đọc đi đọc lại tin nhắn mấy lần, thậm chí còn đưa tay sờ trán, tưởng mình lại sốt nên nhìn nhầm. Gì vậy, "chị thấy chị em thế nào"? Lần trước nghe câu này là lúc có người giới thiệu đối tượng cho nàng. Người mai mối hỏi như vậy, đương nhiên Thời Vụ sẽ không nghĩ Lâm Châu có ý đó, nhưng nàng vẫn nghiêm túc suy nghĩ câu hỏi này.</p><p style="text-align: justify; margin-bottom: 0.9em">Ban đầu, nàng quả thực từng cho rằng Lâm Nhược Đường là kiểu người ham mê sắc đẹp. Cũng chẳng trách nàng được, lần đầu gặp đã bị nhét thẻ phòng vào tay, ai gặp tình huống ấy mà chẳng hiểu lầm. Nhưng sau khi biết Lâm Nhược Đường làm vậy là để nhắc nhở nàng về chuyện giữa mình và Triệu Hy Ngọc, ấn tượng của nàng đã thay đổi đôi chút. Hơn nữa, Lâm Nhược Đường còn giúp nàng vài lần, tuy chẳng thể nói là tốt đến mức nào, nhưng ít nhất cũng không tệ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">["Sao tự nhiên lại hỏi vậy?"]</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">[-"Chị ấy vừa bảo lúc em cười trông giả tạo lắm."]</p><p style="text-align: justify; margin-bottom: 0.9em">Dù chỉ cách một màn hình, Thời Vụ vẫn cảm nhận được vẻ hờn dỗi trẻ con của cô. Chẳng hiểu sao, nàng bỗng nghĩ đến chuyện sau này nếu mình có em gái thì sẽ thế nào. Liệu cũng sẽ giống Lâm Châu, hay sẽ giống Triệu Tinh?</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi đang cong lên của Thời Vụ khẽ hạ xuống. Nàng dỗ dành:</p><p style="text-align: justify; margin-bottom: 0.9em">["Sao có thể chứ, em cười lên trông rất xinh."]</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">["Thật sao chị? Chị thấy em xinh à?"]</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">["Tất nhiên rồi, cười lên còn xinh hơn nữa."]</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">["Em đã bảo mắt chị em có vấn đề mà."]</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhất thời không biết nên trả lời thế nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">["Chị đừng nói cho chị ấy biết nhé."]</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">["Được."]</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đặt điện thoại xuống, bước tới bên cửa sổ. Tầng mười không quá cao, chỉ bằng khoảng nửa tòa nhà đối diện. Cây cối hoa cỏ bên dưới vẫn có thể nhìn thấy rõ, chỉ là trời đã tối, bóng cây loang lổ mờ mờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi chiều Thời Vụ ngủ khá nhiều nên lúc này không buồn ngủ lắm. Nàng cầm điện thoại định ra khỏi phòng, y tá lập tức bước tới ngăn lại. Thời Vụ giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi xuống dưới đi dạo một lát thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá vẫn không yên tâm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô Thời, sức khỏe của cô vẫn chưa hồi phục hẳn, bất cứ lúc nào cũng có thể sốt lại. Tốt nhất đừng ra ngoài hóng gió."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng chẳng biết từ bao giờ mình lại trở nên yếu ớt đến vậy, nhưng nàng rất nghe lời:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, tôi sẽ về ngay."</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá đưa nàng đến thang máy, còn giúp nàng bấm nút. Thời Vụ bước vào. Bên trong thang máy có gương, bộ đồ bệnh nhân màu xanh trên người nàng hơi rộng, trông có phần thùng thình. Thời Vụ vuốt lại tóc, chợt hơi hối hận vì vừa rồi không rửa mặt. Nàng nhìn mình trong gương một lát, rồi "đinh" một tiếng, tầng năm đã tới.</p><p style="text-align: justify; margin-bottom: 0.9em">Khu nội trú về đêm rất yên tĩnh, thỉnh thoảng mới vọng lại tiếng bước chân. Thời Vụ đi dép lê đến quầy y tá, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bác sĩ Dư Mạt có ở đây không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá ngẩng lên nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ấy đang ở phòng phẫu thuật."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, y tá lại nhìn Thời Vụ thêm một lần. Đẹp thật. Là bệnh nhân của Dư Mạt sao? Nhập viện từ lúc nào vậy? Sao cô ấy lại không biết?</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt y tá cứ dừng trên người mình, còn nhìn thêm mấy lần. Nghe nói Dư Mạt đang phẫu thuật, Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá thấy nàng xoay người định đi, vội nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"À, cô ở phòng bệnh nào vậy? Đợi bác sĩ Dư ra tôi bảo cô ấy qua."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đâu, cảm ơn. Tôi là bạn của cô ấy, để tôi tự nhắn tin cho cô ấy là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá tiếc nuối:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ biết Dư Mạt bận. Ca trực này vốn đã chẳng có mấy bác sĩ, Dư Mạt lại càng bận hơn, nên nàng không gọi điện, cũng không nhắn tin làm phiền cô, mà một mình xuống lầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Gió đêm từng cơn thổi tới, hơi lạnh. Nhưng Thời Vụ vẫn còn sốt nhẹ, cái lạnh ấy trái lại khiến nàng dễ chịu hơn đôi chút. Nàng ngồi xuống chiếc ghế dài bên bồn hoa giữa khu nội trú. Đúng lúc ấy, phía sau vang lên một giọng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em biết rồi, em về ngay, chị...."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu, ánh mắt vừa vặn chạm phải Triệu Tinh.</p><p style="text-align: justify; margin-bottom: 0.9em">Không ai ngờ lại gặp nhau vào lúc này. Cô ta hơi khựng lại, vẻ mặt Thời Vụ cũng thoáng sững sờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Tinh siết chặt điện thoại. Giọng người bên kia đầu dây dần xa rồi tắt hẳn. Cô ta nhìn Thời Vụ hồi lâu, ánh mắt từ trên xuống dưới lướt qua bộ đồ bệnh nhân trên người nàng, khẽ nhíu mày.</p><p style="text-align: justify; margin-bottom: 0.9em">Lại giở trò gì nữa đây? Chẳng phải muốn ly hôn sao? Ly hôn đến mức vào cả bệnh viện rồi? Hay là định giả vờ đáng thương?</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Tinh cúp máy, nhìn Thời Vụ với ánh mắt đầy đề phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nhìn cô ta như vậy, Thời Vụ lại chỉ thấy đáng thương.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây nàng còn từng bị Dư Mạt mắng là "não yêu đương", giờ đúng là nên để Dư Mạt tới xem thử thế nào mới gọi là não yêu đương. Nàng thật sự không hiểu nổi, Triệu Tinh đã đồng ý với yêu cầu của Triệu Hy Ngọc bằng cách nào. Hay là... đó vốn cũng là điều cô ta mong muốn?</p><p style="text-align: justify; margin-bottom: 0.9em">Tiếng còi xe cứu thương phá tan sự im lặng giữa hai người. Triệu Tinh lên tiếng trước:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao chị lại ở đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt thấy thái độ hờ hững, nhẹ tênh của Lâm Nhược Đường thật sự rất hữu dụng, nàng học theo:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi bị bệnh."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Tinh không chịu bỏ qua, ánh mắt nghi ngờ lại quét qua nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"  Là Bệnh gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có liên quan gì đến cô?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn Thời Vụ lúc này sắc sảo như có gai, Triệu Tinh bỗng cảm thấy nàng thật xa lạ. Trước kia, khi còn ở bên Triệu Hy Ngọc, Thời Vụ luôn dịu dàng. Mà cũng không hẳn là dịu dàng, chỉ có thể nói nàng luôn bình thản, yên tĩnh như nước, chẳng mấy khi nổi nóng, cũng chẳng hề có góc cạnh như bây giờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ta mím môi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chỉ là quan tâm chị thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quan tâm tôi? Hay là quan tâm xem tôi đã ly hôn hay chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Tinh im lặng. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Yên tâm đi, tôi không thích mấy chuyện lòng vòng dây dưa, càng không khinh dùng những thủ đoạn hèn hạ. Tôi đã nói ly hôn thì chính là ly hôn. Cô có thể ở bên Triệu Hy Ngọc rồi, đáng lẽ cô phải vui mới đúng."</p><p style="text-align: justify; margin-bottom: 0.9em">Không hề tức giận, cũng chẳng có chút lưu luyến nào. Triệu Tinh cuối cùng vẫn không nhịn được:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chị thật sự thích chị ấy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao? Theo cô thì chia tay nhất định phải khóc lóc ầm ĩ, sống chết không chịu buông mới gọi là thích sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Tinh nhìn chằm chằm vào nàng. Thời Vụ không né tránh, trái lại còn thẳng thắn đối diện với ánh mắt cô ta:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Triệu Tinh, thật ra tôi đã sớm biết bộ lễ phục đó là do cô tráo."</p><p style="text-align: justify; margin-bottom: 0.9em">Sắc mặt Triệu Tinh thoáng thay đổi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao chị biết?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô tưởng để Triệu Hy Ngọc cắt đoạn camera giám sát đi thì tôi sẽ không còn bằng chứng sao? Trên khóa điện tử có dấu vân tay của cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ta siết chặt điện thoại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy sao chị không nói với chị tôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bởi vì tôi biết chị ấy vẫn luôn áy náy với cô. Tôi không muốn khiến chị ấy khó xử." Thời Vụ nhìn cô ta, giọng bình thản. "Triệu Tinh, tôi không giống cô. Tôi sẽ không dùng cách làm tổn thương một người khác để đạt được thứ mình muốn."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Tinh cau mày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi chưa từng nghĩ sẽ làm tổn thương chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Triệu Tinh, chẳng lẽ cô không định đợi đến sau khi đứa bé ra đời rồi mới tranh với tôi cho ra lẽ sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bị nói trúng tâm tư, sắc mặt cô ta trầm xuống:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trước đây tôi vẫn không hiểu chị ấy thích chị ở điểm nào. Tôi cứ nghĩ cùng lắm chị chỉ xinh đẹp hơn một chút. Không ngờ chị lại thông minh đến vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi chẳng thông minh chút nào. Bao lâu nay vẫn bị các cô xoay như chong chóng. Nhưng Triệu Tinh, tôi vẫn phải cảm ơn cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Tinh khó hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn tôi chuyện gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn cô đã giúp tôi nhìn rõ Triệu Hy Ngọc."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, Thời Vụ không quay về chiếc ghế dài nữa. Triệu Tinh nhìn theo bóng lưng nàng, hai tay siết chặt đến mức lòng bàn tay đau nhói.</p><p style="text-align: justify; margin-bottom: 0.9em">Rõ ràng cô ta đã thắng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thế nhưng lại chẳng hề thấy vui.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không để tâm đến ánh mắt cay độc sau lưng. Nàng đi được vài bước thì phải vịn vào tường. Cơn ho vừa rồi bị cố nén xuống, giờ lại ập đến dữ dội hơn, ho đến mức đầu óc choáng váng. Nàng dựa vào tường hồi lâu vẫn chưa hoàn hồn.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc điện thoại rung lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Là tin nhắn của Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đến tìm tôi à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ừm, vừa định xem cậu có bận không.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Bận muốn ói luôn rồi, vừa có thêm một ca cấp cứu, tôi phải xuống dưới. Cậu vẫn ổn chứ?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không sao. Tôi còn đi tìm cậu được thì cậu còn lo gì cho tôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cũng phải.】</p><p style="text-align: justify; margin-bottom: 0.9em">Sợ làm ảnh hưởng đến công việc của Dư Mạt, Thời Vụ không nhắn thêm mà quay về phòng bệnh. Y tá còn căng thẳng hơn cả nàng, vừa vào đã đo nhiệt độ ngay cho nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Ba mươi tám phẩy một độ.</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá dặn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phải chú ý bất cứ lúc nào, nếu thấy có chỗ nào không khỏe thì bấm chuông ngay."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu. Nói chuyện với Triệu Tinh nàng không thấy khó chịu, trò chuyện với y tá cũng chẳng có gì không ổn. Thế nhưng khi chỉ còn lại một mình, nàng lại thực sự cảm thấy không được khỏe.</p><p style="text-align: justify; margin-bottom: 0.9em">Nóng quá.</p><p style="text-align: justify; margin-bottom: 0.9em">Cái nóng như từ tận trong xương cốt len ra ngoài. Thời Vụ nhớ lời y tá dặn tạm thời đừng tắm, đành cố nén ý định ấy xuống. Nàng vào phòng vệ sinh, dùng khăn lạnh lau người. Bộ đồ bệnh nhân đã thấm ướt mồ hôi, nàng thay lại chiếc áo ngắn tay màu trắng của mình rồi trở về giường nằm. So với lúc nãy thì dễ chịu hơn một chút, nhưng cũng chỉ một chút mà thôi. Nàng dường như lại trở về trạng thái mê man của buổi chiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Ý thức mơ mơ hồ hồ, cả người đầm đìa mồ hôi. Thời Vụ đá chăn ra, chẳng biết mình đã trằn trọc trên giường bao lâu. Nàng đưa tay sờ trán, lòng bàn tay còn nóng hơn cả trán.</p><p style="text-align: justify; margin-bottom: 0.9em">Chắc là lại sốt rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thể chất Thời Vụ vốn là vậy, mỗi khi sốt rất dễ tái đi tái lại. Bình thường không mấy khi ốm, nhưng hễ ốm một trận là phải mất mấy ngày mới khỏi. Cổ họng khô rát, nàng định ngồi dậy rót cho mình cốc nước. Nhưng vừa xuống giường tìm dép, hai chân đã mềm nhũn, kéo theo cả chăn đập vào tủ đầu giường, phát ra một tiếng động lớn.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa phòng bệnh lập tức bật mở. Không biết là y tá hay bác sĩ, Thời Vụ đã chẳng còn phân biệt nổi. Nàng chỉ biết có người đỡ mình trở lại giường, bên tai là rất nhiều tiếng người nói chuyện.</p><p style="text-align: justify; margin-bottom: 0.9em">Ồn quá.</p><p style="text-align: justify; margin-bottom: 0.9em">Giống hệt ngày Thời Ánh Xuân rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi ấy tất cả mọi người đều khóc, nàng cũng khóc. Nước mắt cứ thế tuôn mãi không ngừng. Chỉ có Thời Ánh Xuân không khóc, bà bước đến trước mặt nàng, ôm nàng thật lâu, chẳng những không khóc mà còn mỉm cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mẹ không thích nhìn con khóc."</p><p style="text-align: justify; margin-bottom: 0.9em">Thường Anh cũng không thích nàng khóc, nhưng nàng không nhịn được, khóc đến đau thắt cả lòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Rất lâu sau, đến lúc Thời Ánh Xuân rời đi, nàng mới chợt hiểu ra: có những lúc, không khóc được còn đau khổ hơn cả bật khóc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng không làm được.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hoàn toàn sụp đổ, khóc òa lên như một đứa trẻ.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Thời Vụ tỉnh lại, hai mắt sưng húp, cổ họng đau rát, tầm nhìn cũng mờ nhòe. Vì thế nàng nhận nhầm người trước mặt là Dư Mạt, nheo mắt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu đến từ lúc nào vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Người trước mặt lạnh nhạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối qua."</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ một câu ấy, chẳng khác nào tiếng sét nổ bên tai.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cứng đờ tại chỗ. Nàng cố mở đôi mắt vừa đau vừa sưng, nhìn người trước mặt thật kỹ.</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải Dư Mạt ?</p><p style="text-align: justify; margin-bottom: 0.9em">Là ai?</p><p style="text-align: justify; margin-bottom: 0.9em">Sao lại là Lâm Nhược Đường?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giật mình ngồi bật dậy trên giường, hai mắt mở to đầy kinh ngạc.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đứng dậy khỏi ghế, bước thẳng đến bên nàng. Thời Vụ theo bản năng ngả người ra sau, chống tay giữ lấy cơ thể. Lâm Nhược Đường cúi xuống, vừa lúc nàng sắp không chống nổi nữa thì bên tai vang lên một tiếng "tít".</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng máy đo nhiệt độ báo:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhiệt độ hiện tại của bạn là 37,8 độ C."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghiêng đầu, thấy Lâm Nhược Đường đang cầm nhiệt kế áp sát bên tai mình, bỗng có chút ngượng ngùng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Để tôi tự làm."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đo xong rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đứng thẳng người. Từ góc nhìn của Lâm Nhược Đường, vừa khéo có thể thấy chóp mũi Thời Vụ hơi ửng đỏ cùng xương quai xanh thấp thoáng dưới chiếc áo phông rộng. Thời Vụ nhận ra ánh mắt cô khẽ hạ xuống, theo bản năng nhích người về sau, cố giữ một khoảng cách.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường xoay người, đặt nhiệt kế lên bàn trà rồi nói với nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đi rửa mặt đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn chưa hoàn hồn khỏi cơn kinh ngạc. Lâm Nhược Đường bảo gì, nàng liền làm theo. Vào phòng vệ sinh, nàng thấy bên trong có một bộ đồ dùng vệ sinh cá nhân hoàn toàn mới, không biết là Lâm Nhược Đường chuẩn bị hay Dư Mạt chuẩn bị.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đã đến rồi sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Tại sao Lâm Nhược Đường lại ở đây?</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đến từ lúc nào?</p><p style="text-align: justify; margin-bottom: 0.9em">Đến đây làm gì?</p><p style="text-align: justify; margin-bottom: 0.9em">Trong đầu Thời Vụ rối thành một mớ. Đến khi nhìn thấy mình trong gương, nàng mới khựng lại. Nàng ngừng động tác đánh răng, cau mày nhìn người trong gương. Mí mắt sưng đỏ, đuôi mắt cũng đỏ hoe, trông chẳng khác nào vừa khóc một trận thật lớn.</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy tối qua không phải nàng nằm mơ thấy mình khóc sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thật sự đã khóc?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đưa ngón tay ấn lên mí mắt, vẫn còn hơi đau rát. Cổ họng thì dễ chịu hơn tối qua nhiều, không biết có phải ban đêm đã được cho uống nước hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chỉ đơn giản rửa mặt, lau khô rồi bước ra ngoài. Lâm Nhược Đường vẫn còn đó, đang ngồi trên sofa gọi điện thoại. Thời Vụ nghe cô nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Biết rồi. Cuộc hẹn lúc chín giờ bảo Triệu Diễm đi thay tôi, buổi chiều tôi sẽ về công ty."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức càng thấy áy náy. Nàng bước đến bên Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, cô cứ đến công ty trước đi. Tôi không sao rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cất điện thoại, quay đầu lại, thong thả quan sát nàng một lượt. Thời Vụ vừa rửa mặt, tóc cũng đã buộc lên, sắc mặt trông khá hơn nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn nàng vài giây, Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bữa sáng muốn ăn gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi ăn gì cũng được. Cô muốn ăn gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đến nhà ăn xem thử, có gì thì ăn nấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Dễ chịu thật !</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu, nhưng vẫn không nhịn được tò mò:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, sao cô lại đến đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi là người liên hệ khẩn cấp của phòng bệnh này. Tối qua cô lại sốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Chuyện mình sốt lại, Thời Vụ biết. Nhưng nàng không hề biết phòng bệnh này còn có cả người liên hệ khẩn cấp!</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ lại mới thấy, đây là phòng bệnh của nhà họ Lâm, vậy nên người được liên hệ đương nhiên là Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cúi đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xin lỗi."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao. Sáng nay Dư Mạt đã đến, mang cho cô ít đồ. Cô xem thử còn thiếu gì không."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ hất cằm. Thời Vụ nhìn về phía tủ quần áo, đi vài bước đến mở ra. Bên trong có khá nhiều quần áo sạch để thay.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng sốt liền hai ngày, người đổ không ít mồ hôi, dính nhớp khó chịu. Nhìn thấy quần áo sạch, nàng lập tức muốn tắm một trận. Nhưng Lâm Nhược Đường vẫn đang chờ nàng ăn sáng, Thời Vụ đành đóng cửa tủ lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Muốn tắm trước à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô. Đôi mắt vì vui mừng mà sáng hẳn lên, nhưng vừa định gật đầu lại có chút do dự:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có làm mất thời gian của cô không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường chẳng hề khách sáo:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đã mất rồi, không sao."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mím môi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi cũng muốn tắm. Lấy cho tôi một bộ quần áo của cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩn ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Của tôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường vẫn điềm nhiên như không:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không mang quần áo đến."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô... sao cô lại muốn tắm?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bật cười, hơi tức giận:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô nói xem, cô Thời. Tối qua là ai truyền dịch xong rồi ôm tôi vừa khóc vừa quậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng chết trân tại chỗ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Biết cô uống say rồi chẳng ngoan ngoãn gì, sao đến lúc sốt cũng quậy như vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lần này Thời Vụ thật sự không bình tĩnh nổi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi... tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy vẻ mặt nàng đầy hoài nghi, Lâm Nhược Đường hít vào một hơi, tiến lên một bước đứng trước mặt nàng rồi dang hai tay ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ cau mày.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường miễn cưỡng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cần tôi giúp cô nhớ lại không?"</p><p style="text-align: justify; margin-bottom: 0.9em">....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn 16 phiếu Bá Vương và 358 chai dung dịch dinh dưỡng của các thiên thần nhỏ~</p><p style="text-align: justify; margin-bottom: 0.9em">Ngẫu nhiên phát một trăm bao lì xì, moah moah.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Thật ra chị không hề để bụng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: .....................</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 32, 'Đồ lót', '<p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn Lâm Nhược Đường đang bước về phía mình thêm một bước, vội vàng đưa tay ngăn lại.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Vì quá cuống, nàng chẳng để ý tay mình đặt ở đâu, vừa khéo lại đặt ngay phía trên ngực Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô khẽ cụp mắt nhìn xuống, rồi lại ngước lên nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chỉ cảm thấy mặt mình còn nóng hơn cả lúc sốt cao. Bàn tay đang lơ lửng giữa không trung luống cuống khua mấy cái, cuối cùng nàng cắn răng buông một câu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi đi tắm trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Phía sau, Lâm Nhược Đường gọi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giật mình quay đầu lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô chưa lấy quần áo thay."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cố nặn ra một nụ cười, quay lại mở tủ, lấy một bộ đồ mặc ở nhà rồi đi thẳng vào phòng tắm.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu lúc nãy nàng vẫn còn hơi mơ màng, thì sau cú giật mình khi nãy, đầu óc nàng giờ đã tỉnh táo hoàn toàn. Không ngờ Lâm Nhược Đường còn có tác dụng này, hiệu quả hơn uống thuốc nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tự cười một tiếng, mở vòi sen.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngồi trên sofa trong phòng bệnh, nghe tiếng nước chảy vọng ra. Cô đưa tay lấy trái cây trên bàn trà, bóc một quả quýt rồi thong thả ăn từng múi.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Thời Vụ bước ra khỏi phòng tắm, Lâm Nhược Đường vừa ăn xong quả thứ hai.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe động tĩnh, cô quay đầu nhìn sang.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ dùng khăn dùng một lần bọc lấy mái tóc còn ướt. Hơi nóng khiến gương mặt nàng càng thêm hồng hào, đôi mắt đọng hơi nước, trong veo sáng ngời, chỉ có đuôi mắt là đỏ hơn bình thường.</p><p style="text-align: justify; margin-bottom: 0.9em">Tựa như một đóa hoa kiều diễm.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây, Lâm Nhược Đường vẫn không hiểu vì sao ngày nào Lâm Châu cũng lải nhải bên tai rằng Thời Vụ đẹp đến mức nào, tựa tiên nữ hạ phàm. Giờ phút này, cô dường như đã hiểu được đôi chút.</p><p style="text-align: justify; margin-bottom: 0.9em">Nước trong veo làm nổi bật đóa phù dung, vẻ đẹp tự nhiên vốn chẳng cần tô điểm. Huống hồ Thời Vụ lúc ốm còn mang theo vài phần yếu ớt mong manh. Giọng Lâm Nhược Đường cũng bất giác dịu xuống, mềm mại đến mức khác thường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quần áo của tôi đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vội vàng lục tìm trong tủ. Lâm Nhược Đường không cao hơn nàng bao nhiêu, phần lớn đồ mặc ở nhà của nàng, cô đều có thể mặc vừa. Chỉ riêng đồ lót, Dư Mạt chuẩn bị cho nàng đều là loại dùng một lần. Chất lượng thế này, nàng đoán Lâm Nhược Đường sẽ chê.</p><p style="text-align: justify; margin-bottom: 0.9em">Quả nhiên, vừa nhìn thấy chiếc quần lót dùng một lần nàng đưa sang, Lâm Nhược Đường đã nhíu mày, ngước mắt nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không có cái khác. Tôi cũng mặc loại này, cô dùng tạm một chút đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Giải thích nhiều như vậy làm gì chứ? Mặc thì mặc, không mặc thì thôi. Hơn nữa Lâm Nhược Đường có phải nàng đâu, người phải nằm viện rõ ràng là nàng mà.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ đến đây, Thời Vụ chợt cảm thấy mình đúng là hơi tự chuốc phiền vào thân. Lâm Nhược Đường vì nàng mà nửa đêm chạy tới đây, vậy mà nàng còn để tâm chuyện này.</p><p style="text-align: justify; margin-bottom: 0.9em">Thôi được, là nàng có lỗi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn chằm chằm chiếc quần lót trong tay Thời Vụ hồi lâu, cuối cùng vẫn nhận lấy rồi đi vào phòng tắm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng phía sau cô, khẽ thở phào.</p><p style="text-align: justify; margin-bottom: 0.9em">Mái tóc nàng vẫn còn ướt sũng. Ban nãy trong phòng tắm không tìm thấy máy sấy, nàng cũng chẳng biết nó sẽ ở đâu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu, chợt nhìn thấy nó trên bàn trà.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thả lỏng người, cầm máy sấy đi tới bên cửa sổ. Luồng gió nóng ù ù thổi qua, chẳng mấy chốc tóc đã khô được một nửa. Hình như nàng nghe thấy tiếng gõ cửa, bèn tắt máy sấy. Tiếng nước trong phòng tắm vẫn còn, tiếng gõ cửa cũng vẫn tiếp tục.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đi vài bước ra cửa, mở cửa ra. Bên ngoài là y tá.</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá thấy nàng thì mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô Thời, cô tỉnh rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ gật đầu, mỉm cười đáp lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ăn sáng chưa? Nếu chưa thì tôi lấy máu trước nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vẫn chưa."</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá lấy ống lấy máu ra, hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sáng nay cô đo nhiệt độ chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đưa nhiệt kế cho cô ấy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đo rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá nhìn qua:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vẫn còn hơi sốt nhẹ. Buổi sáng nên ăn chút cháo loãng hoặc món gì thanh đạm nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu. Cổ họng nàng đau rát, quả thật cũng chẳng nuốt nổi thứ gì khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá nhanh chóng làm xong các kiểm tra. Trước khi rời đi, Thời Vụ ngập ngừng gọi lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"À... chuyện tối qua của tôi..."</p><p style="text-align: justify; margin-bottom: 0.9em">Qua lớp khẩu trang, Thời Vụ nhận ra y tá đang cười. Y tá hỏi lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối qua cô không nhớ sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ xuýt một tiếng, khó xử lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi đã làm gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối qua truyền dịch xong, cô nhất quyết không chịu nghỉ ngơi, cứ ôm cô Lâm, vừa khóc vừa làm ầm lên."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không đùa.</p><p style="text-align: justify; margin-bottom: 0.9em">Là thật sao??</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bị làm sao vậy chứ? Trước đây mỗi lần ốm nàng đâu có như thế.</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có lẽ vì sốt nên đầu óc không được tỉnh táo, lại thêm cô và cô Lâm khá thân thiết, nên mới như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi Thời Vụ giật giật.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng và Lâm Nhược Đường... thân thiết?</p><p style="text-align: justify; margin-bottom: 0.9em">Không nhầm đấy chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng bất kể có nhầm hay không, chuyện nàng thất thố tối qua xem ra đã là sự thật không thể chối cãi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tiu nghỉu ngồi xuống mép giường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường từ phòng tắm bước ra, Thời Vụ quay đầu nhìn sang.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong ấn tượng của nàng, Lâm Nhược Đường lúc nào cũng chỉnh tề, sắc sảo, mang phong thái tinh anh không chút sơ hở. Ngay cả khi ở nhà, mặc đồ mặc nhà, cô vẫn toát lên vẻ xa cách khiến người khác khó lòng với tới.</p><p style="text-align: justify; margin-bottom: 0.9em">Thế nhưng giờ đây, khi khoác lên người quần áo của Thời Vụ, khí thế ấy dường như đã dịu đi không ít.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt mua cho nàng toàn áo phông rộng và quần jeans xanh nhạt. Thời Vụ vốn gầy, Lâm Nhược Đường mặc vào lại vừa vặn. Đôi chân dài càng được tôn lên thon thẳng. Chiếc áo phông trắng phủ qua hông, khiến Lâm Nhược Đường lúc này trông chẳng khác nào người mẫu chuẩn bị chụp một quảng cáo tươi mát, thanh lịch. Trên người cô còn phảng phất mùi sữa tắm quen thuộc.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đưa máy sấy sang cho cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không nhận, chỉ kéo chiếc ghế cạnh giường đến bên cửa sổ rồi ngồi xuống, ánh mắt ra hiệu cho Thời Vụ lại gần.</p><p style="text-align: justify; margin-bottom: 0.9em">Gió ngoài cửa sổ khe khẽ hong mái tóc ướt của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu bước tới.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Biết sấy tóc cho người khác không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghĩ cũng chẳng cần nghĩ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Biết. Chuyện này ai mà chẳng biết, có tay là làm được thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy sấy đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô hơi ngửa đầu, mái tóc dài buông xuống sau lưng ghế, vẫn còn ướt sũng, thấm ẩm cả một khoảng trên chiếc áo phông trắng. Khi phần lưng mảnh mai lộ ra, Thời Vụ mới chợt nhận ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi sấy tóc cho cô á?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay mặt lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi còn mấy email cần trả lời, phiền cô sấy giúp tôi một lát."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nói rất khách sáo, chỉ là Thời Vụ vẫn thấy có gì đó là lạ. Nàng và Triệu Hy Ngọc ở bên nhau bao nhiêu năm cũng chưa từng sấy tóc cho nhau được mấy lần. Chủ yếu vì nàng có thói quen tắm xong đội mũ trùm tóc, chờ tóc gần khô rồi mới sấy, chẳng cần ai giúp. Đương nhiên, nàng cũng chưa từng sấy tóc cho người khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đợi hai giây không thấy nàng đáp, bèn xoay người lại, hơi ngẩng đầu, giọng điệu nhàn nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hoàn hồn. Nhớ tới dáng vẻ thất thố của mình tối qua, nàng cầm máy sấy bằng một tay, tay kia khẽ nâng mái tóc dài của Lâm Nhược Đường lên, cẩn thận sấy từng chút một.</p><p style="text-align: justify; margin-bottom: 0.9em">Tóc Lâm Nhược Đường vừa dày vừa nhiều. Thời Vụ vốn cứ ngỡ với tính cách của cô, tóc hẳn cũng phải cứng như người, nào ngờ khi mái tóc vừa được sấy ráo nằm trong lòng bàn tay lại mềm mại đến bất ngờ, mượt mà rủ xuống giữa những ngón tay.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng sấy rất chăm chú, thỉnh thoảng còn dùng ngón tay vén những lọn tóc ướt trước trán lên. Đầu ngón tay vô tình lướt qua má và vành tai Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt Lâm Nhược Đường đang dừng trên email bỗng khựng lại, rất lâu vẫn không rời khỏi trang đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Một lúc lâu sau, ngón tay cô mới trượt xuống, chuyển sang email tiếp theo.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng chẳng nhớ mình đã sấy bao lâu. Dù sao chắc chắn lâu hơn lúc tự sấy tóc cho mình. Nàng lấy lược chải lại những sợi tóc hơi rối trên bề mặt, chải đến khi hoàn toàn suôn mượt. Nhìn mái tóc dài thẳng tắp buông xuống sau lưng Lâm Nhược Đường, nàng bỗng có cảm giác như vừa hoàn thành một tác phẩm, giọng cũng thoải mái hẳn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xong rồi, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường chẳng mấy để tâm, đưa tay xoa xoa phần sau đầu rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có dây buộc tóc không?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"À, có."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay lại tủ, lấy một sợi dây buộc tóc màu đen đưa cho cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cụp mắt nhìn điện thoại đặt trên đùi, hai tay tùy ý gom mái tóc dài lên, tiện tay kéo vài lọn tóc mai trước trán ra. Chỉ vài động tác đơn giản, mái tóc đã được buộc gọn gàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng bên cạnh nhìn nghiêng gương mặt cô dưới ánh nắng ngoài cửa sổ. Làn da trắng đến gần như trong suốt, hàng mi dài, đôi đồng tử dưới ánh sáng ánh lên sắc xám đậm nhàn nhạt. Đường nét ngũ quan sâu và rõ, ánh mắt khi nhìn điện thoại sắc bén, nghiêm nghị; đôi môi khẽ mím, đường quai hàm gọn ghẽ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn thế nào cũng giống như chỉ một giây nữa thôi là cô sẽ bước vào trạng thái làm việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ có bộ quần áo trên người là hơi làm giảm khí thế.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ miên man suy nghĩ. Lâm Nhược Đường khép điện thoại lại, đứng dậy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đi thôi, ăn sáng."</p><p style="text-align: justify; margin-bottom: 0.9em">Trong nhà ăn có khá đông người. Thời Vụ đứng bên cạnh Lâm Nhược Đường, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, cô muốn ăn gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bánh bao, sữa đậu nành, quẩy, cháo loãng, mì hoành thánh... cũng coi như khá đầy đủ. Nhưng dường như Lâm Nhược Đường chẳng hài lòng lắm, cô hơi nhíu mày nhìn ra phía cửa sổ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đang nghĩ có nên đổi sang chỗ khác thì Lâm Nhược Đường đã gọi hai bát cháo. Thời Vụ cũng lấy hai quả trứng cùng hai phần bánh bao nhân rau.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngồi xuống, nàng đưa một phần cho Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc bóc trứng xong, Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đang sốt thì không được ăn trứng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đưa quả trứng đã bóc sạch sang cho Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ăn không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cũng chẳng khách sáo, nhận lấy rồi hai ba miếng đã ăn hết.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ăn được bánh bao, nhưng nàng cũng không biết Lâm Nhược Đường có ăn hay không. Nàng đang nhìn phần bánh bao nhân rau còn lại, thì Lâm Nhược Đường đã thẳng tay cầm lấy, đặt sang bên cạnh bát của nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cất giọng khàn khàn, nghe hơi giống tiếng vịt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Còn muốn ăn gì nữa không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đúng là có hơi đói. Có lẽ trận sốt cao đã tiêu hao quá nhiều sức lực, giờ không còn sốt dữ như trước nữa, cảm giác đói cũng kéo đến:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ngô."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay đầu nhìn sang. Trong nồi đang luộc ngô, hai tệ một bắp. Cô mua hai bắp rồi quay lại, vừa lúc thấy một đôi mẹ con ngồi xuống bên cạnh Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bé chừng ba bốn tuổi, trắng trẻo sạch sẽ, gương mặt còn phúng phính nét trẻ con. Giọng nói cũng non nớt, ngước nhìn mẹ rồi chỉ sang Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mẹ ơi, chị đẹp quá."</p><p style="text-align: justify; margin-bottom: 0.9em">Mẹ cô bé vội kéo bàn tay đang chỉ người khác xuống, mỉm cười ngượng ngùng với Thời Vụ, sau đó nhẹ giọng dạy con:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không được chỉ tay vào người khác, bất lịch sự lắm."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bé chớp đôi mắt to tròn.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô bé, cong môi mỉm cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Một nụ cười rất dịu dàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường liếc chiếc túi trong tay mình, mặt không biểu cảm bước tới, đặt ngô xuống trước mặt Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngước mắt lên. Ý cười mềm mại nơi đáy mắt còn chưa kịp tan.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt Lâm Nhược Đường vừa chạm phải nàng đã lạnh đi đôi chút. Cô thản nhiên hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô thích trẻ con đến vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghe vậy liền nhìn sang cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đáng yêu thế này, ai mà chẳng thích."</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy phản ứng của Lâm Nhược Đường, Thời Vụ hơi nghi hoặc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô không thích trẻ con sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường chẳng cần suy nghĩ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không thích."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vừa gặm ngô vừa nhìn cô. Thấy gương mặt vốn bình tĩnh kia như phủ thêm một tầng sương lạnh, chẳng khác gì chiếc điều hòa sống, nàng lại cảm thấy với tính cách của Lâm Nhược Đường, không thích trẻ con cũng rất bình thường, nên chẳng nghĩ nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Ăn hết một bắp, nàng gói bắp còn lại lại để mang về.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn động tác của nàng, khẽ nhíu mày, dường như muốn nói gì đó, nhưng cuối cùng vẫn im lặng đứng dậy rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người trở lại phòng bệnh đúng lúc bác sĩ đến kiểm tra.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngồi trên sofa, một tay đặt lên tay vịn, nghiêng đầu nhìn bác sĩ khám cho Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nghe lời há miệng.</p><p style="text-align: justify; margin-bottom: 0.9em">Bác sĩ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cổ họng vẫn còn sưng. Uống thêm nước ấm nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không rời đi, chỉ lặng lẽ ngồi đó. Thời Vụ cũng không tiện đuổi cô, dù sao đây cũng là phòng bệnh của nhà họ Lâm, nghĩ thế nào cũng thấy người không được tự nhiên ở đây phải là nàng mới đúng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng trở mình trên giường.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên ngoài vang lên tiếng gõ cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn chưa kịp lên tiếng, Lâm Nhược Đường đã trầm giọng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vào đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người đứng ngoài cửa lập tức bước vào. Thời Vụ mỉm cười với họ rồi nhìn sang Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trong phòng vệ sinh."</p><p style="text-align: justify; margin-bottom: 0.9em">Người kia đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn chẳng hiểu chuyện gì đang xảy ra. Hai người kia đi vào phòng vệ sinh, lúc trở ra mỗi người xách theo một túi đồ, mỉm cười với nàng rồi rời đi. Suốt từ đầu đến cuối Thời Vụ vẫn ngơ ngác, mãi đến khi họ đi khuất mới hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Họ là ai vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Người của tiệm giặt là."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt hiểu ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô muốn giặt quần áo à?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Họ đã đến lấy rồi, bốn giờ chiều sẽ mang trả lại."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cảm thấy chẳng cần thiết đến thế, cùng lắm chỉ có hai bộ đồ mùa hè, không giặt thì mang về nhà giặt sau cũng được, hoặc dùng nước nóng ở đây vò qua rồi treo lên. Nhưng nghĩ đến quần áo của Lâm Nhược Đường, e rằng không phải thứ có thể tùy tiện vò giặt, nàng mím môi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bao nhiêu tiền?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường chẳng buồn ngẩng đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô hỏi người đến giao quần áo ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ "ồ" một tiếng. Lâm Nhược Đường đứng dậy, nói với nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi về công ty trước, có việc thì...."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi biết rồi, không làm phiền cô đâu. Tôi sẽ liên lạc với Dư Mạt." Thời Vụ vội tiếp lời.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghe vậy khẽ cười, nhìn Thời Vụ một cái rồi xoay người rời khỏi phòng bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Đợi cô đi rồi, Thời Vụ mới thả lỏng người. Vừa uể oải cử động một chút, nàng lập tức xỏ dép xuống giường, đi thẳng vào phòng vệ sinh.</p><p style="text-align: justify; margin-bottom: 0.9em">May mà đồ lót vẫn còn.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thở phào, đồng thời nhìn chằm chằm chiếc quần lót màu đỏ nằm cạnh đồ của mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Là của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Cái này cũng cần giặt sao? Có thể giặt bằng nước không?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không muốn hỏi Lâm Nhược Đường. Với tính tình của người kia, tám chín phần là sẽ vứt luôn ở đây, nhưng nàng lại không thể cứ thế giặt luôn đồ của mình rồi mặc kệ đồ của cô. Dù sao lần này nàng đổ bệnh, vừa ở nhờ phòng bệnh của người ta, lại khiến người ta nửa đêm phải chạy tới đây.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Ánh Xuân từng dạy nàng, làm người không thể không biết báo đáp. Nghĩ vậy, Thời Vụ đành cắn răng, cầm chiếc quần lót của Lâm Nhược Đường trong tay mà lòng run lên bần bật.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vừa bước vào phòng bệnh đã hấp tấp hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu lấy nước giặt làm gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giặt quần áo."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt ngạc nhiên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chẳng phải cậu đang mặc đồ bệnh nhân sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mặc không thoải mái nên tối qua tôi thay ra rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vừa hay ở đây có máy giặt, giặt xong cũng gần khô rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Đồ lót các thứ, Thời Vụ vẫn quen tiện tay giặt luôn sau khi tắm, không quen bỏ vào máy giặt. Nhưng nàng cũng chẳng phản đối, chỉ "ừ" một tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn quanh phòng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phòng bệnh này rộng thật đấy, trên dưới có hai tầng, cái gì cũng có. Cậu ăn sáng chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô, chỉ một câu đã bị đổi liền ba chủ đề, nhưng vẫn gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ăn rồi, còn cậu?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vừa ăn ở nhà ăn xong."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt ngả người xuống sofa. Thời Vụ đi tới:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không về nhà à?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mệt chết đi được. Hay là tôi ngủ ở đây luôn nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu vẫn nên về nhà ngủ đi, thoải mái hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thế chẳng phải sẽ không có ai ở bệnh viện với cậu sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi lớn thế này rồi, còn cần người ở cùng nữa à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt thở dài:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối qua cậu lại sốt mà tôi còn chẳng kịp chạy tới. Hay là để tôi thuê cho cậu một hộ lý nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sự không cần đâu. Hôm nay tôi đỡ nhiều rồi. Sáng nay đo nhiệt độ chỉ còn hơi sốt, bác sĩ bảo ở lại thêm hai ngày, không có vấn đề gì thì có thể về."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Dư Mạt mới gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được rồi. Mấy giờ truyền nước?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mười giờ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giục cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu mau về nghỉ đi. Tối nay chẳng phải còn phải trực ca đêm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt ngáp một cái:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm, chủ nhiệm xin nghỉ rồi, tôi trực thay cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mau về đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt quả thật vừa buồn ngủ vừa mệt, đi đường cũng thấy người lâng lâng. Dù rất muốn ở lại chăm Thời Vụ, nhưng cứ thế này thì chưa chắc ai chăm ai. Nghĩ vậy, cô cũng không ở lại làm nàng thêm vướng bận nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Dư Mạt rời đi, Thời Vụ vén chăn xuống giường. Nàng uống liền hai cốc nước ấm cho dịu cổ họng, lại mở cửa sổ nhìn ra ngoài. Thấy bóng Dư Mạt khuất khỏi cửa khu nội trú, nàng mới quay về bàn trà, cầm nước giặt đi vào phòng vệ sinh.</p><p style="text-align: justify; margin-bottom: 0.9em">Lần đầu tiên trong đời, nàng đổ nhiều nước giặt đến thế. Nhắm mắt vò một hồi, nàng không hề có ý chê đồ lót của Lâm Nhược Đường, chỉ đơn giản là cảm giác tự tay giặt quần áo lót cho người khác khiến nàng thật sự cảm thấy lạ và ngượng ngùng.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ cục vô cùng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu một hơi, vớt đồ lót ra khỏi đám bọt, sang phòng tắm vò sạch rồi liếc qua cỡ áo ngực của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhỏ hơn nàng một cỡ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nhìn thì lại khá đầy đặn, chắc là vì eo Lâm Nhược Đường quá mảnh nên càng tôn lên vòng ngực.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhanh chóng giặt sạch, xả lại bằng nước trong rồi mở cửa sổ phòng vệ sinh, treo đồ ở mép cửa sổ cho thoáng gió. Hai bộ đồ lót được kẹp chung trên một chiếc móc.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc ấy, bên ngoài vang lên tiếng gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời Vụ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Mở cửa ra, nàng thấy y tá cầm thuốc và nước truyền bước vào.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối qua đã truyền thêm hai chai, hôm nay tốc độ truyền phải chậm hơn một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá chủ động đưa tay ra. Sau khi cắm kim xong, Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm nay mấy chai vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bốn chai. Người nhà cô không tới à?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Họ bận, tôi ở một mình cũng được."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy hết nước thì gọi tôi nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Đợi y tá rời đi, nàng nằm trên giường buồn chán, không buồn ngủ nên định tìm một bộ phim xem. Đúng lúc ấy, Lâm Châu nhắn tin riêng cho nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị, đang làm gì đấy?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thấy tin nhắn của cô nàng thì bất giác cong môi:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đang truyền nước.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị ở một mình à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ừ, tối qua Dư Mạt trực đêm, về nhà ngủ rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Vậy chị ở một mình có ổn không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tối qua ngủ đủ rồi, giờ cũng không buồn ngủ, chỉ cần để ý chai truyền là được. Không sao đâu.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tối qua chị không sốt lại đấy chứ?】</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ đến tình trạng tối qua, Thời Vụ không muốn nhớ lại cho lắm, nhưng trong đầu vẫn lờ mờ hiện lên vài mảnh ký ức. Hình như lúc nàng vừa khóc vừa quấy là vì đã nhận nhầm Lâm Nhược Đường thành Thời Ánh Xuân, ôm chặt lấy cô không chịu buông, sợ cô bỏ đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Có sốt lại, nhưng không sao, sáng nay đã hạ rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tội chị quá. Hôm nay em kết thúc sớm thì sẽ qua thăm chị.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Em lo làm việc đi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không sao, mấy hôm nay đều đang quay bổ sung, sắp đóng máy rồi. À đúng rồi chị, chị có dùng Douyin không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không dùng mấy. Chủ yếu là không có thời gian, tài khoản của công ty cũng có người chuyên phụ trách, bản thân nàng không có tài khoản riêng.</p><p style="text-align: justify; margin-bottom: 0.9em">【Không có, giờ chị đăng ký một cái.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được được được, đăng ký xong nói em nhé.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tải Douyin xuống, đăng ký tài khoản một mạch, chỉ đến phần đặt biệt danh thì khựng lại. Nghĩ hồi lâu vẫn không nên biết đặt tên gì, nàng tìm tên của Lâm Châu và theo dõi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Nhất Diệp Biển Châu, tài khoản phụ của em.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bấm theo dõi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cục đá thối! Chị đặt cái tên gì mà buồn cười thế.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cho chị xem tài khoản của chị em.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bấm vào đường link. Biệt danh trên đó cố tình tỏ ra rất ngầu, chỉ có một chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đường】</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng khẽ "xì" một tiếng. Quả nhiên đúng y như ấn tượng cố hữu của nàng về Lâm Nhược Đường. Ảnh đại diện vẫn là con mèo cam ấy, chỉ khác góc chụp và bóng đổ. Tài khoản cũng chẳng đăng gì cả, đến mức Thời Vụ còn nghi Lâm Nhược Đường vốn không dùng tài khoản này.</p><p style="text-align: justify; margin-bottom: 0.9em">So ra, tài khoản phụ của Lâm Châu đúng là muôn màu muôn vẻ, nào đồ ăn ngon, giải trí, vận động, tập luyện, thứ gì cũng có. Nàng còn chưa xem hết, Lâm Châu đã gửi ào ào cả đống video sang, còn nhắn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Xem xong nhớ nói em nhé, chỗ em có nhiều cái buồn cười lắm.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nỡ làm cô nàng mất hứng, bèn nhấn xem.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong phòng bệnh yên tĩnh, tiếng cười trong video hòa lẫn với tiếng cười của Thời Vụ. Ánh nắng xuyên qua cửa sổ rọi xuống giường bệnh. Nàng nằm nghiêng, vừa khéo đối diện với luồng nắng chói mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Bỗng nhiên lại thấy ấm áp đến lạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhìn ánh nắng hồi lâu, đến khi mắt hoa lên mới nhắm mắt, xoay người tiếp tục xem video. Đúng lúc thoát ra để chuyển sang cái tiếp theo, phía trên màn hình bật lên một thông báo:</p><p style="text-align: justify; margin-bottom: 0.9em">Đường đã theo dõi bạn.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhất thời không phản ứng kịp. Sau đó nàng mở to mắt, thoát khỏi video rồi vào trang cá nhân, nhìn số người theo dõi của mình từ một biến thành hai.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc Lâm Châu gửi đường link sang, Thời Vụ tiện tay bấm theo dõi. Nhưng nàng cứ tưởng Lâm Nhược Đường không dùng tài khoản này nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Sao lại theo dõi ngược nàng rồi?</p><p style="text-align: justify; margin-bottom: 0.9em">Đang lúc nàng còn nghi hoặc, avatar mèo gửi tới một dấu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">【?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thở dài. Theo dõi lại thì đã sao, Lâm Nhược Đường cũng đâu biết đó là nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Avatar mèo:</p><p style="text-align: justify; margin-bottom: 0.9em">【Thời Vụ?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【......】</p><p style="text-align: justify; margin-bottom: 0.9em">Xem ra nàng không nên đánh giá thấp trí thông minh của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Là tôi. Sao cô lại online vậy?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Lâm Châu bảo tôi lên.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【......】</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cũng không nên đánh giá thấp khả năng buôn chuyện của Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đang làm gì?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không làm gì, đang truyền nước.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chán à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Lát nữa Trần Hy sẽ mang ít đồ qua, nhớ mở cửa cho cô ấy.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ồ, được.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: 【Là gì vậy?】</p><p style="text-align: justify; margin-bottom: 0.9em">Hai tin nhắn kia vẫn luôn ở trạng thái chưa đọc, chắc cô đang bận. Thời Vụ trở mình trên giường, đặt điện thoại xuống rồi gọi y tá vào thay nước truyền. Chẳng bao lâu sau, ngoài cửa vang lên tiếng động, Thời Vụ lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vào đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Người bước vào là Trần Hy, trên tay xách hai chiếc túi. Thấy Thời Vụ, cô bước nhanh tới, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giám đốc Thời, chị thấy trong người đỡ hơn chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đỡ nhiều rồi, cảm ơn cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cái kia là gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Máy chiếu mẫu mới nhất của MOOM. Tôi để ở đây cho chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đặt máy chiếu lên tủ đầu giường, đối diện vừa khéo là một mảng tường trắng sạch sẽ.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Như vậy chị xem phim, xem TV cũng đỡ mỏi mắt."</p><p style="text-align: justify; margin-bottom: 0.9em">Cũng khá chu đáo. Nhưng chẳng phải trong phòng đã có TV rồi sao? Không có kênh à? Hay không xem được?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu lắm, khoé môi khẽ động:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng bảo tôi mang tới. Tôi chỉnh sẵn cho chị nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhất thời chẳng biết nói gì, chỉ cười khan:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy chuyển sự chú ý sang chiếc túi màu đỏ còn lại. Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cái đó là gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cái này cũng là Lâm tổng bảo tôi mang cho chị. Tôi cũng không biết bên trong là gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đưa túi cho Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có lẽ là quần áo."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chẳng để tâm, một tay vẫn đang truyền nước, tay kia đón lấy chiếc túi từ Trần Hy. Nàng vừa xách một góc túi lên thì miệng túi chúc xuống, đồ bên trong lập tức lả tả rơi ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Quần lót màu đen, quần lót màu đỏ, quần lót màu trắng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tròn mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng quay sang nhìn Trần Hy.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy há miệng, rồi từ từ khép lại, nuốt khan một cái, sau đó quay đầu đi, nghiêm túc chuyên tâm chỉnh máy chiếu.</p><p style="text-align: justify; margin-bottom: 0.9em">⸻</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn 12 phiếu Bá Vương và 650 chai dung dịch dinh dưỡng của các thiên thần nhỏ~</p><p style="text-align: justify; margin-bottom: 0.9em">Phát ngẫu nhiên 100 bao lì xì nhé.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: Trần Hy.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy: Tôi hiểu, tôi mù rồi, tai cũng điếc luôn rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: —"......"</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 33, 'Bạn bè', '<p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cảm thấy trong tình huống này, mình nên giải thích đôi câu. Nhưng đầu óc nàng đang mơ màng vì cơn sốt, vừa mở miệng đã nói sai:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng chu đáo thật đấy, còn chuẩn bị cả thứ này nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng vậy, ha ha."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cắn môi, nói với Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật ra tôi và Lâm tổng không phải như cô nghĩ đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy quay đầu lại, vẻ mặt nghiêm túc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi có nghĩ gì đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy vậy, cô suýt nữa còn muốn thề:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn vẻ mặt đáng tin của cô, lúc này mới hơi yên tâm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy gật đầu lia lịa. Còn cần phải nghĩ lung tung nữa sao? Hôm kia bà cụ làm ầm lên đòi xuất viện, Lâm Nhược Đường đến cũng chẳng làm gì được. Vậy mà tối qua bà cụ mãi không chịu yên, Lâm Nhược Đường thậm chí còn gác cả tiệc tối để sang đây. Ban đầu Trần Hy còn không hiểu tại sao, mãi đến khi nhìn thấy Thời Vụ ngoài hành lang, cô mới hiểu ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Phải công nhận Thời Vụ phản ứng rất nhanh, Trần Hy cười vô cùng chân thành.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thở phào nhẹ nhõm, cầm điện thoại trong tay.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi lắp xong máy chiếu, Trần Hy thử lại một lượt rồi đưa điều khiển cho nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi kéo rèm lại một chút nhé, như vậy xem sẽ rõ hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đi đến bên cửa sổ, khép một nửa cửa lại rồi kéo rèm. Căn phòng lập tức tối đi, hình ảnh hiện lên trong bóng tối, rõ nét hơn hẳn. Trần Hy hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thế này được chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được rồi, cảm ơn cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy được. Nếu nằm nghiêng một bên lâu thấy mỏi, chị có thể đổi sang bên kia, chỉ cần xoay máy chiếu sang hướng đó là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô chỉ cho Thời Vụ cách xoay máy chiếu. Thời Vụ cụp mắt chăm chú nhìn, sau đó gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm, được."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nhìn đồng hồ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy không còn việc gì nữa, tôi về công ty trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ định ngồi dậy tiễn cô, Trần Hy vội ngăn lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đâu, chị cứ nằm đi, đừng dậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bỗng cảm thấy lời mình còn chưa kịp nói hết đã bị chặn lại giữa chừng. Nàng hít một hơi, nhìn Trần Hy rời đi, sau đó lập tức gọi cho Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao cô lại tặng đồ lót cho tôi hả?!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường dường như không hề nghe ra cơn giận trong giọng nàng, vẫn bình thản hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhận được rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng cô lạnh nhạt, hờ hững, thoáng chốc khiến cơn giận của Thời Vụ nghẹn lại. Nàng im lặng giây lát rồi mới nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhận được rồi. Không biết Lâm tổng làm vậy là có ý gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có ý gì cả. Tôi chỉ thấy đồ lót thì vẫn nên hạn chế dùng đồ dùng một lần."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi..." Thời Vụ nói, —"Tôi biết là nên hạn chế dùng. Nhưng tình huống của tôi bây giờ khá đặc biệt, hơn nữa cô không thấy..."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng do dự mãi, cuối cùng vẫn nói ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô không thấy mình hơi vượt quá giới hạn sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường im lặng nghe nàng nói, vài giây sau mới đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không thấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Rồi cô thản nhiên nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ngược lại, cô Thời à, cô nhạy cảm quá rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Còn quay ngược lại nói nàng!</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tức đến không nói nên lời, lập tức cúp máy rồi nằm thẳng xuống giường.</p><p style="text-align: justify; margin-bottom: 0.9em">Là nàng quá nhạy cảm sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi cơn bực qua đi, Thời Vụ thật sự nghiêm túc suy nghĩ về chuyện này.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng từng mua đồ lót cho Dư Mạt. Có lần hai người đi dạo phố, Dư Mạt nhìn trúng hai mẫu nhưng tiếc tiền nên không mua cả hai, thế là nàng mua mẫu còn lại tặng cho Dư Mạt. Dư Mạt cũng từng mua đồ lót cho nàng, là kiểu khá gợi cảm, nhưng vì không thích nên nàng chưa từng mặc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vẫn luôn cảm thấy, ít nhất phải thân thiết đến mức như vậy mới có thể tặng nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đúng là khó hiểu.</p><p style="text-align: justify; margin-bottom: 0.9em">Hay là cô tặng quà cho người khác cũng như vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy nên thật sự là nàng quá nhạy cảm sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ trở mình trên giường. Trước khi Trần Hy rời đi, bộ phim vừa mới bắt đầu. Đó là một bộ phim tình cảm, kể về nữ chính và nữ phụ yêu nhau từ thời cấp ba nhưng bị ép phải chia xa, sau khi tốt nghiệp lại gặp lại nhau. Một câu chuyện gương vỡ lại lành điển hình. Nhưng diễn xuất của hai diễn viên chính quá tốt, Thời Vụ xem đến nhập tâm, đến mức chai truyền đã hết từ lúc nào cũng không để ý.</p><p style="text-align: justify; margin-bottom: 0.9em">Mãi đến khi y tá tranh thủ thời gian bước vào, nàng mới hoàn hồn, có chút ngượng ngùng dụi mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vừa nãy tôi xem phim nên không để ý, xin lỗi."</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Không sao! Vẫn còn hai chai nữa, tôi sẽ để ý thời gian sang xem cho cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ càng thấy ngại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc y tá chuẩn bị rời đi, Thời Vụ chợt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"À phải rồi, tôi có thể đổi phòng bệnh không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng y tá thoáng chút dè dặt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đổi phòng sao? Cô có thể nói với cô Lâm một tiếng."</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy thì thôi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nụ cười gượng gạo trên mặt Thời Vụ lập tức biến mất. Nàng lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phòng bệnh này một ngày bao nhiêu tiền?"</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô muốn hỏi viện phí phải không? Cô Lâm đã thanh toán rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Ai đồng ý để cô ấy thanh toán chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cau mày, nhưng cũng không thể vì chuyện này mà nổi cáu với y tá, đành kìm lại chút khó chịu trong lòng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Y tá thu dọn xong rồi rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi cô ấy đi khỏi, Thời Vụ lại nằm thẳng xuống giường. Lần này đến cả nội dung bộ phim cũng chẳng thể khiến nàng thôi nghĩ ngợi. Suy đi nghĩ lại, nàng vẫn quyết định phải tìm Lâm Nhược Đường nói cho rõ ràng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này, Lâm Nhược Đường đang ngồi trong phòng họp. Giám đốc marketing đang báo cáo chiến lược tiếp thị cho quý tiếp theo thì màn hình điện thoại của cô sáng lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường tiện tay cầm điện thoại, nhìn thấy người gọi đến chính là người đã cúp máy với cô hai tiếng trước.</p><p style="text-align: justify; margin-bottom: 0.9em">Bình thường trông yên yên tĩnh tĩnh, vậy mà tính khí cũng chẳng nhỏ chút nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường giơ tay, giám đốc lập tức ngừng nói. Cô lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mọi người tiếp tục đi, tôi ra ngoài nghe điện thoại."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi cô rời đi, giám đốc nhìn sang Trần Hy. Trần Hy vẫn bình thản như không:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiếp tục đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ra khỏi phòng họp rồi mới nghe điện thoại của Thời Vụ. Vừa bắt máy, đầu bên kia đã khách sáo:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, xin lỗi, lại làm phiền cô rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi Lâm Nhược Đường khẽ cong lên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lúc cô Thời không mắng tôi, khách sáo thật đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hít sâu một hơi, nhắc lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, tôi không mắng cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy lúc nãy là có ý gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi..." Thời Vụ nói, —"Tôi chỉ cảm thấy làm vậy không được thích hợp cho lắm. Nếu bình thường vô duyên vô cớ tôi tặng cô đồ lót, cô sẽ vui sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô có thể thử xem."</p><p style="text-align: justify; margin-bottom: 0.9em">Không đợi Thời Vụ kịp đáp, cô đã nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi thích loại cotton nguyên chất, cỡ L. Cô đã thử đồ lót chưa? Kích cỡ có vừa không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chưa thử."</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải chứ, sao đang nói chuyện có thử hay không lại chuyển sang hỏi kích cỡ rồi?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói thẳng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không thích."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là không thích tôi, hay không thích đồ lót tôi tặng?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không thích cô làm như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Đầu bên kia im lặng. Thời Vụ không biết mình nói thẳng như vậy có phụ ý tốt của Lâm Nhược Đường hay không, cũng không biết cô có tức giận không. Một lúc sau, Lâm Nhược Đường mới nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, tôi biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, cô cúp máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong đầu Thời Vụ đầy dấu hỏi. Gì chứ, biết rồi, rồi sao nữa? Kết quả đâu?</p><p style="text-align: justify; margin-bottom: 0.9em">Không có?</p><p style="text-align: justify; margin-bottom: 0.9em">Khoan đã, hình như lần này nàng gọi điện là để hỏi chuyện phòng bệnh, sao cuối cùng lại bị Lâm Nhược Đường dẫn sang chuyện khác rồi?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn điện thoại trước mặt. Gọi lại lần nữa thì có vẻ không được lịch sự cho lắm, nhưng nàng thật sự không hiểu câu "tôi biết rồi" của Lâm Nhược Đường rốt cuộc có ý gì. Đến trưa Thời Vụ cũng chẳng ăn cơm, chỉ ngồi nhìn điện thoại mãi. Buổi chiều, lúc Dư Mạt đến phòng bệnh, vừa bước vào đã giật mình:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu định biến chỗ này thành rạp chiếu phim à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cười mà như không cười. Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Xem nào, cái này ở đâu ra vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm Nhược Đường bảo thư ký mang tới."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mang cái này tới làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi cũng muốn biết."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đổi qua mấy bộ phim rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đừng nói chứ, hàng xịn có khác, độ nét còn hơn cả TV nhà tôi. Lâm Nhược Đường cũng được đấy, vì chút ân tình năm xưa mà đối xử với cậu tận tình thế này."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không muốn nghe mấy lời kiểu "tận tình hết mức" ấy. Nàng dùng ngón tay gõ nhẹ lên vỏ điện thoại, hạ giọng gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Dư Mạt."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đang loay hoay với máy chiếu, không quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu nói xem, nếu tôi trả lại những thứ này cho cô ấy, cô ấy có khó chịu không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt quay đầu lại, nghiêm túc suy nghĩ một lát:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhíu mày nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu nghĩ xem, mấy thứ này với Lâm Nhược Đường có khi chẳng đáng bao nhiêu tiền, chỉ như chút nước vẩy ra thôi. Nhưng trong mắt người làm chủ, quan trọng đâu phải mấy thứ đó, mà là thể diện. Cậu cứ thế trả lại, chẳng khác nào làm cô ấy mất mặt. Ai mà chẳng giận !"</p><p style="text-align: justify; margin-bottom: 0.9em">Lý lẽ này ai cũng hiểu, sao Thời Vụ lại không biết được. Nếu nàng không hiểu, buổi chiều đã cho người mang đồ lót và máy chiếu đến chỗ Lâm Thái rồi. Nhưng với điều kiện nàng phải chắc chắn sau này mình sẽ không còn bất cứ liên quan gì đến Lâm Nhược Đường hay Lâm Thái nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Điều đó rõ ràng là không thể. Huống hồ xuất phát điểm của Lâm Nhược Đường cũng là vì muốn tốt cho nàng. Chỉ riêng chuyện này thôi, Thời Vụ đã chẳng thể nào nổi giận thật sự.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt ngồi xuống bên giường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy? Có một chỗ dựa lớn thế này mà cậu còn không vui à? Biết đâu sau này cậu bước chân vào giới kinh doanh, còn có cơ hội hợp tác với Lâm Thái nữa. Chuyện tốt thế còn gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đây không phải cơ hội của tôi, mà là cơ hội của mẹ tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có gì khác nhau sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không muốn tiêu xài thiện ý mẹ tôi để lại trên đời này."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu ngốc à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa xót xa lại vừa bất lực, cô nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nếu dì biết sau khi mất rồi mà vẫn có thể giúp được cậu, không biết ở trên trời sẽ vui đến mức nào đâu!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn cố chấp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà ấy sẽ không vui đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn nàng lại bắt đầu cố chấp, biết căn bệnh trong lòng này lại tái phát.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Thường Anh rời đi, Thời Vụ thường xuyên lẫn lộn giữa Thời Ánh Xuân và chính mình, như thể mũi không còn là mũi, mắt cũng chẳng còn là mắt. Thời Ánh Xuân ra đi quá đột ngột, trước lúc mất hai người thậm chí còn chưa kịp nói chuyện tử tế với nhau. Bao năm qua, Thời Vụ vẫn luôn canh cánh trong lòng. Mỗi lần uống quá chén hoặc say đến mơ màng, nàng đều nói với Dư Mạt rằng Thời Ánh Xuân nhất định vẫn còn giận mình, nếu không tại sao chưa từng một lần báo mộng cho nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Có vài lần nàng khóc đẫm mặt trong mơ, tỉnh dậy lại nói Thường Anh đã vào giấc mơ của mình, trách nàng không hiểu chuyện.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt từng nghĩ đến chuyện giới thiệu bác sĩ tâm lý cho nàng, nhưng Thời Vụ chỉ đáp một câu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mẹ tôi cũng là bác sĩ tâm lý."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hết cách, chỉ biết nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nằm trên giường quay lưng về phía Dư Mạt. Dư Mạt vỗ nhẹ lên tấm lưng gầy mảnh của nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối nay muốn ăn gì? Hay là chúng ta ra ngoài ăn?"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối nay cậu không phải truyền nữa đúng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối nay không truyền nữa. Không sốt thì không cần truyền thêm."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy cậu muốn ăn gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chẳng có khẩu vị, trưa cũng không ăn nên lúc này vẫn không thấy đói. Nàng lắc đầu. Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không ăn thì lấy đâu ra sức? Để tôi đi mua cho cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần." Thời Vụ nhớ đến bắp ngô đã đóng gói từ sáng, —"Có đồ ăn rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt thấy nàng lấy một bắp ngô trên bàn trà xuống, không khỏi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chừng này mà no được à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi đau họng, không muốn ăn gì khác."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy ăn cháo nhé? Tôi gọi cháo ngoài cho cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đợi lúc nào muốn ăn rồi gọi, bây giờ không có khẩu vị, gọi lại phí."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn nàng mà xót. Thời Vụ bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sự không sao, đừng lo."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa dứt lời, điện thoại trên tủ đầu giường rung lên. Dư Mạt tiện tay cầm giúp nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Số lạ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đại khái đã đoán được là ai, nàng bình thản nhận lấy. Giọng Triệu Hy Ngọc từ đầu bên kia truyền tới:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ, em bị bệnh à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sao chị ấy biết?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhíu mày. Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là Tinh Tinh nói với chị. Em ở phòng bệnh nào, chị..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngắt lời:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị định làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc im lặng hai giây rồi hạ giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị qua thăm em."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần, cảm ơn chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em còn cố chấp với chị làm gì? Bên cạnh em chẳng có ai, ai chăm sóc em? Chúng ta ly hôn rồi, nhưng cũng đâu đến mức phải tuyệt giao. Em gặp chuyện, sao chị có thể khoanh tay đứng nhìn được?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nén một tiếng thở dài:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi mong chị cứ khoanh tay đứng nhìn."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc không vui:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không chặn số của chị là vì thủ tục ly hôn của chúng ta vẫn chưa xong. Xin chị đừng nghĩ nhiều, tôi không cần chị chăm sóc."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được!" Triệu Hy Ngọc nói, —"Chị không đến. Vậy tối nay Tống Kim sang thăm em được chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không được."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc siết chặt điện thoại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúp máy. Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao chị ta đổi số rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không biết."</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Thời Vụ chẳng mấy bận tâm, Dư Mạt mím môi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu thật sự định chặn hết mọi cách liên lạc với chị ta à?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi chỉ mong chị ấy đừng liên lạc với tôi nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cậu nói xem người này sao có thể chẳng có chút giới hạn nào vậy? Trước đây lúc theo đuổi cậu thì bám riết không buông, giờ sắp ly hôn rồi vẫn còn thế này."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không muốn nói thêm, vừa ăn ngô vừa hỏi Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lát nữa cậu có việc gì không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt quay sang:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Kỳ Mai sẽ qua đây. Cô ấy không biết phòng bệnh, nếu cậu không bận thì xuống đón cô ấy giúp tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là cô quản lý đi cùng cậu lần trước ấy à? Người cao cao đó?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu. Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được thôi. Bao giờ cô ấy tới?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn điện thoại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Khoảng mười phút nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai vốn không biết Thời Vụ đang nằm viện. Buổi chiều cô nhắn cho Thời Vụ mấy tin, sau đó Thời Vụ gọi thẳng lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô mang máy tính qua đây đi, tôi viết code cho cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai biết nàng viết code, nhưng cố tình giả vờ không biết để có cớ hỏi thêm vài câu. Không ngờ lúc gặp mặt, Thời Vụ lại vui vẻ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi đang ở bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai giật mình:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao lại vào viện rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bị sốt thôi, không có gì nghiêm trọng."</p><p style="text-align: justify; margin-bottom: 0.9em">Sốt đến mức phải vào viện mà còn bảo không nghiêm trọng.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai cầm vô lăng. Cô biết Thời Vụ thích Triệu Hy Ngọc, người sáng suốt đều nhìn ra được. Vì thế, kết thúc cuộc hôn nhân này đối với Thời Vụ chắc chắn là một chuyện đau khổ, chỉ là nỗi đau ấy còn nặng nề hơn Kỳ Mai tưởng.</p><p style="text-align: justify; margin-bottom: 0.9em">Cũng không biết đến bao giờ mới có thể nguôi ngoai.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai lái xe vào bãi đỗ. Buổi tối xe ít hơn ban ngày, chỗ trống còn khá nhiều. Cô vừa xuống xe đã thấy có người đang đứng ngóng ở cửa bãi đỗ. Còn chưa kịp lên tiếng, một bóng người đã bước đến bên cạnh người đó. Lâm Châu cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ơ, chẳng phải cô là người bạn bác sĩ của chị Thời Vụ sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn kỹ, vừa bất ngờ vừa vui mừng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm Châu!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đeo khẩu trang, đôi mắt cong lên như mắt mèo. Cô hỏi Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị đứng đây làm gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đợi người."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ai vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bạn của Thời Vụ, trước đây từng làm cùng công ty với cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu quay đầu lại. Kỳ Mai đã đi tới phía sau hai người. Cô vốn quen Lâm Châu, mà hôm Thời Vụ không có mặt ở công ty, hoạt động lại do Kỳ Mai phụ trách, nên Lâm Châu gặp cô ở đây cũng không thấy bất ngờ. Kỳ Mai thì hơi ngạc nhiên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô Lâm?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cũng nhận ra cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quản lý Kỳ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hai người quen nhau à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai cười giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiệc sinh nhật của cô Lâm được tổ chức ở Ưu Lạc bên chúng tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vỗ trán. Đúng là bị Triệu Hy Ngọc làm cho rối cả đầu, sao nàng lại quên mất chuyện này chứ.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai gật đầu. Kỳ Mai hơi căng thẳng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời... tình hình của chị Thời Vụ thế nào rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nhận ra cách xưng hô của cô thay đổi, Lâm Châu quay sang nhìn cô một cái. Dư Mạt không để ý, đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chỉ là bị cảm do trúng gió, rồi lên cơn sốt. Sức khỏe vốn không tốt nên mới không chịu nổi."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có nghiêm trọng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Truyền nước hai ngày rồi, giờ đã hạ sốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai một tay xách túi máy tính, tay kia cầm hoa quả, đi phía sau Dư Mạt, vừa đi vừa hỏi tình hình của Thời Vụ. Lâm Châu khẽ cau mày, càng nghe càng thấy có gì đó không đúng. Đến tầng mười, Dư Mạt hỏi cô nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô sang chỗ bà nội à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vẫn không yên tâm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi sang chỗ chị Thời Vụ trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Tâm trí Kỳ Mai lúc này đều đặt cả vào người sắp gặp, hoàn toàn không để ý Lâm Châu cũng theo mình vào phòng bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngước mắt lên, thấy ba người nối đuôi nhau vừa nói vừa cười bước vào, nàng hơi khựng lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai vừa đặt hoa quả và túi máy tính xuống đã vội bước đến bên giường, định đỡ nàng. Lâm Châu chen tới:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị Thời Vụ, chị muốn lấy gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô khéo léo dùng người chắn Kỳ Mai sang một bên.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nhất thời không kịp phản ứng, đứng ngẩn ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lại chẳng thấy có gì lạ. Dù sao nàng đã không chỉ một lần thấy Lâm Châu đối xử với Lâm Nhược Đường như vậy. Nàng cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không lấy gì cả. Sao em lại sang đây?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lén nhìn Kỳ Mai, cười tươi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chẳng phải em đã nói hôm nay sẽ sang sớm ở bên chị sao."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô cố tình nhấn mạnh mấy chữ "sang sớm ở bên chị". Thời Vụ không để ý, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy em ăn cơm chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lại nhìn Kỳ Mai:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Kỳ Mai, cô ăn chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai cũng lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy chúng ta ra ngoài ăn nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao mọi người đều đến thăm nàng, để ai cũng nhịn đói thì thật thất lễ. Lâm Châu đỡ lấy cánh tay nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị xuống lầu được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ban ngày đã truyền xong rồi, xuống dưới ăn một bữa không sao. Dư Mạt, cậu đi cùng nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vốn đến đây cũng là để tìm nàng ăn tối. Thấy giờ lại có thêm khách, cô gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, vậy để tôi đặt nhà hàng."</p><p style="text-align: justify; margin-bottom: 0.9em">Vì Lâm Châu là người nổi tiếng, nếu ngồi ngay giữa sảnh thì không phải đi ăn mà thành buổi ký tặng mất. Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Muốn ăn gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vốn không định ăn, nhưng lại càng không muốn để Kỳ Mai và Thời Vụ ở riêng với nhau:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Gì cũng được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy ăn thanh đạm một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đang muốn giảm cân, bản thân cũng không ăn được đồ nhiều dầu mỡ, nghe vậy liền quay sang Kỳ Mai:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe giọng cô nàng nhỏ nhẹ, Kỳ Mai mềm lòng hẳn, trả lời cũng không còn lưu loát:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, được."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhanh chóng đặt xong nhà hàng. Lâm Châu khoác tay Thời Vụ, cố tỏ ra tự nhiên vì sợ bị người khác nhận ra. Cô cứ cúi đầu nhìn mũi giày, nửa người gần như tựa vào Thời Vụ, dìu nàng đi cùng.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nhìn tư thế ấy, mấy lần muốn nói rồi lại thôi, cuối cùng cả nhóm cũng đến nhà hàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đặt phòng riêng trên tầng hai, có cửa sổ nhìn sang bệnh viện. Đang đúng giờ ăn tối nhưng phòng riêng ở đây lại ít người dùng, hơn nữa còn có mức chi tiêu tối thiểu. Phần lớn người đến đều vì khám bệnh nên cũng chẳng mấy ai muốn tốn nhiều tiền cho một bữa ăn.</p><p style="text-align: justify; margin-bottom: 0.9em">Vì thân phận của Lâm Châu, họ không thể ngồi ngoài sảnh. Sau khi bốn người ngồi xuống, Lâm Châu ngồi bên trái Thời Vụ, Kỳ Mai ngồi bên phải. Dư Mạt nhìn chỗ ngồi, trong lòng hơi kì lạ bèn ngồi xuống cạnh Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">So với Kỳ Mai, cô vẫn thân với Lâm Châu hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Ai bảo bây giờ cô đang ghét tất cả mọi thứ liên quan đến Ưu Lạc, kể cả người làm việc ở đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai không biết cô đang nghĩ gì, ngồi cạnh Thời Vụ mà vui đến mức không giấu nổi. Cô nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chiều nay tôi không biết chị đang ở bệnh viện. Nếu biết sớm thì đã không làm phiền chị nghỉ ngơi rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao." Nàng nói chuyện công việc rất dứt khoát, —"Mang máy tính theo rồi chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mang rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối ăn xong về, tôi sẽ viết phần code nhúng vào. Sau đó cô sẽ biết vị trí của file."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nhìn Thời Vụ, đôi mắt không giấu được ý cười, gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn ánh mắt ấy, khẽ nhíu mày. Ngón tay cô siết lấy đôi đũa đến mức đầu ngón tay trắng bệch, cả người cũng căng lên. Dư Mạt vô tình quay sang nhìn cô nàng rồi lại nhìn thêm lần nữa, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô... không khỏe à?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không." Lâm Châu lắc đầu rồi hỏi Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hai người họ thân nhau lắm à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sợ Thời Vụ và Kỳ Mai nghe thấy, cô nàng ghé sát bên tai Dư Mạt hỏi nhỏ. Dư Mạt nghe xong cũng ghé lại bên tai cô nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Kỳ Mai là do chính tay Thời Vụ dẫn dắt."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu gãi tai, hơi ngứa. Khi Dư Mạt ghé lại gần, mùi nước sát khuẩn càng rõ hơn. Cô không thích mùi này, nhưng ngoài mùi nước sát khuẩn, trên người Dư Mạt còn phảng phất một mùi khác, nhè nhẹ, giống như mùi cam.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu còn đang phân biệt xem đó là mùi gì thì Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng ngồi thẳng lại, vẻ mặt không hề thay đổi, rồi đặt tay xuống dưới bàn, lén gõ chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị, tan làm chưa?】</p><p style="text-align: justify; margin-bottom: 0.9em">Gửi xong, cô nàng chờ mãi. Đến lúc gần muốn gọi điện luôn thì Lâm Nhược Đường mới trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Em đang ở nhà hàng bên ngoài bệnh viện.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Rồi sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đang ăn cơm với chị Thời Vụ, còn có cả người đang theo đuổi chị ấy nữa. Trời ơi, cô ấy tích cực thật đấy, chị Thời Vụ vừa mới ly hôn mà đã theo đuổi rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Nói chính xác thì phải đến thứ Hai cô ấy mới chính thức ly hôn.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu trợn mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Trọng điểm là chuyện đó sao???</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng lại nhắn cho Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị có đến không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không trả lời. Cô dựa lưng vào ghế, trước mặt là Lâm Ngọc Phượng đang uống canh. Bà hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ai nhắn tin cho con vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Châu." Lâm Nhược Đường đặt điện thoại xuống, đưa khăn giấy cho Lâm Ngọc Phượng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng lau miệng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hai hôm nay nó không bận à? Ngày nào cũng chạy đến bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cong môi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Kệ em ấy đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Con cũng đừng nói nó. Nó đến còn biết chọc ta vui, còn con vừa tới đã xị mặt ra. Không muốn gặp ta thì cứ nói thẳng, ta cũng chẳng cần con ngày nào cũng tới."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, vậy ngày mai con không đến nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng trừng mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Con dám!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bật cười. Gương mặt vốn lạnh nhạt thoáng có thêm chút vui vẻ, giữa hàng mày vẫn bình thản, nhưng ý cười nơi đáy mắt lại rất rõ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thế mới đúng chứ, cười nhiều lên, nhìn đẹp biết bao."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường chậm rãi cầm cốc uống nước nghe Lâm Ngọc Phượng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phòng bên cạnh có một cô gái ở phải không? Con nhà ai thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Một người bạn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng tò mò:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bạn của con?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bà ấy còn tưởng là bạn của Lâm Châu. Lâm Châu có nhiều bạn nên trước đó bà ấy cũng không để tâm. Nghe Lâm Nhược Đường nói vậy, Lâm Ngọc Phượng chợt thấy hơi tiếc vì chiều nay không sang thăm.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thôi, sức khỏe cô ấy không tốt, bà đừng sang làm phiền."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng cau mày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao lại bảo ta đừng sang làm phiền? Ta đã bao giờ làm phiền bạn con chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bà nghĩ một lát rồi chợt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"À, mà con cũng có mấy người bạn đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Yên tâm, ta không sang làm phiền đâu. Khó lắm mới có một người bạn khiến con để tâm như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghĩ một lát rồi đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Con cũng chỉ được người ta nhờ vả thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn 15 phiếu Bá Vương và 500 chai dung dịch dinh dưỡng của các tiểu thiên sứ~</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng: Người ta nhờ con chăm sóc con bé tận giường luôn à?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: 👶👶👶👶👶</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 33.1, 'Tham Khảo Ý Kiến Mọi Người !', '<p style="text-align: justify; margin-bottom: 0.9em">Mình muốn hỏi ý kiến mọi người một chút về Đoạt Vợ: mọi người có muốn mình tiếp tục edit bộ này không?</p><p style="text-align: justify; margin-bottom: 0.9em">Tác giả Ngư Sương là một trong những tác giả mình yêu thích, mình rất thật lòng khi nói như vậy, mình đã đọc qua: Bước Nhầm Vào Con Đường Hôn Nhân, Vi Quang ( editing) và Hợp Cửu Bất Phân, Phân Cửu Tất Hợp, mình đánh giá là đều đáng để đọc và ngọt vì thế mới quyết định edit bộ : Đoạt Vợ , bộ này là bộ mới nhất trong năm nay của tác giả. Nhưng mà... đi đến hơn 30 chương, thật sự mình cần phải thú thật với các bạn.</p><p style="text-align: justify; margin-bottom: 0.9em">Gần đây mình đã suy nghĩ khá nhiều về việc có nên tiếp tục hay dừng lại. Truyện đã đi được khá nhiều, cũng đủ để mình phần nào cảm nhận được hướng phát triển của cốt truyện và cách tác giả xây dựng nhân vật.</p><p style="text-align: justify; margin-bottom: 0.9em">Ban đầu mình chọn edit vì khá thích thiết lập của truyện và mối quan hệ giữa các nhân vật, nên cũng đặt khá nhiều kỳ vọng. Nhưng càng đi tiếp, cảm nhận cá nhân của mình lại thấy bộ này chưa có nhiều điểm nhấn như mình mong đợi. Nhịp truyện tương đối đều, một số tình tiết và chuyển biến tâm lý được xử lý khá nhanh, những chỗ mình chờ đợi câu chuyện được đào sâu hơn thì đôi khi lại lướt qua khá nhẹ. Vì vậy đến hiện tại, mình vẫn chưa có được cảm giác thật sự bị cuốn vào câu chuyện như lúc mới bắt đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Một phần khác khiến mình đắn đo là văn phong.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong quá trình edit, có những đoạn nếu bám thật sát nguyên tác thì khi chuyển sang tiếng Việt mình cảm thấy cách kể và thể hiện cảm xúc hơi đơn giản, chưa đạt được độ mượt và chiều sâu mà mình mong muốn ở một bản edit. Nhưng nếu mình cố trau chuốt quá nhiều để câu chữ hay hơn, trưởng thành hơn, thì lại rất dễ vượt khỏi nguyên tác.</p><p style="text-align: justify; margin-bottom: 0.9em">Mà với mình, edit không phải là viết lại truyện. Người edit có thể làm câu tiếng Việt tự nhiên và dễ đọc hơn, nhưng vẫn nên giữ được cách kể, cảm xúc và chất riêng vốn có của tác phẩm. Nếu mình phải liên tục sửa cả cách tác giả kể chuyện để bản edit trở thành thứ mình muốn đọc, thì có lẽ vấn đề không còn nằm ở bản dịch nữa, mà đơn giản là mình và bộ truyện này không thật sự hợp nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Tất nhiên, đây chỉ là cảm nhận cá nhân của mình về riêng Đoạt Vợ, không có nghĩa truyện hay hay dở. Gu đọc của mỗi người khác nhau, và mình biết vẫn có khá nhiều bạn thích bộ này, theo dõi từng chương và chờ mình edit tiếp. Chính vì vậy mình không muốn chỉ dựa vào cảm nhận của bản thân rồi tự quyết định dừng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nên mình muốn hỏi thật những bạn vẫn đang theo truyện:</p><p style="text-align: justify; margin-bottom: 0.9em">Mọi người có muốn mình tiếp tục edit Đoạt Vợ không?</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu vẫn còn nhiều bạn thực sự muốn đọc tiếp, mình sẽ cân nhắc tiếp tục làm theo mong muốn của mọi người. Còn nếu mọi người cũng không còn quá hứng thú, có lẽ mình sẽ dừng ở đây và dành thời gian cho một bộ khác mà cả người edit lẫn người đọc đều có nhiều cảm xúc hơn khi theo dõi.</p><p style="text-align: justify; margin-bottom: 0.9em">Mọi người cứ góp ý thật lòng nhé. Mình sẽ đọc ý kiến của mọi người rồi mới quyết định. ❤️</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 34, 'Ôm', '<p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng chẳng tin cái lý do "đã nhận lời nhờ vả của người khác" ấy. Trước đây bà từng nhờ Lâm Nhược Đường chăm sóc không biết bao nhiêu người, nhưng chưa bao giờ thấy cô để tâm đến ai như thế. Chẳng qua chỉ là tìm một lý do nghe thật đường hoàng để chặn miệng thiên hạ, hoặc cũng có thể... là để ngăn chính trái tim đang dần xao động của mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Hiếm lắm Lâm Ngọc Phượng mới được thấy Lâm Nhược Đường như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Tâm trạng bà rất tốt, đến bữa tối còn uống thêm một bát canh. Lâm Nhược Đường nhìn hộ lý dọn bữa tối đi rồi mới nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bác sĩ nói tình trạng của bà đã ổn định, ngày mai có thể xuất viện rồi. Bà về nhà nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Mấy hôm trước còn luôn miệng đòi về nhà, vậy mà lúc này Lâm Ngọc Phượng lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tim ta vẫn hơi khó chịu, để hai hôm nữa hẵng về."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cau mày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bắt đầu khó chịu từ khi nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ để có cớ ở lại thêm vài ngày, Lâm Ngọc Phượng nhất quyết nói tim mình vẫn còn hơi khó chịu.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thỉnh thoảng thôi. Bác sĩ đã khám rồi, không có gì đáng ngại."</p><p style="text-align: justify; margin-bottom: 0.9em">Bà lấy khăn giấy lau tay, thuận miệng hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Triệu Diễm về nước rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về được mấy hôm rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhìn cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là con gọi về sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà à, Triệu Diễm cũng nên trở về rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng trầm giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Năm đó ta đã không đồng ý với cách làm của con. Đẩy Triệu Diễm ra nước ngoài, khiến không ít người trong công ty lạnh lòng, một loạt nhân sự nòng cốt cũng lần lượt rời đi. Bây giờ con lại cứ thế gọi trở về, trong lòng người đó sao có thể không oán trách? Triệu Diễm và mẹ con vốn là bạn cũ. Năm đó mẹ con xảy ra chuyện, công ty cũng nhờ người đó đứng ra chống đỡ mới vượt qua được. Nhược Đường, làm người hay làm việc cũng không nên tuyệt tình đến mức ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Sắc mặt Lâm Nhược Đường vẫn không chút thay đổi, ánh mắt lạnh nhạt như thường. Nghe bà nói xong, cô chỉ khẽ cụp mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Con biết rồi. Bà cứ yên tâm, con biết mình đang làm gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhìn cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường từ nhỏ đã thông minh, thậm chí còn thông minh hơn người. Điểm này cô thừa hưởng rất nhiều từ hai người mẹ. Bất kể ngoại hình hay trí tuệ, cô đều được trời ưu ái, thành tích cả ban xã hội lẫn ban tự nhiên đều đứng đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Năm cấp ba, đến lúc phải lựa chọn giữa ban tự nhiên và ban xã hội, giáo viên chủ nhiệm còn nhiều lần tìm đến tận nhà, khuyên gia đình nên cân nhắc thật kỹ. Nhưng Lâm Nhược Đường từ nhỏ đã rất có chính kiến. Cuối cùng cô chọn ban tự nhiên, từ bỏ suất tuyển thẳng để tự mình tham gia kỳ thi đại học.</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng mấy ai hiểu được cô, nhưng Lâm Ngọc Phượng ít nhiều vẫn hiểu đôi chút.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thích tự mình nắm quyền quyết định.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi ấy, tính cách cô vẫn chưa lạnh nhạt như bây giờ. Mãi cho đến khi mẹ cô xảy ra chuyện.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Con biết chừng mực là được. Ngày mai gọi Triệu Diễm đến nhà ăn một bữa đi, ta cũng lâu rồi chưa gặp."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thong thả đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Con biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng liếc cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ta nói cho con biết...."</p><p style="text-align: justify; margin-bottom: 0.9em">Ngoài hành lang chợt vang lên tiếng bước chân. Âm thanh không lớn, nhưng phòng bệnh vốn yên tĩnh nên vẫn có thể nghe thấy chút động tĩnh. Lâm Ngọc Phượng nhìn ra cửa, rồi lại nhìn Lâm Nhược Đường. Thấy những ngón tay buông bên người cô khẽ miết vào nhau, vẻ mặt như đang suy nghĩ điều gì, bà bất giác vui ra mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không ra ngoài xem thử à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lát nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Ngoài cửa, Lâm Châu khoác tay Thời Vụ bước vào phòng bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cầm điện thoại lật qua lật lại mấy lần, nhưng Lâm Nhược Đường vẫn chưa trả lời tin nhắn của nàng. Có ý gì đây? Đang họp sao? Hay là đã chạy đến rồi? Nếu mà là theo đuổi người khác thì tốc độ này cũng quá là chậm rồi, thật khiến nàng không khỏi chê bai.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi vào phòng bệnh, nàng hỏi Kỳ Mai mượn máy tính. Hai người ghé sát đầu vào nhau, cùng bàn bạc vấn đề liên quan đến mã hóa. Lâm Châu ngồi trên sofa cách đó không xa, hai mắt sáng rực nhìn chằm chằm Kỳ Mai. Kỳ Mai nhận ra ánh mắt ấy, quay đầu nhìn lại mấy lần, cuối cùng không nhịn được nữa, hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tiểu thư sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn theo ánh mắt cô sang Lâm Châu. Lâm Châu ngoan ngoãn nở nụ cười với nàng. Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai buồn bực:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô lắc đầu, tiếp tục nhìn vào máy tính. Thời Vụ đang tải tài liệu xuống thì Kỳ Mai hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị nghỉ việc rồi, Triệu tổng phê duyệt chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu lại, giọng bình thản:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phê rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thông thường sau khi nghỉ việc sẽ có một tháng để bàn giao công việc. Dạo này tuy Thời Vụ không đến công ty, nhưng nếu công việc có vấn đề, nàng vẫn sẽ hỗ trợ xử lý. Chỉ là nàng không muốn đến Ưu Lạc, cũng không muốn gặp Triệu Hy Ngọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Còn một chuyện muốn hỏi ý kiến chị. Chị có biết Cự Năng Hoàn Cầu không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sao có thể không biết Cự Năng Hoàn Cầu. Đây là một trong những hệ thống trung tâm thương mại hàng đầu trong nước, với tổng cộng 443 chi nhánh trải rộng trên hơn hai trăm thành phố. Ngoài trung tâm thương mại, họ còn kinh doanh rạp chiếu phim, khu nghỉ dưỡng và nhiều loại hình câu lạc bộ thương mại khác. Trước đây Thời Vụ từng tìm hiểu quy mô cũng như phương thức vận hành của các trung tâm thương mại trong nước.</p><p style="text-align: justify; margin-bottom: 0.9em">Cự Năng Hoàn Cầu là hệ thống trung tâm thương mại lớn thứ hai, chỉ xếp sau thương hiệu dẫn đầu ngành.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hỏi Kỳ Mai:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao tự nhiên lại hỏi chuyện này?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Họ muốn mở một trung tâm thương mại mới ở khu Bắc."</p><p style="text-align: justify; margin-bottom: 0.9em">Theo phản xạ nghề nghiệp, Thời Vụ lập tức hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Khu Bắc? Chẳng phải trong kế hoạch năm nay của họ không có khu Bắc sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Ngay từ đầu năm, Cự Năng Hoàn Cầu đã xác định địa điểm cho ba trung tâm thương mại mới ở khu Đông và khu Tây. Thời Vụ còn từng tham dự tiệc tối của họ, khi ấy người phụ trách cũng nói trọng tâm kế hoạch năm nay sẽ đặt ở hai khu này.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hình như có tin gì đó, nói khu Bắc sắp được khai phá nên họ mới định mở thêm một trung tâm thương mại."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi muốn hỏi xem chị có muốn qua đó không."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ cau mày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Người phụ trách khu Bắc bên họ là bạn học của tôi. Biết chị đã nghỉ việc nên gọi cho tôi mấy lần, muốn mời chị sang phụ trách bộ phận thu hút đối tác."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói là bạn học, thực ra hai người từng học cùng một trường đại học, lại tình cờ ở chung ký túc xá nửa học kỳ. Sau đó Hoàng Doanh chuyển ra ngoài ở, mọi người mới biết hóa ra cô ấy là con gái của ông chủ Cự Năng Hoàn Cầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Bình thường Hoàng Doanh không tiếp xúc với mọi người quá nhiều. Trong ký túc xá, cô ấy cũng chẳng hề tỏ ra mình có tiền, nhưng từ quần áo cho đến đồ ăn, thứ gì dùng cũng đều là loại tốt nhất. Vì vậy, sau khi biết thân phận của cô ấy, mọi người cũng không quá bất ngờ.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai và Hoàng Doanh không thân thiết lắm. Khi Kỳ Mai đi tìm việc, Hoàng Doanh từng hỏi cô có muốn đến Hoàn Cầu không. Nhưng khi ấy Kỳ Mai vừa nhìn đã ưng Ưu Lạc, nên từ bỏ cơ hội sang đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Lần này Hoàng Doanh lại chủ động liên lạc, Kỳ Mai vẫn khá bất ngờ. Chuyện Thời Vụ nghỉ việc còn chưa truyền ra trong công ty, vậy Hoàng Doanh biết được từ đâu?</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai hỏi cô ấy. Hoàng Doanh chỉ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Làm gì có bức tường nào kín gió. Muốn giành người về tay mình thì chẳng phải nên chuẩn bị trước hay sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Cũng phải thôi. Trong mắt cô, Thời Vụ là người xuất sắc nhất, đáng để người khác phải bỏ công sức như vậy để chiêu mộ.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe thấy cái tên ấy, Thời Vụ thoáng trầm ngâm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hoàng Doanh?"</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị quen cô ấy à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Từng gặp rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói chính xác hơn, Hoàng Doanh từng muốn chiêu mộ Thời Vụ, mà lại đúng vào lúc nàng vừa mới kết hôn. Trước đó, hai người từng gặp nhau trong một bữa tiệc, nhưng không thân thiết, cùng lắm chỉ là quan hệ gặp mặt thì gật đầu chào hỏi. Thế nên đến khi Hoàng Doanh hỏi nàng ngay tại tiệc cưới rằng có ý định nhảy việc hay không, Thời Vụ không khỏi bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm nay hình như không thích hợp để nói chuyện này thì phải."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh rất thức thời:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy xem ra là chưa có ý định rồi. Không sao, sau này vẫn còn cơ hội hợp tác."</p><p style="text-align: justify; margin-bottom: 0.9em">Không ngờ cơ hội ấy lại đến nhanh và đột ngột như vậy. Kỳ Mai hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy tôi gửi thông tin liên lạc của chị cho cô ấy nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Dù có thành hay không, ít nhất đây cũng là một cơ hội.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Kỳ Mai đẩy máy tính sang, Thời Vụ cũng vừa chèn mã xong. Kỳ Mai nhìn phần chú thích bên dưới tài liệu, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lần này thì tôi hiểu rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không coi đó là chuyện gì đáng kể:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sau này còn chỗ nào không hiểu thì cứ hỏi tôi bất cứ lúc nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được. Trước đây tôi đã nói sẽ mời chị ăn một bữa, đợi chị xuất viện rồi tôi sắp xếp."</p><p style="text-align: justify; margin-bottom: 0.9em">Sắc mặt Thời Vụ dịu đi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vội gì chứ, tùy duyên thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trong lòng Kỳ Mai chợt rung lên. Cô nhìn nghiêng gương mặt Thời Vụ, bất giác cũng bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn vẻ mặt của hai người khi nói chuyện, khẽ cau mày. Một tay cô nhanh chóng gõ chữ gửi cho Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Xong rồi, chị thua rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: 【?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: 【Sao giờ chị mới trả lời em?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: 【Thua cái gì?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: 【Ồ, chính là quản lý bên Ưu Lạc ấy, quản lý bộ phận quan hệ công chúng, Kỳ Mai. Chị biết không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: 【Chị cần phải biết sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nghẹn lời, đưa tay gãi mày, nhất thời chẳng nghĩ ra được lý do gì để cô nhất định phải biết.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng cố gắng châm ngòi:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cô ấy thích chị Thời Vụ.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: 【Thì sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: 【Có người sắp đào góc tường nhà chị rồi mà chị còn bình thản thế à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: 【Chị có thích chị Thời Vụ không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: 【Em nói cho chị biết, em thích chị ấy lắm đấy. Nếu chị không thích thì em theo đuổi!】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: 【Qua đây.】</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn hai chữ ấy, Lâm Châu bỗng hết cả hứng, không nhắn nữa, cũng chẳng còn mạnh miệng như vừa rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngay giây sau, Lâm Nhược Đường gọi điện thoại tới. Điện thoại trong tay Lâm Châu như củ khoai nóng bỏng tay. Cô nàng quay sang, nhét thẳng điện thoại cho Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nghe máy đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt chỉ vào mình, ngơ ngác:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi á?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Điện thoại của chị tôi, Cứ bảo tôi không có ở đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa dứt lời, điện thoại cũng ngừng rung. Gần như cùng lúc, cửa phòng bệnh "cạch" một tiếng mở ra. Gương mặt không chút biểu cảm của Lâm Nhược Đường xuất hiện ngoài cửa. Cô nhìn Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Qua đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu không ngờ cô còn đích thân tới, căng thẳng nuốt khan một cái, gương mặt như sắp khóc đến nơi. Cô nàng quay sang cầu cứu Thời Vụ. Thời Vụ khó hiểu nhìn lại cô nàng và Lâm Nhược Đường. Dư Mạt vẫn chưa hiểu chuyện gì xảy ra, cũng ngơ ngác nhìn Lâm Châu. Kỳ Mai thì chẳng hiểu vì sao Lâm Nhược Đường lại đột nhiên xuất hiện.</p><p style="text-align: justify; margin-bottom: 0.9em">Cả phòng bệnh chìm vào một sự im lặng kỳ lạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không muốn nhắc lại lần thứ hai. Cô khẽ nhíu mày, ánh mắt nhìn Lâm Châu mang theo ý cảnh cáo. Lâm Châu tê cả da đầu, đành chậm chạp đứng dậy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em tới đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Đến điện thoại cô nàng cũng quên cầm theo. Dư Mạt ở phía sau gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Này......"</p><p style="text-align: justify; margin-bottom: 0.9em">Rõ ràng Lâm Châu mới là người sợ Lâm Nhược Đường, sao đến cô cũng thấy căng thẳng theo vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Ra khỏi phòng bệnh, Lâm Châu dè dặt nhìn sắc mặt Lâm Nhược Đường, nhỏ giọng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy ạ ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà nhớ em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy chị bày ra vẻ mặt đó làm gì chứ!</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu còn tưởng những lời vừa rồi của mình khiến Lâm Nhược Đường không vui, sau lưng toát cả mồ hôi lạnh. Cô nàng thở phào:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chị nói chuyện đàng hoàng một chút được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường sa sầm mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nói gì? Chuyện em muốn theo đuổi Thời Vụ à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng kêu lên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em chỉ đùa thôi mà! Chị không biết đâu, hôm nay vì chị mà em hy sinh lớn lắm rồi, đến cơm tối cũng ăn xong rồi, chẳng biết có béo thêm mấy cân không nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường chẳng buồn nghe cô nàng lải nhải, kéo thẳng sang phòng bệnh của Lâm Ngọc Phượng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng vừa định nghỉ ngơi, nghe thấy tiếng hai chị em thì mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Châu cũng qua đây rồi à."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu thân thiết khoác lấy cánh tay bà:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng cười đến hiền từ. Từ sau khi con gái và người bà yêu qua đời, người khiến bà lo lắng nhất chính là Lâm Nhược Đường. Vốn dĩ trước kia cô cũng không phải người có tính tình lạnh nhạt như vậy, chỉ là hơi ít nói. Sau biến cố ấy, bà muốn trò chuyện với cô cũng chẳng biết nên bắt đầu từ đâu. May mà còn có Lâm Châu, con bé hoạt bát này vẫn luôn ở bên cạnh Lâm Nhược Đường. Nghĩ đến đó, bà cảm thấy rất vui.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao tối nay không sang ăn cơm với ta?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối nay con có hẹn rồi, ngày mai sẽ ăn cùng bà."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, cô nàng còn tranh thủ mách:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà, chị bắt nạt con. Chị ấy nói sẽ không cho con tiền tiêu vặt nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhìn Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lại phạm lỗi gì rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu giơ tay lên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trời đất chứng giám! Con thật sự không làm gì cả, là chị ấy không nói lý lẽ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường liếc cô nàng một cái, lạnh lùng hừ khẽ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lập tức mách:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà xem, bà xem đi, chị ấy lại dọa con !"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng vỗ nhẹ lên mu bàn tay cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao, có ta ở đây. Nó không cho thì ta cho con là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ vì biết mình chẳng còn bao nhiêu thời gian, Lâm Ngọc Phượng đã sớm giao lại cho Lâm Nhược Đường lo liệu nhiều chuyện về sau, kể cả việc chăm sóc Lâm Châu. Thế nên thỉnh thoảng Lâm Nhược Đường vẫn lấy chuyện này ra "dọa". Lâm Châu nghe bà nói vậy, lập tức cười híp mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vẫn là bà thương con nhất."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng chợt nhớ ra một chuyện:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng rồi, ta nghe nói phòng bên cạnh có người mới vào ở, con quen à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quen ạ, là chị Thời Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe cái tên này, Lâm Ngọc Phượng cảm thấy khá quen:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời Vụ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu còn chưa kịp nói, Lâm Nhược Đường đã lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là Triệu tổng của Ưu Lạc, phu nhân của cô ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhíu mày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ồ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu bất giác nuốt khan.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại thản nhiên nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sáng ngày kia họ sẽ ly hôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nấc thêm một tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhìn chằm chằm Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có liên quan đến con?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhận luôn, chẳng hề khách sáo:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng có thể xem là vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô quả thật đã góp công không ít. Thời Vụ không đến khách sạn thì đã sao, dù gì chuyện này cũng có phần công sức của cô mà.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhìn Lâm Nhược Đường, càng nhìn càng thấy ánh mắt cô có gì đó khác thường. Bà cau mày, nếp nhăn giữa hai hàng mày càng hằn sâu, sắc mặt cũng chậm rãi trầm xuống:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đừng nói với ta là con để ý người ta, nên mới khiến cuộc hôn nhân của người khác đổ vỡ đấy nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lập tức hết nấc, vội lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải đâu bà. Là vợ chị Thời Vụ ngoại tình nên chị ấy mới ly hôn, chẳng liên quan gì đến chị con cả. Chị ấy chỉ giúp Thời Vụ nhìn rõ người bên cạnh mình thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng vẫn không nói gì, chỉ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy tại sao con lại giúp cô ấy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cũng nhận ra có gì đó không ổn, bèn thuận theo câu hỏi của bà mà giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vì trước đây chị con từng chịu ơn người ta. Bà còn nhớ hồi cô mất, chị ấy từng đến Hà Kiều gặp một bác sĩ tâm lý không? Người đó chính là mẹ của Thời Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Chuyện cũ được nhắc lại, Lâm Ngọc Phượng mới nhớ ra vì sao cái tên Thời Vụ nghe quen đến vậy. Thì ra là vì họ Thời. Bà khẽ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy thì nên cảm ơn người ta cho đàng hoàng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu thấy bà đã hiểu, liền nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng. Bà không biết đâu, hai người mẹ của chị Thời Vụ đều đã mất rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng thoáng sững lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao lại..."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Một người mất vì bệnh, một người gặp tai nạn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nghe mà xót xa, vẻ mặt trầm xuống. Bà gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy cũng là một đứa trẻ đáng thương. Chỉ e nhà họ Triệu không phải nơi dễ sống. Để tâm đến cô ấy một chút, nếu có gì giúp được thì cứ giúp."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu chớp mắt với Lâm Nhược Đường, nhưng cô chẳng buồn để ý.</p><p style="text-align: justify; margin-bottom: 0.9em">Cứ giả vờ đi!</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, bà."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng còn muốn giữ Lâm Châu lại trò chuyện thêm, nhưng sức khỏe không cho phép. Chỉ nói thêm được vài câu, bà đã bắt đầu buồn ngủ. Lâm Châu dỗ bà ngủ rồi cùng Lâm Nhược Đường ra khỏi phòng bệnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa bước ra ngoài, Lâm Châu đã lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chẳng lẽ chị không nên cảm ơn em một tiếng sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sắc mặt Lâm Nhược Đường dịu đi đôi chút, ngay cả giọng nói cũng ôn hòa hơn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn em chuyện gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vừa rồi em còn giúp chị giải thích với bà đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần? Chị định làm bà tức chết à? Người bà giới thiệu cho chị xem mắt thì chị không chịu, lại cứ nhất quyết để ý một người đã kết hôn. Này, đừng trách em nói khó nghe nhé, bà chắc chắn vẫn mong chị tìm một người chưa từng trải qua hôn nhân. Cho nên chuyện này phải từ từ, từng bước một mới được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy cô nàng nói cứ như thật, Lâm Nhược Đường bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em rành chuyện này lắm à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu đắc ý:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tất nhiên. Chưa ăn thịt heo thì cũng từng thấy heo chạy rồi chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được. Mai chị làm thịt heo cho em ăn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu: "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng lập tức nhào tới. Lâm Nhược Đường nghiêng người tránh sang một bên. Lâm Châu ở phía sau giơ tay định đánh, nào ngờ Lâm Nhược Đường chợt quay đầu. Bắt gặp ánh mắt lành lạnh của cô, Lâm Châu lập tức rụt tay lại, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị sang chỗ chị Thời Vụ à?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừ, lấy một thứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu "ồ" một tiếng, theo cô vào phòng bệnh của Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ Mai đã đi rồi. Lâm Châu đảo mắt nhìn quanh, hỏi Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Người đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt mấp máy môi, không phát ra tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đi rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu gật đầu liên tục. Dư Mạt đưa điện thoại trả lại cho cô, Lâm Châu nhận lấy, cười hơi ngượng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Thời Vụ đang nói chuyện với Lâm Nhược Đường, cô quay sang hỏi Dư Mạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mấy giờ cô tan làm?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi trực ca đêm."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thế mấy giờ mới xong?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bảy giờ sáng mai."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vất vả cho cô rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng không đến nỗi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi thêm WeChat của cô được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hơi bất ngờ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, thêm tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừ. Bà tôi đang nằm viện, tôi không yên tâm lắm. Nếu cô có thời gian thì qua xem giúp tôi một chút, có chuyện gì cứ báo cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vừa lấy điện thoại ra, vừa cảm thấy lý do này nghe có phần quen thuộc. Cô kín đáo nhìn Lâm Châu một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có gì." Dư Mạt nói, "Sức khỏe của bà cô thế nào rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tuổi đã cao, trong người khó tránh khỏi nhiều bệnh."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng phải."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô làm việc trong bệnh viện, chắc thường xuyên chứng kiến cảnh sinh ly tử biệt?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thường xuyên. Có những bệnh nhân phải phẫu thuật, một khi đã lên bàn mổ thì không phải ai cũng có thể trở xuống."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy bình thường cô làm thế nào để cân bằng tâm lý?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt ngẩn ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bộ phim tiếp theo của tôi có một vai bác sĩ, tôi muốn tìm hiểu thêm một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nghiêm túc đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được. Cô có gì muốn hỏi thì cứ hỏi tôi. Chuyện của Thời Vụ lần này cũng nhờ cô và Lâm tổng giúp đỡ rất nhiều. Nếu không có hai người, chẳng biết Triệu Hy Ngọc còn muốn dây dưa đến bao giờ."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chuyện nhỏ thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu liếc sang Lâm Nhược Đường. Xem ra tâm trạng chị cô đang rất tốt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng đang nhìn Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đã thay bộ quần áo mặc lúc sáng. Cũng phải, bộ đồ đó quả thật không hợp với khí chất của cô. Chỉ là không biết cô đã xử lý quần áo của mình thế nào, vứt đi rồi sao? Nếu thật sự vứt đi, Thời Vụ vẫn thấy hơi tiếc, dù sao nàng cũng rất thích chiếc áo phông và quần jean ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Dây da vẫn còn buộc trên đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngồi xuống bên giường, hỏi thẳng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhìn gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bị giọng điệu thản nhiên như không của cô làm nghẹn lời, một lúc sau mới buồn bực hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quần áo của tôi đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường chẳng khách sáo, Thời Vụ cũng không cần khách sáo với cô.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ở công ty, sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi còn tưởng cô vứt rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quần áo đang yên đang lành, tôi vứt đi làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ai biết được. Dù sao cô cũng có tiền, mua lại là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng chăm chú một lúc rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô đang giận à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ như quả bóng đang căng phồng bỗng bị chọc thủng, khí thế lập tức xẹp xuống. Nàng hơi căng thẳng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không, tôi không giận."</p><p style="text-align: justify; margin-bottom: 0.9em">Mình chột dạ làm gì chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cố lấy lại bình tĩnh:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quần áo của cô được người ta mang đến rồi, ở trong tủ đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường "ừ" một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bao nhiêu tiền?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thoải mái đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không bao nhiêu."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó nàng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi nghe y tá nói viện phí là cô đóng?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bao nhiêu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không biết."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy nàng nghẹn lời, Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nếu cô muốn trả lại thì lúc xuất viện sẽ có hóa đơn, đến lúc đó chuyển cho tôi là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức nhẹ nhõm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, cảm ơn Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ cần cô chịu nhận tiền là được. Thời Vụ không muốn cứ mãi nợ ân tình của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Khách sáo rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nghe nói hôm nay người bên công ty cô đến tìm ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bảo cô quay về làm việc?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải. Có vài tài liệu cô ấy không rõ nên đến hỏi tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhân viên của Ưu Lạc chỉ có năng lực làm việc đến vậy thôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nhịn được, lên tiếng giải thích thay Kỳ Mai:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi nghỉ việc đột ngột, cô ấy mới tiếp nhận công việc chưa được bao lâu, có chỗ không rõ cũng là chuyện bình thường."</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt Lâm Nhược Đường từ trán nàng chậm rãi dừng lại nơi đôi môi đang nói. Giọng Thời Vụ không còn khàn như hôm qua, chỉ còn chút trầm đục sau cơn ho. Bản thân đã thế này rồi mà vẫn còn nghĩ cho người khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ hé môi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô Thời đúng là rất biết nghĩ cho người khác."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không vui:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô đừng nói kiểu mỉa mai như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Gan nàng cũng lớn thật rồi, đến Lâm Nhược Đường mà cũng dám lớn tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Còn nghe ra tôi đang mỉa mai, xem ra cũng không tệ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô lớn đến chừng này, chẳng lẽ chưa từng bị ai đánh sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đang bực, Dư Mạt ngồi trên sofa chợt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thời Vụ, trưởng khoa gọi tôi qua đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đứng dậy, vội vàng chào Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, vậy tôi đi trước. Bên Thời Vụ phiền cô để ý giúp."</p><p style="text-align: justify; margin-bottom: 0.9em">Tâm trạng Lâm Nhược Đường có vẻ khá tốt, cô mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vừa mở cửa, Lâm Châu cũng bật dậy khỏi sofa:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị! Em vừa nhận được điện thoại của chị Lâm, nói có một cảnh cần quay bù, giờ chị ấy đang đến đón em."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩn người nhìn hai người lần lượt rời khỏi phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong phòng bệnh thoáng chốc chỉ còn lại nàng và Lâm Nhược Đường. Thời Vụ còn chưa kịp nói gì, Lâm Nhược Đường đã hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối qua cô ra ngoài ăn à?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừ, quán ăn đối diện bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao không gọi tôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chẳng phải cô còn nợ tôi hai bữa cơm sao? Không định mời nữa à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lúc này mới hiểu ý cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mời chứ, đương nhiên phải mời. Hôm nay xảy ra chuyện đột ngột, tôi cứ tưởng cô vẫn còn đang tăng ca."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lần sau hỏi tôi trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghiêm túc gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừ, được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường có vẻ rất hài lòng. Cô đứng dậy, đúng lúc nghe ngoài cửa có tiếng động.</p><p style="text-align: justify; margin-bottom: 0.9em">Là tiếng giày cao gót.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu và Dư Mạt đều đi giày đế bằng, không phải họ, cũng không phải y tá.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ dường như nghĩ ra điều gì, khẽ cau mày nhìn về phía cửa. Quả nhiên, giọng Triệu Hy Ngọc vọng vào từ bên ngoài:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ, em có ở trong đó không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cứng người mất vài giây, lập tức bật xuống giường, đến giày cũng không kịp xỏ đã chạy thẳng ra cửa, khóa lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên ngoài, Triệu Hy Ngọc vẫn đang gõ cửa:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Vụ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trong phòng bệnh im phăng phắc.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn gương mặt tái nhợt cùng thân thể căng cứng của Thời Vụ. Cô bước đến cửa, vừa định lên tiếng thì một bàn tay đã che lấy miệng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Bàn tay nàng nóng ran vì sốt, nhất là lòng bàn tay. Lâm Nhược Đường cúi mắt, hàng mi che khuất ánh nhìn. Vì không vui nên sắc mặt cô lạnh nhạt. Thời Vụ sợ cô lên tiếng, tim đập dồn dập, hơi thở cũng gấp hơn, cố nén cơn ho đang chực trào lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ tiếng gõ cửa đã gọi y tá đến. Bên ngoài, y tá nói với Triệu Hy Ngọc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xin chào, bây giờ đã qua giờ thăm bệnh rồi, phiền cô ngày mai hãy quay lại."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói gì đó, giọng dần xa đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nghe rõ. Cơn ho đã không thể nén thêm được nữa, nàng quay mặt sang một bên, đưa tay che miệng, cố sức ho.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn đôi má vừa rồi còn trắng bệch của nàng giờ đã đỏ lên vì cơn ho, đôi mắt trong veo cũng phủ một lớp hơi nước mờ mịt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tựa lưng vào cửa, ho dữ dội đến mức cả người không ngừng run lên. Một tay nàng muốn vịn lấy khung cửa nhưng còn chưa chạm tới, Lâm Nhược Đường đã nắm lấy tay nàng, khẽ kéo một cái. Nửa người trên của Thời Vụ lập tức ngả vào vai cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sững lại. Vừa định đứng thẳng lên, Lâm Nhược Đường đã đưa tay đỡ lấy eo nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả:</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các tiểu thiên sứ đã tặng 12 vé Bá Vương và 673 chai dịch dinh dưỡng~</p><p style="text-align: justify; margin-bottom: 0.9em">[Danh sách tên người ủng hộ]</p><p style="text-align: justify; margin-bottom: 0.9em">Tiện thể phát ngẫu nhiên một trăm bao lì xì, thế nào?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: —"Đã nói là nhận sự ủy thác của người khác."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: —"Ủy thác kiểu này à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: —"Vẫn có thể chối được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: —"......"</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 35, 'Thử xem', '<p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhịn hồi lâu, cuối cùng khẽ ho một tiếng. Như một phản ứng dây chuyền, cơn ho lập tức dồn dập kéo đến, hơi thở dữ dội bật ra từ cổ họng. Nàng nghiêng đầu, vừa ho vừa ghì trán lên vai Lâm Nhược Đường, cả người không sao ngừng run rẩy. Lúc này cũng chẳng còn tâm trí để ý tư thế có thích hợp hay không, chỉ vì sợ ngã, nàng đưa một tay nắm lấy áo bên hông Lâm Nhược Đường, gần như nửa người đều dựa vào cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Mãi mới dịu xuống được đôi chút, nàng định đứng thẳng người, giọng Lâm Nhược Đường lạnh nhạt vang lên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đừng động."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay lưng về phía cô. Lâm Nhược Đường đưa tay, khẽ vỗ lên lưng nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tư thế này giúp dễ thở hơn. Vừa rồi cô ho dữ như vậy, không chóng mặt sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quả thực vẫn hơi choáng. Thật ra nàng cũng có chút ngại phải nói rằng chân mình vẫn còn mềm nhũn. Không phải vì sốt, mà vì vừa rồi ho đến kiệt sức, nên lúc này gần như đứng không vững. Lâm Nhược Đường một tay đỡ lấy eo nàng, tay kia vỗ nhẹ sau lưng, động tác chậm rãi, dịu dàng như đang dỗ một đứa trẻ ngủ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu, cảm giác thiếu dưỡng khí dần vơi đi. Thỉnh thoảng nàng vẫn ho thêm đôi tiếng, nhưng đã không còn dữ dội như trước.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghiêng mắt nhìn xuống. Mỗi lần Thời Vụ ho, bờ vai lại hơi chúi về phía trước, cả người khẽ run lên. Cánh tay đang ôm bên eo Thời Vụ của cô vô thức siết lại, gần như nửa ôm nàng vào lòng. Thời Vụ vừa rồi chỉ mải điều chỉnh nhịp thở nên không nhận ra tư thế giữa hai người đã thay đổi.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi biết Lâm Nhược Đường chính là cô bé mũm mĩm năm xưa được Thời Ánh Xuân đưa về nhà, nàng quả thực thân thiết với Lâm Nhược Đường hơn rất nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Vì vậy, nàng cũng không còn e dè khi để lộ sự yếu đuối của mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Cuối cùng Thời Vụ cũng ngừng ho. Trải qua trận ho vừa rồi chẳng khác nào một cuộc giằng co thể lực, giờ nàng mới miễn cưỡng đứng vững. Nàng siết người lại, Lâm Nhược Đường cũng buông tay, lùi về sau một bước, giữa hai người lại có một khoảng cách.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không đáp, chỉ rũ mắt nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thấy lạ, cũng ngước mắt nhìn lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Trên mặt Lâm Nhược Đường không có biểu cảm gì, ánh mắt lạnh nhạt. Không biết có phải Thời Vụ nhìn nhầm hay không, nàng lại cảm thấy dường như Lâm Nhược Đường đang giận. Thời Vụ khẽ nhíu mày, Lâm Nhược Đường mới miễn cưỡng mở lời:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sợ Triệu tổng bước vào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sợ cô ta vào rồi lại nhìn thấy trong phòng còn có người khác?</p><p style="text-align: justify; margin-bottom: 0.9em">Hay sợ Triệu Hy Ngọc hiểu lầm?</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe cô nói vậy, Thời Vụ hít sâu một hơi, lê bước đến bên giường bệnh. Ngồi xuống rồi, nàng mới nói với Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không phải sợ chị ấy vào, tôi chỉ sợ phiền phức."</p><p style="text-align: justify; margin-bottom: 0.9em">Sắc mặt Lâm Nhược Đường lúc này mới dịu đi đôi chút:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phiền phức?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thứ Hai sẽ ly hôn rồi, tôi không muốn lại nảy sinh thêm chuyện ngoài ý muốn."</p><p style="text-align: justify; margin-bottom: 0.9em">Đổi lại là bất kỳ ai, chỉ còn hai ngày nữa là ly hôn, lại vào giờ muộn thế này mà nhìn thấy một người khác trong phòng bệnh của vợ mình, e rằng đều sẽ nghĩ nhiều. Nàng và Triệu Hy Ngọc đã đi đến tận cùng rồi, lúc này nàng chỉ muốn mau chóng kết thúc, không muốn bất kỳ khâu nào lại phát sinh thêm rắc rối.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lặng lẽ nhìn Thời Vụ vài giây rồi chuyển sang chuyện khác:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sau khi ly hôn, cô có dự định gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Vốn dĩ Thời Vụ định sau khi ly hôn sẽ về nhà cũ ở một thời gian, nhưng hôm nay Kỳ Mai gửi WeChat cho nàng, nói Hoàng Doanh rất nhiệt tình mời nàng đến trung tâm thương mại mới xem thử. Nàng đã đồng ý chiều thứ Hai sẽ qua đó, nên nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trước tiên tìm một công việc đã."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cân nhắc đến Lâm Thái sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn Lâm tổng, nhưng chắc là không."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, nàng nghĩ, nếu sau này thật sự đến Cự Năng Hoàn Cầu, biết đâu hai bên vẫn sẽ có dịp làm việc cùng nhau, nên lại nói thêm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Biết đâu sau này vẫn còn cơ hội hợp tác với Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ gật đầu. Ngồi bên giường bệnh, cô nhìn màn hình chiếu rồi hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Máy chiếu dùng có ổn không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Khá ổn, hình ảnh rất rõ. Cảm ơn Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có gì." Lâm Nhược Đường nói, —"Viết cho tôi một bản phản hồi của khách hàng đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phản hồi của khách hàng?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Gần đây Lâm Thái đang bàn chuyện hợp tác với MOOM, cần một bản phản hồi sau khi khách hàng sử dụng phản hồi. Tôi thấy cô ở bệnh viện cũng không có việc gì, giúp tôi việc này được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Hóa ra đưa máy chiếu cho nàng dùng là vì mục đích này? Chà!!! Đúng là nhà tư bản.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Lâm Nhược Đường đã giúp nàng nhiều như vậy, Thời Vụ cũng chẳng có lý do gì để từ chối, chỉ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi chưa từng viết."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao. Lát nữa tôi gửi cho cô bản mẫu tham khảo và số liệu, có gì không hiểu thì cứ hỏi tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Thời Vụ mới đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, vậy cô gửi cho tôi đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa dứt lời, Lâm Nhược Đường đã liên tiếp gửi sang cho nàng mấy tài liệu. Thời Vụ nhìn đến hoa cả mắt. Nàng cắn răng, trợn mắt nhìn, Lâm Nhược Đường thấy vậy liền hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ở đây không có máy tính sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Máy tính của tôi ở nhà." Nàng chợt nhớ ra điều gì, —"Nhưng Dư Mạt có máy tính."</p><p style="text-align: justify; margin-bottom: 0.9em">Tối nay Dư Mạt trực ca, nàng cũng không biết cô ấy có cần dùng đến máy tính hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô xem trước đi, tôi quay lại ngay."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ "ừ" một tiếng. Vừa ngẩng đầu lên, Lâm Nhược Đường đã đi mất. Không biết bao lâu sau, cửa phòng bệnh lại mở ra. Lâm Nhược Đường xách hai túi đựng máy tính bước vào, đưa một chiếc cho nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Máy tính trước đây tôi từng dùng, cô xem còn dùng được không."</p><p style="text-align: justify; margin-bottom: 0.9em">Đương nhiên là dùng được. Đồ Lâm Nhược Đường từng dùng thì có thể tệ đến đâu chứ? Quả nhiên, ngay cả tốc độ khởi động cũng nhanh hơn máy tính bình thường.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ dừng lại ở màn hình nhập mật khẩu, quay sang hỏi Lâm Nhược Đường. Cô đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"123456."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Đơn giản đến vậy, không sợ người khác lấy trộm máy tính sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nghi hoặc liếc nhìn Lâm Nhược Đường. Cô đang ngồi trên sofa, trước mặt cũng đặt một chiếc máy tính, có lẽ đang đánh chữ hoặc nhập dữ liệu gì đó, những ngón tay lướt nhanh trên bàn phím.</p><p style="text-align: justify; margin-bottom: 0.9em">Tốc độ tay rất nhanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thu ánh mắt lại, nhìn vào tài liệu trước mặt. Chỉ là một chiếc máy chiếu thôi, sao lại cần nhiều số liệu đến vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ riêng phần cải tiến độ phân giải đã viết đến hai trang. Thời Vụ đọc tài liệu tham khảo Lâm Nhược Đường gửi tới, càng đọc càng thấy đau đầu. Chuyên nghiệp quá mức, nhìn chẳng giống cảm nhận sau khi sử dụng do khách hàng viết, ngược lại còn giống một bản báo cáo phân tích hơn. Thời Vụ kéo xuống dưới, quả nhiên thấy một dãy tên kỹ sư.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">May mà trước đây trung tâm thương mại của Ưu Lạc cũng từng bán các thương hiệu máy chiếu, nàng và Ưu Lạc đã cùng thực hiện không ít hoạt động quảng bá. Thời Vụ mở toàn bộ tài liệu Lâm Nhược Đường gửi sang, lọc ra những từ khóa cần thiết, sau đó lên trang web chính thức tải một mẫu quảng bá về, bắt đầu tổng hợp số liệu.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây nàng từng nói Triệu Hy Ngọc bận đến mức chẳng nhận ra người thân, thật ra bản thân nàng cũng chẳng kém là bao.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay đầu nhìn Thời Vụ trên giường bệnh. Thấy nàng cúi mắt chăm chú nhìn máy tính, hai tay gõ trên bàn phím, ánh sáng từ màn hình hắt lên gương mặt nàng, trắng nhợt, lạnh lẽo. Thời Vụ hoàn toàn không nhận ra có người đang nhìn mình. Gặp chỗ không hiểu, nàng khẽ cau mày, vừa định lên Baidu tìm lại thông tin sản phẩm trước đây thì nghe Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chỗ nào không biết?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không ngẩng đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thông số dữ liệu của con chip này không đúng. Bên dưới là 4.6, bên trên lại ghi 4.1."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"4.6 là số liệu sau khi cập nhật, bên trên không ghi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay lại xem, chậm rãi lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có, tôi không..."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngẩng đầu lên. Chẳng biết Lâm Nhược Đường đã bước tới từ lúc nào, ngồi xuống bên giường, chăm chú nhìn màn hình. Thời Vụ đưa tay sờ mũi, khẽ dịch sang bên cạnh một chút. Ánh mắt Lâm Nhược Đường nhanh chóng lướt qua tài liệu rồi nói với nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Dùng 4.6."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không chút nghi ngờ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Khi nàng ngẩng đầu lần nữa, Lâm Nhược Đường đã rời đi, dường như sang đây chỉ để giúp nàng xem thông số đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng ngồi bên kia nói chẳng phải cũng được sao? Hay là muốn xem nàng có đọc nhầm hay không? Thời Vụ khẽ mím môi, tiếp tục sắp xếp những số liệu phía dưới. Trong phòng bệnh yên tĩnh, chỉ còn tiếng gõ bàn phím của hai người.</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng bao lâu sau, chỉ còn lại tiếng gõ phím từ một chiếc máy tính.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại quay đầu nhìn sang. Thời Vụ đã ngủ mất rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đặt chiếc máy tính đang để trên đầu gối sang một bên, khẽ vươn người. Cơn đau nhức ê ẩm như đàn kiến bò dần lan khắp cơ thể. Lâm Nhược Đường khẽ thở ra, đứng dậy đi đến bên giường Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đã ngủ, máy tính vẫn còn mở, đặt sang một bên. Lâm Nhược Đường đưa tay sờ trán nàng, không còn sốt. Cô lại dùng đầu ngón tay thăm dò bên tai Thời Vụ, mắt hơi rũ xuống. Nhìn thấy bàn tay Thời Vụ đặt cạnh máy tính, trên đó vẫn còn dấu kim. Mạch máu nàng nhỏ, vùng da nơi rút kim bầm tím một mảng, trông rất chói mắt. Lâm Nhược Đường khẽ nhíu mày, kéo chăn đắp cho nàng, rồi tiện tay cầm máy tính đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Màn hình vẫn chưa chuyển sang chế độ bảo vệ. Trên đó là bản phản hồi người dùng Thời Vụ mới làm được một nửa, viết rất nghiêm túc, rất tỉ mỉ, đúng với ấn tượng của Lâm Nhược Đường về nàng. Nội dung phản hồi được sắp xếp mạch lạc, ngay cả những biểu đồ phân tích dữ liệu phức tạp nhất cũng trình bày rõ ràng, ưu khuyết điểm vừa nhìn đã hiểu. Chỉ là một bản cảm nhận sau khi sử dụng, vậy mà Thời Vụ lại nghiêm túc đến thế.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không động vào gì cả. Sau khi giúp nàng lưu lại, cô đặt máy tính lên tủ đầu giường, rồi cúi đầu nhìn Thời Vụ lần nữa. Gương mặt nàng khi ngủ trắng trẻo, sạch sẽ, thỉnh thoảng lại khẽ ho một tiếng, hàng mày theo đó hơi nhíu lại. Lâm Nhược Đường đã ở lại phòng bệnh hơn hai tiếng. Đến ba giờ sáng, cô bước đến bên giường Thời Vụ, đo nhiệt độ cho nàng lần cuối. Thấy nhiệt độ đã bình thường, lúc này cô mới chuẩn bị rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi sắp ra khỏi cửa, cô chợt nhớ đến chuyện Thời Vụ từng nói mình không thích mấy bộ đồ lót kia, còn nói quần áo của nàng đang để trong tủ. Lâm Nhược Đường đi đến bên tủ, mở ra. Treo bên trong là chiếc túi màu đỏ kia, ngoài ba bộ đồ lót còn có thêm một bộ đã được giặt sạch, thoang thoảng mùi nước giặt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giặt sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghiêng đầu nhìn Thời Vụ đang nằm trên giường, nhét bộ đồ lót vào trong rồi mang cả túi đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong cơn mơ màng, Thời Vụ đưa tay sờ gối, chạm được điện thoại. Mấy ngày liền đảo lộn giờ giấc khiến nàng chẳng còn phân biệt nổi sáng tối. Điện thoại hiển thị năm giờ rưỡi.</p><p style="text-align: justify; margin-bottom: 0.9em">Năm giờ rưỡi, ngoài trời vẫn còn tối. Thời Vụ tỉnh lại khi đã hơn năm giờ rưỡi sáng. Nàng chậm rãi ngồi dậy, tựa bên giường, quay đầu nhìn ra ngoài cửa sổ. Chim chóc bay qua ngọn cây, tiếng hót líu ríu vọng lại. Nàng xuống giường vào nhà vệ sinh, rồi lại chui vào chăn. Mùi nước khử trùng nồng nặc đến khó chịu. Thời Vụ cứ thế lặng lẽ nhìn một lúc, chợt nhớ đến bản phản hồi người dùng tối qua mới làm được một nửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngồi dậy, mở máy tính, nhớ mang máng trước khi ngủ mình hình như chưa kịp lưu. Trong lòng vừa thoáng giật mình, nàng mở phần mềm ra thì phát hiện đã có người lưu giúp mình. Thời gian hiển thị là hơn mười hai giờ đêm hôm qua.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi ấy, hình như nàng đã ngủ rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lưu giúp nàng sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Không hổ là bà chủ, năng lực làm việc quả nhiên chẳng có gì để chê. Thời Vụ mở máy tính, tiếp tục làm việc. Lúc bác sĩ vào kiểm tra phòng, thấy vậy không khỏi kinh ngạc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Công việc gì mà bận thế? Bệnh rồi cũng không chịu nghỉ ngơi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười. Giọng nàng vẫn còn hơi khàn, mang theo chút trầm thấp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng lúc cũng chẳng có việc gì làm."</p><p style="text-align: justify; margin-bottom: 0.9em">Bác sĩ trêu nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Kính nghiệp thật đấy. Nhưng cô đang bệnh, vẫn nên nghỉ ngơi nhiều hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi tan ca, Dư Mạt cũng vội vàng chạy sang. Hơi thở còn chưa kịp ổn định đã hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối qua Triệu Hy Ngọc có đến không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ kinh ngạc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao cậu biết?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chị ta đến tìm tôi. Cũng mặt dày thật đấy, hỏi cậu nằm phòng bệnh nào. Tôi không nói, thế mà chị ta vẫn tìm được đến chỗ cậu à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tìm được đến đây rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt há hốc miệng:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chị ta nói gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không mở cửa."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng tốt. Đỡ phải gặp mặt rồi cãi nhau, vừa phiền vừa tốn sức. Bây giờ cậu không thể làm mấy chuyện hao tổn sức lực thế này."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe vậy, Thời Vụ bật cười, hàng mày cũng giãn ra. Dư Mạt liếc về phía đầu giường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Máy tính ở đâu ra vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">—"Của Lâm Nhược Đường." Thời Vụ nói, —"Cô ấy bảo tôi làm giúp một bản phản hồi của khách hàng."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhất thời chưa phản ứng kịp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Phản hồi gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Máy chiếu."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ồ!" Dư Mạt nói, —"Trên đời đúng là chẳng có bữa trưa nào miễn phí. Nhưng thế này cũng tốt. Hôm qua cậu còn nói nhận không mà lòng thấy hổ thẹn, giờ thì hiểu rồi chứ? Lâm Nhược Đường cũng đâu phải kẻ ngốc, sẽ không làm chuyện mua bán lỗ vốn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu, trong lòng quả thực nhẹ nhõm hơn nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Làm xong chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chưa. Lát nữa còn phải truyền nước, chắc không làm được, đợi truyền xong rồi làm tiếp."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vẫn không yên tâm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm nay thấy thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cử động người, giãn gân cốt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Khá ổn, không còn chỗ nào khó chịu nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Trận cảm này đến nhanh mà đi cũng nhanh. Buổi chiều, sau khi truyền xong chai nước cuối cùng, Thời Vụ thay lại quần áo của mình, rồi đặt mua một ít trái cây. Cuối cùng, nàng xách túi trái cây đến trước cửa phòng bệnh của Lâm Ngọc Phượng.</p><p style="text-align: justify; margin-bottom: 0.9em">Đứng trước cửa, nàng thoáng chần chừ. Đúng lúc một vệ sĩ đang đứng gác bước ra từ phòng bệnh bên cạnh, nàng vội lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chờ một chút, tôi muốn vào thăm Chủ tịch Lâm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng ngoài cửa, nghe bà cụ bên trong gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vào đi, vào đi, mau vào đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng xách trái cây, vuốt lại mái tóc, chỉnh trang quần áo rồi mới bước vào. Lâm Ngọc Phượng đang ngồi trên xe lăn, quay mặt về phía cửa sổ. Nghe động tĩnh, bà quay đầu lại. Vừa nhìn thấy Thời Vụ, bà đã nở nụ cười hiền hòa:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là cô Thời phải không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xin lỗi Chủ tịch Lâm, thật ra con nên đến thăm bà sớm hơn. Chỉ là hai hôm trước con vẫn luôn sốt và cảm, sợ lây cho bà nên đến tận bây giờ mới sang."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng chăm chú nhìn nàng. Cô gái trước mặt cao gầy, vừa mới khỏi bệnh nên giữa hai hàng mày vẫn còn vương chút yếu ớt. Dáng vẻ lại thanh tú, làn da trắng sạch, ngũ quan đoan chính tinh tế. Khi nói chuyện không nhanh không chậm, giọng điệu ôn hòa, chừng mực.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ta nhìn con quen mắt lắm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tết năm đó, con từng có duyên gặp bà một lần ở hội trường Thiểm Tây."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhớ lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ồ, ta nhớ ra rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Bà vẫn còn nhớ hôm ấy mình vội đi tìm đối tượng cho Lâm Nhược Đường, nhìn quanh một vòng, vừa hay thấy một cô gái mặc lễ phục trắng, liền hỏi người bên cạnh:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô gái kia là con nhà ai vậy? Trông thanh tú xinh xắn thật."</p><p style="text-align: justify; margin-bottom: 0.9em">Người bên cạnh nói với bà:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đó là phu nhân của Triệu tổng, Triệu tổng của Ưu Lạc."</p><p style="text-align: justify; margin-bottom: 0.9em">Bà có chút tiếc nuối:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó bà cũng dần quên mất chuyện này, không ngờ lúc này lại chợt nhớ ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sức khỏe của bà đã khá hơn chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bệnh tuổi già thôi, cũng chỉ vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ im lặng một lát. Lâm Ngọc Phượng lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ta nghe Nhược Đường nói, trước đây hai người từng gặp nhau ở Hà Kiều, quen biết từ khi đó sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giữ nguyên vẻ bình thản, đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng. Trước đây mẹ con từng đưa Lâm tổng về nhà, cô ấy ở nhà con mấy ngày."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhìn nàng, để ý cả thái độ lẫn giọng điệu. Khi nhắc đến Lâm Nhược Đường, Thời Vụ không hề có chút dao động nào, giọng nói vẫn bình thường như trước. Bà gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nói ra thì, chúng ta còn phải cảm ơn mẹ con."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ điềm đạm đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chủ tịch Lâm khách sáo rồi. Đổi lại là bất kỳ ai, mẹ con cũng sẽ làm như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng rất hài lòng, bà hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ta nghe nói gần đây con đang chuẩn bị ly hôn?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không phải người nổi tiếng, chuyện kết hôn hay ly hôn cũng chưa đến mức khiến cả Hưng Sư xôn xao, nhưng Lâm Ngọc Phượng biết chuyện này, nàng cũng không thấy lạ. Thời Vụ không né tránh, vẫn thản nhiên đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, gần đây con đang làm thủ tục ly hôn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôn nhân xảy ra vấn đề gì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có vài chuyện không thể dung hòa."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chỉ nói ngắn gọn, không oán trách, cũng không nói nửa lời không hay về Triệu Hy Ngọc. Tâm thế vẫn trầm ổn, chỉ có giữa hàng mày còn vương chút buồn nhạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng tán đồng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không hợp thì sớm chia tay cũng tốt. Trên đời này thứ không thiếu nhất chính là người, sau này tìm một người hợp với mình là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn Lâm Ngọc Phượng, khẽ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn Chủ tịch Lâm đã thấu hiểu."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có gì mà không thông cảm được. Ta sống đến từng này tuổi, cũng đã là người gần đất xa trời rồi, còn chuyện gì mà không hiểu. Biết đâu suy nghĩ của ta còn khác người hơn con tưởng ấy chứ ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười, lần này là thật sự cười. Người nhà họ Lâm quả thực đều khá thú vị.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngoại trừ Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Thời, ta gọi con như vậy được chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thoáng ngẩn ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đương nhiên là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Thời à, trước đây Nhược Đường ở nhà con, chắc hẳn đã gây cho gia đình không ít bất tiện. Thật xin lỗi, là chúng ta thất lễ, đến giờ vẫn chưa đến thăm mẹ con."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chủ tịch Lâm không cần khách sáo như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nếu không chê, cứ gọi ta là bà nội đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại, hé môi. Dưới ánh mắt đầy mong đợi của Lâm Ngọc Phượng, nàng đành đổi cách xưng hô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà... bà nội."</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt Lâm Ngọc Phượng dịu hẳn xuống. Bà nhìn Thời Vụ, ánh mắt chẳng khác nào khi nhìn một hậu bối trong nhà:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chuyện nhà con, ta cũng nghe qua rồi. Đừng buồn. Nếu có chuyện gì cần giúp, cứ tìm ta, hoặc tìm Nhược Đường. Không cần phải ngại mở lời."</p><p style="text-align: justify; margin-bottom: 0.9em">Trong lòng Thời Vụ dâng lên một chút ấm áp. Nàng nói với Lâm Ngọc Phượng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật ra gần đây Lâm tổng đã giúp con rất nhiều. Con rất cảm kích cô ấy, cũng rất cảm ơn bà."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng thở phào nhẹ nhõm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Con bé giúp con là chuyện nên làm. Làm người vốn nên như vậy, không cần để trong lòng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khẽ gật đầu, không tranh luận thêm.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm nay con xuất viện sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng, hôm nay xuất viện.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy hiện giờ con đang ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hiện giờ con sống cùng một người bạn. Cậu ấy làm việc ở bệnh viện, nên con ở ngay gần đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy thì tốt, có bạn bè chăm sóc lẫn nhau. Đường Đường từ nhỏ đã không có mấy người bạn, cũng không biết phải hòa hợp với bạn bè thế nào, khiến ta lo muốn chết."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe vậy, Thời Vụ không hề bất ngờ. Lâm Nhược Đường làm việc quá tùy ý, tính tình ngông nghênh lại chẳng chút kiêng dè, hoàn toàn không để tâm đến cảm nhận của người khác. Có bạn mới là chuyện lạ. Nhưng bên cạnh cô hẳn không thiếu người chỉ cần cô lên tiếng liền tranh nhau tiến tới muốn kết bạn.</p><p style="text-align: justify; margin-bottom: 0.9em">Vì phép lịch sự, Thời Vụ vẫn nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật ra Lâm tổng rất tốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng khẽ bật cười, dường như đã nhìn thấu lời nói không thật lòng của nàng. Mặt Thời Vụ hơi đỏ, ánh mắt dừng nơi mũi giày. Đúng lúc ấy, có người gõ cửa. Một y tá mở cửa bước vào, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chủ tịch Lâm, bữa tối vẫn chuẩn bị như hôm qua sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ truyền nước xong vào khoảng bốn giờ rưỡi. Tắm rửa, thay quần áo mất hơn nửa giờ, lại trò chuyện với Lâm Ngọc Phượng lâu như vậy, cũng đã gần đến giờ ăn tối. Nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà, vậy con xin phép về trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về làm gì? Không muốn ăn tối cùng một bà già như ta sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không có ý đó, liền lắc đầu. Lâm Ngọc Phượng cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy thì ở lại ăn với ta một bữa cơm đơn giản, được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy làm phiền bà rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phiền. Bình thường cũng chẳng có mấy người, đông vui một chút càng tốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, bà lấy điện thoại ra gọi thẳng cho Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đường Đường, tối nay có đến ăn cơm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sắp đến rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng khẽ ồ một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm Châu đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tối nay em ấy có việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng cúp máy rồi nói với y tá:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chuẩn bị ba phần cơm tối."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường sắp tới sao? Thời Vụ vốn chỉ đến thăm Lâm Ngọc Phượng, chưa hề chào hỏi Lâm Nhược Đường. Giờ nghe nói cô sắp qua, nàng bỗng thấy đứng ngồi không yên. Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Thời, con có thể đỡ ta vào nhà vệ sinh không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không còn tâm trí nghĩ ngợi lung tung, hai tay đỡ lấy Lâm Ngọc Phượng, đưa bà đến trước cửa nhà vệ sinh. Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đứng chờ bên ngoài.</p><p style="text-align: justify; margin-bottom: 0.9em">Khả năng cách âm ở đây rất tốt, bên trong không vọng ra chút tiếng động nào. Trái lại, phía sau lại vang lên tiếng bước chân, là âm thanh của giày cao gót. Thời Vụ phát hiện Lâm Nhược Đường rất thích đi giày cao gót, đủ kiểu dáng, đủ độ cao. Nghĩ cũng thật kỳ lạ, nàng có thể nhận ra tiếng bước chân của Lâm Nhược Đường. Lẽ nào thính giác của nàng thật sự nhạy bén đến vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa mở ra. Khi nhìn thấy nàng, Lâm Nhược Đường hiếm khi để lộ vẻ ngạc nhiên. Nhưng chỉ hai giây sau, cô đã trở lại bình thường, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trong nhà vệ sinh."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô đứng đó làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe giọng cô có vẻ không vui, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chờ bà ra."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe thấy cách xưng hô của nàng, Lâm Nhược Đường nhướng mắt nhìn. Cửa nhà vệ sinh mở ra, Lâm Ngọc Phượng bước ra ngoài. Nhìn thấy Lâm Nhược Đường, bà mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đường Đường đến rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ có thể cảm nhận rõ sự thân thiết trong nụ cười ấy. Nếu nụ cười của Lâm Ngọc Phượng dành cho nàng mang theo đôi phần khách sáo và lễ độ, thì với Lâm Nhược Đường lại là sự yêu thương không hề che giấu. Lâm Nhược Đường đi đến phía bên kia của Lâm Ngọc Phượng, đỡ lấy bà rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có người ở đây mà bà cũng không nói với con."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chẳng phải con nói Tiểu Thời là bạn của con sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng vậy, là bạn. Phải không, Tiểu Thời?"</p><p style="text-align: justify; margin-bottom: 0.9em">Toàn thân Thời Vụ như dựng hết lông tơ. Đang yên đang lành, cô gọi nàng là Tiểu Thời làm gì? Đúng là không có chuyện cũng tự tìm chuyện. Thời Vụ gượng cười, cắn răng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Lâm tổng nói đúng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng hỏi cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm nay tan làm sớm vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Gần đây không có việc gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nghỉ ngơi một chút cũng tốt. Hôm nay có canh sườn, hôm qua con nói muốn uống nên hôm nay ta lại bảo người ta chuẩn bị."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vâng."</p><p style="text-align: justify; margin-bottom: 0.9em">Ngoan ngoãn như vậy, hoàn toàn không giống Lâm Nhược Đường mà nàng quen biết. Lâm Nhược Đường đỡ Lâm Ngọc Phượng ngồi xuống bên giường bệnh rồi hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bản phản hồi ấy do một mình cô làm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng nhìn sang cô. Lâm Nhược Đường giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bà, con đang nói với cô ấy một chút chuyện công việc."</p><p style="text-align: justify; margin-bottom: 0.9em">Thế là Thời Vụ bị cho ra ngoài. Nàng ngồi xuống chiếc ghế cạnh bàn trà cách giường bệnh không xa. Lâm Nhược Đường mở máy tính lên, nghe Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là tôi làm một mình. Sao vậy? Có số liệu nào không đúng sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không, cô làm rất tốt. Số liệu rất chính xác, trình bày cũng rõ ràng."</p><p style="text-align: justify; margin-bottom: 0.9em">Được cô khen khiến Thời Vụ hơi ngượng ngùng, vừa định cười thì Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đưa mã nhận tiền cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sững lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mã nhận tiền?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô làm việc không lấy tiền sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chẳng phải chỉ là giúp một việc sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghiêm túc đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giúp đỡ cũng phải trả phí. Sao vậy, cô không trả phí tư vấn cho Diệp Lãnh Tinh à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có trả."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy là được rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lấy điện thoại trong túi ra, mở mã nhận tiền rồi đưa cho Lâm Nhược Đường. Điện thoại lập tức vang lên thông báo:</p><p style="text-align: justify; margin-bottom: 0.9em">【Alipay đã nhận 4.000 tệ.】</p><p style="text-align: justify; margin-bottom: 0.9em">Không khí bỗng trở nên yên lặng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không phải người thấy tiền là sáng mắt, nhưng vẫn không khỏi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhiều vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhiều sao? Phản hồi của khách hàng đều có mức giá này."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đâu phải không biết bản phản hồi của khách hàng là gì. Trung tâm thương mại cũng từng làm việc này. Thông thường họ chỉ cần đồng nghiệp bên bộ phận quảng bá viết một bản báo cáo, nếu được sử dụng thì thưởng năm trăm tệ. Vẻ kinh ngạc của Thời Vụ quá rõ ràng, Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô có biết mẫu quảng bá dùng để bàn giao sản phẩm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là mẫu dùng để quảng bá ra bên ngoài sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Là mẫu bàn giao nội bộ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng biết đôi chút. Mẫu quảng bá bàn giao nội bộ là tài liệu do công ty thương hiệu chuyển giao cho công ty quảng cáo. Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mỗi tháng Lâm Thái đều có sản phẩm mới ra mắt, cần một người có thể viết mẫu quảng bá bàn giao nội bộ. Cô có hứng thú không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngạc nhiên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Bản phản hồi cô viết lần này rất tốt, mạch suy nghĩ rõ ràng, vừa nhìn đã hiểu, cách dùng từ cũng rất chặt chẽ. Tôi rất thích. Nếu cô muốn thử, tôi có thể đưa cho cô một sản phẩm mới. Làm xong thì gửi cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật ra hôm nay bên Cự Năng Hoàn Cầu đã liên lạc với tôi, muốn mời tôi đến phỏng vấn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không sao, cô có thể làm thêm."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, cô bổ sung:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mẫu quảng bá bàn giao nội bộ, mỗi bản ba mươi nghìn tệ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ kinh ngạc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải mười nghìn sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đó là giá thị trường, không phải giá của Lâm Thái."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tại sao giá của Lâm Thái lại cao như vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vì có tiền."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thật sự không phải người thấy tiền là sáng mắt, nhưng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi có thể thử."</p><p style="text-align: justify; margin-bottom: 0.9em">.....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả:</p><p style="text-align: justify; margin-bottom: 0.9em">Phát ngẫu nhiên một trăm hồng bao nhé?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: Tôi thật sự không phải người thấy tiền là sáng mắt, chỉ là cô ấy cho quá nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Hóa ra em thích tiền à, vậy thì dễ rồi. ....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời nhắn: Do dạo này mình bận quá nên không edit nhanh hơn được, mình sẽ ra thường xuyên hơn để mọi người có thể đón đọc. ❤️</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 36, 'Tức giận', '<p style="text-align: justify; margin-bottom: 0.9em">Nghề nhiều chẳng thiệt thân, huống chi Thời Vụ còn cần kiếm tiền. Sau khi Thời Ánh Xuân rời đi, nàng dựa vào số tiền bà để lại mà học xong đại học, còn khoản tiền bồi thường thì chưa từng động đến một đồng, vẫn luôn nằm nguyên trong tài khoản. Khi sửa sang căn nhà cũ, nàng từng nghĩ đến việc dùng số tiền ấy, nhưng cuối cùng vẫn lấy toàn bộ tiền tích góp được sau khi đi làm để sửa lại căn nhà một lượt.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau này kết hôn, mua nhà mới cũng phải sửa sang. Nàng không nỡ dùng đến khoản tiền bồi thường kia, xem đó như lời chúc phúc song thân để lại cho cuộc sống mới của mình. Chỉ tiếc nàng có mắt không tròng, đến cuối cùng ngay cả khoản tiền ấy cũng bị liên lụy. Vì vậy nàng đã nghĩ kỹ, đợi lần phân chia tài sản này kết thúc, nàng sẽ gửi lại tiền bồi thường vào tài khoản, không động đến nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Cho nên nàng cần làm việc, cần kiếm tiền.</p><p style="text-align: justify; margin-bottom: 0.9em">Bởi vậy, trước đề nghị của Lâm Nhược Đường, nàng quả thực có chút động lòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Bởi vì tiền nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Vào khoảnh khắc này, nàng đã hoàn toàn cảm nhận được sự hào phóng của Lâm tổng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe nàng đồng ý, Lâm Nhược Đường dường như không hề bất ngờ, chỉ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy tôi sẽ chuẩn bị một bản hợp đồng. Sau khi cô ký xong, tôi sẽ gửi tài liệu chi tiết về sản phẩm mới cho cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không ngờ giữa mình và Lâm Nhược Đường lại có ngày tồn tại quan hệ thuê mướn, thân phận thoắt cái đã thay đổi. May mà từ trước đến nay nàng vẫn luôn xem Lâm Nhược Đường là Lâm tổng cao cao tại thượng, tâm thế cũng chẳng cần thay đổi, chỉ là thái độ càng thêm cung kính:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng đang cúi đầu bằng ánh mắt có phần kỳ lạ, hơi ghé lại gần, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hôm qua đồ lót của tôi là cô giặt giúp sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không ngờ cô lại hỏi chuyện này, lập tức ngẩng đầu, đối diện với đôi mắt trong veo của Lâm Nhược Đường. Nàng cố nén cảm giác ngượng ngùng khi phải giặt đồ lót cho người khác, gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng, là tôi giặt."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giặt tay?"</p><p style="text-align: justify; margin-bottom: 0.9em">Có cần phải hỏi rõ đến vậy không?</p><p style="text-align: justify; margin-bottom: 0.9em">Giặt tay hay giặt máy, chẳng phải mặc lên cũng như nhau sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nén giận:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Giặt tay."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn, giặt rất sạch."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô vô tình đưa tay chỉnh cổ áo sơ mi, để lộ dây áo ngực màu đỏ. Thời Vụ vừa nhìn thấy liền dời mắt đi, một chút nóng ran âm thầm phủ lên gò má.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Ngọc Phượng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đường Đường, hai đứa nói chuyện gì vậy, nói xong chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngẩng đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xong rồi. Con chỉ nói hồi nhỏ cô ấy rất khéo tay."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Có ai giải thích như cô không?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cắn răng nén giận, ngoài mặt vẫn nở một nụ cười giả lã.</p><p style="text-align: justify; margin-bottom: 0.9em">Bữa tối sau đó cũng yên ổn trôi qua. Lâm Ngọc Phượng ăn khá thanh đạm, vừa hay hợp khẩu vị của Thời Vụ. Không ngờ Lâm Nhược Đường cũng ăn nhiều hơn mọi khi. Ăn xong, Thời Vụ không khỏi liếc nhìn cô. Trần Hy chẳng phải từng nói cô thích ăn cay sao? Đồ ăn thanh đạm thế này mà cũng ăn được hai bát cơm?</p><p style="text-align: justify; margin-bottom: 0.9em">Giờ này còn không sợ béo sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Không biết nghĩ đến chuyện gì, nàng bỗng khẽ bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhận ra ánh mắt của nàng, nghiêng đầu liếc sang. Thời Vụ lập tức thu lại ý cười, mím môi, cố giữ vẻ mặt lạnh nhạt như thường ngày.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tâm trạng có vẻ không tệ nhỉ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn Lâm tổng đã cho tôi một cơ hội kiếm tiền."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng hồi lâu, dường như đã nhìn thấu câu nói chẳng mấy thật lòng ấy, nhưng cũng không vạch trần, chỉ khẽ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chuyện nhỏ thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Tâm trạng tốt, ba chữ ấy vừa lọt vào tai, chút vui vẻ ban nãy của Thời Vụ lập tức tan biến.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau bữa cơm, Lâm Ngọc Phượng nói với Lâm Nhược Đường vài chuyện công việc. Thời Vụ nhân lúc ấy lên tiếng xin phép về trước.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về phòng bệnh đợi tôi một lát."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tưởng cô còn có chuyện muốn nói với mình, bèn trở về phòng bệnh chờ. Trong lúc đợi, nàng lại kiểm tra tất cả đồ đạc từ trong ra ngoài một lượt. Vừa kiểm tra xong, ngoài cửa đã vang lên tiếng giày cao gót.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa phòng bệnh mở ra, Lâm Nhược Đường đứng ngoài cửa, nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thu dọn xong hết chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xong rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng còn chuyện gì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không có gì. Tôi đưa cô về."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thì ra là chuyện này. Thời Vụ có chút ngại ngùng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi tự về được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiện đường thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô khẽ hất cằm:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đi thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không tìm được lý do để từ chối. Đến cửa, nàng mới chợt nhớ ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, máy tính."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường liếc chiếc túi đựng máy tính trong tay nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô cứ dùng đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi có máy tính rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cứ xem như công ty cấp cho cô. Công việc cần dùng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Một lần nữa, nàng lại có nhận thức hoàn toàn mới về độ hào phóng của Lâm tổng. Rồi nàng chợt nghĩ, nếu thật sự đồng ý đến chỗ Lâm tổng làm việc, vậy tiền lương sẽ là bao nhiêu?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mải nghĩ đến thất thần, bước ra khỏi khu nội trú cũng chẳng để ý dưới chân có bậc thềm. Nàng bước hụt một chân, cả người chúi về phía trước, theo bản năng đưa tay túm lấy người bên cạnh, vừa khéo nắm trúng vạt áo của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cũng bị nàng kéo nghiêng người về phía trước, bả vai va vào người Thời Vụ. Cô khẽ rên một tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng vững lại, trên trán lập tức túa ra một lớp mồ hôi.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa rồi hình như nàng nghe thấy Lâm Nhược Đường kêu đau.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quả thật đang đau. Cô khẽ nhíu mày, định cử động mắt cá chân, nhưng cơn đau nhói bất chợt truyền tới khiến sắc mặt cô lập tức trắng bệch. Thời Vụ thấy vậy cũng tái mặt theo, vội đặt hết đồ đang cầm trên tay xuống, căng thẳng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, có phải cô bị trẹo chân rồi không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đau đến mức hạ thấp giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô nói xem?"</p><p style="text-align: justify; margin-bottom: 0.9em">Da đầu Thời Vụ tê rần:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xin lỗi, xin lỗi. Vừa rồi tôi không cố ý va vào cô đâu. Cô đừng cử động, đừng cử động."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nói, nàng vừa lấy từ trong túi ra một đôi dép bông mà Dư Mạt mang đến cho mình. Thời Vụ ngồi xổm xuống trước mặt Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô mang tạm đôi này trước đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Vốn đã bị trẹo chân, lại còn đi giày cao gót thế này, chẳng khác nào tự hành xác!</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn đôi dép trước mặt, vẫn chưa nhúc nhích. Thời Vụ một tay đỡ mắt cá chân cô, tay kia giúp cô cởi giày, sau đó xỏ dép vào chân cô. Đó là bên chân bị thương, không thể dùng sức. Đến lúc đổi sang chiếc còn lại, Lâm Nhược Đường mới lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đứng lên."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức đứng dậy. Lâm Nhược Đường đưa tay khoác lấy vai nàng, mượn sức nàng để đứng vững. Sau khi thay nốt chiếc dép còn lại, Thời Vụ cất đôi giày cao gót của cô vào túi, xách theo túi đựng giày, một tay đỡ eo Lâm Nhược Đường, chậm rãi dìu cô về phía bãi đỗ xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Từ xa, nàng đã nhìn thấy xe của Lâm Nhược Đường, còn có cả Trần Hy đang ngồi bên trong.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đang ngáp, vừa nhìn thấy Lâm Nhược Đường và Thời Vụ liền sững người mất mấy giây, sau đó vội xuống xe, ba bước thành hai đi tới bên họ. Thời Vụ thấy cô ấy đến thì thở phào, định giao Lâm Nhược Đường cho cô ấy đỡ. Không ngờ Trần Hy lại nhanh tay nhận lấy túi đựng giày và túi máy tính từ tay nàng trước.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đành tiếp tục dìu Lâm Nhược Đường trở lại xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đặt đồ xuống rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng bị sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trẹo chân rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có cần bác sĩ xem qua không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng lập tức nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đúng đấy, đang ở bệnh viện rồi, hay để bác sĩ kiểm tra một chút đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khéo léo từ chối:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về nhà xoa ít thuốc là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đã lên tiếng, Thời Vụ và Trần Hy cũng không nói thêm gì nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người ngồi ở hàng ghế sau.</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về nhà."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt nhận ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, nhà tôi ở ngay gần đây thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường quay đầu nhìn nàng. Bị cô nhìn đến khó hiểu, Thời Vụ bắt đầu nghi ngờ không biết mình vừa nói sai điều gì, hay trên mặt dính thứ gì đó. Nàng chần chừ gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Gây họa xong là muốn chạy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy siết chặt hai tay trên vô lăng, sống lưng lập tức thẳng tắp, hai tai cũng dựng lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu nhìn bên chân bị thương của Lâm Nhược Đường, lúc này mới hiểu ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không phải, ý tôi là tôi đi cùng cô đến gặp bác sĩ nhé?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không muốn đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy rốt cuộc cô muốn làm gì đây!!!</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy..."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đưa tôi về nhà trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là nên đưa Lâm Nhược Đường về trước. Dù sao cô bị thương cũng là do nàng. Thời Vụ không ngừng liếc xuống mắt cá chân Lâm Nhược Đường. Chẳng phải sưng rồi sao? Hình như còn đỏ lên nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi xe sắp đến biệt thự, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thư ký Trần, có thể dừng ở cửa hàng một lát không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nhìn sắc mặt Lâm Nhược Đường. Thấy cô khẽ gật đầu, Trần Hy mới đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, chờ một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Xe vừa dừng hẳn trước cổng, Thời Vụ lập tức xuống xe, chạy nhanh vào hiệu thuốc. Chẳng bao lâu sau nàng đã quay lại, trên tay xách một túi có in logo của hiệu thuốc. Nàng mỉm cười với Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn, đi được rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đạp ga, đưa họ đến trước cửa biệt thự.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ dặn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, thuốc này bôi lên chỗ trẹo chân rất hiệu quả. Trước đây tôi từng bị trẹo chân, cũng dùng loại này. Cô thử xem?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không nhận lấy, chỉ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô không xuống xe sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Xuống chứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Ý gì đây? Lâm Nhược Đường định bảo nàng tự bắt xe về sao? Cũng phải, chắc cô đang giận lắm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ xuống xe, lại nghe Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lại đây đỡ tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đi đến bên Lâm Nhược Đường, dìu cô vào biệt thự. Trần Hy xách theo những món đồ nàng mang từ bệnh viện về, cũng đi vào theo, nhưng chỉ dừng ở cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, Giám đốc Thời, tôi về trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Lâm Nhược Đường nhàn nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừ."</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa biệt thự khép lại. Thời Vụ dìu Lâm Nhược Đường ngồi xuống sofa. Sau một hồi tất bật, Lâm Nhược Đường duỗi thẳng bên chân bị thương, kê lên gối tựa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ở trên xe không nhìn nhầm, mắt cá chân cô quả thật đã sưng lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, cô nhớ phải bôi thuốc này."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ nhíu mày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô không bôi cho tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại hai giây:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi bôi cho cô?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi không với tới."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Chân có dài đến mức ấy đâu, sao có thể không với tới được? Hơn nửa là vẫn còn giận sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy để tôi bôi cho cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vừa nói vừa chuẩn bị mở lọ thuốc, Lâm Nhược Đường lại lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đợi đã, để tôi tắm xong rồi bôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nhiều chuyện thật!</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thầm càu nhàu, ngoài mặt vẫn gượng cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đưa tay ra:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đỡ tôi đi tắm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu một hơi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chưa từng hầu người khác tắm bao giờ. Tuy thế này cũng chưa hẳn gọi là hầu tắm, nhưng Lâm Nhược Đường quả thật lắm chuyện, lúc thì bảo nàng chuẩn bị nước tắm, lúc lại bảo nàng lấy đồ ngủ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhíu mày:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chân cô thế này còn tắm được sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhấc chân lên là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thoáng nghĩ đến tư thế ấy, vành tai bất giác đỏ lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường sao có thể nói chuyện ấy một cách đường hoàng, thản nhiên đến vậy chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quả thật không có cái khí thế làm bà chủ lớn, chẳng thể nào bình tĩnh được như cô. Trước đây Dư Mạt còn nói dạo này nàng đã chín chắn hơn nhiều, xem ra nàng thật sự nên học Lâm Nhược Đường một chút, có gặp chuyện cũng phải giữ được vẻ mặt không đổi sắc.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nước chuẩn bị xong chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm, xong rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô không ra ngoài à? Muốn giúp tôi cởi quần áo sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ra, tôi ra ngay."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng bước ra khỏi phòng tắm, hít sâu hai hơi mới miễn cưỡng bình tâm lại. Không biết đã qua bao lâu, nàng nghe tiếng Lâm Nhược Đường gọi từ bên trong:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vò tóc, lạnh mặt mở cửa bước vào.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đang ngồi trên ghế, trên người mặc đồ ngủ màu trắng. Không rõ là chất liệu gì, có lẽ không phải cotton, mềm mại hơn một chút, nhưng lại không lạnh như lụa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ dìu cô ra khỏi phòng tắm, cuối cùng vẫn không nhịn được:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô có thể đừng gọi tôi là Tiểu Thời được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghiêng đầu. Một chân cô bước đi, chân còn lại nhấc lên, nửa người dựa vào nàng. Thời Vụ cúi đầu chú ý dưới chân nên không nhận ra ánh mắt Lâm Nhược Đường đang nhìn sang. Nàng hơi mím môi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nghe hơi kỳ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Kỳ chỗ nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhất thời không nói nên lời. Lâm Nhược Đường hỏi đến tận cùng như vậy, ai mà đỡ nổi. Nàng bèn hỏi ngược lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy tôi gọi cô là Đường Đường, cô không thấy kỳ sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chắc chắn cô sẽ không chịu nổi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại thản nhiên:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không thấy. Nếu cô muốn gọi như vậy thì cứ gọi đi."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi!"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghẹn một hơi trong lồng ngực, cứng giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy tôi cứ gọi cô là Đường Đường."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ung dung mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tùy cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Sao cô lại dầu muối không ăn thế này chứ? Thời Vụ thật sự hết cách. Lâm Nhược Đường ngồi xuống sofa, gác chân lên gối ôm rồi ngẩng đầu gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ buột miệng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thật muốn tự tát mình một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thích nghi cũng nhanh đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười mà như không cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ha ha."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tôi khát, rót cho tôi cốc nước."</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ trẹo chân thôi mà, có yếu ớt đến vậy không? Lúc nàng sốt đến bốn mươi độ cũng chưa từng sai người khác hết việc này đến việc kia như Lâm Nhược Đường. Nhưng nghĩ đến chân cô bị thương là do mình, nàng đành nhịn xuống. Thời Vụ đứng dậy đi vào bếp, tìm một vòng rồi lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cốc của cô..."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa định hỏi, nàng im lặng hai giây, cố ý đổi cách gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đường Đường, cốc của cô đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Gọi thân mật đến thế, chắc Lâm Nhược Đường phải khó chịu lắm đây?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn qua khe cửa bếp, muốn xem biểu cảm của Lâm Nhược Đường, trong lòng không khỏi thất vọng. Sắc mặt cô chẳng hề thay đổi, chỉ quay đầu nhìn về phía bếp.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ còn tưởng mình nhìn lén bị phát hiện, vội đứng thẳng người.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trong tủ phía trên đầu cô. Cốc màu vàng là của tôi, cốc màu trắng cũng là của tôi, còn cốc màu xanh là lần trước cô đến đã dùng. Muốn uống nước thì dùng cái đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mở tủ, quả nhiên thấy một hàng cốc. Nàng lấy chiếc màu vàng ra, rót một cốc nước rồi trở lại phòng khách, đưa cho Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đưa một tay nhận lấy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Vẻ mặt Thời Vụ có chút méo mó.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"À, máy tính của tôi ở trong phòng, lấy giúp tôi một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ rất chu đáo hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô không tự vào phòng được sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đến mí mắt cũng chẳng buồn nhấc:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không được, đau chân."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lặng lẽ quay lại bếp, rót cho mình một cốc nước. Đúng lúc ấy, Lâm Nhược Đường ở ngoài phòng khách hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô làm gì đấy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lớn tiếng đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Uống nước!"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bật cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng là tính như pháo, chạm một chút đã bùng lên.</p><p style="text-align: justify; margin-bottom: 0.9em">Uống hết nước, Thời Vụ cũng bình tâm lại, đi vào phòng Lâm Nhược Đường lấy máy tính. Bên trong tối om, nàng tìm thấy công tắc đèn, lần tay trên tường một hồi mới bật được. Đèn vừa sáng, trên trần lập tức hiện ra cả một khoảng trời sao.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩng đầu nhìn thêm hai giây rồi tắt đi, sau đó bật công tắc bên cạnh. Lần này mới là đèn pha lê bình thường. Có điều trần sao vừa rồi quả thật rất đẹp.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vừa nghĩ vừa đưa mắt nhìn quanh. Căn phòng rất rộng, được chia làm hai phần, một bên là phòng ngủ, bên còn lại được bố trí như phòng làm việc. Máy tính đặt trên bàn phía phòng làm việc.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bước tới, rút dây nguồn rồi nhanh chóng mang máy tính trở lại bên Lâm Nhược Đường, đưa cho cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đang gọi điện thoại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ừm, gửi qua cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Máy tính vừa được đưa đến trước mặt, Lâm Nhược Đường ngước mắt nhìn Thời Vụ rồi nói vào điện thoại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cúp đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó cô nhận lấy máy tính, nói với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lát nữa tôi đưa hợp đồng cho cô, cô xem qua một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Khoảng hơn mười phút sau, từ phòng ngủ vang lên tiếng máy in chạy rè rè. Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vào lấy đi, hợp đồng của cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức đứng dậy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Vì vui, bước chân nàng cũng nhẹ hẳn đi. Chỉ vài bước đã vào đến phòng, lấy tập tài liệu vừa được in ra khỏi máy in rồi cúi đầu đọc nội dung hợp đồng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nếu có điều khoản nào muốn bổ sung, cô có thể viết thêm ở phía sau."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chăm chú đọc hợp đồng. Công việc nàng ký là quảng bá cho một dòng nước hoa, phải bàn giao bản thảo quảng bá cho Lâm Nhược Đường trước ngày mùng Mười tháng sau. Nội dung cần rõ ràng, làm nổi bật được đặc trưng của sản phẩm. Trong thời gian đó, nếu có chuyến công tác, nàng sẽ phải đi cùng để tiện tìm hiểu kỹ hơn những thông tin chi tiết về sản phẩm.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn chung hợp đồng không có vấn đề gì, các điều khoản nàng cũng hiểu được. Chỉ riêng chuyện phải đi công tác khiến Thời Vụ có chút băn khoăn. Nàng hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhất định phải đi cùng sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cố gắng thôi. Tôi sẽ báo cho cô trước hai ngày. Nếu thật sự không đi được, tôi sẽ bảo Trần Hy gửi toàn bộ nội dung cuộc họp cho cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Có thường xuyên phải đi công tác không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không nhất định. Có khi một tháng một lần, có khi ba tháng mới có một lần."</p><p style="text-align: justify; margin-bottom: 0.9em">Vậy thì cũng không nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ trầm ngâm. Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô mang hợp đồng về xem kỹ đi. Nếu không có vấn đề gì, ngày mai đến Lâm Thái tìm tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lại là ngày mai.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngày mai nàng còn không ít việc phải làm. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ngày mai tôi phải gặp người bên Cự Năng Hoàn Cầu trước. Nếu không có vấn đề gì, chiều mai tôi sẽ đến tìm cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô duỗi thẳng chân, đặt lên gối ôm. Thấy lúc này cô cũng không còn việc gì khác, Thời Vụ chủ động nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, để tôi bôi thuốc cho cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Bôi xong là nàng có thể về rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe nàng gọi mình như vậy, Lâm Nhược Đường nhướng mắt nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được, cảm ơn nhé, Tiểu Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng lấy tuýp thuốc mỡ trên bàn trà, mở nắp. Một mùi thuốc nhàn nhạt lập tức lan ra trong không khí. Tuy không đến mức hắc mũi, nhưng cũng chẳng dễ ngửi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cố nén xuống cơn giận trong lòng, lấy một ít thuốc trong suốt thoa lên mắt cá chân Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ vì đau, Lâm Nhược Đường khẽ dịch chân về phía trước để đổi tư thế, vô tình chạm ngay vào bụng dưới của Thời Vụ. Những ngón chân đang hơi dựng lên vừa vặn tì ngay phía trên bụng nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Sắc mặt Thời Vụ lập tức trở nên nghiêm túc. Nàng lặng lẽ dịch người ra sau, đưa tay chỉnh chân Lâm Nhược Đường lại cho ngay ngắn rồi cúi đầu tiếp tục bôi thuốc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng tỉ mỉ thoa quanh mắt cá chân cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm giác dưới đầu ngón tay mát lạnh. Đầu ngón tay Thời Vụ mềm mại, chậm rãi xoa thành từng vòng. Ánh mắt Lâm Nhược Đường lướt từ trên xuống, cuối cùng dừng lại nơi sống mũi và đôi môi mỏng của nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thỉnh thoảng Thời Vụ lại khẽ thổi lên chỗ bôi thuốc, để thuốc thấm nhanh hơn. Vùng da dưới những ngón tay xoa bóp dần nóng lên, ửng đỏ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đưa tay chạm thử, thấy hơi nóng.</p><p style="text-align: justify; margin-bottom: 0.9em">Kỳ lạ thật. Trước đây nàng từng dùng loại thuốc này, rõ ràng là có cảm giác mát lạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Sao lần này lại nóng đến vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhíu mày, chăm chú nhìn mắt cá chân cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm tổng, tình trạng của cô hình như không giống lần trước tôi bị. Hay là để bác sĩ xem thử?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu sáng mai cô không đi nổi, vậy tội của nàng lớn thật rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ nghiêng mắt nhìn xuống mắt cá chân:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mai rồi tính."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn không yên tâm, ánh mắt không rời khỏi chân cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Hay là tôi đổi sang loại thuốc khác bôi cho cô?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường vừa duỗi chân về phía nàng, Thời Vụ còn chưa kịp làm gì thì ngoài cửa bỗng vang lên một tiếng động. Cửa mở ra, Lâm Châu lê thân thể mệt mỏi bước vào nhà. Thấy phòng khách vẫn sáng đèn, cô nàng chớp mắt, vừa thay giày vừa nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, hôm nay chị không tăng ca à? Em nói chị nghe, cái tên đạo diễn bên chỗ bọn em đúng là đầu óc có vấn đề, cô ta cứ nhất quyết..."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu vừa ngẩng đầu lên, nhìn thấy hai người đang ngồi trên sofa, giọng nói lập tức im bặt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lên tiếng chào cô:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tiểu Châu, em về rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lúc này mới hoàn hồn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"À, ừm."</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người này đang làm gì vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Chân của chị cô sao còn đặt bên phía chị Thời Vụ?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu mở to mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em chợt nhớ ra túi của em vẫn còn ở trên xe."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, cô nàng lập tức quay người.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Quay lại."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu cứng đờ cả người, quay đầu lại, khó hiểu nhìn Lâm Nhược Đường. Cô không hiểu chị mình có ý gì, chẳng lẽ còn không hiểu ra là cô đang tạo cơ hội cho họ sao? Chị cô thế mà chẳng nhận ra à?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đưa cô ấy về."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nhìn sang Thời Vụ. Nàng vội đứng dậy:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đâu, tôi bắt xe về là được."</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị có thể ở lại đây mà."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa dứt lời, thấy cả Thời Vụ lẫn Lâm Nhược Đường đều nhìn mình, Lâm Châu mới "ồ" một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Ý em là cũng muộn rồi, nhà mình có phòng cho khách."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khéo léo từ chối:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Không cần đâu, cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này Lâm Châu mới gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Vậy được, để em đưa chị về."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Thật sự không cần đâu. Về đến nhà chị sẽ gọi cho em."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn Lâm Châu.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị gọi cho chị em đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nàng khổ sở nhăn mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Điện thoại em hỏng rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nghi ngờ, gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lại dặn:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Về đến nhà nhất định phải gọi đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Nhận ra sự quan tâm trong lời cô, Thời Vụ mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—" Chị biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Chỗ bắt taxi cách đó không xa, chỉ hơn mười phút là đến. Thời Vụ xách túi của mình đi ra ngoài. Lên xe, Lâm Châu đưa túi máy tính cho nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị em nói cái này là của chị."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đành nhận lấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Xe vừa đi khỏi, Lâm Châu lập tức chạy về nhà, ngồi xuống bên cạnh Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị, chuyện gì vậy? Sao chị Thời Vụ lại đến nhà mình? Hai người vừa rồi đang làm gì thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhấc chân lên. Lâm Châu nhăn mặt đầy ghét bỏ, đang định phủi ra thì Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chị bị trẹo chân, cô ấy đưa chị về."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu buông vai:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em còn tưởng......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhướng mắt, lạnh nhạt liếc cô nàng một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu lập tức làm vẻ mặt vô tội:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Em đi tìm....Đồ ăn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi trên taxi, cuối cùng cũng thở phào nhẹ nhõm. Nàng tựa vào cửa sổ xe suốt quãng đường về khu nhà. Xe dừng trước cổng, tài xế định giúp nàng xách đồ nhưng nàng khéo léo từ chối.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đang chuẩn bị đi vào khu nhà thì nghe phía sau có tiếng gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Dư Mạt!"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt quay đầu lại, trông thấy Thời Vụ thì khá bất ngờ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chẳng phải chiều nay cậu mới xuất viện sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Trước khi xuất viện tôi có ghé qua chỗ Chủ tịch Lâm, ăn tối cùng bà ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhận lấy một chiếc túi từ tay nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng phải, nhà họ Lâm đã giúp không ít. Tiền viện phí cậu chuyển cho Lâm Nhược Đường rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Chuyển rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cô ấy nhận à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Sao lại không nhận? Chính cậu nói mà, cô ấy đâu phải kẻ ngốc."</p><p style="text-align: justify; margin-bottom: 0.9em">Nhắc Tào Tháo, Tào Tháo tới. Thời Vụ vừa dứt lời, điện thoại đã báo có tin nhắn. Lâm Nhược Đường hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">【Về đến nhà chưa?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngoan ngoãn trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Vừa xuống xe.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được, mai gặp.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đang gõ chữ thì một tin nhắn khác lại tới.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tiểu Thời.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">—"......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhìn chằm chằm hai chữ ấy, ngọn lửa vô danh trong lòng lại âm ỉ bùng lên. Thời Vụ không trả lời Lâm Nhược Đường, nhét điện thoại vào túi, đi đến dưới tòa nhà mình. Cuối cùng vẫn không nhịn được, nàng nghiến răng mắng một câu:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Đồ đáng ghét !"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nghe thấy liền quay sang hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Mắng ai đấy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Lâm Nhược Đường. Đúng là chẳng hiểu nổi cô ấy. Bà nội cô ấy gọi tôi là Tiểu Thời thì đó là trưởng bối gọi hậu bối, còn cô ấy cứ nhất quyết gọi tôi là Tiểu Thời. Cô ấy không thấy kỳ quặc sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt phì cười:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Cũng kỳ thật. Tiểu Thời? Ha ha ha ha ha ha......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu một hơi.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt chọc vào má nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Nhưng nói thật nhé, Thời Vụ, lâu lắm rồi tôi mới thấy cậu như thế này."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Như thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">—"Tức giận."</p><p style="text-align: justify; margin-bottom: 0.9em">⸻</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả:</p><p style="text-align: justify; margin-bottom: 0.9em">Tùy cơ hội sẽ phát một trăm bao lì xì.</p><p style="text-align: justify; margin-bottom: 0.9em">Chúc mừng Lâm tổng đã mở khóa cách gọi thân mật đầu tiên dành cho Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: Nói như thể chẳng ai biết đặt biệt danh ấy. Tiểu Béo, chị nói xem có đúng không?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Ha ha.</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 36.1, 'THÔNG BÁO !', '<p style="text-align: justify; margin-bottom: 0.9em">📢 THÔNG BÁO CHỈNH SỬA TRA SOÁT NỘI DUNG ĐÃ EDIT TRONG 26 CHƯƠNG ĐẦU CỦA BỘ: ĐOẠT VỢ</p><p style="text-align: justify; margin-bottom: 0.9em">Vì mình sẽ đưa lên cả Website mới nên xin phép tạm ngưng edit truyện Đoạt Vợ của Ngư Sương trong một thời gian để rà soát và chỉnh sửa lại 26 chương đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong quá trình edit, mình phát hiện bản tiếng Trung mình nhận được có một số chỗ khác với bản chính thức trên Tấn Giang, dẫn đến không ít lỗi và chi tiết chưa chính xác trong bản edit hiện tại. Nếu không xử lý dứt điểm mà tiếp tục edit các chương sau, những sai sót này có thể gây khó hiểu, ảnh hưởng đến trải nghiệm của mọi người và bản thân mình cũng không thoải mái khi để bản truyện chưa được chỉn chu như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Vì thời gian cá nhân có hạn, mình đã nhờ một bạn tình nguyện hỗ trợ rà soát và chỉnh sửa lại các chương cũ. Tuy nhiên, bạn ấy cũng không có nhiều thời gian rảnh nên quá trình này có thể sẽ mất khá nhiều thời gian. Sau khi 26 chương đầu được kiểm tra và chỉnh sửa ổn thỏa, mình mới tiếp tục edit những chương tiếp theo.</p><p style="text-align: justify; margin-bottom: 0.9em">Mong mọi người kiên nhẫn chờ đợi và thông cảm cho sự gián đoạn này. Cảm ơn bạn tình nguyện viên đã giúp đỡ mình, đồng thời cảm ơn mọi người vì đã luôn theo dõi và ủng hộ truyện.</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 37, 'Có Thể', '<p style="text-align: justify; margin-bottom: 0.9em">Sao có thể không tức giận được? Chuyện giữa Triệu Hy Ngọc và Triệu Tinh, nàng đã tức giận không biết bao nhiêu lần. Mỗi lần cãi nhau với Triệu Hy Ngọc, nàng cũng đều mang theo cơn giận. Biết rõ những tính toán trong lòng Triệu Hy Ngọc, nàng lại càng giận không thể nguôi. Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không phải kiểu tức giận này."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhíu mày:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy còn có kiểu tức giận nào nữa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nói thế này đi. Cậu giận Triệu Hy Ngọc vì Chị ta đã làm chuyện chạm đến giới hạn của cậu, cho nên cậu mới tức giận. Vậy còn khi cậu giận Lâm Nhược Đường thì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bởi vì cô ấy..."</p><p style="text-align: justify; margin-bottom: 0.9em">Phiền thật! Đặc biệt phiền!</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừ, cậu sẽ đặc biệt tức giận với Lâm tổng vào khoảnh khắc đó, nhưng lại không thật sự để trong lòng, giống như đối với một người bạn vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng xem Lâm Nhược Đường như bạn bè sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ im lặng. Dư Mạt lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi thấy Lâm tổng cũng khá tốt. Bất kể cô ấy chăm sóc cậu có phải vì mẹ cậu hay không, ít nhất cô ấy thật sự đã quan tâm đến cậu. Quân tử xét việc chứ không xét lòng. Cô ấy hoàn toàn có thể coi cậu như người xa lạ. Chẳng ai thích để người khác nhìn thấy lúc mình chật vật nhất, nhưng Lâm tổng thì không. Cô ấy vẫn luôn chăm sóc cậu rất chu đáo. Vì vậy, tôi cảm thấy Lâm tổng thật sự xem cậu như một người bạn."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe Dư Mạt nói xong, Thời Vụ ngẫm kỹ lại. Lâm Nhược Đường đôi khi ăn nói không được dễ nghe, nhưng những việc cô ấy làm đều là vì muốn tốt cho nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Quả thật là xem nàng như một người bạn.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ là cô ấy quá kiêu ngạo.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lấy điện thoại từ trong túi ra. Vừa mở lên, màn hình vẫn dừng ở cuộc trò chuyện giữa nàng và Lâm Nhược Đường. Nàng nhìn chằm chằm hai chữ "mấy tiếng". Tuy trong lòng vẫn có chút không được tự nhiên, nhưng cũng không đến mức không thể chấp nhận. Thời Vụ ngoan ngoãn trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ngày mai gặp, Lâm tổng】</p><p style="text-align: justify; margin-bottom: 0.9em">Ngay khoảnh khắc nhận được tin nhắn, Lâm Nhược Đường khẽ nhướng mày, sau đó lập tức gọi điện tới. Thời Vụ sững người mất hai giây rồi mới bắt máy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, có chuyện gì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không có gì, tôi chỉ muốn xác nhận xem có đúng là cô không thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">"Cạch" một tiếng, cuộc gọi bị ngắt. Thời Vụ nhìn chằm chằm vào điện thoại, cơn giận vừa mới dằn xuống lại bốc lên ngùn ngụt. Nàng nghiến răng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đồ thần kinh!"</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa quay đầu lại, nàng thấy Dư Mạt đang nhìn mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không có gì, về nhà thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt bật cười khúc khích. Nụ cười ấy khiến Thời Vụ chẳng hiểu ra sao. Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bộ dạng tức giận vừa rồi của cậu trông giống hệt lúc trước cậu cãi nhau với mẹ mình, cậu còn nhớ không......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu, gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Dư Mạt."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đang nói dở thì quay đầu lại. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi đau đầu."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt lập tức căng thẳng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao lại đau đầu nữa rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi cũng không biết. Tôi muốn mau về nghỉ ngơi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt tiện tay xách túi đựng máy tính của nàng lên rồi kéo tay Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi đi đi, mau về nhà nằm nghỉ."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này cô ấy mới nhớ ra Thời Vụ là bệnh nhân vừa xuất viện. Dư Mạt theo nàng vào nhà, thu dọn bàn qua loa rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu muốn ăn gì không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không đói."</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng rồi nàng lại muốn ăn chút gì đó, bèn hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu muốn ăn đồ nướng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được thôi, nhưng cổ họng cậu không còn đau nữa à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chỉ mím môi một cái rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thôi bỏ đi, tôi đi tắm đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn theo bóng lưng nàng, khẽ bật cười. Gần đây Thời Vụ đã thay đổi rất nhiều, trở nên tươi tỉnh hơn hẳn bằng mắt thường cũng có thể nhận ra. Không biết có phải nhờ cú sốc ly hôn hay không; nếu vậy, Triệu Hy Ngọc cũng coi như đã làm được một chuyện tốt.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Thời Vụ bước ra khỏi phòng tắm, Dư Mạt đã gọi gà rán. Cô ấy gọi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lại ăn một chút đi, tôi không gọi cay."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi xuống sofa. Dư Mạt xé một chiếc đùi gà đưa cho nàng rồi bật tivi lên, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trước đây lúc nào cũng mong mình mau lớn. Lớn lên để làm gì chứ? Quần quật sống chết kiếm được chẳng bao nhiêu, còn không đủ trả tiền thuốc men, ngày nào cũng ôm một bụng tức."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nghe vậy, Thời Vụ liền hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lại bị trưởng khoa mắng à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hậm hực:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cậu nói xem đầu óc bà ta có bị úng nước không? Lúc xếp lịch chẳng phát hiện có vấn đề, bây giờ xếp sai lại chạy tới tìm tôi, trách tôi không nhắc bà ta. Tôi biết nhắc thế nào được? Tôi còn tưởng bà ta cố ý xếp như vậy. Chiều nay còn có một ca phẫu thuật, bệnh nhân đã hẹn với bà ta lúc ba giờ, thế mà bà ta lại quên mất ba giờ còn có ca phẫu thuật khác, rồi bắt tôi đi điều phối. Người bị bệnh nhân mắng là tôi, người bị khiếu nại cũng là tôi!"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt vung tay:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lãnh đạo chỉ giỏi đùn đẩy trách nhiệm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nhìn nàng, tức đến bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trước đây cậu cũng từng làm lãnh đạo đấy, còn gật đầu nữa à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy cậu cứ mắng tôi đi, mắng xong sẽ nguôi giận."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi mới không mắng cậu."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nghiêng người tựa vào Thời Vụ, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bé đáng thương nhà chúng ta đã đủ đáng thương rồi, ai mà nỡ mắng cậu chứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm nhận được hơi ấm và sự mềm mại của Dư Mạt khi tựa vào mình, Thời Vụ khẽ cong môi cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sáng mai mấy giờ cậu đến Cục Dân chính?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hẹn lúc chín giờ."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt gật đầu thật mạnh:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhất định phải mang theo đầy đủ mọi thứ, kiểm tra đi kiểm tra lại cho kỹ!"</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong vẫn chưa yên tâm, cô ấy lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hay ngày mai tôi xin nghỉ để đi cùng cậu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không cần đâu, luật sư Diệp sẽ đến đón tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Diệp Lãnh Tinh cũng đi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừm, cô ấy cũng đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy thì tốt, tôi yên tâm rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ấy quả thật đã yên tâm hơn. Một phần gà rán, Thời Vụ chỉ ăn một chiếc đùi, phần còn lại đều bị Dư Mạt chén sạch, sau đó cô ấy còn ăn thêm một bát mì ăn liền. Trước khi đi ngủ, Dư Mạt lại nghiêm túc hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tối nay có cần tôi ngủ cùng cậu không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khó hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngủ cùng tôi làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt gãi đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chỉ là muốn ở bên cậu thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Vẻ mặt Thời Vụ vẫn bình thản:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi ngủ đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Ngày nhận giấy đăng ký kết hôn là thứ Tư, thời tiết rất đẹp.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngày nhận giấy ly hôn lại là thứ Hai, trời mưa lất phất.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Thời Vụ bước ra khỏi phòng, nàng nhìn thấy bữa sáng Dư Mạt để lại trên bàn: hai chiếc bánh bao nhân thịt và một chai sữa đậu nành. Nàng đứng trước cửa sổ, vừa ăn xong thì Diệp Lãnh Tinh gọi điện, nói rằng đã đến cổng khu chung cư:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chờ tôi một lát."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, nàng xách túi, cầm ô ra khỏi nhà rồi nhanh chân đi thẳng tới cổng khu chung cư. Nhìn thấy một hàng xe đỗ ven đường, nàng vừa định kiểm tra biển số thì Diệp Lãnh Tinh mở cửa chiếc xe thể thao màu đỏ, gọi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— " Cô Thời ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại một thoáng rồi lập tức bước tới, lên xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sớm vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng đáp lại:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chào buổi sáng. Xe đẹp lắm."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh bật cười ha hả:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Xe của vợ tôi đấy, cô ấy thích sưu tầm xe thể thao."</p><p style="text-align: justify; margin-bottom: 0.9em">Sưu tầm xe thể thao — đúng là sở thích của người giàu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười có phần ngượng ngùng rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cảm ơn cô đã đến đón tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiện đường thôi. Ngày mưa xe cộ đông, tránh bị tắc ở đâu đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Quả thật xe rất đông, lại đúng vào giờ cao điểm buổi sáng. Trên đường đi, họ liên tục phải dừng rồi lại chạy, đến chín giờ mười phút mới tới Cục Dân chính. Từ xa, Thời Vụ đã nhìn thấy xe của Triệu Hy Ngọc. Diệp Lãnh Tinh cảm thán:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Triệu tổng đến khá sớm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không lên tiếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi xuống xe, Thời Vụ đi đến trước xe của Triệu Hy Ngọc. Nàng không biết người ngồi ở ghế lái là ai, bên trong chỉ có một mình Triệu Hy Ngọc, không có luật sư.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đó, Triệu Hy Ngọc đã bảo luật sư Trương soạn một bản thỏa thuận ly hôn. Căn nhà tân hôn cùng toàn bộ số tiền hai người dành dụm được trong mấy tháng sau khi kết hôn đều để lại cho Thời Vụ. Diệp Lãnh Tinh hỏi ý kiến nàng, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Quy căn nhà đó thành tiền đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao nàng cũng sẽ không quay lại căn nhà ấy nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Diệp Lãnh Tinh và luật sư Trương bàn bạc ổn thỏa, hai bên ký vào thỏa thuận cuối cùng rồi tiến hành công chứng.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc đã gầy đi rất nhiều. Chỉ trong vài ngày, cô không còn rạng rỡ, tươi tắn như trước. Dù quần áo vẫn phẳng phiu, lớp trang điểm vẫn không có chút khuyết điểm nào, nhưng dù sao Thời Vụ cũng từng sống cùng cô nên dễ dàng nhìn thấu vẻ mệt mỏi ẩn dưới lớp ngụy trang hoàn hảo ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Có đau lòng không?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không biết. Tâm trạng nàng rất phức tạp. Theo lý mà nói, nàng nên cầu mong Triệu Hy Ngọc sống thật tồi tệ, càng tồi tệ càng tốt. Nhưng lúc này, khi tận mắt nhìn thấy dáng vẻ tiều tụy của chị ấy, nàng lại cảm thấy đôi chút khó chịu.</p><p style="text-align: justify; margin-bottom: 0.9em">Dù sao cũng từng là người nàng yêu. Khi gặp lại, nàng vẫn mong đối phương có thể giữ được vẻ đàng hoàng, thể diện.</p><p style="text-align: justify; margin-bottom: 0.9em">Qua lớp cửa kính xe, Triệu Hy Ngọc nhìn thẳng vào Thời Vụ. Trong những ngày không có nàng, thế giới của cô dường như đã trở nên rối loạn, mọi thứ đều sai lệch.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô đã gọi cho Thời Vụ rất nhiều lần nhưng bị chặn. Sau khi đổi số mới, cô lại đột nhiên không dám gọi nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Biết nàng bị bệnh, Triệu Hy Ngọc tìm mọi cách dò hỏi số phòng bệnh, cuối cùng lại bị từ chối ngay ngoài cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Mấy ngày nay, cô sống trong trạng thái mơ mơ màng màng. Ngày nào cũng bận rộn, nhưng chính cô cũng không biết mình đang bận việc gì. Hễ rảnh rỗi lại trở về căn nhà tân hôn, nhìn căn nhà trống trải cùng căn phòng vẫn còn lưu lại hơi thở của Thời Vụ, cô bỗng nhớ nàng da diết.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc không mang ô, cứ đứng bên ngoài cửa xe như vậy. Mưa nhỏ rơi lất phất. Thời Vụ đưa chiếc ô còn lại cho cô, giọng điệu bình thản, ánh mắt xa lạ như đang nhìn một người dưng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vào trong thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nhận lấy chiếc ô nàng đưa, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trước đây vào mỗi buổi sáng, em đều thích nghe dự báo thời tiết. Hễ thời tiết không tốt, em luôn nhắc chị mang ô."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chỉ cười, không tỏ ý kiến gì. Triệu Hy Ngọc nhìn nàng rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cảm cúm đỡ hơn chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng điệu của cô vẫn dịu dàng như trước, tựa như hôm nay hai người không phải đến để ly hôn mà là để đăng ký kết hôn. Thời Vụ thoáng hoảng hốt trong chốc lát nhưng rất nhanh đã hoàn hồn, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đỡ rồi, cảm ơn Triệu tổng đã quan tâm."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhìn về phía cổng, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Phía sau, Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị hối hận rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu lại.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Vụ, chị hối hận rồi. Em có thể cho chị thêm một cơ hội nữa không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn vào mắt cô. Nàng đã từng rất thích quan sát sự thay đổi trong ánh mắt của Triệu Hy Ngọc, vậy nên lúc này mới không nhịn được mà bật cười. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hy Ngọc, điều chị hối hận không phải là đã đưa ra quyết định ấy. Điều chị hối hận là để em biết được chuyện này."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc siết chặt chiếc ô trong tay.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chị đã đưa ra lựa chọn của mình. Bây giờ, đến lượt em đưa ra lựa chọn."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng xoay người, quay lưng về phía Triệu Hy Ngọc, giọng nói nhẹ nhàng nhưng kiên quyết:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vào trong thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Không tranh cãi, không gào khóc, cũng chẳng có những tiếng nức nở đến xé lòng. Tình cảm giữa họ tựa như một cốc nước trắng, từng cuộn trào, từng sôi sục, từng nóng bỏng; giờ đây chỉ còn lại sự lạnh lẽo. Chỉ cần chạm nhẹ cũng cảm nhận được cái lạnh thấu xương. Triệu Hy Ngọc không đủ can đảm chạm vào, nhận giấy ly hôn xong liền vội vã rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Thời Vụ đến bãi đỗ xe, nàng thấy xe của Triệu Hy Ngọc vẫn còn ở đó. Triệu Hy Ngọc nhìn nàng qua kính chắn gió phía trước. Thời Vụ cúi đầu, theo Diệp Lãnh Tinh lên xe.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh hiểu ý nên không nói gì, chỉ vỗ nhẹ lên vai nàng. Thời Vụ quay đầu, siết giấy ly hôn trong tay rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cha mẹ chị ấy luôn không tán thành chuyện tôi và chị ấy kết hôn. Bây giờ nghĩ lại, quả nhiên một cuộc hôn nhân không nhận được lời chúc phúc từ gia đình sẽ chẳng thể bền lâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, nàng bật cười rồi quay sang hỏi Diệp Lãnh Tinh:</p><p style="text-align: justify; margin-bottom: 0.9em">— " Tôi nói như vậy có phải là đang trốn tránh trách nhiệm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh thấy vành mắt nàng hơi đỏ nhưng vẻ mặt vẫn khá bình tĩnh, bèn lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không tính. Đây là chúng ta được sống lại một lần nữa. Đi thôi, tôi đưa cô đi quậy một trận."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bây giờ sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh hỏi lại:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô còn có việc khác à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừm, tôi đã hẹn gặp một người ở quán cà phê Triều Đỉnh."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nghe vậy liền gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được, tôi đưa cô qua đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cảm ơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh xoay vô-lăng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Khách sáo gì chứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu. Điện thoại rung liên hồi, nàng lấy từ trong túi ra, thấy có mấy tin nhắn. Dư Mạt, Lâm Châu, thậm chí cả Kỳ Mai đều hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đã lấy được giấy ly hôn chưa?】</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng không ngờ lại có nhiều người quan tâm đến chuyện mình có ly hôn hay không như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không trả lời từng người mà hiếm khi đăng một bài lên vòng bạn bè. Nàng chụp giấy ly hôn rồi viết hai chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cũng tốt.】</p><p style="text-align: justify; margin-bottom: 0.9em">Chưa đầy hai phút sau khi đăng, WeChat của nàng hoàn toàn bùng nổ.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau này cuối cùng nàng cũng không cần phải giải thích với từng người về chuyện mình đã ly hôn nữa. Cũng tốt.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thở phào nhẹ nhõm rồi quay đầu nhìn ra ngoài cửa sổ. Cảnh quan cây xanh trên những con phố ở Cửu Xuyên quanh năm hầu như không có gì thay đổi, năm nay cũng không ngoại lệ. Giữa những mảng cây xanh điểm xuyết đầy hoa đỏ, trông có vẻ là hoa hồng. Nghe nói chúng nở suốt bốn mùa, rực rỡ và xinh đẹp.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đưa ngón tay phác theo hình dáng những bông hoa trên cửa kính. Chiếc xe lao vụt qua, nàng quay đầu lại, phong cảnh vẫn như cũ.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh đưa nàng đến trước cửa quán cà phê. Khi xuống xe, Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mấy hôm nữa tôi muốn mời cô và phu nhân dùng một bữa."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhưng cô phải báo trước thời gian cho tôi, tránh để lịch trình bị trùng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhất định rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng muốn nói lại thôi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chỉ là......"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nhìn nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có lẽ còn có Lâm tổng, Lâm Châu và một người bạn của tôi nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh tươi cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có gì đâu chứ? Vốn dĩ chỉ là bạn bè cùng nhau ăn một bữa, càng đông càng vui. Lần trước vợ tôi còn nói đã lâu không gặp Lâm tổng, muốn cùng nhau dùng một bữa. Vậy thì đúng lúc rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chợt hiểu ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh lại nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhưng cô đã nói chuyện này với Lâm tổng chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vẫn chưa. Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Diệp Lãnh Tinh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Người đó khá cầu kỳ trong chuyện ăn uống. Nguyên liệu phải ngon, không khí phải tốt, lại không thích ồn ào hay quá đông người. Cô ấy có rất nhiều thói quen khó chiều. Tôi nghĩ tốt nhất cô nên hỏi ý kiến cô ấy trước. Nếu cô ấy không có ý kiến thì chúng tôi cũng không có ý kiến."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thật sự không biết Lâm Nhược Đường lại có những thói quen này. Lần trước nàng còn đưa Lâm Nhược Đường đến một quán ăn nhỏ, chắc hẳn cô ấy đã phải chịu đựng lắm. Thời Vụ bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được, vậy chúng ta liên lạc lại sau."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đứng nhìn Diệp Lãnh Tinh lái xe rời đi. Vừa định quay người, một cái đầu bỗng ghé sát bên vai nàng, cất tiếng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đó là Diệp Lãnh Tinh sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giật nảy mình, quay đầu lại, thấy Hoàng Doanh đang nghển cổ nhìn theo chiếc xe thể thao vừa rời đi. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đúng, là luật sư Diệp. Cô Hoàng cũng biết cô ấy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Biết chứ, là bạn của cô à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Là luật sư đại diện cho vụ ly hôn của tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh nhìn nàng từ trên xuống dưới:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô mời được cô ấy bằng cách nào vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bị ánh mắt ấy nhìn đến ngẩn ngơ, Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Một người bạn giới thiệu."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Người bạn này của cô lợi hại thật đấy. Cô ấy nổi tiếng là người rất khó mời."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu. Hoàng Doanh nhiệt tình gọi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi đi đi, vào trong nói chuyện. Tôi thấy bài cô đăng trên vòng bạn bè rồi, lấy được giấy ly hôn rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Quả nhiên, bất cứ lúc nào thì chuyện hóng hớt cũng là cách tốt nhất để mở đầu câu chuyện.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừ, lấy được rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Khi nào cô có thể đi làm?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sớm nhất cũng phải đến cuối tháng."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi xin nghỉ việc vẫn cần một tháng để bàn giao. Nàng không giấu Hoàng Doanh. Hoàng Doanh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không vấn đề gì. Cuối tháng, trung tâm thương mại mới của chúng tôi cũng gần hoàn thiện. Trong thời gian này, nếu cô muốn đến xem thì tôi có thể đưa cô qua bất cứ lúc nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao đột nhiên lại phát triển khu Bắc vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh vẫn luôn mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đã hỏi thẳng như vậy thì tôi cũng không giấu nữa. Nửa cuối năm nay, khu Bắc sẽ có thay đổi rất lớn. Gần Dao Quan sẽ xây dựng hai khu đô thị đại học, dự kiến còn có ba phố thương mại. Lâm Giang cũng sẽ xây một sân bay, hiện đã bắt đầu lựa chọn địa điểm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ biết chuyện khu đô thị đại học, nhưng không ngờ nơi đó lại đột nhiên được chú trọng phát triển đến vậy. Nàng gật đầu. Hoàng Doanh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không chỉ trung tâm thương mại của chúng tôi, những nơi khác cũng đang rục rịch hành động. Điều may mắn là chúng tôi đã mua đất từ mấy năm trước nên sẽ hoàn thành khá sớm. Đương nhiên, nhanh tay nhất vẫn là Ưu Lạc. Triệu tổng quả thật rất có tầm nhìn."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Hy Ngọc lựa chọn mảnh đất ấy cũng vì gần khu đô thị đại học. Giờ vô tình lại trở thành một nước cờ đúng lúc.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Triệu tổng rất có năng lực."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh nhìn nàng, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi còn tưởng nhắc đến Triệu tổng sẽ khiến cô không vui."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nâng tách cà phê lên nhấp một ngụm rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đã qua rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh cùng nàng uống cà phê, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy thì chúng ta cùng nhìn về phía trước, cùng nhau cố gắng phát triển lớn mạnh. Đúng rồi, đây là mức lương và chế độ đãi ngộ, cô xem thử có điểm nào cần điều chỉnh không."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhận tập tài liệu Hoàng Doanh đưa rồi mở ra xem. Bên trong là một bản hợp đồng, ghi rất chi tiết về cơ cấu lương năm, sắp xếp công việc, chế độ nghỉ phép cùng nhiều nội dung khác. Tuy nhiên, nàng không lập tức đưa ra quyết định mà hỏi Hoàng Doanh:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi có thể mang về nghiên cứu thêm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đương nhiên không vấn đề gì. Cô cứ mang về xem kỹ. Cô cũng biết trước đây tôi đã muốn mời cô sang đây làm việc. Về chế độ đãi ngộ, tôi sẽ không để cô phải chịu thiệt."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi biết cô Hoàng luôn đối xử rất tốt với tôi, tôi cũng vô cùng cảm kích."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không cần cảm kích, đến làm việc là được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mấy hôm nữa rảnh rỗi, tôi muốn đến trung tâm thương mại xem thử."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bất cứ lúc nào cũng hoan nghênh."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, Thời Vụ lại trao đổi với cô ấy một vài chi tiết cụ thể trong công việc. Trước đây, nàng phụ trách quan hệ công chúng và truyền thông, nhưng ranh giới công việc giữa các bộ phận của Ưu Lạc không được phân chia quá rõ ràng. Thỉnh thoảng nàng cũng phụ trách cả công việc kêu gọi đầu tư, vì vậy việc hợp tác với Lâm Thái đều do một tay nàng thúc đẩy. Nội dung công việc này không hề xa lạ với nàng. Hoàng Doanh nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đã làm ở Ưu Lạc bốn năm, chắc hẳn cũng quen thuộc với nghiệp vụ của các bộ phận. Tôi sẽ không giới thiệu quá nhiều nữa. Có gì chưa rõ thì cứ hỏi tôi bất cứ lúc nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được, vậy chúng ta giữ liên lạc qua điện thoại."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh mỉm cười gọi nhân viên phục vụ đến thanh toán, nhưng được báo rằng Thời Vụ đã trả tiền. Cô nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lại khiến cô tốn kém rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sau này có khi tôi còn phải nhờ cô Hoàng quan tâm nhiều hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Hoàng Doanh hiểu được hàm ý trong lời nàng, cười nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đôi bên cùng giúp đỡ nhau."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô ấy rời đi. Hoàng Doanh nói mình phải tham gia một buổi triển lãm gì đó, còn hỏi nàng có muốn đi cùng không. Thời Vụ khéo léo từ chối.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong lúc trò chuyện với Hoàng Doanh, điện thoại nàng rung liên tục, lúc là tin nhắn, lúc lại là cuộc gọi. Nàng lấy ra xem, kéo xuống hai trang trong nhóm chat WeChat vẫn chưa thấy hết. Hóa ra quan hệ của nàng với mọi người tốt đến vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây, bất kể có thân thiết hay không, ai cũng hỏi nàng một câu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cô và Triệu tổng thật sự ly hôn rồi sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Còn có người hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đây là hoạt động ngày Cá tháng Tư à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Đáng tiếc, hôm nay không phải ngày 1 tháng 4, cũng chẳng phải trò đùa Cá tháng Tư.</p><p style="text-align: justify; margin-bottom: 0.9em">Trong nhóm nhỏ còn có người liên tục điên cuồng @ nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">【Thời Vụ, cô thật sự ly hôn với Triệu Hy Ngọc rồi sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi đã nói rồi, trong đám người có tiền chẳng có mấy ai tử tế.】</p><p style="text-align: justify; margin-bottom: 0.9em">【Chắc chắn là thật. Người có tính tình tốt như Thời Vụ còn bị ép đến mức phải ly hôn, nhà họ Triệu đúng là... chậc chậc chậc.】</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu nàng nhớ không lầm, nhóm chat này laf vì Lâm Nhược Đường mà lập ra. Khi ấy, ngày nào mọi người cũng cùng nhau ngồi chờ Lâm Thái, lâu dần đã gây dựng được tình đồng đội như cùng chung chiến tuyến. Thỉnh thoảng, họ còn báo cáo tiến độ của mình và tin tức mới nhất về Lâm Nhược Đường trong nhóm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đích thân lên tiếng xác nhận:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cảm ơn mọi người đã quan tâm, tôi thật sự ly hôn rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Một thành viên trong nhóm lập tức xuất hiện:</p><p style="text-align: justify; margin-bottom: 0.9em">【Thời Vụ! Cô xuất hiện rồi! Tôi còn tưởng cô không dùng tài khoản WeChat này nữa chứ.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không cần thiết.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thành viên nhóm:</p><p style="text-align: justify; margin-bottom: 0.9em">【Nhưng cô đã ly hôn rồi, còn làm ở Ưu Lạc làm gì nữa? Có muốn đến trung tâm thương mại của chúng tôi không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Tâm trạng Thời Vụ thoải mái hơn không ít:</p><p style="text-align: justify; margin-bottom: 0.9em">【Để tôi đến rồi chiếm mất vị trí của cô à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thành viên nhóm:</p><p style="text-align: justify; margin-bottom: 0.9em">【Cô có thể đến trung tâm thương mại mới của chúng tôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không đâu. Thủ tục nghỉ việc vẫn chưa hoàn tất, tôi ngại nhận lương mà không làm gì.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thành viên nhóm:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đáng tiếc thật! Cô còn nhớ lần trước chúng ta cùng Lâm Thái ngồi chờ người không? Khi ấy cô là người tích cực nhất. Triệu Hy Ngọc đúng là chẳng ra gì. Bây giờ ký được hợp đồng với Lâm Thái rồi thì liền đá cô ra khỏi công ty.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sững lại:</p><p style="text-align: justify; margin-bottom: 0.9em">【 Chị ấy ký hợp đồng với Lâm Thái rồi sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thành viên nhóm:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đúng vậy, ký vào chiều hôm qua. Cô không biết à?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thật sự không biết. Lâm Nhược Đường không nói với nàng. Nhưng cũng phải, tại sao Lâm Nhược Đường phải nói chuyện đó với nàng chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Thành viên nhóm:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ba thương hiệu sẽ vào hoạt động, Ưu Lạc đã giành thắng lợi ngay trận đầu.】</p><p style="text-align: justify; margin-bottom: 0.9em">Ba thương hiệu sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhớ rõ khi ấy hai bên đã bàn ít nhất là sáu thương hiệu. Chỉ có ba thì phải sắp xếp thế nào?</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ lại, chuyện đó còn liên quan gì đến nàng nữa đâu. Đúng là rảnh rỗi sinh nông nổi. Thời Vụ không tiếp tục trả lời trong nhóm mà kéo xuống tìm ảnh đại diện của Lâm Nhược Đường. Vì không muốn lần sau lại phải tìm kiếm phiền phức, nàng ghim cuộc trò chuyện với Lâm Nhược Đường lên đầu, tiện cho việc liên lạc sau này. Thời Vụ gửi cho Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi xong việc rồi, bây giờ cô qua đây sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Tin nhắn vừa gửi đi được hai, ba phút, Lâm Nhược Đường đã gọi điện tới, hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đã nói chuyện với phía Cự Năng Hoàn Cầu rồi à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừm, nói xong rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô định sang đó làm việc?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vẫn chưa quyết định. Tôi muốn đợi đến khi xem trung tâm thương mại rồi mới tính."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hờ hững hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bây giờ cô đang ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Quán cà phê Triều Đỉnh."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Quán ở trung tâm thành phố?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừm, đúng, ở trung tâm thành phố."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mười phút nữa ra ngoài."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vội nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi bắt xe qua đó."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không cần, tôi đang giải quyết công việc gần đây, mười phút là xong."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nuốt lại lời đang định nói rồi đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Biết rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cúp máy. Thời Vụ ngồi trong quán cà phê, nghĩ lát nữa Lâm Nhược Đường sẽ tới nên lại gọi thêm hai tách cà phê. Không biết Lâm Nhược Đường thích vị gì, nàng nhắn WeChat hỏi. Lâm Nhược Đường trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Nửa đường, không thêm sữa.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ồ, vậy còn Trần Hy thì sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường trả lời bằng một dấu chấm:</p><p style="text-align: justify; margin-bottom: 0.9em">【.】</p><p style="text-align: justify; margin-bottom: 0.9em">Ý gì đây? Nghĩa là gọi giống nhau sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu, nhưng cũng không dám hỏi thêm, đành gọi hai phần giống nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên ngoài, mưa nhỏ vẫn rơi tí tách. Thời Vụ nhìn giờ, đã gần mười một giờ. Chắc Lâm Nhược Đường vẫn chưa ăn cơm. Nàng có nên chuẩn bị bữa trưa không? Hay là đến chỗ Lâm Thái ăn? Nàng vẫn còn nợ Lâm Nhược Đường hai bữa cơm. Nhưng Diệp Lãnh Tinh nói Lâm Nhược Đường không thích nơi đông người. Thời Vụ ôm điện thoại, cau mày do dự. Sau nửa ngày, nàng vẫn lấy hết can đảm gửi tin nhắn:</p><p style="text-align: justify; margin-bottom: 0.9em">【Lâm tổng, hai hôm nữa tôi muốn mời cô dùng một bữa, không biết cô có tiện không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lần này, Lâm Nhược Đường trả lời bằng câu mà người bình thường cũng có thể hiểu được:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tiện.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chậm rãi gõ chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Còn có luật sư Diệp và phu nhân của cô ấy, Tiểu Châu và Dư Mạt.】</p><p style="text-align: justify; margin-bottom: 0.9em">Gửi xong, chính nàng cũng cảm thấy ngượng ngùng. Nếu Lâm Nhược Đường từ chối, vậy nàng sẽ mời riêng cô ấy vào hôm khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Điện thoại khẽ rung lên. Thời Vụ cúi đầu, màn hình hiển thị tin nhắn Lâm Nhược Đường vừa gửi:</p><p style="text-align: justify; margin-bottom: 0.9em">【Có thể.】</p><p style="text-align: justify; margin-bottom: 0.9em">Đồng ý rồi sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ấy thật sự đồng ý rồi?</p><p style="text-align: justify; margin-bottom: 0.9em">Dễ nói chuyện đến vậy ư?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không khỏi nghi ngờ rằng những lời Diệp Lãnh Tinh nói về việc Lâm Nhược Đường cầu kỳ trong chuyện ăn uống, yêu cầu nguyên liệu và không khí đều phải tốt, không thích ồn ào cũng chẳng thích đông người, hoàn toàn chỉ là để dọa nàng. Chẳng phải cô ấy rất dễ nói chuyện sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Vậy chúng ta hẹn ở Túy Tiên Lâu nhé?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được thôi .】</p><p style="text-align: justify; margin-bottom: 0.9em">.....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả:</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các tiểu thiên sứ đã tặng 12 phiếu Bá Vương và 513 chai dinh dưỡng~</p><p style="text-align: justify; margin-bottom: 0.9em">Tặng ngẫu nhiên 100 bao lì xì, moah moah.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: Cô ấy chẳng phải rất dễ nói chuyện sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Những người khác trong nhóm nhỏ: Cô sợ là đã quên trước đây tại sao chúng ta phải ngồi canh người rồi đấy. 🙄🙄🙄</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: ......</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 38, 'Bôi Thuốc', '<p style="text-align: justify; margin-bottom: 0.9em">Ngoài cửa kính xe, mưa nhỏ rơi thẳng xuống, đập vào kính xe và bệ cửa sổ, bắn lên những bọt nước li ti. Lâm Nhược Đường ngồi trong xe, xuyên qua kính chắn gió phía trước nhìn người phụ nữ đang ngồi trong quán cà phê.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mặc một bộ váy dài denim màu xám đậm gồm hai lớp. Bên trong là váy hai dây, bên ngoài khoác áo denim. Một hàng cúc nhỏ chỉ được cài hai chiếc. Khi nàng ngẩng đầu, chiếc cổ thon dài hiện ra. Mái tóc được tùy ý búi thành một búi tròn, vài sợi tóc mai rủ xuống hai bên, vừa chạm đến xương quai xanh, khiến đường nét nơi ấy như ẩn như hiện.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ trong chốc lát, đã có hai, ba người tiến tới xin phương thức liên lạc của nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lấy cớ điện thoại đang ở chỗ bạn, không thể dùng điện thoại, đành im lặng nhìn ly cà phê đã được đóng gói trước mặt. Không biết đã qua bao lâu, nàng nghiêng người về phía trước, đặt cằm lên bàn rồi thở dài.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngồi trong xe gọi điện cho nàng. Thời Vụ liếc nhìn những người xung quanh rồi mới bắt máy:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đang ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Không phải nói mười phút sao? Nàng cảm thấy đã hai mươi phút trôi qua rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trời mưa, tắc đường. Cô ra ngoài đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc này, Thời Vụ mới xách hai ly cà phê bước ra. Trần Hy mở cửa xe đi tới đón nàng. Thời Vụ thoáng nhìn thấy hôm nay Lâm Nhược Đường không lái chiếc Range Rover màu đen mà là một chiếc sedan màu xanh lam nhạt.</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng lẽ cô ấy cũng có sở thích sưu tầm xe giống vợ của Diệp Lãnh Tinh?</p><p style="text-align: justify; margin-bottom: 0.9em">Người có tiền đúng là vui thật.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đang cảm thán thì nghe Trần Hy hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đợi lâu rồi phải không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng cong môi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Dù sao tôi cũng không có việc gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nói, nàng vừa đưa ly cà phê cho Trần Hy. Trần Hy sửng sốt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cho tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừm, tôi không biết khẩu vị của cô nên gọi nửa đường, không thêm sữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy sau này đây chính là khẩu vị của tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bị cô ấy chọc cười. Hai người sóng vai trở lại bên xe. Trần Hy mở cửa ghế sau, Thời Vụ nhìn thấy Lâm Nhược Đường đang ngồi bên trong. Vẻ mặt Lâm Nhược Đường điềm tĩnh, cô nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lên xe."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khép ô lại rồi lên xe, đưa ly cà phê cho Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhấp một ngụm, hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thêm bao nhiêu đường?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nửa đường. Lâm tổng thấy đắng sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hơi ngọt."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy lần sau tôi sẽ cho ít hơn một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hờ hững "ừm" một tiếng. Thời Vụ nhớ đến cú ngã hôm qua, bèn hỏi cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, chân cô đỡ hơn chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng dùng khóe mắt liếc qua bắp chân của Lâm Nhược Đường. Hôm nay Lâm Nhược Đường không đi giày cao gót mà mang một đôi giày da nhỏ màu trắng. Trong xe tối, nàng không nhìn rõ mắt cá chân của cô. Lâm Nhược Đường đưa chân tới trước mặt nàng, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chưa đỡ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhận ra đâu chỉ là chưa đỡ, chỗ đó vẫn còn sưng, lại đỏ đến đáng sợ. Nàng hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đã đi khám bác sĩ chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Lâm Nhược Đường rất khẽ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cân nhắc một lúc. Sao nghe giọng cô có vẻ hơi ấm ức vậy? Chắc chắn là nàng nghe nhầm rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bác sĩ nói thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đã lấy thuốc, chỉ cần bôi đúng giờ là được. Điện thoại của cô đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lấy điện thoại từ trong túi ra, hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đặt vài báo thức: một giờ, bốn giờ, bảy giờ và mười giờ."</p><p style="text-align: justify; margin-bottom: 0.9em">Tay Thời Vụ phản ứng nhanh hơn đầu óc, nghe thấy những giờ ấy liền trực tiếp đặt báo thức. Đến cuối cùng nàng mới nhớ ra phải hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đây là giờ gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói như thể đó là chuyện đương nhiên:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Giờ tôi bôi thuốc. Cô phải nhắc tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩng mắt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi......"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không muốn chịu trách nhiệm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sửng sốt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không phải, tôi chịu trách nhiệm."</p><p style="text-align: justify; margin-bottom: 0.9em">Xét về tình hay lý, nàng đều không thể từ chối. Chân Lâm Nhược Đường bị thương là vì nàng, hơn nữa hiện giờ nàng còn muốn nhận việc làm thêm từ chỗ cô. Làm nhiều thêm một chút cũng chẳng có gì không tốt. Thời Vụ tự khuyên nhủ bản thân, rồi nghe Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô ăn trưa chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vẫn chưa. Lâm tổng ăn chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói với Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đến Tiểu Thái Viên."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vâng, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Tiểu Thái Viên, đó lại là nơi nào nữa đây?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tuân theo nguyên tắc không biết thì không nhiều lời, cứ thế yên lặng đi suốt quãng đường. Xe dừng vững trước cửa một nhà hàng riêng. Có lẽ Lâm Nhược Đường thường xuyên đến đây, ngay cả nhân viên phục vụ cũng nhận ra cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, phòng riêng đã chuẩn bị xong rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn quanh. Cách bài trí ở đây vô cùng tao nhã, mang vẻ cổ kính thanh nhã. Ngay giữa lối vào còn có hòn non bộ và dòng nước róc rách.</p><p style="text-align: justify; margin-bottom: 0.9em">Đây không phải đến để ăn cơm, mà là đến thưởng thức không khí.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây, khi dùng bữa với đại diện các nhãn hàng, Thời Vụ cũng từng tìm một số nhà hàng đặc sắc, nhưng không nơi nào đặc biệt bằng chỗ này. Lâm Nhược Đường hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhìn đủ chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thu hồi ánh mắt. Lâm Nhược Đường đưa tay khoác lên vai nàng, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đỡ tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Chân bị thương nặng như thể sắp gãy đến nơi rồi. Thời Vụ âm thầm than thở trong lòng nhưng ngoài mặt vẫn mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đỡ Lâm Nhược Đường, một tay ôm lấy eo cô. Khó khăn nhất là lúc lên cầu thang. Nàng rất muốn nhờ Trần Hy giúp một tay, nhưng Trần Hy lại đang nói chuyện với nhân viên phục vụ, hình như là gọi món. Thời Vụ bất đắc dĩ đành một mình dìu Lâm Nhược Đường lên tầng hai.</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Lâm Nhược Đường đi lại khó khăn như vậy, Thời Vụ nghi ngờ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, sáng nay cô có đến công ty không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không, tôi đến bệnh viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức cảm thấy vô cùng áy náy:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Xin lỗi, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng, dường như thở dài:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thôi bỏ đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ trước giờ vốn là người chỉ chịu mềm, không chịu cứng. Khi Lâm Nhược Đường tỏ thái độ lạnh nhạt với nàng, nàng ngược lại còn có thể vực dậy tinh thần. Nhưng bây giờ cô vừa tỏ ra yếu đuối, Thời Vụ lại càng thêm áy náy. Nàng dìu Lâm Nhược Đường vào phòng riêng.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên trong phảng phất hương đàn hương nhàn nhạt. Kết hợp với những món đồ nội thất mang vẻ cổ kính, nơi đây khiến người ta có cảm giác như xuyên không về thời xưa. Thời Vụ ngồi trên ghế gỗ. Trước mặt nàng là một chiếc bàn tròn được thêu hoa bằng chỉ vàng. Họa tiết trải trên mặt bàn tựa như một đóa hoa thật sống động. Thời Vụ không khỏi nghi ngờ đây chẳng phải món đồ cổ nào đó chứ.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa phòng riêng nhanh chóng vang lên tiếng gõ. Trần Hy bước vào, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, bắt đầu lên món được chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Món ăn không nhiều, khẩu phần cũng ít, mỗi lần chỉ mang lên hai món. Đầu tiên là món nguội. Cách bày biện vô cùng phô trương, vài miếng rau vốn chỉ đáng mấy đồng, đổi cách tạo hình liền có giá 288 hoặc 388 tệ. Thời Vụ vừa cảm thấy việc chế biến tinh tế đến mức này rất đáng khâm phục, vừa cảm thấy thật đắt đỏ.</p><p style="text-align: justify; margin-bottom: 0.9em">Đặc biệt là đĩa tôm hùm kia, giá hơn tám nghìn tệ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thịt còn chưa được tám miếng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mím môi. Lâm Nhược Đường hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không thích món ăn ở đây sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Hai nhân viên phục vụ đồng loạt nhìn sang.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thích, rất thích. Rất đặc sắc."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ nâng cằm:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nếm thử món tôm này đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gắp một miếng, nếm thử rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Rất tươi và ngọt."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôm vừa mới làm, thịt rất săn chắc. Thích thì ăn thêm hai miếng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu, nghe Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, Viễn tổng đã tới."</p><p style="text-align: justify; margin-bottom: 0.9em">Viễn tổng?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Viễn?</p><p style="text-align: justify; margin-bottom: 0.9em">Phó tổng của Lâm Thái.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đặt đũa xuống. Động tác nhẹ nhàng, mềm mại nhưng lại mang đến cảm giác áp bức vô hình. Thời Vụ thấy cô đứng dậy, một mình gắng sức đi về phía cửa.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa vừa mở, tiếng cười nói rôm rả bên ngoài lập tức im bặt. Đám người đang huyên náo cũng trở nên lặng ngắt khi nhìn thấy Lâm Nhược Đường. Cô nheo mắt cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trần tổng, Trương tổng, trùng hợp thật đấy. Hai người đang dùng bữa với cậu của tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Hai vị giám đốc bị cô gọi tên lập tức lắp bắp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng cũng dùng bữa ở đây sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thản nhiên đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đúng vậy. Nghe nói tôm hùm ở Tiểu Thái Viên không tệ nên tôi cùng bạn đến nếm thử."</p><p style="text-align: justify; margin-bottom: 0.9em">Khi nhìn thấy cô, sắc mặt Lâm Viễn lập tức sa sầm, nhưng vẫn cố nén cơn giận, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đã tới rồi mà cũng không nói với cậu một tiếng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con chỉ tụ họp với bạn bè thôi. Nghĩ đến chuyện cậu mở nhà hàng mới mà con vẫn chưa đến ủng hộ nên ghé qua xem thử. Không ngờ lại trùng hợp gặp được cậu ở đây. Nếu đã gặp nhau rồi, vậy cậu không thể lấy tiền của con đâu đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Viễn tức đến muốn chết nhưng vẫn phải cố nặn ra nụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đều là người một nhà, còn khách sáo như người ngoài làm gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu rồi nói với nhân viên phục vụ bên cạnh:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nghe thấy rồi chứ? Chi phí hôm nay, Viễn tổng thanh toán."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nhân viên phục vụ hơi run:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vâng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Viễn hừ một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi chợt nhớ ra mình còn chút việc, về công ty trước đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Hai vị giám đốc còn lại nhìn sang Lâm Nhược Đường, khóe miệng khẽ giật. Lâm Nhược Đường mỉm cười với họ, nhưng ánh mắt lạnh lẽo, sắc bén như gai nhọn. Cuối cùng, họ chỉ chào hỏi qua loa rồi xám xịt rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy Thời Vụ vẫn ngồi trong phòng riêng nhưng vì góc nhìn thuận lợi, nàng vừa hay nhìn thấy Lâm Nhược Đường đối phó với cả ba người. Cảm thấy kỳ lạ, nàng hỏi Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Họ là ai vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhà cung cấp vật liệu. Số vật liệu họ cung cấp tháng trước có vấn đề về chất lượng, tỷ lệ chiết khấu lại quá cao. Họ cứ liên tục thoái thác trách nhiệm, còn tưởng Lâm tổng không biết những chuyện mờ ám của họ. Một mặt họ lấy lòng Lâm tổng, mặt khác lại cấu kết với Viễn tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy bữa cơm hôm nay là do Lâm tổng cố ý sắp xếp sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nhìn Thời Vụ, không biết nên trả lời thế nào.</p><p style="text-align: justify; margin-bottom: 0.9em">Nếu Thời Vụ vẫn là vị giám đốc bộ phận từng chạy theo Lâm Nhược Đường như trước kia, cô ấy chắc chắn sẽ nói thẳng. Nhưng điều quan trọng là bây giờ người chạy theo Thời Vụ lại là Lâm Nhược Đường. Hơn nữa, sáng nay khi lướt vòng bạn bè, cô ấy còn giật nảy mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vậy mà đã ly hôn rồi!</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm tổng mới bắt đầu ra tay được bao lâu chứ? Vậy mà đã khiến cuộc hôn nhân của Thời Vụ tan vỡ. Thời Vụ và Triệu Hy Ngọc vốn là câu chuyện đẹp nổi tiếng trong giới. Hai người tự do yêu đương, Triệu Hy Ngọc còn bất chấp mọi sự phản đối của gia đình để kiên quyết kết hôn với Thời Vụ. Không ngờ Lâm tổng lại nhẹ nhàng khuấy một cái đã khiến họ tan đàn xẻ nghé.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy thật lòng khâm phục Lâm tổng.</p><p style="text-align: justify; margin-bottom: 0.9em">Đồng thời, cô ấy cũng không dám nhiều lời. Đối diện với câu hỏi của Thời Vụ, Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chắc không phải đâu. Có lẽ Lâm tổng chỉ muốn cô nếm thử món ăn của nhà họ. Nhà hàng này rất nổi tiếng ở Cửu Xuyên."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói sai trước mặt Lâm Nhược Đường sẽ có hậu quả gì, cô ấy hiểu rõ trong lòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nói sai trước mặt Thời Vụ sẽ có hậu quả gì, cô ấy lại càng thấp thỏm hơn.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe Trần Hy nói đỡ, Thời Vụ bật cười. Lâm Nhược Đường cũng quay trở lại chỗ ngồi, nghiêng đầu hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô nghe thấy những lời vừa rồi chưa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa rồi họ nói khá nhiều, Thời Vụ không biết cô đang nhắc đến câu nào, bèn hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nghe thấy gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có người thanh toán bữa này rồi, cô cứ ăn thỏa thích."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nói cứ như nàng là vua dạ dày không đáy vậy. Thời Vụ cười lạnh, quay đầu nói với nhân viên phục vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mang thêm ba con tôm hùm."</p><p style="text-align: justify; margin-bottom: 0.9em">Nhân viên phục vụ vừa định đáp lời thì Lâm Nhược Đường nói thêm:</p><p style="text-align: justify; margin-bottom: 0.9em">— " Hai con tôm hùm, thêm hai con cua."</p><p style="text-align: justify; margin-bottom: 0.9em">Đợi nhân viên phục vụ rời đi, Lâm Nhược Đường nghiêng đầu nói với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cua cũng vừa được vận chuyển bằng đường hàng không tới vào sáng nay, rất tươi. Hai người nếm thử đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy bị kéo theo một cách khó hiểu. Cô ấy ngồi thẳng người, ưỡn lưng, cung kính đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vâng, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Vẻ nghiêm túc ấy khiến Thời Vụ phải quay đầu nhìn cô ấy hết lần này đến lần khác, sau đó tự kiểm điểm xem có phải mình đã cư xử quá tùy tiện trước mặt Lâm Nhược Đường hay không.</p><p style="text-align: justify; margin-bottom: 0.9em">Có lẽ lời Dư Mạt đã vô thức in sâu vào đầu nàng, khiến nàng xem Lâm Nhược Đường như một người bạn. Nàng vô tình đánh đồng Lâm Nhược Đường hiện tại với cô nhóc mập mạp năm xưa, không còn giữ chừng mực như trước nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng ngồi thẳng người, vừa mới ưỡn lưng lên thì khuỷu tay của Lâm Nhược Đường vô tình chạm vào bên eo nàng. Tuy lực không mạnh, nhưng Thời Vụ không kịp đề phòng nên vẫn khẽ run lên:</p><p style="text-align: justify; margin-bottom: 0.9em">— "A......"</p><p style="text-align: justify; margin-bottom: 0.9em">Tay Trần Hy đang cầm đũa cũng run theo. Cô ấy vừa định ngồi thẳng người thì Lâm Nhược Đường liếc mắt sắc lạnh sang, khiến cô ấy lập tức ngồi ngay ngắn trở lại. Thời Vụ quay đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao cô lại đụng vào tôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tay vô tình chạm phải thôi, không cẩn thận."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy nàng lại chuẩn bị siết chặt eo, Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hai người cứ ăn trước đi, tôi ra ngoài nghe điện thoại."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra cô ấy có thể nghe điện thoại thay Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng cô ấy không dám nói, chỉ cúi đầu. Sau khi Lâm Nhược Đường rời đi, Trần Hy quay sang, mang theo cả bụng ấm ức. Nhưng vừa đối diện với gương mặt Thời Vụ, cô ấy lại nuốt hết những lời định nói trở về.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ than thở:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Điện thoại của cô ấy nhiều thật đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ha ha, đúng vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bình thường cô ấy cũng bận như thế sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bình thường Lâm tổng còn bận hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu. Tôm hùm và cua lần lượt được mang lên, bốn chiếc đĩa vừa khéo bày kín một bàn. Thời Vụ hỏi Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có cần đợi cô ấy không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chắc là không cần đâu, chúng ta cứ ăn trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Ý của Lâm tổng rõ ràng là muốn Thời Vụ ăn nhiều một chút. Trần Hy đã đi theo Lâm Nhược Đường lâu như vậy, chút tinh ý này đương nhiên vẫn có. Thời Vụ gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy cũng được."</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người không ăn hết tất cả, chỉ xử lý hết một con tôm hùm và một con cua. Khi Lâm Nhược Đường trở lại, nhìn thấy đồ ăn vẫn còn trên bàn, cô hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ăn no rồi thì đi thôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đứng dậy, hỏi cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô không ăn nữa sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi no rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt Thời Vụ vô thức nhìn về hai món vẫn chưa được động tới trên bàn. Lâm Nhược Đường mím môi, nói với nhân viên phục vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Gói lại."</p><p style="text-align: justify; margin-bottom: 0.9em">Nhân viên phục vụ bưng thức ăn ra ngoài. Lâm Nhược Đường chìa tay, gọi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lại đây đỡ tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi ăn xong bữa cơm này, Thời Vụ đã hoàn toàn tâm phục khẩu phục mà đỡ cô. Ngay cả khi Lâm Nhược Đường tựa vào người, nàng cũng không hề oán trách. Thậm chí vì sợ cô xuống cầu thang không tiện, nàng còn dang tay ôm ngang eo, để nửa người Lâm Nhược Đường tựa vào mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Sức nặng trên vai Thời Vụ đột nhiên tăng lên. Sợ làm Lâm Nhược Đường ngã, nàng càng siết chặt vòng tay, bàn tay ôm sát bên eo cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Phải công nhận, eo này thật sự rất thon, hoàn toàn không lưu lại chút dấu vết nào cho thấy cô từng mập.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây, lúc xem video, Thời Vụ từng thấy da của một số người sẽ trở nên chùng nhão sau khi giảm cân. Không biết Lâm Nhược Đường có như vậy không. Nàng cúi đầu, nghe Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đang sờ tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đi phía sau hai người bỗng loạng choạng, suýt nữa ngã từ cầu thang xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe thấy động tĩnh, Lâm Nhược Đường quay đầu liếc cô ấy. Trần Hy lập tức nghiêm mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, cầu thang trơn, ngài đi chậm một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vừa định rút bàn tay đang đặt bên eo Lâm Nhược Đường về thì bị cô kéo trở lại, ấn xuống eo mình. Lâm Nhược Đường quay đầu, thong thả nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thư ký Trần vừa nói cầu thang trơn, cô đỡ tôi cho chắc."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Đỡ thì đỡ!</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi đỡ Lâm Nhược Đường lên xe, Thời Vụ cảm thấy mình cần phải giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, vừa rồi tôi không sờ cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhướng mắt nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không sờ thì không sờ, nghiêm túc như vậy làm gì? Số tôm hùm gói lại hôm nay, cô có muốn mang về không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô còn chưa ăn mà."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi không thích ăn tôm hùm của nhà họ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhớ lại, vừa rồi Lâm Nhược Đường hình như đã nói nhà hàng này do Lâm Viễn mở. Quan hệ giữa hai người vô cùng tệ, cho nên cô mới ghét món ăn ở đây sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy Thời Vụ không lên tiếng, Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô không ăn thì vứt đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......Tôi ăn."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nói hai chữ ấy vô cùng khó khăn. Nhưng một phần tôm hùm có giá hơn tám nghìn tệ, cua cũng hơn sáu nghìn tệ, vứt đi thì quá đáng tiếc.</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra từ nhỏ, bất kể Thời Vụ muốn ăn gì, Thời Ánh Xuân và Thường Anh đều cố gắng đáp ứng nàng. Điều kiện duy nhất là không được quá lãng phí. Gia đình họ không quá giàu có nhưng đã dành cho nàng rất nhiều tình yêu, đồng thời cũng dạy nàng phải cần cù, tiết kiệm.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường thật sự quá lãng phí.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cô bằng ánh mắt trách móc.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường tựa vào ghế nghỉ ngơi. Khi xe sắp đến công ty, điện thoại Thời Vụ rung lên. Nàng còn tưởng có người gọi đến, lấy ra nhìn mới phát hiện là báo thức.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tắt báo thức rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, đến một giờ rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lát nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không lên tiếng. Xe chạy xuống tầng hầm B1, vừa dừng lại, Lâm Nhược Đường đã lấy một chiếc túi bên cạnh đưa cho Thời Vụ. Nàng ngơ ngác nhìn cô. Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thuốc ở bên trong."</p><p style="text-align: justify; margin-bottom: 0.9em">Lại muốn nàng bôi thuốc cho cô sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Người này được người khác phục vụ đến nghiện rồi à?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu. Trần Hy quay đầu nói với Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, tôi lên trước chuẩn bị tài liệu cho cuộc họp."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hờ hững đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừm."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy lại nhìn sang Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— " Cô Thời, tôi lên trước nhé."</p><p style="text-align: justify; margin-bottom: 0.9em">Người ta đã niềm nở như vậy thì nàng cũng không thể lạnh mặt đáp lại. Thời Vụ khẽ cong môi cười. Nhưng Trần Hy vừa rời đi, khóe môi nàng lập tức hạ xuống. Lâm Nhược Đường đặt chân lên hai đùi nàng, nhấc bàn chân lên rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bôi đi, lát nữa tôi còn phải lên họp."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhẫn nhịn hít thở, lấy từng chai từng lọ trong túi ra. Có ba chai thuốc nước và một tuýp thuốc mỡ. Nàng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bôi loại nào trước?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Từ chai lớn đến chai nhỏ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lấy chai lớn nhất, đổ thuốc nước lên bông gòn rồi ấn lên mắt cá chân Lâm Nhược Đường. Cô khẽ rít lên:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhẹ thôi, a..."</p><p style="text-align: justify; margin-bottom: 0.9em">Thái dương Thời Vụ giật mạnh, giọng nói cũng căng lên:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô có thể đừng kêu được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy cô nhẹ tay một chút."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhẹ quá thì thuốc không thấm vào được, sẽ không có tác dụng. Trong hướng dẫn ghi phải ấn xuống."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn vẻ mặt bực bội của nàng, khẽ cong môi. Cô miễn cưỡng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được rồi, tôi nhịn."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe tiếng cô khẽ rên, vành tai Thời Vụ ngứa ran.</p><p style="text-align: justify; margin-bottom: 0.9em">Người này kêu kiểu gì vậy chứ...</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vội vàng bôi thuốc xong, sau lưng đã túa mồ hôi. Vừa mở cửa xe, gió thổi lên mặt mát lạnh. Chẳng biết từ lúc nào trán nàng cũng đã lấm tấm mồ hôi. Lâm Nhược Đường còn hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô nóng lắm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cơ thể tôi yếu."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy phải bồi bổ nhiều hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ muốn trợn mắt nhưng cố nhịn xuống. Nàng xách túi, dìu Lâm Nhược Đường vào thang máy. May mà thang máy ở đây đi thẳng lên các tầng, suốt đường không gặp trở ngại gì.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi lên đến tầng hai mươi tám, cửa thang máy vừa mở, đã có người giúp họ mở sẵn cửa. Nhân viên lễ tân cũng không ngẩng đầu lên, thái độ vô cùng cung kính. Thời Vụ tiếp tục dìu Lâm Nhược Đường vào văn phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi ngồi xuống, Lâm Nhược Đường nhấn điện thoại nội bộ, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vào đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, cửa văn phòng vang lên tiếng gõ. Trần Hy nhỏ giọng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, ngài gọi tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cuộc họp đã chuẩn bị thế nào rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đã chuẩn bị xong."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đưa Thời Vụ sang đó họp."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vâng, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại dặn dò:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mẫu nội dung quảng bá của Nguyệt Ẩn sẽ do Thời Vụ phụ trách. Cô đưa cô ấy đi ký hợp đồng trước."</p><p style="text-align: justify; margin-bottom: 0.9em">Nói xong, cô hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không có vấn đề gì chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Quả thật Thời Vụ đến đây để ký hợp đồng, nhưng hiệu suất làm việc của Lâm Nhược Đường đúng là quá cao. Nàng gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không vấn đề gì."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đưa tay ra:</p><p style="text-align: justify; margin-bottom: 0.9em">— " Cô Thời, mời đi bên này."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đi theo sau cô ấy. Còn chưa bước ra khỏi văn phòng, Lâm Nhược Đường đã gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng theo phản xạ quay người lại, khựng một chút rồi cong môi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, còn chuyện gì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thuốc vừa rồi đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ở trên sofa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi làm việc đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ theo Trần Hy đến phòng nhân sự, thái dương khẽ giật. Chỉ hơn mười phút sau, nàng đã ký xong hợp đồng. Trần Hy đi bên cạnh nàng, giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lát nữa, cuộc họp chủ yếu sẽ tập trung vào việc phân tích nguyên liệu và tỷ lệ phối trộn của Nguyệt Ẩn. Cô có thể nghe thử. Nếu có chỗ nào không hiểu thì cứ hỏi tôi bất cứ lúc nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cảm kích:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được, tôi biết rồi. Tôi có thể ghi âm không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thật sự lo mình sẽ không hiểu. Dù sao đây cũng là lần đầu tiên nàng tiếp xúc với nước hoa, chắc chắn sẽ có một số thuật ngữ chuyên ngành mà nàng cần tra cứu tài liệu. Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có bản ghi âm chuyên dụng. Đợi cuộc họp kết thúc, tôi sẽ gửi cho cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không còn băn khoăn nữa:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cảm ơn thư ký Trần."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy vội đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô khách sáo rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thư ký Trần, sao cô còn khách sáo hơn cả tôi vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy mím môi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nên như vậy, nên như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô ấy hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy bây giờ chúng ta qua đó luôn nhé? Cô có cần nói với Lâm tổng một tiếng không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không cần đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cũng được."</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây, cô ấy từng nghe nói Thời Vụ phân biệt công tư rất rõ ràng. Xem ra đúng là như vậy. Trần Hy hiểu.</p><p style="text-align: justify; margin-bottom: 0.9em">Hai người cùng bước vào phòng họp. Quả nhiên đúng như Thời Vụ dự đoán, rất nhiều thuật ngữ chuyên ngành nàng hoàn toàn không hiểu. Nhưng Trần Hy vô cùng chu đáo, đưa cho nàng một bản nội dung cuộc họp bằng văn bản. Tuy vẫn có vài chỗ nàng không hiểu, nhưng nhờ tra cứu tài liệu và tìm kiếm trên Baidu, nàng cũng học được không ít.</p><p style="text-align: justify; margin-bottom: 0.9em">Không ai trong phòng họp cảm thấy kỳ lạ khi có thêm nàng. Đến lúc cuộc thảo luận trở nên gay gắt, một cô gái đứng dậy:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đã nói không cần tiếp tục dùng tỷ lệ phối trộn của Nguyệt Hạ nữa. Lần trước khách hàng đã ngửi ra rồi. Chỉ có lớp hương nổi là khác, còn hương nền lại giống nhau. Nguyệt Ẩn cần phải đổi mới!"</p><p style="text-align: justify; margin-bottom: 0.9em">Người đối diện cô gái không chịu nhượng bộ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trên thị trường có rất nhiều loại nước hoa dùng cùng một hương nền. Khách hàng lần trước của cô có gia đình chuyên sản xuất hương liệu, cô ta ngửi ra được một chút khác biệt cũng chẳng có gì lạ. Phần lớn mọi người đều không thể nhận ra."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô gái nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhưng cũng không thể làm qua loa cho xong!"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi không nói phải làm qua loa! Nhưng cô đã nghĩ đến việc thay đổi hương nền sẽ làm tăng thêm bao nhiêu chi phí chưa? Những hao tổn đó, cô chịu trách nhiệm sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghe họ tranh luận qua lại, đại khái hiểu được ý của hai bên. Nhưng nàng chỉ biết sơ qua về nước hoa nên không xen vào, chỉ yên lặng lắng nghe. Tuy nhiên, Trần Hy lại không định bỏ qua cho nàng, nhỏ giọng hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— " Cô Thời, cô thấy thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sửng sốt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy gật đầu, ánh mắt vẫn nhìn Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thành thật đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi không biết."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không sao, tham gia thêm vài lần sẽ hiểu. Vì cô phải viết mẫu nội dung quảng bá nên tốt nhất vẫn cần nắm rõ những số liệu này."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ làm một dấu OK.</p><p style="text-align: justify; margin-bottom: 0.9em">Cuộc họp kéo dài hơn hai tiếng. Hai bên vốn đối đầu gay gắt, đến nửa sau lại tranh luận về khả năng thay đổi hương nền, vừa phải ước tính chi phí, vừa phải phối chế lại từ đầu. Thời Vụ chăm chú lắng nghe.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi cuộc họp kết thúc, nàng vẫn đang ghi chép. Trần Hy vỗ nhẹ lên vai nàng, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Điện thoại."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lật điện thoại lại. Đó là báo thức lúc bốn giờ, cũng là giờ Lâm Nhược Đường phải bôi thuốc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng do dự rồi đứng dậy, định đến văn phòng của Lâm Nhược Đường. Sau đó, nàng chợt nhớ người bị thương là chân chứ không phải tay. Chỉ cần nhắc cô một tiếng là được, đâu nhất thiết phải đích thân sang đó?</p><p style="text-align: justify; margin-bottom: 0.9em">Nghĩ vậy, Thời Vụ lại ngồi xuống và nhắn tin cho Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Lâm tổng, đến giờ cô bôi thuốc rồi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Một lát sau, Lâm Nhược Đường trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ừm, qua đây.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn điện thoại, im lặng vài giây:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi vẫn đang ở phòng họp.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được, vậy tôi qua đó.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giật mình:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không cần, tôi qua chỗ cô.】 ...,</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả:</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các tiểu thiên sứ đã tặng 10 phiếu Bá Vương và 408 chai dung dịch dinh dưỡng~</p><p style="text-align: justify; margin-bottom: 0.9em">Tặng ngẫu nhiên 100 bao lì xì, moah moah.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Thứ tôi muốn, tôi nhất định phải có được.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: 🙄🙄🙄</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 39, 'Nhận Xét', '<p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngồi trên sofa trong văn phòng, trước mặt là một tách cà phê. Đối diện cô là một người phụ nữ. Người phụ nữ nhìn quanh văn phòng một lượt rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không tệ. Nghe nói tháng trước cháu vừa ký một hợp đồng lớn với Giang Hà?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhấp một ngụm cà phê, mỉm cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chỉ là cùng nhau nghiên cứu và phát triển mà thôi. Dì Triệu, mấy năm nay vất vả cho dì rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Diễm nhìn cô, ánh mắt dịu dàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Khi dì quen mẹ con, bà ấy còn nhỏ hơn con bây giờ vài tuổi. Con rất giống bà ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con không thể sánh với bà ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Diễm cảm thán:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con có bản lĩnh hơn bà ấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Năm ấy, khi Lâm Nhược Đường vừa tiếp quản Lâm Thái, những người thuộc các chi thứ luôn rình rập, còn liên kết với Triệu Diễm, định ép cô rời đi. Trong tình thế bất đắc dĩ, Lâm Nhược Đường đã nhờ Triệu Diễm phối hợp diễn một màn tương kế tựu kế, sau đó mượn tay Triệu Diễm đánh cho những người thuộc các chi thứ tan tác.</p><p style="text-align: justify; margin-bottom: 0.9em">Mấy năm nay, cô đã ngồi vững ở vị trí phó tổng. Lần này gọi Triệu Diễm trở về cũng bởi Lâm Viễn lại bắt đầu rục rịch hành động.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Diễm nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Gần đây ông ta sẽ phải bận rộn một thời gian."</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ riêng việc tìm kẻ nội gián cũng đã đủ khiến ông ta bận tối mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường cong môi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vẫn phải cảm ơn dì Triệu đã giúp đỡ."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Diễm nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Dì đã nhìn con lớn lên từ nhỏ, giữa con và dì còn khách sáo gì nữa? Năm đó nếu không phải con nhất quyết muốn dì nắm quyền điều hành đại cục của Lâm Thái, dì đã từ chức từ lâu rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường biết mẹ mình và Triệu Diễm từng là bạn học đại học, quan hệ giữa hai người luôn rất tốt. Sau này họ kết hôn, có rất nhiều lời đồn rằng Triệu Diễm từng theo đuổi mẹ cô nhưng không thành, vì vậy mới ôm lòng oán hận.</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc ấy, Lâm Viễn và mẹ cô tranh giành vị trí phó tổng. Mẹ cô thuận thế cài Triệu Diễm vào nội bộ của Lâm Viễn.</p><p style="text-align: justify; margin-bottom: 0.9em">Kể từ đó, Triệu Diễm trở thành lưỡi dao trong tay mẹ cô, bà chỉ đâu thì Triệu Diễm đánh đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Những người khác đều cho rằng Triệu Diễm căm hận mẹ cô, mà bà cũng hận Triệu Diễm. Nhưng thật ra không ai biết, người mẹ còn lại của cô chính là con gái của ân sư Triệu Diễm. Hai người quen biết nhau cũng do Triệu Diễm mai mối.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi hai người mẹ của cô chia tay, Triệu Diễm trở thành lưỡi dao sắc bén mà mẹ cô để lại. Đó cũng là món quà tốt nhất bà dành cho cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Chuyện này ngay cả Lâm Ngọc Phượng cũng không biết.</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Diễm nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lão phu nhân bảo dì hai hôm nữa về nhà dùng bữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có cần con về không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Diễm đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Việc đó còn phải xem lịch trình của con. Đúng rồi, dì nghe bà ấy nói con đã có người mình thích?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường mím môi, nhấp một ngụm cà phê rồi thản nhiên nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bà nói linh tinh mà dì cũng tin sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa dứt lời, chiếc điện thoại đặt trên bàn trà rung lên. Lâm Nhược Đường cầm điện thoại xem tin nhắn, vẻ mặt lạnh nhạt lập tức trở nên dịu dàng trông thấy. Triệu Diễm tựa vào sofa, quan sát sự thay đổi trên gương mặt cô rồi cúi đầu cười.</p><p style="text-align: justify; margin-bottom: 0.9em">Đã bảo giống mẹ mình mà còn không chịu tin. Mức độ cứng miệng này đúng là giống hệt nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Cửa văn phòng phía sau vang lên tiếng gõ. Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vào đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ mở cửa bước vào. Không ngờ bên trong còn có người khác, nàng sửng sốt một giây rồi rất nhanh khôi phục vẻ bình thường, cúi đầu gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường giới thiệu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vị này là Triệu Diễm, người phụ trách thị trường nước ngoài, Triệu tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, cô quay đầu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Còn vị này là nhân viên mới của bộ phận truyền thông, Thời Vụ, Thời tiểu thư."</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn thấy Triệu Diễm, Thời Vụ có phần kinh ngạc. Bên ngoài vẫn luôn đồn rằng hai người đối đầu gay gắt, không ngờ họ lại có thể ngồi xuống uống cà phê cùng nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đưa tay về phía Triệu Diễm:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hóa ra chính là Triệu tổng. Tôi đã nghe danh từ lâu, rất hân hạnh được gặp ngài."</p><p style="text-align: justify; margin-bottom: 0.9em">Triệu Diễm đứng dậy, bắt tay nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Rất hân hạnh."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ định rút tay về nhưng lại bị Triệu Diễm nắm chặt. Nàng ngước mắt lên. Triệu Diễm vỗ nhẹ lên mu bàn tay nàng, nở nụ cười ôn hòa. Thời Vụ khẽ cau mày. Triệu Diễm buông tay nàng ra rồi quay sang nói với Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có một đề nghị, Lâm tổng có thể cân nhắc thử. Cơ hội một khi đã bỏ lỡ thì sẽ không quay lại đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Quan hệ giữa hai người quả nhiên không tốt, ngay cả nói chuyện cũng đầy hàm ý châm chọc.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ yên lặng làm phông nền.</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Lâm Nhược Đường lạnh nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Phiền Triệu tổng phải bận tâm rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nhìn về phía cửa, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trần Hy, tiễn khách."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy lập tức bước nhanh vào văn phòng. Triệu Diễm nhìn Thời Vụ một cái rồi theo Trần Hy rời đi.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi bà rời khỏi, Lâm Nhược Đường ngồi xuống sofa. Vẻ mặt bình thản của cô không để lộ vui giận. Thời Vụ vẫn đứng trước mặt cô. Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngồi đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngồi xuống đối diện cô, đúng vào vị trí Triệu Diễm vừa ngồi. Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngồi sang bên cạnh tôi. Xa như vậy thì bôi thuốc thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Tay cô bị gãy rồi sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ âm thầm than thở nhưng vẫn ngoan ngoãn chuyển đến ngồi bên cạnh Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi nàng ngồi xuống, Lâm Nhược Đường đưa túi thuốc cho nàng. Nhờ kinh nghiệm lần trước, lần này Thời Vụ đã thuần thục hơn nhiều. Lâm Nhược Đường cũng không còn rít lên kêu đau hay bảo nàng nhẹ tay, mà chỉ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cuộc họp hôm nay thế nào? Cô có theo kịp không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nói đến công việc, thái độ của Thời Vụ trở nên vô cùng nghiêm túc và cung kính:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có một số tỷ lệ phối trộn, thuật ngữ và kiến thức chuyên ngành tôi quả thật chưa hiểu rõ. Nhưng Trần Hy đã đưa cho tôi rất nhiều tài liệu. Hai ngày tới tôi sẽ nghiên cứu kỹ, cố gắng không kéo lùi tiến độ của mọi người."</p><p style="text-align: justify; margin-bottom: 0.9em">Gương mặt nàng căng cứng, nghiêm túc đến mức chẳng hề mỉm cười, trông cứ như một khúc gỗ.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nâng tách cà phê trước mặt lên, khẽ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không cần phải nghiêm túc như vậy. Cô thuộc bộ phận truyền thông chứ không phải nhóm nghiên cứu kỹ thuật. Chỉ cần cung cấp dữ liệu cần thiết cho là được, không cần chuyện gì cũng phải tinh thông."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ im lặng hai giây rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi cũng rất muốn học hỏi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngước mắt nhìn nàng. Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cảm ơn Lâm tổng đã cho tôi cơ hội này. Tôi cảm thấy công việc rất thú vị."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ừm."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường một tay bưng tách cà phê, tay còn lại đặt trên tay vịn sofa, chân bị thương đặt trên đầu gối Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chăm chú bôi thuốc. Nàng cúi đầu, những sợi tóc mai lòa xòa rủ xuống, che khuất nửa bên gương mặt. Lâm Nhược Đường khẽ cử động mắt cá chân, Thời Vụ cũng hơi nâng nửa người trên theo động tác của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Mấy sợi tóc mai khẽ lay động. Lâm Nhược Đường mím chặt môi, ánh mắt từ đỉnh đầu nàng chậm rãi dời xuống chân tóc, rồi dừng lại nơi nửa bên gương mặt bị tóc che khuất cùng xương quai xanh như ẩn như hiện.</p><p style="text-align: justify; margin-bottom: 0.9em">Một lúc lâu sau, Lâm Nhược Đường nâng tách cà phê đã nguội từ sáng lên nhấp một ngụm.</p><p style="text-align: justify; margin-bottom: 0.9em">Cà phê hôm nay đặc biệt ngọt.</p><p style="text-align: justify; margin-bottom: 0.9em">Bôi thuốc xong, Thời Vụ ngẩng đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, xong rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Bây giờ nàng chăm sóc người khác cũng ngày càng thành thạo, quả thật là một người rất có khả năng học hỏi. Thời Vụ tự tìm niềm vui trong khổ. Lâm Nhược Đường gật đầu, lấy điện thoại ra rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vào đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn cửa văn phòng mở ra. Trần Hy dẫn theo vài người chuyển một chiếc bàn làm việc vào trong. Lâm Nhược Đường đứng dậy, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô hỏi xem cô ấy muốn sắp xếp thế nào."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy cúi đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vâng, Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, cô ấy hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— " Cô Thời, cô muốn đặt bàn làm việc ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn chiếc bàn, ngơ ngác hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cho tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đúng vậy. Nhân viên tạm thời thường không có chỗ làm việc cố định, vì vậy Lâm tổng đã sắp xếp riêng cho cô một chiếc bàn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tại sao không đặt ở bên ngoài?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trong những cuộc họp mà cô tham gia có rất nhiều tài liệu không được phép truyền ra ngoài, cần phải giữ bí mật. Vì vậy, mong cô thông cảm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cảm thấy cả người không được tự nhiên:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy cũng đâu nhất thiết phải đặt trong văn phòng của Lâm tổng?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy mỉm cười giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thật ra Lâm tổng không thường xuyên làm việc trong văn phòng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cau mày:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy cô ấy làm việc ở đâu?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bình thường cô ấy ở phòng tiếp khách bên cạnh."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gật đầu. Trần Hy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vì vậy cô cứ yên tâm, về cơ bản sẽ không có ai đến làm phiền cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng không sợ bị làm phiền, chỉ cảm thấy chuyện này rất kỳ lạ. Nàng chẳng phải chỉ làm thêm sao? Tại sao còn sắp xếp cả bàn làm việc?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi cần đến đây mỗi ngày sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đương nhiên là không. Sau khi cô nắm được số liệu của các bộ phận liên quan đến Nguyệt Ẩn thì không cần tới đây nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hít sâu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thư ký Trần, cô cứ gọi thẳng tên tôi đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây, khi nàng đến ngồi chờ Lâm Nhược Đường, trong vài lần tiếp xúc giữa hai người, thái độ của Trần Hy với nàng chẳng khác gì với một giám đốc bộ phận bình thường. Bây giờ cô ấy lại quá mức cung kính. Thời Vụ không quen với sự thay đổi này, cảm thấy chỗ nào cũng không được tự nhiên.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy kinh ngạc:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Như vậy không được tốt lắm thì phải?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có gì mà không tốt? Chúng ta quen nhau cũng gần một năm rồi. Lần trước tôi đến bệnh viện còn do cô đưa đi. Cô cứ liên tục dùng kính ngữ với tôi như vậy, tôi cũng thấy không được tự nhiên."</p><p style="text-align: justify; margin-bottom: 0.9em">Thấy nàng đã nói đến mức này, Trần Hy đành nghiến răng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hài lòng. Trần Hy hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi đặt bàn làm việc của cô ở đây được không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Đó là vị trí sát cửa sổ sát đất, phía trên có đèn nên ánh sáng rất đầy đủ. Nếu ban ngày cảm thấy chói mắt, nàng còn có thể khép rèm lá sách bên cạnh. Thời Vụ nhìn vị trí cô ấy chọn rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Khá ổn."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy sắp xếp người đặt bàn ghế vào đó, lại bảo bộ phận thu mua mang một chiếc máy tính mới tới. Thời Vụ bỗng có cảm giác khó hiểu như thể mình đã chính thức nhận việc. Trần Hy hỏi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Còn cần thêm gì nữa không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nghĩ ra mình còn cần gì. Nhưng sau khi Trần Hy rời đi, nàng thật sự phát hiện vẫn còn thiếu một thứ.</p><p style="text-align: justify; margin-bottom: 0.9em">Tài liệu của nàng chưa được in.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi hỏi Trần Hy và biết có thể in ở văn phòng thư ký, nàng cầm USB đi đến phòng in. Khi đi ngang qua phòng trà nước, nàng nghe thấy tiếng bàn tán bên trong:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vừa rồi Triệu tổng đến công ty phải không?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi cũng nhìn thấy. Bà ấy về nước từ khi nào vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trước đây hình như bà ấy cũng là phó tổng của Lâm Thái. Nghe nói bây giờ chủ yếu phụ trách các dự án ở nước ngoài?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không biết lần này bà ấy trở về có phải để giúp Viễn tổng không."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ trước giờ không quá hứng thú với chuyện hóng hớt. Nàng đã đi qua phòng trà nước nhưng lại nghe thấy một câu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tháng trước Lâm tổng đi xem mắt, mọi người có biết không?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ai vậy, ai vậy? Xem mắt với ai?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hình như là con gái của Trương tổng bên Thấm Thủy."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi từng gặp con gái bà ấy rồi, là một nghệ sĩ. Nghe nói cô ấy đã ở nước ngoài vài năm, cũng khá xứng đôi với Lâm tổng nhà chúng ta."</p><p style="text-align: justify; margin-bottom: 0.9em">Trương tổng bên Thấm Thủy?</p><p style="text-align: justify; margin-bottom: 0.9em">Trương Thanh Thanh?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ biết thương hiệu này, chuyên sản xuất đồ uống. Nàng cũng từng gặp Trương Thanh Thanh. Trương Thanh Thanh đã tham dự dạ tiệc Khuyết Tây, lúc ấy còn trò chuyện rất vui vẻ với Lâm Ngọc Phượng. Có lẽ họ đang bàn chuyện xem mắt của Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Không ngờ cô cũng cần đi xem mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa tưởng tượng đến gương mặt lạnh như băng của Lâm Nhược Đường trong buổi xem mắt, Thời Vụ đã bị chọc trúng điểm buồn cười. In tài liệu xong trở về văn phòng, nụ cười nơi khóe môi nàng vẫn chưa biến mất. Khi nàng vừa mở cửa, bên cạnh đã vang lên một giọng nói lạnh nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vui đến vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu, lập tức thu lại khóe môi đang cong lên, nghiêm chỉnh gọi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường vừa mở cửa vừa hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có chuyện gì mà vui thế?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nụ cười vừa bị Thời Vụ cố nén xuống lại thoáng hiện lên. Nàng ép khóe môi xuống, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không có gì. Vừa rồi Dư Mạt gửi cho tôi một câu chuyện cười."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy gửi cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ liếc cô một cái.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi muốn xem thử có thật sự buồn cười hay không."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lấy điện thoại ra, chuyển tiếp video Dư Mạt đã gửi cho mình sang cho Lâm Nhược Đường. Cô xem xong mà mặt vẫn không chút biểu cảm, ngẩng đầu hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Điểm gây cười thấp đến vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Tính hiếu thắng của Thời Vụ lập tức trỗi dậy. Nàng liên tục gửi cho Lâm Nhược Đường mấy video hài hước nhất trên mạng, mắt không chớp lấy một lần, chỉ chăm chăm quan sát phản ứng của cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ngồi trên ghế văn phòng, một tay chống cằm, nhìn những video hài hước trên máy tính. Vẻ mặt cô vẫn bình thản như một đầm nước chết.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không nhịn được:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không buồn cười sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Lâm Nhược Đường vẫn lạnh nhạt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Buồn cười sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Khóe môi Thời Vụ khẽ giật.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không cười khi xem video, nhưng nhìn vẻ mặt này của cô, Thời Vụ ngược lại còn cảm thấy khá vui. Nàng bật cười rồi hài lòng trở về bàn làm việc, mở tài liệu ra, cẩn thận đối chiếu số liệu.</p><p style="text-align: justify; margin-bottom: 0.9em">Nguyệt Ẩn là loại nước hoa mới nhất do Nguyệt Hạ nghiên cứu và phát triển, cũng là sản phẩm khép lại dòng nước hoa này, đồng thời sẽ được ra mắt nhân dịp kỷ niệm sáu năm thành lập Nguyệt Hạ.</p><p style="text-align: justify; margin-bottom: 0.9em">Những gì Thời Vụ và Trần Hy nói không sai. Nàng quả thật không am hiểu nước hoa, nhưng nàng hiểu về truyền thông. Ra mắt sản phẩm mới vào thời điểm này là lựa chọn tốt nhất, vì vậy nàng tán thành việc thay đổi hương nền.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng với tư cách người ngoài cuộc, nàng chỉ cần ghi lại số liệu chứ không tham gia phân tích. Dù sao nói thì rất dễ, còn mọi rủi ro đều do bộ phận nghiên cứu và phát triển gánh chịu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thế nhưng Lâm Nhược Đường vẫn không định bỏ qua cho nàng, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trong cuộc họp hôm nay có người đề nghị thay đổi hương nền. Cô thấy thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩng đầu khỏi tập tài liệu, nhìn thẳng vào Lâm Nhược Đường rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi cho rằng vẫn nên lấy ý kiến của bộ phận nghiên cứu và phát triển làm chính."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không sao."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô cũng có thể đưa ra một số ý kiến từ góc độ truyền thông."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Xét từ góc độ truyền thông, tôi cho rằng thay đổi sẽ tốt hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vốn dĩ cũng đã định thay đổi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy tại sao trong cuộc họp hôm nay vẫn còn thảo luận xem có nên thay đổi hay không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cùng một việc, do tôi phân công cho cô làm và do cô chủ động tranh thủ thực hiện, cô cảm thấy cách nào sẽ khiến cô tận tâm hơn?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thủ đoạn quả thật cao tay.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhìn nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hãy quan sát nhiều hơn, suy nghĩ nhiều hơn. Những chuyện cô cho rằng mình phải gấp rút hoàn thành, chưa biết chừng lại chính là cái bẫy của người khác."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cảm thấy lời này của cô còn mang một tầng hàm ý khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng lẽ đang ám chỉ cuộc hôn nhân của nàng sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Ý cô là Thời Vụ từng tràn đầy vui sướng khi kết hôn với Triệu Hy Ngọc, nhưng ngay từ trước hôn lễ đã bị người ta tính toán rõ ràng?</p><p style="text-align: justify; margin-bottom: 0.9em">Hình như đúng là như vậy thật. Sắc mặt Thời Vụ trắng bệch, nàng cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng nói đúng."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhếch môi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tại sao phải mang vẻ khổ đại cừu thâm như thế? Rất ít người có thể thuận buồm xuôi gió suốt cả đời......"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô im lặng một chút rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô không cần nhìn tôi. Tuy tôi đúng là người như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Người này cũng quá tự luyến rồi. Tuy cô quả thật có tư cách để tự luyến.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bắt gặp ánh mắt của Thời Vụ, tiếp tục nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cho nên, đi nhầm đường cũng không đáng sợ, chỉ cần kịp thời dừng tổn thất là được. Cô cũng không cần cảm thấy đó là lỗi của mình."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô nhận xét:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhiều nhất chỉ là mắt nhìn người của cô không được tốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe cô nói vậy, Thời Vụ hiếm khi không tức giận mà ngược lại còn cong môi. Đôi mắt nàng cong cong như vầng trăng non, ánh lên vẻ điềm tĩnh. Nàng nhìn thẳng vào Lâm Nhược Đường, một lúc lâu sau mới hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, cô đang an ủi tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Bởi hôm nay nàng ly hôn, cô sợ tâm trạng nàng không tốt nên đang an ủi nàng sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hẳn không thường xuyên làm chuyện như vậy, hoặc có thể chưa bao giờ làm. Bởi lời an ủi của cô nghe cứng nhắc đến thế, nhưng Thời Vụ lại cảm thấy vô cùng cảm động.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi biết nàng ly hôn, tám phần người chỉ đứng xem náo nhiệt, một phần thì chế giễu, chỉ còn một phần thật lòng quan tâm đến nàng. Nhưng những người đó sợ khiến nàng tổn thương lần nữa nên không dám nói thẳng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại thẳng thắn đến mức khiến nàng cảm động.</p><p style="text-align: justify; margin-bottom: 0.9em">Dư Mạt nói đúng. Lâm Nhược Đường thật sự xem nàng như một người bạn.</p><p style="text-align: justify; margin-bottom: 0.9em">Vẻ mặt Lâm Nhược Đường hơi mất tự nhiên. Cô cau mày, giọng nói vẫn lạnh nhạt như trước:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nếu cô muốn hiểu như vậy thì cứ xem là vậy đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, cô đúng là miệng nói một đằng, lòng nghĩ một nẻo."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Gan của nàng đúng là càng lúc càng lớn, đã bắt đầu trêu chọc cô rồi. Thời Vụ trước mặt lúc này và Thời Vụ khi mới gặp cứ như hai người hoàn toàn khác nhau.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường im lặng nhìn nàng vài giây rồi khẽ hừ một tiếng, quay đầu nhìn máy tính. Trên máy tính là đoạn video hài vừa mới xem được một nửa. Lâm Nhược Đường xem lần lượt cho hết, sau đó lại phát lại thêm một lần.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vùi đầu vào đống tài liệu và số liệu. Trong lúc đó, nàng ra ngoài tìm Trần Hy. Khi đến văn phòng thư ký, vài thư ký đồng loạt ngẩng đầu nhìn nàng. Một người thậm chí còn đứng bật dậy:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô chẳng phải là... Giám đốc Thời của Ưu Lạc sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Có người kéo nhẹ vạt áo cô ấy. Đúng lúc ấy, Trần Hy cũng trở về văn phòng. Thấy tình hình trước mắt, cô ấy nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vẫn chưa giới thiệu với mọi người. Đây là nhân viên mới của bộ phận truyền thông chúng ta, Cô Thời."</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy mọi người đều kinh ngạc nhưng vẫn có thể hiểu được. Nghe nói Thời Vụ và Triệu Hy Ngọc đã ly hôn, nàng nghỉ việc cũng là chuyện hợp lý. Trước đây nàng vốn làm ở bộ phận truyền thông, vì vậy đến Lâm Thái nhận việc cũng rất bình thường.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ là không ai ngờ mọi chuyện lại diễn ra nhanh như vậy. Chân trước nàng vừa rời chức, chân sau đã đến Lâm Thái.</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây, mọi người không thân với Thời Vụ, chỉ từng nghe chuyện giữa nàng và Triệu Hy Ngọc. Thêm vào đó, Ưu Lạc vẫn luôn muốn hợp tác với Lâm Thái nên họ cũng từng nghe nói về nàng. Bây giờ tận mắt nhìn thấy Thời Vụ, tất cả đều không ngừng quan sát nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy nhe răng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vỗ tay đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Một thư ký bên cạnh lập tức phản ứng, đứng dậy vỗ tay:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hoan nghênh, hoan nghênh!"</p><p style="text-align: justify; margin-bottom: 0.9em">Những người khác cũng lần lượt vỗ tay theo.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu tại sao họ lại làm long trọng đến vậy, cảm thấy hơi ngượng ngùng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cảm ơn mọi người."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, nàng nhìn sang Trần Hy rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trần Hy, tôi có chút chuyện muốn tìm cô."</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy gọi nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đến văn phòng của tôi đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ theo cô ấy vào văn phòng, ngăn cách tiếng bàn luận bên ngoài:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô ấy vào bộ phận truyền thông từ khi nào vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chắc là buổi trưa. Tôi thấy thư ký Trần đưa cô ấy đi làm thủ tục."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lần này cô ấy được điều thẳng vào vị trí của ai? Quản lý bộ phận truyền thông hay phó quản lý?"</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không biết, nhưng nghe nói là do Lâm tổng đích thân mời tới."</p><p style="text-align: justify; margin-bottom: 0.9em">Mọi người đồng loạt nhìn về phía người phụ nữ vừa lên tiếng. Bình thường cô ấy có quan hệ khá tốt với Trần Hy, lời nói rất đáng tin.</p><p style="text-align: justify; margin-bottom: 0.9em">Ban đầu, việc Thời Vụ gia nhập công ty chỉ là đề tài để mọi người bàn tán sau giờ ăn. Nhưng nếu người đích thân mời nàng lại là Lâm Nhược Đường thì lại là chuyện khác. Ai cũng biết hiện tại, số người có thể khiến cô tự mình lên tiếng mời chỉ đếm được trên đầu ngón tay.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Thời Vụ bước ra khỏi văn phòng lần nữa, mọi người đã nhiệt tình hơn hẳn.</p><p style="text-align: justify; margin-bottom: 0.9em">Người bên trái hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— " Cô Thời, cô ăn cam không? Ngọt lắm."</p><p style="text-align: justify; margin-bottom: 0.9em">Người bên phải lại hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— " Cô Thời, cô ăn bánh quy không? Tôi tự nướng đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc đến, hai tay nàng còn trống không. Khi trở về văn phòng, trong lòng đã ôm cả một đống đồ ăn. Lâm Nhược Đường thờ ơ ngẩng đầu khỏi máy tính nhìn nàng, sau đó lại nhìn thêm lần nữa rồi cau mày:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đi xin ăn đấy à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Người này có biết nói chuyện đàng hoàng không vậy!</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng thật sự muốn nhét bánh quy vào miệng Lâm Nhược Đường!</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nàng không dám, chỉ có thể hung hăng trừng mắt nhìn cô, sau đó đặt mọi thứ lên bàn của mình. Lâm Nhược Đường khựng lại vài giây rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vừa rồi cô trừng tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười ha ha:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao có thể chứ, Lâm tổng? Vừa rồi mắt tôi bị co giật thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Hỏng rồi, nàng lại bắt đầu nói móc người ta rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe vậy, Lâm Nhược Đường đứng dậy. Vì chân không tiện nên cô đi rất chậm, mỗi bước đều khẽ cau mày. Chỉ vài bước ngắn ngủi mà mãi cô mới đến bên bàn làm việc của Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đang phân loại đồ ăn vặt thì một bóng người đột nhiên phủ xuống. Nàng quay đầu, Lâm Nhược Đường đã cúi người sát trước mặt. Thời Vụ ngả lưng vào ghế văn phòng, đối diện với ánh mắt cô, không hiểu sao lại thấy chột dạ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô... cô làm gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đứng thẳng dậy. Vì một chân bị đau, cô ngồi nửa người lên mép bàn của Thời Vụ. Lớp quần âu căng lên, phác họa rõ đường nét thon gọn. Thời Vụ dời mắt đi, nghe Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Những thứ này từ đâu ra?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đồng nghiệp bên văn phòng thư ký vừa cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lục trong đống đồ ăn vặt của nàng, lấy ra một quả cam rồi đưa cho Thời Vụ. Nàng nhận lấy bằng một tay:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lát nữa tôi sẽ ăn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi ăn."</p><p style="text-align: justify; margin-bottom: 0.9em">Cô khẽ nâng cằm:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bóc cho tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt Thời Vụ rơi xuống bàn tay cô. Mười ngón tay thon dài, trắng nõn, các khớp ngón tay trông rất có lực. Nàng lẩm bẩm:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao không tự bóc đi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường xoa vành tai:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô nói gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nén giận, ngẩng đầu đối diện với ánh mắt Lâm Nhược Đường, ngoài cười nhưng trong không cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi nói được."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhanh chóng bóc quả cam rồi đưa cho Lâm Nhược Đường. Nhưng cô không nhận, chỉ khẽ nâng cằm:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vẫn còn xơ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thứ này tốt mà, có lợi cho tiêu hóa."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy tôi không ăn nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lại cẩn thận nhặt sạch từng sợi xơ còn sót lại rồi đưa quả cam cho cô. Lâm Nhược Đường hài lòng bóc lấy một múi, chậm rãi nhai.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thu dọn số đồ ăn vặt còn lại rồi nhét vào ngăn kéo. Qua khóe mắt, nàng thấy Lâm Nhược Đường vẫn ngồi trên bàn làm việc của mình. Nàng không tiện đuổi người, đành lén dùng góc tập tài liệu chọc nhẹ vào mông cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nghiêng đầu. Thời Vụ vẫn giữ vẻ mặt bình thản, cứ như mình chưa làm gì cả.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Lâm Nhược Đường lại nhìn chằm chằm vào vành tai đang dần đỏ lên của nàng, cắn một múi cam.</p><p style="text-align: justify; margin-bottom: 0.9em">Nước cam tràn khắp đầu lưỡi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ngọt.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bật cười, đứng dậy rời khỏi bàn làm việc của Thời Vụ. Lúc ấy, nàng mới âm thầm thở phào.</p><p style="text-align: justify; margin-bottom: 0.9em">Chẳng phải Trần Hy nói cô không thường xuyên ở trong văn phòng sao? Tại sao đến giờ vẫn chưa chịu rời đi?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ liếc nhìn về phía bàn làm việc của Lâm Nhược Đường. Trên màn hình bật ra tin nhắn của Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi thêm cô vào nhóm của bộ phận truyền thông nhé?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đang do dự.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">【Để sau này tiện phối hợp công việc.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không còn thắc mắc:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được.】</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">【Còn có một nhóm chung của công ty, tôi cũng thêm cô vào nhé.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được.】</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Trần Hy gửi tin nhắn xong, Thời Vụ nhận được ba, bốn lời mời vào nhóm. Tất cả các nhóm đều im phăng phắc. Thời Vụ không cảm thấy kỳ lạ, chủ động nhắn riêng cho Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">【Buổi tối công ty có nhà ăn không?】</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【Buổi tối không có. Nếu tăng ca thì sẽ được trợ cấp tiền ăn. Cô định tăng ca sao?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Vẫn còn một số dữ liệu cần sắp xếp, có lẽ nhất thời chưa thể làm xong.】</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">【Tôi có thể giúp cô xin trợ cấp tiền ăn.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Không cần, không cần đâu. Cảm ơn nhé.】</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng không được trả tiền tăng ca, theo lý cũng không có trợ cấp tiền ăn. Ban đầu, nàng và Lâm Nhược Đường đã thỏa thuận một mẫu nội dung tương ứng với một mức giá cố định. Còn mất bao lâu để hoàn thành mẫu đó thì phụ thuộc vào chính nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Không thể vì tốc độ của nàng chậm mà toàn bộ thời gian làm thêm trong tháng này đều tính thêm tiền được. Lâm Nhược Đường đâu phải kẻ ngốc, sao có thể chấp nhận một vụ mua bán lỗ vốn như vậy? Vì thế, nàng không muốn làm khó Trần Hy.</p><p style="text-align: justify; margin-bottom: 0.9em">Trần Hy:</p><p style="text-align: justify; margin-bottom: 0.9em">【Được. Nếu còn cần gì khác thì cứ nói với tôi bất cứ lúc nào.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ gửi lại cho cô ấy một biểu tượng đầu mèo đáng yêu.</p><p style="text-align: justify; margin-bottom: 0.9em">Tin nhắn vừa gửi đi, nàng liền nghe Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Thời, buổi tối ăn gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Sao lại gọi Tiểu Thời nữa rồi!</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ giả vờ không nghe thấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Muốn ăn gì thì ăn đi. Vừa rồi cô còn ăn mất của nàng một quả cam lớn đấy!</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hâm nóng tôm hùm và cua được gói về lúc trưa, ăn không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngẩng đầu khỏi màn hình máy tính. Vừa khéo đối diện với ánh mắt Lâm Nhược Đường, không kịp tiếp tục giả vờ không nghe thấy, nàng đành nở một nụ cười giả tạo:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ăn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường liếc nàng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao cười giống hệt Tiểu Châu vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Giống chỗ nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhận xét:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Xấu như nhau." ......</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả:</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các tiểu thiên sứ đã tặng 9 phiếu Bá Vương và 305 chai dung dịch dinh dưỡng~</p><p style="text-align: justify; margin-bottom: 0.9em">Tặng ngẫu nhiên 100 bao lì xì, moah moah.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: Sau này muốn ăn cam thì tự bóc.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường: Được thôi, chị bóc cam nhanh nhất đấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: Này!!! Sao chị lại cởi quần áo của tôi!!!</p>', 'published', now(), now(), now()),
  ('8548ee4d-bb05-4d04-87ec-ed453f709512'::uuid, 40, 'Cầu Kỳ', '<p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không phải kiểu người thích mách lẻo sau lưng người khác, nhưng nàng vẫn nhắn cho Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị em nói xấu em.】</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng có thể kể cho Lâm Châu, bởi nàng biết cô nhất định sẽ hiểu ý mình. Lâm Châu nhanh chóng trả lời:</p><p style="text-align: justify; margin-bottom: 0.9em">【???】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị ấy nói gì vậy?】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Nói chị giống em, lúc cười trông rất xấu.】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu gửi một biểu tượng phẫn nộ, kèm theo:</p><p style="text-align: justify; margin-bottom: 0.9em">【Vâng, vâng, vâng! Ai mà giống chị ấy được chứ? Đóa hoa trên đỉnh núi cao, bông hồng nơi đỉnh băng, tiên nữ hạ phàm!】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【......】</p><p style="text-align: justify; margin-bottom: 0.9em">Đây là đang mắng hay đang khen Lâm Nhược Đường vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Trút giận xong, Lâm Châu lại nhắn cho Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【Chị, chị đừng để ý đến chị ấy. Chị ấy chỉ đang ghen tị với hai chị em mình thôi.】</p><p style="text-align: justify; margin-bottom: 0.9em">Đây là lần đầu tiên Thời Vụ nghe thấy cách giải thích này, nàng kinh ngạc hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">【Ghen tị với hai chị em mình?】</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Châu:</p><p style="text-align: justify; margin-bottom: 0.9em">【Đương nhiên rồi. Ngày nào chị ấy cũng phải duy trì hình tượng lạnh lùng, kiêu ngạo của mình, thật ra trong lòng ghen tị muốn chết vì hai chị em mình muốn cười là có thể cười.】</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">【......】</p><p style="text-align: justify; margin-bottom: 0.9em">Lạnh lùng? Kiêu ngạo?</p><p style="text-align: justify; margin-bottom: 0.9em">Sao nàng chẳng nhìn ra điều đó ở Lâm Nhược Đường vậy? Nàng chỉ cảm thấy lời nói và cách hành xử của cô lúc nào cũng khiến người khác ngứa ngáy mà thôi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ liếc nhìn Lâm Nhược Đường. Cô đang nhìn máy tính, đường nét gương mặt nghiêng căng lại, ánh mắt sắc bén, tay phải chống bên cằm, tay trái gõ trên bàn phím. Không biết cô đang xem thứ gì, nhưng dường như tâm trạng không được tốt, đôi mày thanh tú hơi cau lại, hơi thở không vui lặng lẽ lan ra xung quanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Được rồi, Lâm Châu nói đúng. Lâm Nhược Đường khi không mở miệng quả thật trông rất lạnh lùng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thu ánh mắt lại thì nghe tiếng chuông điện thoại vang lên từ phía Lâm Nhược Đường. Cô dùng tay trái nhấc ống nghe lên, áp vào tai.</p><p style="text-align: justify; margin-bottom: 0.9em">Không biết người ở đầu bên kia là ai, nói suốt hồi lâu, Lâm Nhược Đường mới lên tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cho thêm một cơ hội nữa sao? Được thôi. Bảo ông ta nhả lại hai mươi triệu tiền lời đã nuốt vào lần trước, tôi sẽ cho ông ta thêm một cơ hội."</p><p style="text-align: justify; margin-bottom: 0.9em">Có phải là nhà cung cấp nguyên liệu mà họ gặp hôm nay không?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vẫn chưa hiểu rõ, nhưng nàng cảm thấy Lâm Nhược Đường thật sự quá yên tâm về mình. Cô lại để nàng ngồi ngay trong văn phòng, nghe những bí mật kinh doanh này, chẳng lẽ không sợ nàng bán đứng cô sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Không biết có thể bán được bao nhiêu tiền nhỉ?</p><p style="text-align: justify; margin-bottom: 0.9em">Chắc Lâm Nhược Đường đáng giá lắm?</p><p style="text-align: justify; margin-bottom: 0.9em">Trước giờ Thời Vụ không biết mình còn có những suy nghĩ nhỏ nhen như vậy. Cứ đến gần Lâm Nhược Đường, những ý nghĩ đen tối này lại thi nhau nhảy ra. Tuy nàng sẽ không thật sự làm thế, nhưng chỉ nghĩ thôi cũng cảm thấy khá sảng khoái.</p><p style="text-align: justify; margin-bottom: 0.9em">Giống như hồi còn đi học, nàng luôn mơ mình trúng năm triệu: mua nhà ở chỗ này, mua xe ở chỗ kia, ngày nào cũng đi du lịch, muốn ăn gì thì ăn nấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đang chìm đắm trong giấc mộng đẹp thì nghe một giọng nói lạnh nhạt vang lên:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vui chuyện gì vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hoàn hồn, thấy Lâm Nhược Đường đang nhìn mình. Nàng đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi có vui gì đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy cô cười gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức nghiêm chỉnh lại vẻ mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, tôi cho rằng vẫn nên chuyển bàn làm việc của tôi ra ngoài thì hơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường dứt khoát kết luận:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Muộn rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngơ ngác:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cái gì muộn rồi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đã nghe nhiều bí mật kinh doanh của Lâm Thái như vậy, bây giờ mới chuyển ra ngoài để phủi sạch quan hệ thì đã muộn rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi chẳng nghe thấy gì cả."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hé môi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy vừa rồi cô cười gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Tính phản nghịch trong nàng lập tức trỗi dậy:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi đang nghĩ xem bán những bí mật này có thể kiếm được bao nhiêu tiền, sau đó ôm tiền bỏ trốn."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không nhìn ra đấy."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng Lâm Nhược Đường lạnh lẽo:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hóa ra cô còn là kiểu người như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đúng, tôi chính là kiểu người như vậy. Cho nên tốt nhất Lâm tổng nên để tôi ra ngoài làm việc, tránh cho tôi nghe thêm nhiều tin tức khác."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Người lần trước bán tin tức của Lâm Thái rồi ôm tiền bỏ trốn đã bị kết án sáu năm. Cô muốn đi thăm tù không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quay đầu, khó tin nhìn Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chỉ nói đùa thôi, Lâm Nhược Đường lại tưởng thật sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đối diện với ánh mắt nàng, nở nụ cười kín đáo nhưng trông lại có phần âm hiểm.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức dẹp bỏ ý định đùa giỡn, quay đầu nhìn chằm chằm vào máy tính của mình. Khi Lâm Nhược Đường lại nhìn sang, nàng đã đeo tai nghe kín cả hai tai.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Không còn nghe thấy giọng Lâm Nhược Đường, Thời Vụ vùi đầu vào công việc. Đột nhiên, một bóng đen phủ xuống trước mặt.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngẩng đầu, thấy Lâm Nhược Đường đang đứng trước bàn làm việc của mình. Thời Vụ tháo tai nghe xuống, nghe cô nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ buột miệng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi không đi thăm tù đâu."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bị nàng chọc cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi ăn cơm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng tháo tai nghe xuống, nghe Lâm Nhược Đường cúi người hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vừa rồi cô vẫn luôn nghĩ xem có thể bán tin tức của Lâm Thái được bao nhiêu tiền phải không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghiêm túc đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, tôi không nhàm chán đến thế."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có tiền rồi, cô muốn làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mua nhà, mua xe, mua......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngẩng đầu khỏi ghế làm việc, đôi mắt oán trách nhìn chằm chằm vào Lâm Nhược Đường. Cuối cùng nàng không thể nhịn thêm được nữa, buông ra hai chữ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhàm chán."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đứng dậy, vẫy tay gọi nàng. Tuy Thời Vụ tỏ vẻ ghét bỏ, nàng vẫn đi đến bên cạnh, đỡ cô sang phòng tiếp khách bên cạnh.</p><p style="text-align: justify; margin-bottom: 0.9em">Thức ăn đã được chuẩn bị xong. Ngoài tôm cua gói về từ buổi trưa, còn có thêm canh và cơm. Có lẽ để ăn cùng tôm cua nên hôm nay họ dùng canh hải sản cay.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ nhìn màu sắc thôi đã khiến người ta thèm ăn, hương thơm cũng cay nồng hấp dẫn. Canh hải sản Thời Vụ từng ăn trước đây phần lớn chỉ có tôm tươi và mực khoanh, khá hơn một chút thì thêm vài con vẹm xanh.</p><p style="text-align: justify; margin-bottom: 0.9em">Còn bát canh này có đủ loại hải sản, bên dưới lót cua hoa, lại thêm vi cá và hải sâm. Thời Vụ nhất thời không phân biệt nổi trước mặt mình là canh hải sản hay món Phật nhảy tường nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chưa từng ăn hương vị này. Sau khi ngồi xuống, Lâm Nhược Đường đưa thìa cho nàng rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nếm thử đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hề nghi ngờ khẩu vị của Lâm Nhược Đường. Nàng đã vài lần ăn cơm ở nhà cô, biết cô rất kén chọn đồ ăn, nên đoán bát canh này chắc chắn cũng ngon. Nhưng không ngờ nó lại ngon đến vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ uống một ngụm canh, cảm giác linh hồn mình cũng được thăng hoa.</p><p style="text-align: justify; margin-bottom: 0.9em">Quả nhiên người chưa từng được ăn món ngon rất dễ bị chấn động.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thành thật đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngon lắm."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cong môi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi đoán cô nhất định sẽ thích."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tại sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chẳng phải cô thích ăn hải sản sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sửng sốt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao cô biết?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra cũng không thể nói là thích, chỉ là so với những món ăn thông thường, nàng có phần ưu ái hải sản hơn một chút.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mẹ cô kể."</p><p style="text-align: justify; margin-bottom: 0.9em">Bàn tay đang cầm thìa của Thời Vụ siết chặt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mẹ tôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngước mắt nhìn Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Thời Ánh Xuân rời đi, nàng vẫn luôn né tránh những chủ đề liên quan đến bà. Thỉnh thoảng, khi uống quá nhiều hoặc đang mơ màng buồn ngủ, nàng sẽ trò chuyện với Dư Mạt vài câu. Nhưng mỗi lần Dư Mạt nhắc đến Thời Ánh Xuân, nàng đều vội vàng lảng tránh.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng sợ phải nghe thấy cái tên Thời Ánh Xuân. Điều nàng sợ chính là cảm giác tội lỗi nặng nề, ngột ngạt đang dâng lên trong lòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mẹ cô từng kể, mỗi lần bà ấy nhận lương, cô đều mè nheo đòi đi ăn một bữa hải sản thật thịnh soạn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thật ra đâu phải lần nào cũng như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Ngày phát lương của Thời Ánh Xuân là hai mươi lăm hằng tháng, nhưng ngay từ tối ngày hai mươi ba, nàng đã bắt đầu giục bà đi ăn, còn đường hoàng gọi đó là "ăn mừng trước".</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Ánh Xuân nói nàng chỉ giỏi ngụy biện, nhưng vẫn đưa nàng và Thường Anh đến nhà hàng ấy. Sau khi Thường Anh rời đi, hai người họ không bao giờ đến đó nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cụp mắt, dùng thìa khuấy bát súp hải sản. Lâm Nhược Đường lại buông một câu khiến người ta chỉ muốn đánh:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi nhắc đến những chuyện này, chắc không khiến cô mất ngon đấy chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thật sự rất muốn đẩy cả bát súp lẫn thức ăn trước mặt sang một bên. Nàng càng muốn nổi giận, giống như trước đây mỗi khi bị Thời Ánh Xuân vạch trần, nàng đều thẹn quá hóa giận.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng lần này sẽ không còn ai dỗ dành nàng nữa.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cúi đầu, múc một thìa súp hải sản rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ăn thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Giọng nàng rất bình thản, nhưng những cảm xúc bị đè nén quá lâu lại như thủy triều nặng nề nhấn chìm nàng. Ngay cả việc cầm thìa, Thời Vụ cũng cảm thấy mất sức, cổ họng nghẹn lại đến khó chịu.</p><p style="text-align: justify; margin-bottom: 0.9em">Điện thoại Lâm Nhược Đường đặt trên bàn rung lên. Cô không chút biểu cảm liếc nhìn màn hình cuộc gọi đến rồi nói với Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi nghe điện thoại."</p><p style="text-align: justify; margin-bottom: 0.9em">Lắm điện thoại thật!</p><p style="text-align: justify; margin-bottom: 0.9em">Sau khi Lâm Nhược Đường rời đi, Thời Vụ mới ngẩng đầu lên. Hơi nước phủ kín khóe mắt, nàng ra sức chớp mắt, cố ép cảm giác nóng rát vừa dâng lên vì cái tên Thời Ánh Xuân xuống.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đúng là chuyên nhắc đến chuyện người ta không muốn nghe. Có địa vị, có quyền thế thì ghê gớm lắm sao? Muốn nói gì cũng được à?</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng thật ra cô cũng chẳng nói gì quá đáng.</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ là nhắc đến Thời Ánh Xuân, nhắc đến quãng thời gian trước đây của hai mẹ con nàng mà thôi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói đúng, nàng thật sự quá nhạy cảm.</p><p style="text-align: justify; margin-bottom: 0.9em">Đã nhiều năm trôi qua, nàng vẫn không thể thản nhiên đối diện với sự thật Thời Ánh Xuân đã rời xa mình.</p><p style="text-align: justify; margin-bottom: 0.9em">Lần đầu tiên Triệu Hy Ngọc đến nhà nàng, nàng đã cho cô ấy xem rất nhiều ảnh cũ. Thế nhưng nàng không dám nhìn vào đôi mắt Thời Ánh Xuân trong những bức ảnh ấy.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng sợ sẽ nhìn thấy sự thất vọng.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Lâm Nhược Đường trở lại phòng tiếp khách, cô còn chưa bước vào đã nhìn thấy Thời Vụ ngửa đầu, hít sâu hai lần. Sau đó nàng cũng chẳng ăn uống gì, chỉ ngồi ngẩn người.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô tựa người vào chiếc bàn bên cạnh:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sh..."</p><p style="text-align: justify; margin-bottom: 0.9em">Nghe thấy động tĩnh, Thời Vụ quay đầu lại. Nàng thấy Lâm Nhược Đường chống một tay lên góc bàn, cả người nghiêng sang một bên, trông như vừa va phải thứ gì đó.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vội vàng đặt đũa xuống, bước nhanh đến bên cô. Nàng theo thói quen đỡ lấy eo Lâm Nhược Đường, cau mày.</p><p style="text-align: justify; margin-bottom: 0.9em">Sao lại bị thương nữa rồi? Cái chân này còn muốn khỏi hay không đây?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng muốn hỏi nhưng cố nhịn xuống, khiến cả gương mặt thanh tú đỏ bừng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường mượn sức nàng trở lại bên bàn. Hai người dùng bàn họp làm bàn ăn. Sau khi Thời Vụ đỡ cô ngồi xuống, nàng nghe cô hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lát nữa cô có bận gì không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi vẫn còn chút tài liệu cần xem. Lâm tổng có việc gì sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hôm nay bà xuất viện. Gần đây tâm trạng của bà vẫn luôn không được tốt, tôi muốn tặng bà một món quà. Không biết cô có thể giúp tôi chọn hay không."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ sửng sốt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Những món quà tôi tặng, bà đều không thích lắm. Có lẽ thứ cô chọn, bà sẽ thích."</p><p style="text-align: justify; margin-bottom: 0.9em">Tự hỏi lòng mình, Thời Vụ rất sẵn lòng giúp bà cụ chọn quà, nhưng nàng không muốn đi cùng Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Ánh mắt Thời Vụ hạ xuống, dừng lại nơi mắt cá chân của cô rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, hay là cô nói cho tôi biết thương hiệu và kiểu dáng bà thường thích, tôi sẽ đi mua giúp cô?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường có vẻ không vui:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao vậy? Không muốn đỡ tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ vội vàng lắc đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không phải. Chỉ là chân cô đang bị trẹo, tốt nhất vẫn nên nghỉ ngơi nhiều hơn, không nên đi lại quá nhiều."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cũng đúng, vậy thì không đi nữa."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nói, cô vừa lấy điện thoại ra, bấm một số rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vào đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Sau đó, cánh cửa gỗ của phòng tiếp khách được mở ra. Trần Hy bước vào, cùng với chiếc xe lăn cô ấy đang đẩy trên tay.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nhìn Trần Hy, lại nhìn chiếc xe lăn, sau đó quay sang nhìn Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng không hiểu nhầm đấy chứ?</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chuẩn bị xong rồi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ suýt bị một ngụm canh làm sặc chết.</p><p style="text-align: justify; margin-bottom: 0.9em">Được, chuẩn bị rất chu đáo.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ từng phải ngồi xe lăn một lần. Hồi tiểu học, nàng ngã từ trên cầu trượt xuống, bị gãy xương cẳng chân. Chiếc xe lăn ấy do Thường Anh chuẩn bị cho nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi đó còn thấy mới lạ, nàng ngồi xe lăn đến trường. Nhưng chỉ sau một ngày, nàng đã cảm thấy vô cùng khó chịu, bởi rất nhiều bạn học lén lút gọi nàng là:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đồ tàn phế."</p><p style="text-align: justify; margin-bottom: 0.9em">Lúc ấy nàng còn rất nhỏ, đã nói với Thường Anh:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mẹ, bọn họ xấu xa quá, đáng ghét thật."</p><p style="text-align: justify; margin-bottom: 0.9em">Thường Anh dịu dàng dỗ dành:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tiểu Thạch Đầu nhà chúng ta sẽ không bao giờ làm chuyện đáng ghét như vậy."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Con mới không làm."</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng ngay từ khi nhìn thấy chiếc xe lăn, nàng vẫn lo Lâm Nhược Đường sẽ phải đón nhận những ánh mắt khác thường. Im lặng một lúc, nàng nói với cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Không nhất thiết phải ngồi xe lăn đâu nhỉ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy cô đỡ tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cứng đầu đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Là lỗi do nàng gây ra thì nàng sẽ chịu trách nhiệm về hậu quả. Thời Vụ nhận!</p><p style="text-align: justify; margin-bottom: 0.9em">Nhìn vẻ mặt khổ đại cừu thâm của nàng, khóe môi Lâm Nhược Đường khẽ cong lên. Sau đó cô lại giả vờ như không có chuyện gì, cúi đầu uống hai ngụm canh.</p><p style="text-align: justify; margin-bottom: 0.9em">Buổi tối ăn xong, Thời Vụ súc miệng rồi vào nhà vệ sinh chỉnh trang lại lớp trang điểm và quần áo. Không có vấn đề gì, nàng mới trở về văn phòng.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường đang gọi điện thoại, ngồi trên sofa. Thấy nàng bước vào, cô vẫy tay gọi. Thời Vụ cảm thấy động tác này cứ như đang gọi một chú cún con. Khóe môi nàng giật giật, nhưng vẫn đi tới.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nhường ra một khoảng trống, một tay cầm điện thoại, tay còn lại vỗ nhẹ lên chỗ bên cạnh. Thời Vụ ngồi xuống, cô rất tự nhiên đặt chân bị thương lên đầu gối nàng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cũng theo thói quen lấy một thứ trên bàn trà.</p><p style="text-align: justify; margin-bottom: 0.9em">Trên đường đi, Thời Vụ thật sự không hiểu tại sao chỉ mua một món quà mà nhất định phải đến trung tâm thương mại Hiểu Băng. Nơi đó cách công ty rất xa, hơn nữa những thương hiệu bên trong đều có bán ở các trung tâm thương mại khác.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng Lâm Nhược Đường kiên quyết muốn đến đó, Thời Vụ cũng hết cách. Là tài xế, nàng chỉ có thể nghe theo.</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy chưa đến giờ cao điểm buổi tối, nhưng vì trời mưa nên xe cộ trên đường rất đông. Thời Vụ phải liên tục lái rồi dừng. Nàng nghe Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Có bài hát nào cô muốn nghe không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Trước đây, khi ngồi trên xe, Thời Vụ thường kết nối Bluetooth với điện thoại rồi trực tiếp mở danh sách nhạc yêu thích. Bây giờ lại phải đọc tên từng bài cho Lâm Nhược Đường, nàng cảm thấy hơi ngượng nên hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng muốn nghe bài gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi rất ít khi nghe nhạc. Nếu cô cảm thấy buồn chán thì có thể kết nối Bluetooth của cô để nghe."</p><p style="text-align: justify; margin-bottom: 0.9em">Ban đầu Thời Vụ không định làm vậy, nhưng sau khi dừng đèn đỏ đến bốn lần, nàng thật sự cảm thấy hơi chán, đành kết nối Bluetooth với điện thoại rồi mở nhạc.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng nghe khá nhiều bài hát cũ. May mà tuổi tác giữa Lâm Nhược Đường và nàng không chênh lệch bao nhiêu. Nghe được một bài, cô hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nhạc chủ đề của Kiếm Tiên sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng cũng từng xem Kiếm Tiên à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bộ phim đó rất nổi tiếng, tôi từng xem cũng đâu có gì lạ. Còn cô, hồi nhỏ thích xem phim truyền hình nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ buồn chán đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hồi nhỏ tôi không xem phim truyền hình, tôi thích xem hoạt hình, Tom và Jerry. Lâm tổng biết không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Cô bật cười, hỏi lại Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chẳng lẽ trong mắt cô, tôi là người nguyên thủy sống trong hang núi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ khựng lại, cũng hơi ngượng vì bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tôi chỉ cảm thấy Lâm tổng không giống người sẽ xem phim truyền hình thôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy cô cảm thấy tôi giống kiểu người nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nghiêm túc suy nghĩ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Giống học bá. Tôi nghe Tiểu Châu kể, thành tích của cô hồi đi học đặc biệt tốt. Hồi nhỏ tôi rất ngưỡng mộ những bạn học có thành tích tốt."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ngưỡng mộ điều gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mỗi lần có kết quả thi, giáo viên đều thưởng cho họ rất nhiều đồ ăn vặt."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi cô:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hồi nhỏ, cô chắc thường xuyên được thưởng lắm nhỉ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mẹ tôi thường thưởng cho tôi rất nhiều tiền, để tôi muốn ăn gì, mua gì thì tự mình lựa chọn."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng chớp mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Đây chính là cái gọi là không cùng tiếng nói, nói thêm nửa câu cũng thừa sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Hiểu rồi, nàng hiểu rồi.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường lại không cảm thấy có gì không ổn. Trái lại, cô dường như rất thích kiểu trò chuyện không có mục đích này.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô lại thích trò chuyện phiếm sao? Nói ra thật khó tin.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không tìm được chủ đề.</p><p style="text-align: justify; margin-bottom: 0.9em">Cô liền chủ động hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô còn thích gì nữa?"</p><p style="text-align: justify; margin-bottom: 0.9em">Đúng lúc đang dừng đèn đỏ, Thời Vụ thuận miệng đáp mà không suy nghĩ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hả?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Hồi nhỏ cô còn thích làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Chỉ một câu của cô đã kéo Thời Vụ trở về quãng thời gian trước đây. Hai tay nàng nắm vô lăng rồi nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thích chơi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường định thần lại, một tay đặt bên mép cửa sổ, chống nửa gương mặt. Cô quay đầu nhìn Thời Vụ rồi hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy hồi nhỏ cô chắc hẳn rất nghịch ngợm."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Trước cửa nhà tôi có một cái cây, cô biết chứ? Quanh năm nó đều trụi lủi. Cô biết tại sao không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường suy nghĩ một lúc rồi lắc đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chưa nói đã bật cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Là do tôi trèo đấy. Hồi nhỏ, hễ không có việc gì làm là tôi thích trèo cây, trèo lên rồi hái lá, mỗi lần hái cả một nắm lớn."</p><p style="text-align: justify; margin-bottom: 0.9em">Dường như Lâm Nhược Đường đã tưởng tượng ra được khung cảnh ấy. Cô nhìn chăm chú vào gương mặt nghiêng của Thời Vụ rồi  nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mẹ cô đã đặt nhầm tên cho cô rồi. Cô không nên tên là Thời Vụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hề nghi ngờ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy nên gọi là gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nên gọi là Thời Khỉ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Muốn làm tổn thương lẫn nhau phải không?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cong môi, hỏi Lâm Nhược Đường:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy hồi nhỏ Lâm tổng thích làm gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thích học."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ "ồ" một tiếng:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy chẳng phải là mọt sách sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường bật cười hai tiếng. Thời Vụ được đà nói tiếp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Vậy chắc chắn Lâm tổng chẳng có người bạn nào."</p><p style="text-align: justify; margin-bottom: 0.9em">— "Sao có thể chứ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chẳng phải cô là bạn của tôi sao?"</p><p style="text-align: justify; margin-bottom: 0.9em">Đo ván!</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ há miệng nhưng không thể phản bác.</p><p style="text-align: justify; margin-bottom: 0.9em">Nói không phải sao? Nếu nàng không xem Lâm Nhược Đường là bạn, hai người có thể trò chuyện với nhau như thế này sao?</p><p style="text-align: justify; margin-bottom: 0.9em">Nhưng nếu thừa nhận thì nàng lại cảm thấy quá ấm ức.</p><p style="text-align: justify; margin-bottom: 0.9em">Quả nhiên Lâm Nhược Đường gian xảo, đúng là bản tính của thương nhân!</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ tự biết mình không bằng, đành khâm phục nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cảm ơn Lâm tổng đã coi trọng tôi."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường khẽ cười:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Dễ nói."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đạp chân ga, chiếc xe lao đi. Chẳng bao lâu sau, họ đã đến trung tâm thương mại Hiểu Băng, khu B, bãi đỗ xe số ba.</p><p style="text-align: justify; margin-bottom: 0.9em">Lần trước nàng cũng đến đây đón Lâm Nhược Đường. Bây giờ xuống xe ở chỗ này, Thời Vụ đỗ xe xong rồi đỡ cô xuống, hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô định mua gì tặng bà ?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Bà thích sưu tầm trà cụ."</p><p style="text-align: justify; margin-bottom: 0.9em">Bấy giờ Thời Vụ mới hiểu tại sao Lâm Nhược Đường nhất định phải đến trung tâm thương mại Hiểu Băng. Ở đây có một cửa hàng trà cụ thủ công rất nổi tiếng. Chủ tiệm là một phụ nữ ngoài ba mươi tuổi. Những sản phẩm hoàn thiện của cô ấy thường xuyên lên xu hướng vì tinh xảo và đẹp mắt, giá cả cũng cao đến mức khiến người ta phải líu lưỡi.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đoán Lâm Nhược Đường muốn đến cửa hàng đó. Quả nhiên, hai người đi thẳng lên tầng bốn.</p><p style="text-align: justify; margin-bottom: 0.9em">Chủ tiệm mặc một bộ sườn xám màu xanh nhạt. Nhìn thấy Lâm Nhược Đường, cô ấy lập tức vui mừng ra mặt:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lâm tổng, cô đến rồi."</p><p style="text-align: justify; margin-bottom: 0.9em">Với thái độ này, chắc hẳn Lâm Nhược Đường từng mua đồ ở đây.</p><p style="text-align: justify; margin-bottom: 0.9em">Khi nhìn thấy Thời Vụ, chủ tiệm hơi khựng lại, sau đó quan sát tư thế nàng đang đỡ Lâm Nhược Đường.</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường không hề tránh né, gần nửa người đều dựa vào nàng. Nhưng nếu cô ấy nhớ không nhầm, Lâm Nhược Đường vốn không thích tiếp xúc thân thể với người khác. Ngay cả thư ký Trần Hy cũng luôn giữ khoảng cách an toàn với cô.</p><p style="text-align: justify; margin-bottom: 0.9em">Người này là ai vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Đôi mắt đẹp của chủ tiệm kín đáo đánh giá Thời Vụ. Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lấy mấy bộ đó ra đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Chủ tiệm vẫn đứng im. Thời Vụ tò mò nhìn cô ấy một cái, cô ấy mới hoàn hồn:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ồ, được. Cô đợi một lát."</p><p style="text-align: justify; margin-bottom: 0.9em">Chủ tiệm đi vào phía sau cửa hàng. Chẳng bao lâu sau, cô ấy mang ra ba bộ trà cụ rồi giới thiệu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thính Lan, Tượng Tâm và Bán Sơn. Lâm tổng, ba bộ cô muốn xem đều ở đây."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô cảm thấy bộ nào đẹp?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ nhìn đến hoa cả mắt. Quả nhiên không hổ là những tác phẩm thường xuyên lên xu hướng, bộ nào cũng tinh xảo và đẹp mắt.</p><p style="text-align: justify; margin-bottom: 0.9em">Điểm nhấn của ba bộ khác nhau, trong đó Bán Sơn mang vẻ trang nhã, khoáng đạt nhất. Không hiểu tại sao, vừa nhìn thấy nó, nàng đã nghĩ đến Lâm Ngọc Phượng.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ quan sát thêm vài giây rồi Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Lấy bộ này đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ lập tức cảm thấy trách nhiệm nặng nề:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Quyết định luôn rồi sao? Không xem thêm à?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Ấn tượng đầu tiên là quan trọng nhất."</p><p style="text-align: justify; margin-bottom: 0.9em">Chủ tiệm mang bộ trà cụ đi đóng gói. Thời Vụ đứng bên cạnh Lâm Nhược Đường, nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Thật ra cũng không thể quá dựa vào ấn tượng đầu tiên."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Nói thế nào?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ im lặng.</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng đâu thể nói với Lâm Nhược Đường rằng ấn tượng đầu tiên của mình về cô là một kẻ vô cùng vô sỉ. Thời Vụ không có lá gan ấy, chỉ cúi đầu nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Khi làm việc vẫn không nên quá dựa vào cảm giác."</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường gật đầu:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cũng đúng."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ thả lỏng, đảo mắt nhìn quanh cửa hàng. Trên quầy trưng bày đủ loại trà cụ, giá cao thấp khác nhau, nhưng món rẻ nhất cũng hơn một nghìn.</p><p style="text-align: justify; margin-bottom: 0.9em">Tuy nàng không am hiểu trà cụ, nhưng bộ vừa chọn chắc chắn là hàng cực phẩm, có lẽ giá cũng vô cùng đắt. Nàng đang nhìn đến xuất thần thì Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đợi ở đây, tôi đi lấy một thứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Được."</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng vừa định hỏi Lâm Nhược Đường đi lại có bất tiện không thì chủ tiệm đã gọi nàng lại, hỏi muốn chọn màu gì để đóng gói.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ chọn màu xanh navy. Chủ tiệm nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô có mắt nhìn thật đấy, màu này rất hợp với dòng Bán Sơn."</p><p style="text-align: justify; margin-bottom: 0.9em">Được khen khiến Thời Vụ hơi ngượng ngùng. Nàng cười đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Là do cô thiết kế đẹp. Bộ nào cũng rất tinh xảo, phối với màu gì cũng hợp."</p><p style="text-align: justify; margin-bottom: 0.9em">Khi Lâm Nhược Đường quay lại, hai người đang khách sáo khen ngợi lẫn nhau. Thời Vụ vừa ngẩng đầu nhìn thấy cô đã bước đến, vô thức hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Cô đi đâu vậy?"</p><p style="text-align: justify; margin-bottom: 0.9em">Hỏi xong, nàng mới cảm thấy mình quản quá nhiều.</p><p style="text-align: justify; margin-bottom: 0.9em">May mà Lâm Nhược Đường không phản ứng gì, chỉ giải thích:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đi mua một thứ."</p><p style="text-align: justify; margin-bottom: 0.9em">Vừa nói, cô vừa lấy từ trong túi ra một chiếc hộp nhỏ vuông vức rồi đưa cho Thời Vụ.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ không hiểu, ngẩng đầu nhìn cô. Lâm Nhược Đường khẽ nâng cằm:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Mở ra đi."</p><p style="text-align: justify; margin-bottom: 0.9em">Bấy giờ Thời Vụ mới nhận lấy chiếc hộp rồi mở ra.</p><p style="text-align: justify; margin-bottom: 0.9em">Bên trong là một viên đá đỏ như máu, được chạm thành hình giọt mưa. Bề mặt nhẵn bóng, cảm giác chạm vào rất mịn màng. Tuy kiểu dáng đơn giản nhưng lại mang vẻ đẹp tự nhiên, như thể vốn đã được tạo thành như vậy.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ hỏi:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Đây là gì?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường nói:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Quà. Cô thích không?"</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ cảm thấy câu này là lạ. Sao nghe cứ như món quà này được tặng cho nàng vậy?</p><p style="text-align: justify; margin-bottom: 0.9em">Nàng ngẩng đầu nhìn Lâm Nhược Đường, chần chừ chỉ vào mình. Cô gật đầu.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ ngơ ngác:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Tại sao cô lại tặng quà cho tôi?"</p><p style="text-align: justify; margin-bottom: 0.9em">Lâm Nhược Đường ung dung đáp:</p><p style="text-align: justify; margin-bottom: 0.9em">— "Chẳng phải cô cũng vừa xuất viện sao? Đây là quà mừng xuất viện."</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ:</p><p style="text-align: justify; margin-bottom: 0.9em">— "......"</p><p style="text-align: justify; margin-bottom: 0.9em">Nhà họ Lâm coi trọng lễ nghi đến vậy sao? Xuất viện cũng phải tặng quà?</p><p style="text-align: justify; margin-bottom: 0.9em">.....</p><p style="text-align: justify; margin-bottom: 0.9em">Lời tác giả:</p><p style="text-align: justify; margin-bottom: 0.9em">Cảm ơn các tiểu thiên sứ đã tặng 12 phiếu Bá Vương và 452 chai dung dịch dinh dưỡng~</p><p style="text-align: justify; margin-bottom: 0.9em">Tặng ngẫu nhiên 30 bao lì xì, moah moah.</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: Nhà họ Lâm khách sáo quá.</p><p style="text-align: justify; margin-bottom: 0.9em">Nhà họ Lâm: Vậy không khách sáo nữa, tặng Lâm Nhược Đường cho cô, có muốn không?</p><p style="text-align: justify; margin-bottom: 0.9em">Thời Vụ: ......</p>', 'published', now(), now(), now())
